  FT["PH-H5637"] = {"id":"PH-H5637","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1991/ra_7149_1991.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Tanauan市","en":"An Act Establishing a High School in the Municipality of Tanauan, Province of Leyte, to Be Known as the Tanauan National High School, and Appropriating Funds Therefor","orig":"An Act Establishing a High School in the Municipality of Tanauan, Province of Leyte, to Be Known as the Tanauan National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7149","issuingBody":"Congress of the Philippines","promulgatedDate":"1991-08-22","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1991/ra_7149_1991.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5637-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a high school in the Municipality of Tanauan, Province of Leyte, to be known as the Tanauan National High School."}},{"id":"PH-H5637-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H5637-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act is hereby authorized to be appropriated in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5637-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p80"};
  FT["PH-H5638"] = {"id":"PH-H5638","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1991/ra_7150_1991.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Palo市","en":"An Act Establishing a High School in the Municipality of Palo, Province of Leyte, to be known as the Palo National High School, and Appropriating Funds Therefore","orig":"An Act Establishing a High School in the Municipality of Palo, Province of Leyte, to be known as the Palo National High School, and Appropriating Funds Therefore"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7150","issuingBody":"Congress of the Philippines","promulgatedDate":"1991-08-22","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1991/ra_7150_1991.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5638-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a high school in the Municipality of Palo, Province of Leyte, to be known as the Palo National High School."}},{"id":"PH-H5638-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H5638-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act is hereby authorized to be appropriated in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5638-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p80"};
  FT["PH-H5639"] = {"id":"PH-H5639","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1991/ra_7151_1991.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"授予 Cebu Air, Inc. 以宿务为基地设立、运营和维护国内与国际航空客运、邮件、货物与财产运输服务的特许经营权法案","en":"An Act Granting Cebu Air, Inc., a Franchise to Establish, Operate and Maintain Transport Services for the Carriage of Passengers, Mail, Goods and Property by Air, Both Domestic and International, with Cebu as its Base","orig":"An Act Granting Cebu Air, Inc., a Franchise to Establish, Operate and Maintain Transport Services for the Carriage of Passengers, Mail, Goods and Property by Air, Both Domestic and International, with Cebu as its Base"},"level":"law","status":"active","topics":["investment","trade"],"docNumber":"Republic Act No. 7151","issuingBody":"Congress of the Philippines","promulgatedDate":"1991-08-30","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1991/ra_7151_1991.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5639-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise – Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to Cebu Air, Inc., hereunder referred to as the grantee, its successors or assigns, a franchise to establish, operate and maintain transport services for the carriage of passengers, mail, goods and property by air, both domestic and international, with Cebu as its base.\nAir transport services shall include the maintenance and operation of hangars and aircraft service stations and facilities and other services of similar nature which may be necessary, convenient or useful as an auxiliary to aircraft transportation.\nThe grantee shall have the right as its terminal and landing fields, as well as in its aircraft, to construct, operate and maintain stations or transmitting sets for wireless telegraphy and direction findings, and other radio aids to air navigation, using wavelengths in accordance with the rules and regulations made from time to time by the proper agencies of the Government. The wireless communication facilities shall be used solely for receiving and transmitting weather forecasts and other matters in connection with the grantee's services."}},{"id":"PH-H5639-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Civil Aeronautics Board – The grantee shall secure from the Civil Aeronautics Board the appropriate permits and licenses for its operations.\nAll aircraft used by the grantee including their accessories and equipment shall at all times be airworthy and the crew members shall be licensed by the Government of the Philippines. They shall be equipped with radio communication, safety and other equipment and shall be operated and maintained in accordance with the regulations and technical requirements of the Air Transportation Office or such other regulatory bodies as the Government may prescribe for this purpose.\nThe grantee's equipment and the operation of such equipment shall at all times be subject to inspection and regulation by the Air Transportation Office.\nThe grantee shall comply with the provisions of Republic Act Numbered Seven hundred and seventy-six, and the regulation promulgated thereunder from time to time."}},{"id":"PH-H5639-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Responsibility to the Public – Excepting cases of force majeure and whenever weather conditions permit, the grantee shall maintain scheduled and/or non-scheduled and/or charter air transport services between any and all points and places throughout the Philippines and other countries at such frequencies as traffic needs may require with Cebu as its base: provided, however, that at least twenty-five percent (25%) of all its frequencies shall be for the domestic market."}},{"id":"PH-H5639-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Rates for Services – The grantee shall fix just and reasonable rates for the transportation of passengers, mail, goods and freight, subject to the regulations and approval of the Civil Aeronautics Board and other proper regulatory agencies of the Government."}},{"id":"PH-H5639-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Term of Franchise – The grantee shall be for a term of forty (40) years from the date of the approval, of this Act, unless sooner revoked or canceled. In the event that the grantee fails to operate within two (2) years from the effectivity of this Act, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H5639-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Landing Facilities – The grantee may use the landing and other airport facilities on land and water as may be maintained or owned by the Government within the Philippines on the grantee's lines subject to such terms and conditions, restrictions and national policy considerations as the Philippine Government may prescribe and, reciprocally, the Philippine Government shall have the right to use the landing and other airport facilities as may be maintained or owned by the grantee in the Philippines."}},{"id":"PH-H5639-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Contracts – The grantee is authorized to enter into transportation contracts with the Philippine Government, including the carrying of mail, upon such terms and conditions as may be mutually agreed upon. The grantee shall give preferential consideration to contracts with the Philippine Government. The grantee may likewise enter into transportation maintenance and/or servicing contracts, and such other contracts relating to air transport with other foreign-owned airlines particularly with those which have international routes."}},{"id":"PH-H5639-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Right of Government – In case of war, insurrection, domestic trouble, public calamity or national emergency, the Philippine Government, upon the order of the President, shall have the right to take over and operate the equipment of the grantee paying for its use or damages."}},{"id":"PH-H5639-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Public Equity Participation – In compliance with the constitutional mandate to democratize ownership of public utilities, the herein grantee shall make public offering through the stock exchanges of at least thirty percent (30%) of its common stocks within a period of ten (10) years from the date of effectivity of this Act: provided, that no single person or entity shall be allowed to own more than five percent (5%) of the stock offerings."}},{"id":"PH-H5639-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments – The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the operation of the services under the franchise hereby granted, attributable solely to the act or omission of the grantee."}},{"id":"PH-H5639-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Tax Provisions – The grantee shall pay to the Philippine Government during the life of this franchise a franchise tax of five percent (5%) of the gross revenues derived by the grantee from transport operations.\nIn the event that any competing individual, partnership or corporation receives and enjoys tax privileges and other favorable terms which tend to place the herein grantee at any disadvantage, then such provisions shall be deemed ipso facto part hereof and shall operate equally in favor of the grantee.\nThe grantee shall, however, be subject to income tax levied under Title II of the National Internal Revenue Code, as amended, and tax on its real property under existing laws on revenues earned from activities other than air transportation."}},{"id":"PH-H5639-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Sale, Lease, Transfer, Assignment, Usufruct, etc – The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise and the rights and privileges acquired thereunder to any person, firm, company, corporation, or legal entity, nor shall the controlling interest in the grantee be transferred to any such private person, firm, company, corporation or entity without the prior approval of Congress.\nAny person or entity to which this franchise is sold, transferred, or assigned shall be subject to all the conditions, terms, restrictions, and limitations of this Act."}},{"id":"PH-H5639-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Legislative Amendments – This franchise is subject to amendments or repeal by Congress when the common good so requires."}},{"id":"PH-H5639-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Separability Clause – If any section or provisions of this franchise, as amended, is held or declared unconstitutional or invalid by a competent court in a final judgment, the other sections or provisions hereof shall continue to be in force as if the section or provision so annulled or voided had never been incorporated in this franchise."}},{"id":"PH-H5639-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Repealing Clause – All laws, decrees, orders, instructions, and rules and regulations, or parts thereof, which are inconsistent herewith are hereby repealed or modified accordingly."}},{"id":"PH-H5639-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Effectivity – This Act shall take effect fifteen (15) days after its publication in at least two (2) national newspapers of general circulation."}}],"pack":"ph-p80","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Cebu Air, Inc., a Franchise to Establish, Operate and Maintain Transport Services for the Carriage of Passengers, Mail, Goods and Property by Air, Both Domestic and International, with Cebu as its Base","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5640"] = {"id":"PH-H5640","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1991/ra_7152_1991.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"在哥打巴托省设立 Arakan 市镇的法案","en":"An Act Creating the Municipality of Arakan in the Province of Cotabato","orig":"An Act Creating the Municipality of Arakan in the Province of Cotabato"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7152","issuingBody":"Congress of the Philippines","promulgatedDate":"1991-08-30","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1991/ra_7152_1991.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5640-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Barangays Allab, Anapolan, Badiangon, Binongan, Doroluman, Ganatan, Greenfield, Kabalantian, Katipunan, Sto Niño, Makalangot, Malibatuan, Maria Caridad, Meocan, Naje, Napalico, Salasang, and Tumanding, all in the Municipality of Magpet, Province of Cotabato, are hereby separated from their municipality and constituted into a distinct and independent municipality in the Province of Cotabato to be known as the Municipality of Arakan."}},{"id":"PH-H5640-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The new municipality shall be bounded as follows:\nThe point of beginning is the junction of Kulaman and Tinanan River which is the common point boundary of the Municipalities of Magpet and President Roxas, point 1; thence, following the said boundary of Magpet and President Roxas through the upstream course of Kulaman River to its intersection with the Cotabato-Bukidnon provincial boundary, point 2; thence, following the said provincial boundary in northeasterly direction to a common point boundary of the Provinces of Cotabato, Davao and Bukidnon, point 3; thence, generally south following the Cotabato-Davao boundary to the peak of Mount Tinanan, point 4; thence, due west to its intersection with Mamag Creek, a tributary of Tinanan River, point 5, thence, northwesterly in an imaginary straight line to a common point boundary of PLA 1016 and PLA 1015 near Meocan River, point 6; thence, following the said common PLA boundary in a northwesterly direction to a common point of TL Project 42-Y and PLS 79 Case 2 to its intersection with Maleri Creek, point 8; thence, northerly following downstream course of Maleri Creek to its junction with (amutan Creek a common boundary of Antipas and the mother Municipality of Magpet, point 9; thence, northwesterly and northeasterly following the boundary of Antipas and Magpet to Arakan River, point 10; thence, following the downstream course of Arakan River to a common point boundary of Barangay Naje and Ilustre at the northern bank of the said river, point 11; thence, northwesterly following the said boundary of barangays Naje and Ilustre to Kulaman River, point 12; thence, upstream Kulaman River to its junction with Tinanan River, the point of beginning."}},{"id":"PH-H5640-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The seat of government of the new municipality shall be the present Barangay Greenfield."}},{"id":"PH-H5640-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All other barangays and sitios within the aforestated technical description but not specified in Section 1 hereof are hereby included in the new municipality."}},{"id":"PH-H5640-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"After ratification by the majority of the votes cast in a plebiscite to be conducted in the areas affected within a period of one hundred twenty days from the approval of this Act, the first mayor, vice-mayor and other officials of the new municipality shall be elected in the next regular election of local officials."}},{"id":"PH-H5640-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The Commission on Election shall conduct and supervise the plebiscite. The expenses in holding the plebiscite shall be taken out of the Contingent Fund under the current fiscal year appropriations."}},{"id":"PH-H5640-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p80","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Municipality of Arakan in the Province of Cotabato","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5641"] = {"id":"PH-H5641","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1991/ra_7153_1991.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Talisay市","en":"An Act Declaring April Fifteen of Every Year a Special Working Holiday in the Municipality of Talisay, Negros Occidental, in Honor of the Late General Anecito Lacson","orig":"An Act Declaring April Fifteen of Every Year a Special Working Holiday in the Municipality of Talisay, Negros Occidental, in Honor of the Late General Anecito Lacson"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7153","issuingBody":"Congress of the Philippines","promulgatedDate":"1991-08-30","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1991/ra_7153_1991.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5641-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"April Fifteen of every year is hereby declared a special working holiday in the Municipality of Talisay, Province of Negros Occidental, in honor of the late General Anecito Lacson."}},{"id":"PH-H5641-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p80"};
  FT["PH-H5642"] = {"id":"PH-H5642","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1991/ra_7154_1991.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"修订第 129 号国民议会法（即 1981 年司法重组法）第 14 条的法案","en":"An Act to Amend Section Fourteen of Batas Pambansa Bilang 129, Otherwise known as the Judiciary Reorganization Act of 1981","orig":"An Act to Amend Section Fourteen of Batas Pambansa Bilang 129, Otherwise known as the Judiciary Reorganization Act of 1981"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 7154","issuingBody":"Congress of the Philippines","promulgatedDate":"1991-09-04","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1991/ra_7154_1991.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5642-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 14, paragraph (a), of Batas Pambansa Blg. 129, otherwise known as the Judiciary Reorganization Act of 1981, is hereby amended to read as follows:\n\"(a) Seventy Regional Trial Judges shall be commissioned for the First Judicial Region. There shall be:\n\"Three branches with seats thereat for the Province of Abra, with seats at Bangued and Bucay;\n\"Fourteen branches with seats thereat for the Province of Benguet and the City of Baguio, with seats at Baguio City, La Trinidad, and Buguias;\n\"Ten branches with seats thereat for the Province of Ilocos Norte and the City of Laoag, with seats at Laoag City, Batac, and Bangui;\n\"Six branches with seats thereat for the Province of Ilocos Sur, with seats at Vigan, Narvacan, Cabigao and Tagudin;\n\"Eleven branches with seats thereat for the Province of La Union, with seats at San Fernando, Agoo, Bauang, and Balaoan;\n\"Two branches with seats thereat for the Province of Mountain Province, with seats at Bontoc; and \"Twenty-four branches with seats thereat for the Province of Pangasinan and the Cities of Dagupan and San Carlos, with seats at Lingayen, Dagupan City, Urdaneta, Villasis, Tayug, Rosales, Alaminos, Burgos, and San Carlos City.\""}},{"id":"PH-H5642-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 14, paragraph (b), of Batas Pambansa Blg. 129, otherwise known as the Judiciary Reorganization Act of 1981, is hereby amended to read as follows:\n\"(b) Thirty-eight Regional Trial Judges shall be commissioned for the Second Judicial Region. There shall be:\n\"Thirteen branches with seats thereat for the Province of Cagayan, with seats at Tuguegarao, Aparri, Tuao, Sanchez Mira, and Ballesteros;\n\"One branch for the Province of Batanes, with seat at Basco;\n\"Three branches with seats thereat for the Province of Ifugao, with seats at Lagawe, Alfonso Lista, and Banaue;\n\"Eleven branches with seats thereat for the Province of Isabela, with seats at Ilagan, Cauayan, Santiago, Cabagan, Roxas, and Echague;\n\"Two branches with seats thereat for the Province of Kalinga-Apayao, with seats at Tabuk and Luna;\n\"Five branches with seats thereat for the Province of Nueva Vizcaya, with seats at Bayombong and Bambang; and \"Three branches with seats thereat for the Province of Quirino, with seats at Cabarroguis and Maddela.\""}},{"id":"PH-H5642-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 14, paragraph (c), of Batas Pambansa Blg. 129, otherwise known as the Judiciary Reorganization Act of 1981, is hereby amended to read as follows:\n\"(c) Eighty-nine Regional Trial Judges shall be commissioned for the Third Judicial Region. There shall be:\n\"Five branches with seats thereat for the Province of Bataan, with seats at Balanga, Mariveles, and Dinalupihan;\n\"Twenty-seven branches with seats thereat for the Province of Bulacan (except the Municipality of Valenzuela), with seats at Malolos;\n\"Twenty-two branches with seats thereat for the Province of Nueva Ecija and the Cities of Cabanatuan, San Jose and Palayan, with seats at Cabanatuan City, Guimba, Gapan, Sto. Domingo, San Jose City, and Palayan City;\n\"Twenty-two branches with seats thereat for the Province of Pampanga and the City of Angeles, with seats at San Fernando, Guagua, Macabebe, and Angeles City;\n\"Six branches with seats thereat for the Province of Tarlac, with seats at Tarlac, Capas, Paniqui, and Camiling; and \"Seven branches with seats thereat for the Province of Zambales and the City of Olongapo, with seats at Iba and Olongapo City.\""}},{"id":"PH-H5642-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 14, paragraph (d), of Batas Pambansa Blg. 129, otherwise known as the Judiciary Reorganization Act of 1981, is hereby amended to read as follows:\n\"(d) Two hundred seventy-six Regional Trial Judges shall be commissioned for the National Capital Judicial Region. There shall be:\n\"Ninety-seven branches for the City of Manila, with seats thereat;\n\"Forty-eight branches for Quezon City, with seats thereat;\n\"Thirteen branches for Pasay City, with seats thereat;\n\"Thirteen branches for Caloocan City, with seats thereat;\n\"One hundred two branches for the Municipalities of Navotas, Malabon, San Juan, Mandaluyong, Makati, Pasig, Pateros, Taguig, Marikina, Parañaque, Las Piñas, and Muntinlupa; with fifty-eight seated in Makati, thirty-four seated in Pasig, two seated in Marikina, five in Malabon, one in Parañaque, one in Las Piñas, and one in Muntinlupa; and \"Three branches for the Municipality of Valenzuela, with seats thereat.\""}},{"id":"PH-H5642-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section 14, paragraph (e), of Batas Pambansa Blg. 129, otherwise known as the Judiciary Reorganization Act of 1981, is hereby amended to read as follows:\n\"(e) Ninety-six Regional Trial Judges shall be commissioned for the Fourth Judicial Region. There shall be:\n\"Nineteen branches with seats thereat for the Province of Batangas and the Cities of Lipa and Batangas, with seats at Batangas City, Lemery, Taal, Tanauan, Balayan, Lipa City, Nasugbu, and Rosario;\n\"Twelve branches with seats thereat for the Province of Cavite and the Cities of Cavite, Tagaytay and Trece Martires, with seats at Naic, Cavite City, Bacoor, Imus, Trece Martires City, and Dasmariñas;\n\"Seventeen branches with seats thereat for the Province of Laguna and the City of San Pablo, with seats at Biñan, San Pedro, Sta. Cruz, San Pablo City, Siniloan, and Calamba;\n\"Two branches for the Province of Marinduque, with seats at Boac;\n\"Five branches with seats thereat for the Province of Mindoro Oriental, with seats at Calapan, Pinamalayan, and Roxas;\n\"Three branches with seats thereat for the Province of Mindoro Occidental, with seats at Mamburao and San Jose;\n\"Seven branches with seats thereat for the Province of Palawan and the City of Puerto Princesa, with seats at Puerto Princesa City, Roxas, Brooke's Point, and Coron;\n\"Thirteen branches with seats thereat for the Province of Quezon and the City of Lucena, with seats at Lucena City, Gumaca, Calauag, Mauban, and Infanta;\n\"Two branches for the Province of Aurora, with seats at Baler;\n\"Fourteen branches with seats thereat for the Province of Rizal, except the cities and municipalities embraced within the National Capital Judicial Region, with seats at Binangonan, Antipolo, San Mateo, Morong, and Tanay; and \"Two branches with seats thereat for the Province of Romblon, with seats at Romblon and Odiongan.\""}},{"id":"PH-H5642-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Section 14, paragraph (f), of Batas Pambansa Blg. 129, otherwise known as the Judiciary Reorganization Act of 1981, is hereby amended to read as follows:\n\"(f) Sixty-five Regional Trial Judges shall be commissioned for the Fifth Judicial Region. There shall be:\n\"Eighteen branches with seats thereat for the Province of Albay and the City of Legaspi, with seats at Legaspi City, Ligao, and Tabaco;\n\"Twenty-seven branches with seats thereat for the Province of Camarines Sur and the Cities of Naga and Iriga, with seats at Naga City, Libmanan, Tigaon, San Jose, Pili, Iriga City, Buhi, Nabua, Sipocot, Ragay, and Calabanga;\n\"Five branches with seats thereat for the Province of Camarines Norte, with seats at Daet and Labo;\n\"Two branches for the Province of Catanduanes, with seats at Virac;\n\"Seven branches with seats thereat for the Province of Masbate, with seats at Masbate, Claveria, Cataingan, and San Jacinto; and \"Six branches with seats thereat for the Province of Sorsogon, with seats at Sorsogon, Gubat, Irosin, and Bulan.\""}},{"id":"PH-H5642-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Section 14, paragraph (g), of Batas Pambansa Blg. 129, otherwise known as the Judiciary Reorganization Act of 1981, is hereby amended to read as follows:\n\"(g) Sixty-nine Regional Trial Judges shall be commissioned for the Sixth Judicial Region. There shall be:\n\"Nine branches with seats thereat for the Province of Aklan, with seats at Kalibo;\n\"Five branches with seats thereat for the Province of Antique, with seats at San Jose, Culasi, and Bugasong;\n\"Eight branches with seats thereat for the Province of Capiz and the City of Roxas, with seats at Roxas City and Mambusao;\n\"Twenty-two branches with seats thereat for the Province of Iloilo, the Sub-province of Guimaras, and the City of Iloilo, with seats at Iloilo City, Barotac Viejo, Guimbal, and Dumangas; and \"Twenty-five branches with seats thereat for the Province of Negros Occidental and the Cities of Bacolod, Bago, Cadiz, La Carlota, San Carlos and Silay, with seats at Silay City, Bacolod City, Himamaylan, San Carlos City, Cadiz City, Kabankalan, Bago City, La Carlota City, and Sipalay.\""}},{"id":"PH-H5642-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Section 14, paragraph (h), of Batas Pambansa Blg. 129, otherwise known as the Judiciary Reorganization Act of 1981, is hereby amended to read as follows:\n\"(h) Sixty-four Regional Trial Judges shall be commissioned for the Seventh Judicial Region. There shall be:\n\"Ten branches with seats thereat for the Province of Bohol and the City of Tagbilaran, with seats at Tagbilaran City, Carmen, Talibon, and Loay;\n\"Thirty-five branches with seats thereat for the Province of Cebu and the Cities of Cebu, Danao, Lapu-Lapu, Mandaue and Toledo, with seats at Cebu City, Danao City, Argao, Lapu-Lapu City, Mandaue City, Toledo City, Barili, Bogo, and Oslob;\n\"Eighteen branches with seats thereat for the Province of Negros Oriental and the Cities of Dumaguete, Bais and Canlaon, with seats at Dumaguete City, Bayawan, Guihulngan, Bais City, Tanjay; and \"One branch for the Province of Siquijor, with seats at Siquijor.\""}},{"id":"PH-H5642-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Section 14, paragraph (i), of Batas Pambansa Blg. 129, otherwise known as the Judiciary Reorganization Act of 1981, is hereby amended to read as follows:\n\"(i) Forty-one Regional Trial Judges shall be commissioned for the Eighth Judicial Region. There shall be:\n\"Five branches with seats thereat for the Province of Eastern Samar, with seats at Borongan, Guiuan, Dolores, and Oras;\n\"Seventeen branches with seats thereat for the Province of Leyte, the Sub-province of Biliran, and the Cities of Ormoc and Tacloban, with seats at Tacloban City, Abuyog, Calubian, Ormoc City, Carigara, Baybay, Burauen, Naval, Palompon, Hilongos, and Caibiran;\n\"Six branches with seats thereat for the Province of Northern Samar, with seats at Catarman, Laoang, Allen, and Gamay;\n\"Four branches with seats thereat for the Province of Southern Leyte, with seats at Maasin, San Juan, and Sogod; and \"Nine branches with seats thereat for the Province of Samar and the City of Calbayog, with seats at Catbalogan, Basey, Calbayog City, Calbiga, Tarangnan, and Gandara.\""}},{"id":"PH-H5642-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Section 14, paragraph (j), of Batas Pambansa Blg. 129, otherwise known as the Judiciary Reorganization Act of 1981, is hereby amended to read as follows:\n\"(j) Thirty Regional Trial Judges shall be commissioned for the Ninth Judicial Region. There shall be:\n\"Two branches for the Province of Basilan, with seats at Isabela;\n\"Three branches with seats thereat for the Province of Sulu, with seats at Jolo, Parang, and Siasi;\n\"Two branches with seats thereat for the Province of Tawi-Tawi with seats at Bongao and Sapa-Sapa;\n\"Eight branches with seats thereat for the Province of Zamboanga del Norte and the Cities of Dipolog and Dapitan, with seats at Dipolog City, Sindangan, Siocon, and Liloy; and \"Fifteen branches with seats thereat for the Province of Zamboanga del Sur and the Cities of Pagadian and Zamboanga, with seats at Zamboanga City, Pagadian City, Molave, San Miguel, Ipil, and Aurora.\""}},{"id":"PH-H5642-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Section 14, paragraph (k), of Batas Pambansa Blg. 129, otherwise known as the Judiciary Reorganization Act of 1981, is hereby amended to read as follows:\n\"(k) Forty-four Regional Trial Judges shall be commissioned for the Tenth Judicial Region. There shall be:\n\"Seven branches with seats thereat for the Province of Agusan del Norte and the City of Butuan, with seats at Butuan City and Cabadbaran;\n\"Two branches with seats thereat for the Province of Agusan del Sur, with seats at Prosperidad and Bayugan;\n\"Four branches with seats thereat for the Province of Bukidnon, with seats at Malaybalay, Don Carlos, and Manolo Fortich;\n\"Seven branches with seats thereat for the Province of Misamis Occidental and the Cities of Oroquieta, Ozamiz and Tangub, with seats at Oroquieta City, Calamba, Ozamiz City, and Tangub City;\n\"Nineteen branches with seats thereat for the Province of Misamis Oriental and the Cities of Cagayan de Oro and Gingoog, with seats at Cagayan de Oro City, Medina, Gingoog City, and Initao;\n\"One branch for the Province of Camiguin, with seat at Mambajao; and \"Four branches with seats thereat for the Province of Surigao del Norte and the City of Surigao, with seats at Surigao City, Dapa, and Dinagat, Dinagat Island.\""}},{"id":"PH-H5642-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Section 14, paragraph (l), of Batas Pambansa Blg. 129, otherwise known as the Judiciary Reorganization Act of 1981, is hereby amended to read as follows:\n\"(l) Forty-one Regional Trial Judges shall be commissioned for the Eleventh Judicial Region. There shall be:\n\"Six branches with seats thereat for the Province of Davao del Norte, with seats at Tagum, Nabunturan, and Panabo;\n\"Four branches with seats thereat for the Province of Davao Oriental, with seats at Mati, Baganga, and Lupon;\n\"Sixteen branches with seats thereat for the Province of Davao del Sur and the City of Davao, with seats at Davao City, Digos, Malita, and Bansalan;\n\"Ten branches with seats thereat for the Province of South Cotabato and the City of General Santos, with seats at General Santos City, Koronadal, Surallah, Alabel, and Polomolok; and \"Five branches with seats thereat for the Province of Surigao del Sur, with seats at Tandag, Lianga, Bislig, and Cantilan.\""}},{"id":"PH-H5642-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Section 14, paragraph (m), of Batas Pambansa Blg. 129, otherwise known as the Judiciary Reorganization Act of 1981, is hereby amended to read as follows:\n\"(m) Twenty-five Regional Trial Judges shall be commissioned for the Twelfth Judicial Region. There shall be:\n\"Eight branches with seats thereat for the Province of Lanao del Norte and the City of Iligan, with seats at Iligan City, Kapatagan, and Tubod;\n\"Five branches with seats thereat for the Province of Lanao del Sur and the City of Marawi, with seats at Marawi City and Malabang;\n\"Three branches with seats thereat for the Province of Maguindanao and the City of Cotabato, with seats at Cotabato City and Maganoy;\n\"Six branches with seats thereat for the Province of North Cotabato, with seats at Kabacan, Kidapawan, and Midsayap; and \"Three branches with seats thereat for the Province of Sultan Kudarat, with seats at Isulan, Tacurong, and Kalamansig.\""}},{"id":"PH-H5642-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The Supreme Court shall effect the renumbering of the Regional Trial Courts from the Roman numeral system to Arabic numeral system. It shall also reorder the numbering of all the Regional Trial Courts all over the country in accordance with the allocations of seats provided herein."}},{"id":"PH-H5642-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"The amount necessary to carry out the provisions of this Act on priority basis as determined by the Supreme Court is hereby authorized to be included in the appropriations of the Supreme Court in the annual General Appropriations Act of the year following its enactment into law and thereafter: provided, that, to effectively implement this Act, the Supreme Court is hereby vested with the power to prioritize or to determine which sala or salas shall be established for a given year: provided, further, that, for reasons of efficiency, economy and accessibility, the Supreme Court is hereby authorized to transfer a sala from one station, as determined herein, to another within the same Judicial Region; Provided, finally, that the Supreme Court shall not effect the transfer of a sala oftener than once every three (3) years."}},{"id":"PH-H5642-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p80","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Section Fourteen of Batas Pambansa Bilang 129, Otherwise known as the Judiciary Reorganization Act of 1981","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5643"] = {"id":"PH-H5643","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1991/ra_7155_1991.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"在北甘马粦省设立 Tulay-Na-Lupa 市镇的法案","en":"An Act Creating the Municipality of Tulay-Na-Lupa in the Province of Camarines Norte","orig":"An Act Creating the Municipality of Tulay-Na-Lupa in the Province of Camarines Norte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7155","issuingBody":"Congress of the Philippines","promulgatedDate":"1991-09-06","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1991/ra_7155_1991.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5643-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Barangays Tulay-na-Lupa, Lugui, San Antonio, Mabilo I, Napaod, Benit, Bayan-bayan, Baay, Matanlang, Pagasa, Maot, and Calabasa, all in the Municipality of Labo, Province of Camarines Norte, are hereby separated from said municipality to form and constitute an independent Municipality of Tulay-na-Lupa without in any manner affecting the legal existence of the mother Municipality of Labo."}},{"id":"PH-H5643-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The new Municipality of Tulay-na-Lupa shall be bounded on the north by Mabilo II, on the northeast by Iberica, on the east by Municipality of San Vicente, on the southeast by Municipality of San Vicente, on the south by the boundary of Camarines Sur, on the southeast by the boundary of Tagkawayan, Quezon, and on the west by Labo River."}},{"id":"PH-H5643-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The seat of the new municipality shall be in Barangay Tulay-na-Lupa."}},{"id":"PH-H5643-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Except as herein provided, all provisions of laws now or hereafter applicable to regular municipalities shall be applicable to the new Municipality of Tulay-na-Lupa."}},{"id":"PH-H5643-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"After ratification by the majority of the votes cast in a plebiscite to be conducted in the area or areas affected within a period of one hundred eighty (180) days after the approval of this Act, the mayor, vice-mayor and other officials of the new Municipality of Tulay-na-Lupa shall be elected in the next regular election of local officials. The new municipality shall be considered duly organized upon the assumption of office of the first set of elected local officials."}},{"id":"PH-H5643-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The Commission on Elections shall conduct and supervise the plebiscite. The expenses in holding the plebiscite shall be taken out of the Contingent Fund under the current fiscal year appropriations."}},{"id":"PH-H5643-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Upon the organization of the new municipality, the proportionate share of the new Municipality of Tulay-na-Lupa in the obligations, funds, assets, and other properties of the Municipality of Labo shall be determined by the Provincial Board of Camarines Norte and transferred to the newly created municipality."}},{"id":"PH-H5643-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This Act shall take effect upon its publication in at least (2) newspaper of general circulation."}}],"pack":"ph-p80","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Municipality of Tulay-Na-Lupa in the Province of Camarines Norte","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5644"] = {"id":"PH-H5644","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1991/ra_7156_1991.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"微型水电激励法","en":"Mini-hydroelectric Power Incentive Act","orig":"Mini-hydroelectric Power Incentive Act An Act Granting Incentives to Mini-Hydroelectric Power Developers and for Other Purposes"},"level":"law","status":"active","topics":["energy"],"docNumber":"Republic Act No. 7156","issuingBody":"Congress of the Philippines","promulgatedDate":"1991-09-12","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1991/ra_7156_1991.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5644-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title. – This Act shall be known as the \" Mini-hydroelectric Power Incentive Act. \" ."}},{"id":"PH-H5644-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. – It is hereby declared the policy of the State to strengthen and enhance the development of the country's indigenous and self-reliant scientific and technological resources and capabilities and their adaptation to the country in order to attain energy self-sufficiency and thereby minimize dependence on outside source of energy supply. In pursuance thereof, it is further declared that mini-hydroelectric power developers shall be granted the necessary incentives and privileges to provide an environment conducive to the development of the country's hydroelectric power resources to their full potential."}},{"id":"PH-H5644-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Declaration of Objectives. – The objectives of the framework being established for the development of mini-hydroelectric power generation are as follows:\n(1) To encourage entrepreneurs to develop potential sites for hydroelectric power existing in their respective localities;\n(2) To encourage entrepreneurs to develop potential sites for hydroelectric power existing in the country by granting the necessary incentives which will provide a reasonable rate of return;\n(3) To facilitate hydroelectric power development by eliminating overlapping jurisdiction of the many government agencies whose permits, licenses, clearances and other similar authorizations issued by various government agencies as presently required for such development, and by vesting in one agency the exclusive authority and responsibility for the development of mini-hydroelectric power;\n(4) To apportion a part of the realty and special privilege taxes and other economic benefits of the hydroelectric power potential to the respective localities where they are established; and\n(5) To provide a contractual framework wherein some stability of conditions can be relied upon for long-term financing purposes."}},{"id":"PH-H5644-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Definition of Terms. – As used in this Act, the following terms shall be understood, applied and construed as follows:\n(1) \"Hydroelectric power\" shall refer to the electric power produced by utilizing the kinetic energy of falling or running water to turn a turbine generator;\n(2) \"Mini-hydroelectric power plant\" shall refer to an electric-power-generating plant which: (a) utilizes the kinetic energy of falling or running water (run-of-river hydro plants) to turn a turbine generator producing electricity; and (c) has an installed capacity of not less than 101 kilowatts nor more than 10,000 kilowatts.\n(3) \"Mini-hydroelectric power development\" shall refer to the construction and installation of a hydroelectric- power-generating plant and its auxiliary facilities such as transmission, substation and machine shop with an installed capacity of not less that 101 kilowatts nor more than 10,000 kilowatts;\n(4) \"Mini-hydroelectric power developer\" or \"developer\" shall refer to any individual, cooperative, corporation or association engaged in the construction and installation of a hydroelectric-power-generating plant with an installed capacity of not less than 101 kilowatts nor more than 10,000 kilowatts;\n(5) \"Domestic use\" shall refer to the utilization of water for drinking, washing, bathing, cooking or other household needs, home gardens and watering of lawns or for domestic animals;\n(6) \"Municipal use\" shall refer to the utilization of water for supplying the water requirements of the community; and\n(7) \"Irrigation use\" shall refer to the utilization of water for producing agricultural crops."}},{"id":"PH-H5644-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Agency in Charge. – The Office of Energy Affairs, hereinafter referred to as the OEA, shall be the sole and exclusive authority responsible for the regulation, promotion and administration of mini-hydroelectric power development and the implementation of the provisions of this Act."}},{"id":"PH-H5644-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Powers and Duties of the OEA. – The OEA shall exercise the following powers and duties:\n(1) Within six (6) months from approval of this Act, promulgate, in consultation with the National Water Resources Board (NWRB), such rules and regulations as may be necessary for the proper implementation and administration of this Act;\n(2) Process and approve applications for mini-hydroelectric power development, imposing such terms and conditions as it may deem necessary to promote the objectives of this Act, subject to the following standards, namely:\n(a) The applicant must be a citizen of the Philippines or a corporation, partnership, association or joint stock company, constituted and organized under the laws of the Philippines, at least sixty percent (60%) of the stock or paid-up capital of which belongs to citizens of the Philippines;\n(b) The applicant must prove that the operation of the proposed mini-hydroelectric project and the authorization to do business will promote the public interest in a proper and suitable manner and, for this purpose, within six (6) months from approval of this Act, formulate, in consultation with the National Economic and Development Authority (NEDA), the National Electrification Administration (NEA), and the Department of Trade and Industry (DTI), standards to measure the technical and financial capability of the developer; and\n(c) The applicant must be financially capable of undertaking the proposed mini-hydroelectric project and meeting the responsibilities incident to its operations;\n(3) Charge reasonable fees in connection with the filing, processing, evaluation, and approval of applications for mini-hydroelectric power development in all suitable sites in the country;\n(4) Exclusive authority to issue permits and licenses relative to mini-hydroelectric power development;\n(5) Require the developer to post a bond or other guarantee of sufficient amount in favor of the Government and with surety or sureties satisfactory to the OEA upon the faithful performance by the contractor of any or all of the obligations under and pursuant to the contract within sixty (60) days after the effective date of the contract; and\n(6) Generally, exercise all the powers necessary or incidental to attain the purposes of this Act and other laws vesting additional powers on the OEA."}},{"id":"PH-H5644-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Sale of Power. – The mini-hydroelectric power developer must first offer to sell electric power to either the National Power Corporation (NPC), franchised private electric utilities or electric cooperatives at a price per kilowatt-hour based on the NPC's or the utility's avoided cost which shall refer to the costs of the affected grids had NPC generated the equivalent electric power itself before disposing the power to third parties. The NPC shall allow the mini-hydroelectric developer to deliver its generated electricity to the developer's customers through existing NPC lines so as to serve such third parties under terms which are to be mutually agreed upon or, if no agreement can be reached, under terms set by the OEA."}},{"id":"PH-H5644-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Non-exclusive Development. – Development of less than fifty percent (50%) of the hydroelectric power potential of the proposed site shall be non-exclusive. The OEA, after a thorough review and evaluation of its technical and economic viability, may grant the development of the site to its full power potential to any qualified developer: provided, that first option shall be given to the original developer: provided, further, that in case the original developer forfeits his option to pursue development of the hydroelectric power resource to its full potential, it shall be reimbursed by the successor-developer of the value of its investment based on the declared value of the development for real estate tax purposes over the immediately preceding three (3) years or, in case the declared value over said period differs, on the average value thereof."}},{"id":"PH-H5644-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Mandatory Restoration Work. – In all cases where the proposed mini-hydroelectric power development entails the closure or stoppage of existing water outlets, passageways, connections, conduits, apertures or the like from the water source, it shall be mandatory for the developer to restore or reengineer such water outlets, passageways, connections, conduits, apertures or the like on its account or expense, and in such manner that existing users or appropriators shall not be permanently deprived of their use or appropriation."}},{"id":"PH-H5644-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Tax Incentives. – Any person, natural or judicial, authorized to engage in mini-hydroelectric power development shall be granted the following tax incentives or privileges:\n(1) Special Privilege Tax Rates. – The tax payable by grantees to develop potential sites for hydroelectric power and to generate, transmit and sell electric power shall be two percent (2%) of their gross receipts from the sale of electric power and from transactions incident to the generation, transmission and sale of electric power. Such privilege tax shall be made payable to the Commissioner of Internal Revenue or his duly authorized representative on or before the 20th day of the month following the end of each calendar or fiscal quarter;\n(2) Tax and Duty-free Importation of Machinery, Equipment and Materials. – Within seven (7) years from the date of award, importation of machinery and equipment, materials and parts shipped with such machinery and equipment including control and communication equipment shall not be subject to tariff duties and value-added tax: provided, that the said machinery, equipment, materials and parts: (a) are not manufactured domestically in reasonable quantity and quality at reasonable prices; (b) are directly and actually needed and will be used exclusively in the construction and impounding of water, transformation into energy, and transmission of electric energy to the point of use; and (c) are covered by shipping documents in the name of the duly registered developer to whom the shipment will be directly delivered by customs authorities: provided, further, that prior approval of the OEA was obtained before the importation of such machinery, equipment, materials and parts was made;\n(3) Tax Credit on Domestic Capital Equipment. – A tax credit equivalent to one hundred percent (100%) of the value of the value-added tax and customs duties that would have been paid on the machinery, equipment, materials and parts had these items been imported shall be given to an awardee-developer who purchases machinery, equipment, materials and parts from a domestic manufacturer: provided, that such machinery, equipment, materials and parts are directly needed and will be used exclusively by the awardee-developer: provided, further, that prior approval by the OEA was obtained by the local manufacturer: provided, finally, that the sale of such machinery, equipment, materials and parts shall be made within seven (7) years from the date of award;\n(4) Special Realty Tax Rates on Equipment and Machinery. – Any provision of the Real Property Tax Code or any other law to the contrary notwithstanding, realty and other taxes on civil works, equipment, machinery and other improvements of a registered mini-hydroelectric power developer shall not exceed two and a half percent (2.5%) of their original cost;\n(5) Value-added Tax Exemption. – Exemption from the ten percent (10%) value-added tax on the gross receipts derived from the sale of electric power whether through the NPC grid or through existing electric utility lines; and\n(6) Income Tax Holiday. – For seven (7) years from the start of commercial operation, a registered mini-hydroelectric power developer shall be fully exempt from income taxes levied by the National Government."}},{"id":"PH-H5644-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Disposition and Allotment of Special Privilege Taxes. – If the mini-hydroelectric power development is located in a city, sixty percent (60%) of the special privilege taxes collected shall accrue to the city and forty percent (40%) to the National Government.\nIf the mini-hydroelectric power development is located in a municipality, thirty percent (30%) of the special privilege taxes collected shall accrue to the municipality, thirty percent (30%) to the province and forty percent (40%) to the National Government."}},{"id":"PH-H5644-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Term of Contract. – The term of contract shall be for a period of twenty-five (25) years extendible for another twenty-five (25) years under the same original terms and conditions: provided, that said awardee has complied faithfully with all terms and conditions of the award."}},{"id":"PH-H5644-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Official Development Assistance. – The provision of Executive Order No. 230 of 1986, on the power of the NEDA Board, and rules and regulations governing the evaluation and authorization for the availment of Official Development Assistance notwithstanding, the privatization of the mini-hydroelectric power plants as provided for in this Act shall be eligible for foreign loans and grants without further evaluation by the NEDA Board, subject to Section 21, Article XII of the Constitution."}},{"id":"PH-H5644-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Reporting Requirements. – The OEA shall submit an annual report to the Congress of the Philippines with respect to the implementation of this Act."}},{"id":"PH-H5644-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Repealing Clause. – All laws, decrees, executive orders, rules and regulations, or parts thereof, inconsistent with this Act are hereby repealed, amended or modified accordingly."}},{"id":"PH-H5644-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Effectivity. – This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p80","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"Mini-hydroelectric Power Incentive Act","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5645"] = {"id":"PH-H5645","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1991/ra_7157_1991.html","fetchedAt":"2026-10-06","articleCount":91,"structureMode":"ARTICLE","title":{"zh":"1991 年菲律宾外交公务法","en":"Philippine Foreign Service Act of 1991","orig":"Philippine Foreign Service Act of 1991 An Act Revising Republic Act No. 708, as Amended"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7157","issuingBody":"Congress of the Philippines","promulgatedDate":"1991-09-19","completenessNote":"全文，共 91 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1991/ra_7157_1991.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5645-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title. – This Act shall be known as the \" Philippine Foreign Service Act of 1991. \""}},{"id":"PH-H5645-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Table of Contents. – The table of contents of this Act is as follows:\nTABLE OF CONTENTS\nSection 1 – Title\nSection 2 – Table of Contents\nSection 3 – Declaration of Policy\nSection 4 – Objective\nSection 5 – Definition of Terms\nSection 6 – Undersecretaries\nSection 7 – Categories of Personnel\nSection 8 – Designation of Foreign Service Officers in the Foreign Service\nSection 9 – Designations of Foreign Service Officers in the Home Office\nSection 10 – Foreign Service Staff Personnel\nSection 11 – Staffing Pattern and Appointments\nSection 12 – Establishment of Foreign Service Posts\nSection 13 – Promotion of Philippines Arts and Culture Part A. Foreign Service Officers\nSection 14 – Initial Appointment of Foreign Service Officers\nSection 15 – Internship Program\nSection 16 – Ambassadorial Appointments\nSection 17 – Heads of Diplomatic and Permanent Missions\nSection 18 – Reinstatement of Foreign Service Officers Part B. Service Staff Officers and Employees\nSection 19 – Appointments\nSection 20 – Civil Service Eligibility Part C. Provisions of General Application to All Officers\nSection 21 – Philippine Citizenship and Permanent Residency\nSection 22 – Auditing Requirements\nSection 23 – Compulsory Retirement Part D. Alien or Locally Hired Employees\nSection 24 – Appointments and Transfers Part E. Honorary Consuls\nSection 25 – Appointments Part A. Foreign Service Officers\nSection 26 – Foreign Service Officers Promotion List\nSection 27 – Cumulative Number of Years of Service in Each Class\nSection 28 – Examination for Promotion\nSection 29 – Determination of Seniority\nSection 30 – Lateral Entry Part B. Foreign Service Staff Officers and Employees\nSection 31 – Foreign Service Staff Officers and Employees Promotion List\nSection 32 – Senior Staff Officers Part C. Provisions of General Application to All Officers and Employees\nSection 33 – Performance Evaluation System\nSection 34 – Effects of Promotions\nSection 35 – Auditing Requirements\nSection 36 – Initial Service in the Home Office\nSection 37 – Tour of Duty\nSection 38 – Rotation Plan\nSection 39 – Security Clearance\nSection 40 – Regular Attaches\nSection 41 – Service Attaches and Representatives of Other Departments\nSection 42 – Appointment\nSection 43 – Relationship Between the Chief of Mission and Service Attaches\nSection 44 – Relationship Between the Principal Officer and Representative\nSection 45 – Inter-department Committee\nSection 46 – Composition\nSection 47 – Functions\nSection 48 – Qualifications of Applicants\nSection 49 – Staff\nSection 50 – Composition\nSection 51 – Functions\nSection 52 – Prohibitions\nSection 53 – Disqualifications\nSection 54 – Disciplinary Actions\nSection 55 – Separation from the Service\nSection 56 – Composition\nSection 57 – Functions\nSection 58 – Operations\nSection 59 – Performance Report\nSection 60 – Foreign Information Council\nSection 61 - Salary Rates\nSection 62 - Membership in the Government Service Insurance System Part A. Allowances\nSection 63 – System of Allowances\nSection 64 – Rates and Policies on Allowances\nSection 65 – Living Quarters Allowance\nSection 66 – Overseas Allowance\nSection 67 – Adjustment in the Overseas Allowance\nSection 68 – Family Allowance\nSection 69 – Post Allowance\nSection 70 – Representation Allowance\nSection 71 – Clothing Allowance\nSection 72 – Education Allowance\nSection 73 – Medical Allowance\nSection 74 – Relocation Allowance Part B. Per Diems\nSection 75 – Persons Entitled to Per Diems\nSection 76 – Service Allowance in Lieu of Per Diems\nSection 77 – Computation Part C. Travel Expenses\nSection 78 – Class of Transportation Part D. Benefits\nSection 79 – General Benefits\nSection 80 – Leaves of Absence\nSection 81 – Exemption from Taxation Part E. Provisions of General Application\nSection 82 – Foreign Service Compensation Plan\nSection 83 – Organization\nSection 84 – Use of Savings\nSection 85 – Pool of Foreign Service Officers\nSection 86 – Passport Revolving Fund\nSection 87 – Rules and Regulations\nSection 88 – Appropriations\nSection 89 – Separability Clause\nSection 90 – Repealing Clause\nSection 91 – Effectivity Clause GENERAL PROVISIONS"}},{"id":"PH-H5645-A3","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"TITLE I"},"text":{"en":"Declaration of Policy. – The State shall pursue an independent foreign policy. In its relations with other states, the paramount consideration shall be national sovereignty, territorial integrity, national interest, and the right to self-determination."}},{"id":"PH-H5645-A4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"TITLE I"},"text":{"en":"Objective. – The main objective of this Act is to reorganize and strengthen the Philippine Foreign Service in order to:\n(a) Upgrade the qualifications of the Career Foreign Service Corps and thereby enable its officers and employees to serve effectively the interests of the Republic of the Philippines abroad;\n(b) Strengthen the capability of the Career Foreign Service Corps to conduct studies, analyses and evaluation of events, both domestic and international, that will serve as guidelines for achieving an independent foreign policy for the country;\n(c) Ensure broad representation of the Philippine society in the foreign service and, further, to ensure equal opportunities in the enlistment and recruitment of officers and employees taking into account the ethnic composition of the country;\n(d) Institute improvements in the selection and training of personnel so that only competent persons of good moral character are recruited in the Service;\n(e) Provide that promotions in the Service shall be on the basis of merit;\n(f) Guarantee permanence or security of tenure of the career personnel of the Service during good behavior and satisfactory performance of duty;\n(g) Provide suitable salaries, allowances and benefits that will attract personnel from all walks of Philippine life and to appoint persons to the highest positions in the Service solely on the basis of merit and demonstrated capability in the promotion of national interests;\n(h) Provide a comprehensive and flexible framework for the administration of the foreign service consistent with modern practices in this field; and\n(i) Consolidate into one act all provisions of the law relating to the administration of the foreign service.\nIn pursuance of the foregoing objective, the principle of nondiscrimination with respect to sex, creed, language, ethnic identity and religion shall be strictly enforced."}},{"id":"PH-H5645-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"TITLE I"},"text":{"en":"Definition of Terms. – When used in this Act, the term:\n(a) \" Government \" means the Government of the Philippines;\n(b) \" Constitution \" means the 1987 Constitution of the Philippines;\n(c) \" President \" means the President of the Philippines;\n(d) \" Department \" means the Department of Foreign Affairs;\n(e) \" Institute \" means the Foreign Service Institute;\n(f) \" Secretary \" means the Secretary of Foreign Affairs;\n(g) \" Undersecretary \" means the Undersecretary of Foreign Affairs;\n(h) \" Government agency \" means any executive branch of the Philippine Government, or any corporation owned or controlled by the Government of the Philippines;\n(i) \" Service \" means the Foreign Service of the Philippines which includes all officers and employees of the Department of Foreign Affairs in the home office and/or foreign service;\n(j) \" Home office \" means the Department of Foreign Affairs and its offices in the Philippines;\n(k) \" Post \" means all Philippine embassies, missions, consulates general and other foreign service establishments maintained by the Department of Foreign Affairs;\n(l) \" Chief of mission \" means the head of an embassy or other diplomatic missions of the Philippines, or any person appointed by the President to such position, whether serving in the home office or foreign service; and\n(m) \" Principal officer \" means the head of a consulate or consulate general of the Philippines."}},{"id":"PH-H5645-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"TITLE I"},"text":{"en":"Undersecretaries. – Upon recommendation of the Secretary, the President shall appoint three (3) undersecretaries to advise and assist the Secretary in the formulation and implementation of the Department objectives and policies, and to coordinate and oversee the operational activities of the Department of Foreign Affairs.\nThe Secretary shall designate one (1) of the undersecretaries in his absence."}},{"id":"PH-H5645-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"TITLE I"},"text":{"en":"Categories of Personnel. – The Service shall consist of the following categories of officers and employees:\n(a) Chiefs of Mission, Class I and II;\n(b) Career Ministries;\n(c) Foreign Service Officers, Class I, II, III, and IV;\n(d) Foreign Service Staff Officers, Class I, II, III and IV;\n(e) Foreign Service Staff Employees, Class I, II, and III;\n(f) Alien or locally hired employees; and\n(g) Honorary Consuls."}},{"id":"PH-H5645-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"TITLE I"},"text":{"en":"Designation of Foreign Officers in the Foreign Service. – In the Service, foreign, service officers shall be commissioned as diplomatic or consular officers, or both, and all the official acts of these officers shall be performed under such commissions. Diplomatic and consular titles shall be coterminous with the assignment at the post.\nA chief of mission shall be assigned as ambassador extraordinary and plenipotentiary to head a diplomatic mission, or as deputy head of mission or as consul general to head a consular establishment.\nA career minister shall be assigned as career minister in a diplomatic mission or as consul general to head a consular establishment.\nA foreign service officer, class I, shall be assigned as first secretary in a diplomatic mission or consul in a consular establishment.\nA foreign service officer, class II, shall be assigned as second secretary in a diplomatic mission or consul in a consular establishment.\nA foreign service officer, class III, shall be assigned as third secretary in a diplomatic mission or vice-consul in a consular establishment.\nA foreign service officer, class IV, shall be assigned as third secretary in a diplomatic mission or vice-consul in a consular establishment.\nIn a diplomatic post where there is a consular section, foreign service officers may be designated as both diplomatic and consular officers."}},{"id":"PH-H5645-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"TITLE I"},"text":{"en":"Designations of Foreign Service Officers in the Home Office. – A chief of mission shall be designated by the Secretary as assistant secretary when assigned to head any of the eleven (11) principal offices of the Department. These offices are: Office of American Affairs; Office of Asia and Pacific Affairs; Office of European Affairs; Office of Middle East and African Affairs; Office of Administration, Protocol and Personnel Services; Office of Fiscal Management; Office of ASEAN Affairs ; Office of United Nations and International Organizations; Office of Consular Affairs; Office of Legal Affairs; and Office of Policy Planning and Coordination. The Secretary is hereby authorized to review and realign periodically the principal offices of the Department in order to effectively meet the requirements of the Service.\nThe Director of the Foreign Service Institute shall be also have the title of assistant secretary.\nChiefs of mission designated as assistant secretaries shall retain their items as chiefs of mission. The post of assistant secretary shall be reserved for career chiefs of mission: provided, however, that all incumbent assistant secretaries who are non-career officials shall continue to hold office until June 30, 1992 unless sooner removed by the President. Thereafter, only career officials may be appointed assistant secretaries.\nA career minister may be designated as executive director of an office.\nA foreign service officer, class I, may be designated as division director.\nA foreign service officer, class II, may be designated as assistant division director.\nA foreign service officer, class III, may be designated as assistant division director.\nA foreign service officer, class IV, may be designated as assistant division director.\nA foreign service officer in any class, including chiefs of mission and career ministers, may be designated as special assistant to the Secretary or the Undersecretary.\nA foreign service officer below the rank of the chief of mission may be designated as principal assistant in any office.\nAny assignment in the home office requiring a rank higher than the actual rank of the officer assigned shall be in an acting capacity."}},{"id":"PH-H5645-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"TITLE I"},"text":{"en":"Foreign Service Staff Personnel. – There shall be a Service Staff Corps to provide the skills, technical assistance and support services in the home office and the foreign service."}},{"id":"PH-H5645-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"TITLE I"},"text":{"en":"Staffing Pattern and Appointments. – The Department shall maintain a permanent staffing pattern for the home office and for each post in the foreign service which shall enumerate a definite number of position items in the budget of the Department for all categories of officers and employees: provided, that the staffing pattern may be modified by the Secretary when necessitated by the opening of new posts in its foreign service or new offices in the home office as may be required by a reorganization of the Department approved by the President: provided, further, that the modification shall be incorporated in the budget. The number of appointments in all categories of positions shall strictly conform to the staffing pattern. Appointments may be made only to specific existing vacant items. Appointments in excess of the number of items in the budget shall be null and void ab initio. An appointment, including the appointment of a non-career officer and initial and promotional appointment of a career officer, shall be valid only if it expressly indicates the specific number of the item in the budget. The appointment must bear the date when it was signed, and the Department must certify that the item is vacant on the specified date."}},{"id":"PH-H5645-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"TITLE I"},"text":{"en":"Establishment of Foreign Service Posts. – The national interest and security shall be the paramount consideration in the establishment of embassies, missions, consulates general and other foreign service establishments maintained by the Department and the priority areas shall be in the countries where the following exist:\n(a) Extending diplomatic, financial, material, humanitarian support and other expressions of solidarity;\n(b) Favorable trade relations and investments currently exist or prospects for trade and investments are favorable;\n(c) A considerable number of Filipino citizens; and\n(d) Adherence to the principle of reciprocity and where such is extended to us.\nThe Secretary shall define the territorial limits of consular jurisdictions."}},{"id":"PH-H5645-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"TITLE I"},"text":{"en":"Promotion of Philippine Arts and Culture. – All Service establishments abroad shall promote Philippine arts and culture, works of art of Filipino artists and Philippine products, including paintings, records, books and literature on Philippine history and culture, which shall be used, displayed and exhibit in these offices. Whenever practicable, Philippine products shall be used to furnish these offices.\nAll gifts given by reason of official and social functions of the foreign service establishments shall be products sourced from the Philippines. The Secretary shall provide in the annual budget of the Department amount as is necessary to cover the cost acquisition, display and exhibition of these works.\nAPPOINTMENTS\nPart. A. Foreign Service Officers"}},{"id":"PH-H5645-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"TITLE II"},"text":{"en":"Initial Appointment of Foreign Service Officers. – Consistent with the goal of developing and strengthening the Career Foreign Service Corps, recruitment into the ranks of foreign service officers shall be exclusively through open competitive examinations to determine the competence, fitness and aptitude of candidates for foreign service work. No person shall be eligible for appointment as a foreign service officers unless he has passed these examinations and demonstrated his loyalty to the Republic of the Philippines and adheres to the principles of the Constitution. The President shall extend initial appointments of foreign service officers exclusively from the list submitted by the Secretary containing the names of those who passed the examinations. Such initial appointments shall be to the lowest rank of foreign service officer, class IV. Any person who, after having passed the examinations, declines to accept an initial appointment as foreign service officer within a period of one (1) year from the date of he was offered the appointment shall be required to take and pass examinations again in order to be eligible for an initial appointment.\nAll appointments of foreign service officers shall be to a class and to not to a particular post."}},{"id":"PH-H5645-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"TITLE II"},"text":{"en":"Internship Program. – Immediately following their appointments as foreign service officers, class IV, the individuals concerned shall undergo a one-year cadetship. The program shall consist of (6) months intensive classroom instructions on all aspects of consular and diplomatic duties and responsibilities. The next six (6) months shall be cover an on-the-job training."}},{"id":"PH-H5645-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"TITLE II"},"text":{"en":"Ambassadorial Appointments. – The President shall nominate and, with the consent of the Commission on Appointments, appoint ambassador extraordinary and plenipotentiary to head embassies and permanent missions. All ambassadorial appointments shall be to a particular post only.\nCareer foreign service officers may be appointed by the President as ambassadors extraordinary and plenipotentiary and shall retain their items originally held prior to their appointments after their tour of duty as ambassadors extraordinary and plenipotentiary: provided, however, that, during their tour of duty as ambassadors extraordinary and plenipotentiary, they shall not be promoted to the next higher rank."}},{"id":"PH-H5645-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"TITLE II"},"text":{"en":"Heads of Diplomatic and Permanent Missions. – In order to strengthen the Career Foreign Service Corps and to enable to it respond to challenges in the field of international relations, the President shall be guided, as much as possible, by the principle that a majority of diplomatic and permanent missions shall be headed by career ambassadors."}},{"id":"PH-H5645-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"TITLE II"},"text":{"en":"Reinstatement of Foreign Service Officers. – The President may, upon recommendation of the Secretary, reappoint to the Service a former foreign service officer who has served continuously for at least two (2) years in the Department, who has been separated from the Service by reason of appointment or election to some other position in the government service. The same privilege shall apply to a former foreign service officer who has been separated from the Service by reason of appointment to the United Nations or other reorganized regional or international organizations and who has served continuously in said regional or international body for at least two (2) years up to the time of reappointment. The Secretary shall, taking into consideration the qualifications and experiences of the candidate of reappointment and the rank of his contemporaries in the Service, recommend the class to which the candidate shall be reappointed. Such reappointment shall be availed of only once and be subject to confirmation by the Commission on Appointments."}},{"id":"PH-H5645-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"PART  B. Foreign Staff Officers and Employees"},"text":{"en":"Appointments. – The shall appoint all foreign service staff officers and foreign service staff employees in accordance with the Civil Service rules and regulations. Recruitment on the foreign service staff officer level shall be made through a competitive examination open to personnel of the Department and outsiders, the successful candidates of which shall be certified by the Board of Foreign Service Examinations for appointment by the Secretary."}},{"id":"PH-H5645-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"PART  B. Foreign Staff Officers and Employees"},"text":{"en":"Civil Service Eligibility. – No person shall be appointed foreign service staff officer or foreign service staff employee unless he is a civil service eligible: provided, however, that priority shall be given to those who passed the examinations for foreign service staff officers and foreign service staff employees conducted by the Board of Foreign Service Examinations."}},{"id":"PH-H5645-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"PART C Provisions of General Application to All Officers"},"text":{"en":"Philippine Citizenship and Permanent Residency. – No person shall be eligible for appointment to a permanent item in the career service to whatever rank or class who is not a citizen and permanent resident of the Philippines at the time of his appointment and, thereafter, for the entire duration of his tenure in the Department: provided, that those who have secured permanent residence status in a foreign country cannot be appointed to a permanent item in the career service unless they have given up said status for at least one (1) year and established permanent residence in the Philippines for at least the same period."}},{"id":"PH-H5645-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"PART C Provisions of General Application to All Officers"},"text":{"en":"Auditing Requirements. – The Department shall be authorize nor shall the Commission on Audit pass in audit payment of salaries and allowances of any person appointed to any position in the Department in violation of the requirements enumerated under Parts A, B and C, Title II of this Act. Any salary and allowance received on the basis of such invalid appointments shall be refunded by the persons so appointed."}},{"id":"PH-H5645-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"PART C Provisions of General Application to All Officers"},"text":{"en":"Compulsory Retirements. – All officers and employees of the Department who have reached the age of sixty-five (65) shall be compulsorily and automatically retired from the Service: provided, however, that all incumbent non-career chiefs of mission who are seventy (70) years old and above shall continue to hold office until June 30, 1992 unless sooner removed by the appointing authority. Non-career appointees who shall serve beyond the age of sixty-five (65) years shall be entitled to retirement benefits."}},{"id":"PH-H5645-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"PART D Alien or Locally Hired Employees"},"text":{"en":"Appointments and Transfers. – The Secretary may authorize chiefs of mission or principal officers to appoint alien or locally hired employees for their respective embassies and consulates: provided, that Filipino citizens shall be given preference. Such employees, however, may not be transferred to another country but may be assigned from one office to another within the same country where originally appointed at the discretion of the chief of mission concerned."}},{"id":"PH-H5645-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"PART  E. Honorary Consuls"},"text":{"en":"Appointments. – The Secretary may appoint honorary consuls in areas where there are no Philippine embassies or consulates, under such regulations as may be prescribed by the Department. Honorary consuls shall be appointed from among qualified private persons preferably of Philippine citizenship to perform certain consular functions on non-career basis. Honorary consuls are not given fixed salaries or allowances.\nPROMOTIONS"}},{"id":"PH-H5645-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"PART  A. Foreign Service Officers"},"text":{"en":"Foreign Service Officers Promotion List. – On the basis of recommendations made by the Board of Foreign Service Administration, the Secretary shall, from time to time, furnish the President with the names of career service officers qualified for appointment to the next higher class, from foreign service officer, class IV, to chief of mission, class I."}},{"id":"PH-H5645-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"PART  A. Foreign Service Officers"},"text":{"en":"Cumulative Number of Years of Service in Each Class. – The Secretary may determine a standard performance based on merit for each class which must be met before any foreign service officer may become eligible for promotion to a higher class. All foreign service officers shall be required to render satisfactory service continuously for a minimum period of three (3) years in each class and for the total cumulative period computed at three (3) years for each class before they become eligible for promotion to the next higher class: provided, however, that foreign service officers who have shown exceptional and meritorious qualities and have rendered exemplary service may be promoted to the next higher rank as an exception hereof."}},{"id":"PH-H5645-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"PART  A. Foreign Service Officers"},"text":{"en":"Examination for Promotion. – Foreign service officers, class, I, who have completed at least two (2) years of \"very satisfactory\" service in the rank are required to pass an examination for promotion to the administered by the Board of Foreign Service Examinations before they shall be eligible for appointment as career ministers."}},{"id":"PH-H5645-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"PART  A. Foreign Service Officers"},"text":{"en":"Determination of Seniority. – Career ministers and chiefs of mission, class I and II, shall not have grades classifications within each class. Seniority shall be determined by their original dates of appointment as career ministers, as well as the dates of their original entry into the Department."}},{"id":"PH-H5645-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"en":"PART  A. Foreign Service Officers"},"text":{"en":"Lateral Entry. – Lateral entry into the Career Foreign Service Corps shall be permitted for those individuals who have successfully passed at the written and oral examinations conducted by the Board of Foreign Service Examinations but at the time when offered an appointment as foreign service officer, class IV, decided to join another government agency: provided, however, that:\n(a) The duration from initial offer of appointment and his request for lateral entry in the Career Foreign Service Corps shall not exceed more than six (6) years;\n(b) That he has very satisfactorily served another government agency for the same duration;\n(c) His reappointment shall be confirmed by the Commission on Appointments; and\n(d) The rank to which he is being reappointed shall not be higher than that of his successful co-examinees who have joined by the Service immediately after being offered the appointment."}},{"id":"PH-H5645-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"en":"PART  B. Foreign Service Staff Officers and Employees"},"text":{"en":"Foreign Service Staff Officers and Employees Promotion List. – On the basis of recommendations made by the Office of Personnel and Management Services, the Board of Foreign Service Administration shall, from time to time, furnish the Secretary with the names of career foreign service staff officers and foreign service staff employees qualified for appointment to the next higher class from foreign service staff employee, class II, to foreign service staff officer, class I. All foreign service staff personnel shall be required to render satisfactory service continuously for a maximum period of two (2) years in each class and for the total cumulative period computed at two (2) years in each class before they become eligible for promotion to the next higher class."}},{"id":"PH-H5645-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"en":"PART  B. Foreign Service Staff Officers and Employees"},"text":{"en":"Senior Staff Officers. – Personnel who have attained the highest rank in the staff service and have rendered service in that position continuously for a period of five (5) years and a cumulative period totaling at least fifteen (15) years shall be eligible for promotion in salary and allowances equivalent to the maximum salary and allowances of foreign service officer, class IV: provided, that they shall have consistently received a minimum efficiency rating of \"very satisfactory\" throughout those years of service.\nThereafter, for every additional six (6) years of continuous very satisfactory service, they shall be eligible for promotion in salary and shall allowances equivalent to the minimum salary and allowances of the next higher class of foreign service officer."}},{"id":"PH-H5645-A33","no":33,"noLabel":{"en":"Section 33."},"chapter":{"en":"PART C Provisions of General Application to All Officers and Employees"},"text":{"en":"Performance Evaluation System. – The Secretary shall prescribe a performance evaluation system which shall be the basis for the periodic review of performance of all officers and employees. Particularly, the performance evaluation system shall address itself to the weeding-out of incompetent and sterile career personnel and abusive political appointees."}},{"id":"PH-H5645-A34","no":34,"noLabel":{"en":"Section 34."},"chapter":{"en":"PART C Provisions of General Application to All Officers and Employees"},"text":{"en":"Effects of Promotions. – Promotions made in violation of this Act shall be null and void and thus have no force and effect. The persons so promoted under such circumstances are deemed to have retained their old positions. Any salaries and allowances derived from such promotions shall be subject to the provisions of the following sections."}},{"id":"PH-H5645-A35","no":35,"noLabel":{"en":"Section 35."},"chapter":{"en":"PART C Provisions of General Application to All Officers and Employees"},"text":{"en":"Auditing Requirements. – The Department Fiscal Officer shall not authorize nor shall the Commission on Audit pass in audit the payment of salaries and allowances of any person promoted to any position in the Department in violation of the requirements enumerated under Parts A and B, Title III of this Act. Any salaries and allowances received on the basis of such invalid promotions shall be refunded by the persons so promoted.\nASSIGNMENTS AND TRANSFERS"}},{"id":"PH-H5645-A36","no":36,"noLabel":{"en":"Section 36."},"chapter":{"en":"TITLE IV"},"text":{"en":"Initial Service in the Home Office. – Except for non-career chiefs mission appointed by the President, no member of the Career Foreign Service Corps shall be assigned to any post abroad unless he has rendered continuous and satisfactory service in the home office for at least three (3) years including undertaking an intensive familiarization program of Philippine conditions, urban and rural."}},{"id":"PH-H5645-A37","no":37,"noLabel":{"en":"Section 37."},"chapter":{"en":"TITLE IV"},"text":{"en":"Tour of Duty. – Subject to the exigencies of the service;\n(a) The tour of duty of a foreign service officer at any post shall be six (6) years commencing on the date of his arrival at the post, after which he shall serve in the home office;\n(b) The tour of duty of a foreign service officer or employee at any post shall be for a period of six (6) years commencing on the date of his arrival at the post, after which he shall serve in the home office;\n(c) No foreign service, office, foreign service staff officer or employee shall be assigned abroad after return to the home office or recall unless he has rendered continuous and satisfactory service in the home office for at least three (3) years;\n(d) Any foreign service officer, foreign service staff officer or employee on assignment abroad may be recalled to the home or dismissed from the Service at any time for unsatisfactory performance as certified by the head of post and approved by the Secretary upon recommendation of the Board of Foreign Service Administration; and\n(e) No foreign service officer may serve for more than three (3) consecutive years in home office, except when designated as Secretary, Undersecretary or Assistant Secretary."}},{"id":"PH-H5645-A38","no":38,"noLabel":{"en":"Section 38."},"chapter":{"en":"TITLE IV"},"text":{"en":"Rotation Plan. – The Secretary shall established a system of assignment and transfer to ensure that all qualified career service officers and employees in the Department shall alternately serve in the diplomatic and consular post in different regions of the world and in the home office. Excluded from the rotation plan are those in the non-career service and those in the career service appointed to such positions which, in the judgment of the Secretary, require a posting of longer duration in the home office.\nFor this purpose, Manila shall be considered a separate post. The Secretary shall promulgate the guidelines including the financial implications of the provision.\nThe assignments and transfers of personnel shall follow a regular rotation plan and no officer or employee shall be assigned to a post for less than two (2) or more than six (6) years. For the purpose of assignments, the home office shall be considered as another post. In no case shall an officer or employee be assigned to the same post for two (2) consecutive tours of duty unless he shall have served in other posts located in other regions where there are foreign service establishments. Assignments to hardship posts shall not exceed three (3) years.\nAssignments to posts abroad shall take into consideration the particular area of concern that the Government seeks to promote so that only personnel qualified and trained, with a basic knowledge of the language, shall be assigned to said country."}},{"id":"PH-H5645-A39","no":39,"noLabel":{"en":"Section 39."},"chapter":{"en":"TITLE IV"},"text":{"en":"Security Clearance. – To ensure immediately availability of officers and employees foreign assignments and appointments, the Secretary shall periodically submit the names and personal histories of newly recruited officers and employees to the appropriate government security agency or agencies for clearance. The security agency or agencies concerned shall act with dispatch on requests for clearance and failure to act on said requests within forty-five (45) days shall be deemed a grant thereof.\nATTACHES"}},{"id":"PH-H5645-A40","no":40,"noLabel":{"en":"Section 40."},"chapter":{"en":"TITLE V"},"text":{"en":"Regular Attaches. – The Secretary shall designate attaches to various posts abroad from the rank of foreign service officer and foreign service staff officer."}},{"id":"PH-H5645-A41","no":41,"noLabel":{"en":"Section 41."},"chapter":{"en":"TITLE V"},"text":{"en":"Service Attaches and Representatives of Other Departments. – The assignment and accreditation of personnel in any department, bureau or agency of the Government as service attaches to embassies or representatives to consulates shall have the prior clearance of the Secretary who shall take into account the specific places where the services of these officers or employees from other the government agencies are needed, except trade attaches who shall be assigned and accredited only after consultation with the Trade Secretary."}},{"id":"PH-H5645-A42","no":42,"noLabel":{"en":"Section 42."},"chapter":{"en":"TITLE V"},"text":{"en":"Appointment. – The authority to appoint service attaches and representatives shall be vested in the department secretary sending said officers and employees. A department or agency shall only one (1) service attaché or representative accredited to one (1) post, except military and commercial attaches."}},{"id":"PH-H5645-A43","no":43,"noLabel":{"en":"Section 43."},"chapter":{"en":"TITLE V"},"text":{"en":"Relationship Between the Chief of Mission and Service Attaches. – The chief mission shall be responsible for the conduct of the affairs of the Government at his diplomatic post and all service attaches of the other departments and agencies of the Government shall, during their tour of duty abroad, be under his immediate control and administrative supervision. Said attaches shall course through the chiefs of mission all reports, documents and materials to their respective home agencies in the Philippines and shall transmit the same through the diplomatic pouch, the costs of which shall, however, be shouldered by their respective offices. The service attaché shall clear with the chief of mission concerned all their public pronouncements at the post."}},{"id":"PH-H5645-A44","no":44,"noLabel":{"en":"Section 44."},"chapter":{"en":"TITLE V"},"text":{"en":"Relationship Between the Principal Officer and Representative. – The relationship between the principal officer at a consular post and the representative assigned thereto shall be the same as the relationship between the chief of mission and the service attaché at diplomatic post, under Section 43, Title V of this Act."}},{"id":"PH-H5645-A45","no":45,"noLabel":{"en":"Section 45."},"chapter":{"en":"TITLE V"},"text":{"en":"Inter-department Committee. – There shall be an Inter-department Committee to be composed of an Undersecretaries or their counterparts from other departments and government agencies with service attaches or representatives abroad, as members. The Committee shall prescribe a uniform set or rules and regulations for attaché and representative services and shall meet regularly to assess the performance of their respective officers and employees abroad with the view to improve their output as well as maintaining and strengthening efficient and harmonious relationships with the chief of mission and principal officer and other government workers in the embassy or consulate where they are assigned.\nBOARD OF FOREIGN SERVICE EXAMINATIONS"}},{"id":"PH-H5645-A46","no":46,"noLabel":{"en":"Section 46."},"chapter":{"en":"TITLE VI"},"text":{"en":"Composition. – There shall be a Board of Foreign Service Examinations to be composed of an Undersecretary of Foreign Affairs, as Chairman, the Head of Personnel and Administrative Services and a Commissioner of the Civil Service Commission, as members, and the Director of the Foreign Service Institute, as Board Secretary."}},{"id":"PH-H5645-A47","no":47,"noLabel":{"en":"Section 47."},"chapter":{"en":"TITLE VI"},"text":{"en":"Functions. – The Board shall conduct examinations and nominate to the President, through the Secretary, successful candidates for appointments as foreign service officers, class VI. It shall receive and screen applications for the foreign service officer (FSO) examinations.\nThe Board shall prescribe the academic training and practical experiences required of candidates and determine the subjects on which the written and oral examinations shall be held. The Board shall prepare, conduct and grade the written examinations and certify to the Secretary for oral examinations those candidates who obtained a general average of seventy-five percent (75%) or higher. In the preparation of questions and the grading of examination papers on any subject, the Board may request, through the secretary of the department concerned, the assistance of any competent officer in the government service."}},{"id":"PH-H5645-A48","no":48,"noLabel":{"en":"Section 48."},"chapter":{"en":"TITLE VI"},"text":{"en":"Qualifications of Applicants. – Foreign service officer (FSO) examinations shall be open to those who are citizens and permanent residents of the Philippines. No person, of either sex, married to an alien may take the examinations without the written consent of the Secretary. Applicants must be holders of a four-year bachelor's degree, below thirty-six (36) years old, and physically and psychologically fit: provided, that any person who is holding a position of responsibility in the Department or the Institute for at least two (2) years prior to the date of examination and who is otherwise qualified to take the examinations may do so, regardless of the maximum age limit prescribed."}},{"id":"PH-H5645-A49","no":49,"noLabel":{"en":"Section 49."},"chapter":{"en":"TITLE VI"},"text":{"en":"Staff. – The Secretary shall assign to the Board such officers and employees as may be necessary to assist in the efficient performance of its functions.\nBOARD OF FOREIGN SERVICE ADMINISTRATION"}},{"id":"PH-H5645-A50","no":50,"noLabel":{"en":"Section 50."},"chapter":{"en":"TITLE VII"},"text":{"en":"Composition. – There shall be a Board of Foreign Service Administration to be composed of one (1) of the Undersecretaries, as Chairman, and the two (2) other Undersecretaries and the Assistant Secretaries of the different offices in the Department, including the Director of the Institute, as members."}},{"id":"PH-H5645-A51","no":51,"noLabel":{"en":"Section 51."},"chapter":{"en":"TITLE VII"},"text":{"en":"Functions. – The Board shall make recommendations to the Secretary concerning the functions and operations of the Service, the policies and procedures to govern the selection, assignment, promotion, discipline and separation from the Service of chiefs of mission, career ministers, foreign service officers, foreign service staff officers and foreign service staff employees, and the policies to govern the administration and personnel management of the Service: provided, that the chiefs of mission who are commissioned by the President as ambassadors extraordinary and plenipotentiary shall not be investigated by the Board or separated from the Service unless there is an express written directive from the President. It shall establish the efficiency ratings of service personnel and shall perform such other duties as may be assigned to it by law or regulation, including those that may be issued by the Secretary. It shall consider administrative cases brought against officers and employees who commit offenses against the interest of public service and submit to the Secretary its findings and recommendations.\nThe Board shall keep a lineal roster of all chiefs of mission, career ministers, foreign service officers, foreign service staff officers and foreign service staff employees strictly in the order of their ranks and seniority in each rank or class, based on their respective dates of appointment. In submitting recommendations for promotions to the President, through the Secretary, the Board shall base its recommendations on/the efficiency ratings and seniority of the officers and employees concerned."}},{"id":"PH-H5645-A52","no":52,"noLabel":{"en":"Section 52."},"chapter":{"en":"TITLE VII"},"text":{"en":"Prohibitions. – No member of the Board, while acting as such member, shall intervene in any way, directly or indirectly, in Board deliberations affecting himself or any relative of his within the fourth civil degree either be consanguinity or affinity."}},{"id":"PH-H5645-A53","no":53,"noLabel":{"en":"Section 53."},"chapter":{"en":"TITLE VII"},"text":{"en":"Disqualifications. – The following circumstances shall disqualify any officer or employee from being considered for assignment abroad or promotion:\n(a) Pending criminal case with the Sandiganbayan;\n(b) Lack of required length of service as foreign service officer, as embodied under Section 27, Part A, Title III of this Act, except those who enjoyed merit promotion;\n(c) Below \"very satisfactory\" rating covering the six-month period immediately before the deliberations for assignments or promotions are held; and\n(d) Seeking political interference for his promotion/assignment which weakens the principles of the foreign service."}},{"id":"PH-H5645-A54","no":54,"noLabel":{"en":"Section 54."},"chapter":{"en":"TITLE VII"},"text":{"en":"Disciplinary Actions. – In the investigation of administrative cases against officers and employees of the Department, the applicable rules and regulations and guidelines promulgated by the Civil Service Commission shall be strictly observed.\nNo officer or employee of the Department shall be subjected to disciplinary action or otherwise be removed or separated from the Service except for cause as provided for by law in accordance with requirements of due process.\nDisciplinary action may be taken against an officer or an employee only by the appropriate disciplinary authority, to wit:\n(a) The President for all presidential appointees of the Department, upon the recommendation of the Secretary; and\n(b) The Secretary for all those appointed by him or by his predecessors.\nNo officer or employee of the Department facing administrative charges shall be effectively suspended or otherwise prevented from exercising his normal duties and functions unless so ordered by appropriate disciplinary authority on grounds provided for by law.\nIn the interest of harnessing all the human resources in the Department, no officer or employee shall be \"frozen\" or \"floated\" or otherwise deprived of an assignment, duties or functions appropriate to his rank and position, except for justifiable reasons."}},{"id":"PH-H5645-A55","no":55,"noLabel":{"en":"Section 55."},"chapter":{"en":"TITLE VII"},"text":{"en":"Separation from the Service. – The following shall constitute sufficient bases for separation from the Service of any foreign service officer or employee, of all ranks and classes:\n(a) Voluntary resignation;\n(b) Disloyalty to the Government, unsatisfactory performance of duty, neglect of duty, misconduct, malfeasance, graft, corruption, immoral conduct or gross violation of the Civil Service laws, rules and regulations and reasonable Department rules and regulations;\n(c) Any officer or employee who has been given an \"unsatisfactory\" rating for three (3) consecutive years under the rating system as promulgated by the Secretary in accordance with this Act shall automatically be recommended for separation from the Service;\n(d) Refusal of assignment or recall order without valid justifications.\nAll those found by the Board to be guilty of charges mentioned in paragraph (b) shall be separated from the Service by the President or the Secretary, as the case may be.\nThe rating system mentioned in paragraph (c) shall be based on generally accepted Civil Service rules and regulations including the right of the officer or employee being rated to appeal to higher authorities for what he feels is arbitrary or overly subjective rating;\n(e) With respect to locally or hired or alien employees, the chief of mission or principal officer concerned may separate them from the Service at any time for any cause he may deem sufficient for the purpose, in accordance with local laws and regulations on the matter; and\n(f) Honorary consuls may be separated from the Service by the Secretary at any time and for any cause he may deem for the purpose.\nFOREIGN SERVICE INSTITUTE"}},{"id":"PH-H5645-A56","no":56,"noLabel":{"en":"Section 56."},"chapter":{"en":"TITLE VIII"},"text":{"en":"Composition. – There shall be a Foreign Service Institute, whose board shall be composed of the Secretary, as Chairman, and the Chairman of the Civil Service Commission, the President of the University of the Philippines, the President of the Development Academy of the Philippines, and the Director of the Foreign Service Institute, as members."}},{"id":"PH-H5645-A57","no":57,"noLabel":{"en":"Section 57."},"chapter":{"en":"TITLE VIII"},"text":{"en":"Functions. – The Institute, through its academic, training, research, information, publication, systems development and other programmes, shall serve as the center for the development and professionalization of the career corps of the foreign service of the Department and other government agencies which have officers and employees assigned abroad. It shall maintain a Center of International Relations and Strategic Studies (CIRSS) and shall otherwise function as a research institution on issues and problems with foreign policy implications, global and regional strategies and management of foreign affairs while serving as institutional consultant of the Department on matters related to foreign policies and programmes as well as development management, planning, review and evaluation processes in the Department. The Institute shall, inter alia, pursue a training program for those who are leaving for foreign assignments and for those who are recalled and shall hold seminars, including language courses, to prepare such officers and employees for their new assignments."}},{"id":"PH-H5645-A58","no":58,"noLabel":{"en":"Section 58."},"chapter":{"en":"TITLE VIII"},"text":{"en":"Operations. – The Institute shall continue to operate under its own charter. The Director of the Institute shall be a senior career chief of mission with the title of assistant secretary."}},{"id":"PH-H5645-A59","no":59,"noLabel":{"en":"Section 59."},"chapter":{"en":"TITLE VIII"},"text":{"en":"Performance Report. – The Foreign Service Institute shall submit to the President and to Congress an annual performance report.\nFOREIGN INFORMATION COUNCIL"}},{"id":"PH-H5645-A60","no":60,"noLabel":{"en":"Section 60."},"chapter":{"en":"TITLE IX"},"text":{"en":"Foreign Information Council. – There is hereby created a Foreign Information Council composed of the Secretary of Foreign Affairs, as Chairman, and the Secretaries of Defense, Trade and Industry, Tourism, Labor and Employment, and the Office of the Press Secretary, as members. The Foreign Information Council shall provide policy guidance in the formulation of effective overseas information and communications strategies to ensure better understanding of Filipino values, culture and institutions overseas; an accurate presentation of policies in the Government especially in the fields of trade and investment; and coordination of overseas information programs of various government agencies and other entities.\nSALARIES"}},{"id":"PH-H5645-A61","no":61,"noLabel":{"en":"Section 61."},"chapter":{"en":"TITLE X"},"text":{"en":"Salary Rates. – The President upon recommendation of the Secretary shall recommend to Congress a scale of salaries for officers and employees in the Department and the Institute which shall be subject to periodic review.\nINSURANCE AND RETIREMENT SYSTEM"}},{"id":"PH-H5645-A62","no":62,"noLabel":{"en":"Section 62."},"chapter":{"en":"TITLE XI"},"text":{"en":"Membership in the Government Service Insurance System. – All permanent officers and employees of the Service who are citizens of the Philippines shall have compulsory insurance coverage under the rules and regulations governing the same: provided, however, that the President upon recommendation of the Secretary may, as soon as practicable, submit for enactment by Congress a foreign affairs retirement and disability system, taking into account the difficulties of foreign service personnel in setting aside sufficient savings to take care their eventual retirement in the Philippines due to old age or some other disability, with the increased burden of establishing a home in the Philippines after completion of their tour of duty abroad.\nALLOWANCES, PER DIEMS, TRAVEL EXPENSES AND BENEFITS"}},{"id":"PH-H5645-A63","no":63,"noLabel":{"en":"Section 63."},"chapter":{"en":"PART  A. Allowances"},"text":{"en":"System of Allowances. – The President upon recommendation of the Secretary shall recommend to Congress the establishment of a system of allowances for foreign service personnel which shall be subject to periodic review and shall include the following:\n(a) Overseas allowance. – To adjust take home pay of foreign service personnel for any changes in the cost of living abroad which arise from changes in foreign currency conversion rates, differentials in cost of living between the Philippines and foreign post, and extraordinary and necessary expenses not otherwise compensated for, which are incurred by officers or employees in the foreign service;\n(b) Living quarters allowances. – To enable personnel to whom those are granted to live in a manner benefitting their representative capacity but not purpose of augmenting basic salary;\n(c) Clothing allowance. – To compensate for increased cost of clothing incurred by foreign service personnel assigned to post whose climates are different from that of the Philippines or where unusual circumstances exist;\n(d) Post allowance. – To defray unusual expenses incident to the operation and maintenance of an official residence suitable for the chief diplomatic or consular representative of the Philippines at his post;\n(e) Representation allowance. – The enable chiefs of mission, special envoys, ministers, permanent delegates or representatives to international bodies, principal officers and other ranking diplomatic officers stationed abroad uphold the prestige of the Republic of the Philippines and otherwise to present the country with distinction and dignity;\n(f) Education allowance. – To compensate for additional educational cost incurred by officers and employees assigned abroad for legal dependent children not exceeding three (3) in number who are enrolled in the primary and elementary grades and high school where free public education is absent;\n(g) Medical allowance. – Intended to cover the cost of medical insurance in countries where medical care is unusually expensive, including cost of hospitalization and medical treatment for foreign service personnel and legal dependents living with the officers and employees at the post; and\n(h) Family allowance. – To assist foreign service personnel living with their families at the post of assignment in meeting the incremental expenses arising from foreign assignment computed for the dependent spouse and for unmarried legal minor dependent children not exceeding three (3) in number."}},{"id":"PH-H5645-A64","no":64,"noLabel":{"en":"Section 64."},"chapter":{"en":"PART  A. Allowances"},"text":{"en":"Rates and Policies on Allowances. – The President shall approve, upon recommendation of the Secretary and the Secretary of Budget and Management, rates, indices, maximum allowable amounts and policies on allowances which shall be applicable to all national government employees stationed abroad pursuant to the Foreign Service Decree."}},{"id":"PH-H5645-A65","no":65,"noLabel":{"en":"Section 65."},"chapter":{"en":"PART  A. Allowances"},"text":{"en":"Living Quarters Allowance. – Commutable living quarters allowable shall be granted to officers or employees in the Service assigned aboard who are citizens of the Philippines. Such allowance may cover the rental or quarters including utilities, telephone and other maintenance expenses which may be revised as to amounts not more often than once a year with the approval of the President.\nOn transfer from post, allowances shall cease at the end of the month following departure therefrom. Commutable living quarters allowance shall be granted at a per annum rate and shall be commuted and paid monthly beginning on the first day of the month following the arrival of the payee at his post of assignment: provided, however, that the suitability of said quarters in each post shall be officially certified under oath by the chief of mission or principal officer: provided, further, that the equivalent of said allowance corresponding to the first three (3) months following arrival at post shall be paid immediately upon its accrual. On transfer from post, allowances shall cease at the end of the month following departure therefrom.\nNo living quarters allowance shall be paid to persons occupying government-owned, furnished and heated quarters. No allowance shall be paid for quarters occupied free or under arrangements with other parties permitting direct or indirect gain to the claimant or his family.\nIf a person entitled to living quarters allowance occupies quarters owned by him, his wife or children, he shall be entitled to a quarters allowance equal to fifty percent (50%) of the rental value of the quarters. The chief of mission or principal officer, as the case may be, jointly with the administrative officer shall certify under their official oaths the rental value on the face of the cash voucher.\nLease contracts entered into by any officer or employee assigned abroad should contain a \"Diplomatic Clause\" whereby the tenant should he be reassigned to another post or is recalled to the home office.\nIn case of detail of the officer or employee from his post of assignment (detail to the home office excluded), the quarters allowance shall cease to accrue from the first day of the month following the date of his departure unless it can be shown that the rented quarters used as his residence has been retained at the post of assignment and the rentals thereof are continued, but in no case shall the allowance continue beyond three (3) months without the prior approval of the Secretary. If the officer or employee own the quarters occupied by him, payment of the allowance shall cease immediately unless otherwise authorized by the Secretary.\nIn case officer or employee is on home leave, the allowance shall cease to accrue from the first day of the month following the date of his departure from his post, unless it can be shown that the rented quarters used as residence has been retained at the post of assignment, but in no case shall the allowance continue beyond three (3) months. This regulation shall apply also in cases where extended leaves of absence are taken in any other emergency cases necessitating departure from the post of assignment unless otherwise authorized by the President upon recommendation of the Secretary. If the officer or employee owns the house occupied by him, the allowance shall be discontinued."}},{"id":"PH-H5645-A66","no":66,"noLabel":{"en":"Section 66."},"chapter":{"en":"PART  A. Allowances"},"text":{"en":"Overseas Allowances. – Overseas allowance shall be given to any officer or employee in the Service assigned abroad, who is a citizen of the Philippines, whenever the following conditions exist, and certified by the Secretary:\n(a) That the cost of living at a post abroad is proportionately so high that an allowance is necessary to enable an officer or employee at such post to carry out his work efficiently;\n(b) That extraordinary and necessary expenses, not otherwise compensated for, are incurred by an officer or employee of the foreign service incident to the establishment of his post of assignment; and\n(c) That an allowance is necessary to assist an officer or employee of the foreign service who is compelled by reason of dangerous, notably unhealthy or excessively adverse living conditions at his post abroad or for the convenience of the Government to meet the additional expenses of maintaining an assignment."}},{"id":"PH-H5645-A67","no":67,"noLabel":{"en":"Section 67."},"chapter":{"en":"PART  A. Allowances"},"text":{"en":"Adjustment in the Overseas Allowance. – A permanent committee is hereby created, consisting of the Secretary as Chairman and, as members, the Secretary of Budget and Management and the Governor of the Central Bank, with the objectives of compiling information on foreign currency exchange rate fluctuations and price levels abroad and of recommending periodic adjustments in the amount of overseas allowance to foreign service personnel of the National Government in each foreign service post: provided, that official United Nations consumer indices shall be specifically considered in the committee's evaluation: provided, further, that the adjustments shall be made not more often than once a year: provided, furthermore, that the implementation shall be subject to the availability of funds."}},{"id":"PH-H5645-A68","no":68,"noLabel":{"en":"Section 68."},"chapter":{"en":"PART  A. Allowances"},"text":{"en":"Family allowance. – A commutable family allowance shall be granted to any officer or employee assigned abroad who is a citizen of the Philippines and who is living with his family at the post of assignment, to a dependent spouse and to each unmarried legal minor dependent child but not exceeding three (3) in number. If both husband and wife are in the Service and assigned in the same post, only one (1) of them may claim the allowance.\nNo family allowance for spouse shall be payable if the claimant is a widow/widower or separated or when his/her spouse is gainfully employed. However, if the claimant has minor unmarried dependent children to support, he/she shall be entitled to the family allowance of each child but not exceeding three (3) in number.\nUnmarried children living with the officer or employee who are mentally and physically retarded regardless of age and who are incapable of supporting themselves shall, for family allowance purposes, be considered as minor children.\nSubject to the prior approval of the Department Head, full family allowances may be paid to any claimant.\n(a) Who is compelled by reason of dangerous, notably unhealthy, or excessively adverse living conditions, or by other unavoidable circumstances, like lack of educational facilities for his children at his post of assignment, which renders its inadvisable for any or all the members of his family to live with him at his post; or\n(b) Who, for the convenience of the Government, must live alone without any or all the members of his family at his post of assignment.\nAll other meritorious cases by considered by the Department Head as the circumstances and the exigencies of the Service may warrant."}},{"id":"PH-H5645-A69","no":69,"noLabel":{"en":"Section 69."},"chapter":{"en":"PART  A. Allowances"},"text":{"en":"Post Allowance. – An allotment of fund may be made by the Secretary to any post to defray the unusual expenses incident to the operation and maintenance of an official residence suitable for the chief diplomatic or consular representative of the Philippines at the post.\nPost allowance shall be granted at a per annum rate for fiscal years beginning on the first day of the month following arrival thereat. Post allowance shall be payable only when the officer is on duty status at his station. For the purpose of this allowance, such officer shall be deemed on duty status at his station;\n(a) When on temporary duty even outside by the city or place where he maintains regular office but remains within the territorial limits of his diplomatic or consular jurisdiction;\n(b) When temporary duty outside his diplomatic or consular jurisdiction for consecutive period not exceeding sixty (60) days during he shall be paid the post allowance. Beyond sixty (60) days, no allowance shall be paid except as specially approved by the President. Payment of the post allowance shall be resumed only on the date of the actual return within diplomatic or consular jurisdiction; or\n(c) When he is on leave of absence with fully pay provided the leave is spent within the territorial jurisdictions of his post. No allowance shall be paid if the officer goes on leave with pay outside the territorial jurisdiction of his post.\nThe territorial limits, in case of concurrent jurisdiction, shall extend to all countries or areas comprised in the concurrent office.\nNo post allowance shall be paid if the officer lives in a hotel as his residence."}},{"id":"PH-H5645-A70","no":70,"noLabel":{"en":"Section 70."},"chapter":{"en":"PART  A. Allowances"},"text":{"en":"Representation Allowance. – Representation allowance may be granted to chiefs of mission, special envoys, ministers, permanent delegates or representative to international bodies, principal officers, and other ranking diplomatic officers stationed abroad in order to enable such officers to uphold the prestige of the Republic of the Philippines, to represent their country with dignity, distinction and to carry out their functions more effectively.\nRepresentations allowances shall be expended only for purposes which are of a public character, beneficial to the interests of the public service, and connected with the exercise of the functions of the Government in relation to the conduct of foreign affairs. They may be expended for necessary entertainment, charitable contributions, memorials, flowers, gifts, club initiation fee and membership dues, and the like. The officer to whom the allowance is granted may disburse any portion of it to cover necessary entertainment by his subordinates to accomplish certain task assigned to them.\nExpenses charged to representation allowance must be supported by proper receipts or vouchers if the individual amount of expenditures exceeds Fifty United States dollars (U.S. $50.00) or its equivalent. Where expenses are incurred for entertainment, the voucher must be accomplished by a statement of the officer concerned or by such proofs as may be shown that the expenses have been made in the public interest.\nShould special entertaining be necessary because of formal visits of the Philippine dignitaries traveling on diplomatic or special passports, the Department Head shall be informed in advance thereof and specific request for funds thereforee be made. No such expenses shall be incurred without the prior authorization of the Department Head.\nMaximum allowable amounts shall be established for each category of representation allowance in accordance with Section 64, Part A, Title XII of this Act."}},{"id":"PH-H5645-A71","no":71,"noLabel":{"en":"Section 71."},"chapter":{"en":"PART  A. Allowances"},"text":{"en":"Clothing Allowance. – Clothing allowance may be granted to officers and employees of the Service assigned abroad who are citizens of the Philippines not more often than once every twelve (12) months, the rates of which shall be determined by the Department."}},{"id":"PH-H5645-A72","no":72,"noLabel":{"en":"Section 72."},"chapter":{"en":"PART  A. Allowances"},"text":{"en":"Education Allowances. – Education allowance may be granted to officers and employees assigned abroad who are citizens of the Philippines of their legal dependent children not exceeding three (3) in number, who are enrolled in the primary, elementary and high school levels. This grant shall not, however, be payable in respect to post where free educational is provided for.\nThe allowance may be granted as reimbursement of actual costs within such maximum amounts as shall be fixed by the Secretary and the Department of Budget and Management, with the approval of the President, per school year of each child subject to presentation of receipts and other evidence of payment of matriculation, tuition, books and other school fees."}},{"id":"PH-H5645-A73","no":73,"noLabel":{"en":"Section 73."},"chapter":{"en":"PART  A. Allowances"},"text":{"en":"Medical Allowance. – Foreign service personnel may be required by the Department concerned to subscribe to a medical insurance scheme available in the host country. Twenty-five percent (25%) of the corresponding premiums shall be payable by the personnel concerned and seventy-five (75) thereof shall be borne by the Government as its contribution.\nIn the event of illness or injury requiring hospitalization of a foreign service personnel, not as a result of vicious habits, intemperance or misconduct or his part, the Government shall reimburse the cost of medical expenses in accordance with the regulations prescribed in the first paragraph of the section: provided, that no medical insurance scheme is available in the post of assignment.\nThe medical expenses shall cover the cost of hospitalization and/or payment of the services of the attending physician, including travel expenses to and from the hospital or clinic, and such other incidental expenses as may be incurred in connection with such hospitalization treatment but not to exceed the amount as fixed pursuant to Section 64 hereof.\nOnly legal dependents of those mentioned in the first paragraph hereof living with the officer or employee at the post shall be entitled to the medical allowance."}},{"id":"PH-H5645-A74","no":74,"noLabel":{"en":"Section 74."},"chapter":{"en":"PART  A. Allowances"},"text":{"en":"Relocation Allowance. – Any office or employee of the Service on assignment or from a post shall be entitled to an allowance for packing at destination furniture and other household goods and personal effects in such amounts and within such limitations as may be prescribed pursuant to Section 64, Part A, Title XII of this Act.\nThis allowances entitles the officer or employee to choose either of the following:\n(a) Ship his household goods and personal effects to the authorized destination at the expense of the Government in accordance with the rules regulations as the Secretary and the Secretary of the Department of Budget and Management may prescribe with the approval of the President; or\n(b) Receive the money plus equivalent to fifty percent (50%) of the estimated cost or packing and shipping of the household goods and personal effects to the authorized destination as computed in letter (a) above."}},{"id":"PH-H5645-A75","no":75,"noLabel":{"en":"Section 75."},"chapter":{"en":"PART  B. Per Diems"},"text":{"en":"Persons Entitled to Per Diems. – All officers and employees of the Service on travel status or on assignment out of their regular post shall be entitled to per diems at such amounts as the Secretary with the approval of the President, may prescribe by regulations."}},{"id":"PH-H5645-A76","no":76,"noLabel":{"en":"Section 76."},"chapter":{"en":"PART  B. Per Diems"},"text":{"en":"Service Allowance in Lieu of Per Diems. – When meals are included in the fare of any carrier, no per diems shall be allowed but service allowance equal to fifty percent (50%) of the per diems authorized shall be payable to the traveler."}},{"id":"PH-H5645-A77","no":77,"noLabel":{"en":"Section 77."},"chapter":{"en":"PART  B. Per Diems"},"text":{"en":"Computation. – Per diems and service allowance shall be computed by dividing the day into quarters beginning at midnight. No per diems will be paid for fractions of a quarter. Local time will be used computing per diems, no consideration being given to time lost or gained by traveling through the time zones. All vouchers for per diems must clearly state the exact hour, local time of entry into each area, as well as the time of original departure from the Philippines or post of duty and arrival at new post or return to the Philippines or other post of permanent duty."}},{"id":"PH-H5645-A78","no":78,"noLabel":{"en":"Section 78."},"chapter":{"en":"PART C Travel Expenses"},"text":{"en":"Class of Transportation. – All officers and employees of the Service shall be entitled to economy class transportation by any usual means of public transportation for themselves, their spouse and dependent minor children, not exceeding three (3) in number, whenever such travel is duly authorized by the Secretary: provided, that this restriction shall not apply to the children in excess of three (3) of any officer or employee already in the service of the Department on December 31, 1950. For local travel away from post but within the district of assignment by any member of the staff, authority for such travel may be granted by the principal officer present at the post.\nWhenever deemed necessary due to high cost of living or unhealthy conditions obtaining at the post of assignment abroad, the spouse of any officer or employee in the foreign service and their children, including their reasonable personal effects may, upon request to the parties concerned, be allowed economy class return transportation to Manila at the expense of the Government. This privilege may be extended to unmarried dependent children of the officer or employee concerned until they become of age (21 years old) while living with their parents abroad.\nThis privilege may be granted only once. Any member of the family (wife, husband or unmarried children) of any officer or employee who returns to the Philippines in the manner provided in the second paragraph hereof and who may want to rejoin later the officer or employee abroad either at the post where such member of the family came, or at another post in the same country to which the officer or employee has been subsequently transferred, shall be not be allowed official transportation for his proposed trip. Should such member rejoin the parent-officer or employee abroad, even at his own expenses, such member shall not be entitled thereafter to official return transportation to the Philippines."}},{"id":"PH-H5645-A79","no":79,"noLabel":{"en":"Section 79."},"chapter":{"en":"PART D Benefits"},"text":{"en":"General Benefits. – The Secretary shall extend benefits including medical services and comprehensive health insurance coverage for home office personnel and their families."}},{"id":"PH-H5645-A80","no":80,"noLabel":{"en":"Section 80."},"chapter":{"en":"PART D Benefits"},"text":{"en":"Leaves of Absence. – Kinds of Leave – All officers and employees of the Service who are citizens of the Philippines shall be entitled to thirty (30) days vacation leave and thirty (30) days sick leave with full pay for each year of service. Alien or locally hired employees shall be entitled to such vacation and sick leaves as they might be entitled to if they were employed by their own government in the place where the post is situated, but in no case should such leave exceed thirty (30) days vacation leave and thirty (30) days sick leave for each year of service.\nAccumulation of Leaves – Under such regulations as the Secretary shall prescribe with the approval of the President, all officers and employees of the Service shall be entitled to the accumulation of any vacation or sick leave not taken in any year, in accordance with Civil Service rules and regulations and subject to the exigencies of the Service.\nHome Leave – The Secretary may order to the Philippines for home leave any officer or employee who is a citizen of the Philippines, together with his family, upon completion of three (3) years of continuous and satisfactory service abroad or as soon as possible thereafter. The time actually and necessarily spent in going to and from the Philippines shall not be counted as leave. While on leave in the Philippines, such officer or employee may be required to serve in a position of comparable importance in the Department, but the period of such assignment shall not be counted as leave: provided, that the period of this home leave shall not exceed thirty (30) working days."}},{"id":"PH-H5645-A81","no":81,"noLabel":{"en":"Section 81."},"chapter":{"en":"PART D Benefits"},"text":{"en":"Exemption from Taxation. – All allowances, per diems, benefits, and the like received by officers and employees of the Service in consideration of their service while on assignment abroad, except their basic salaries, shall be exempt from the Philippine income tax.\nAny officer or employee returning from a regular assignment abroad for reassignment to the home office or who dies, resigns, or is retired from the Service shall be exempt from the payment of all duties and taxes on his personal and household effects, including one (1) used motor car duly registered in his name for at least six (6) months: provided, however, that the exemption shall apply only to the value of motor car and to the aggregate assessed value of said personal and household effects, the latter not to exceed fifty percent (50%) of the total amount received by such officer or employee in salary and allowances during his latest assignment abroad but not to exceed four (4) years: provided, further, that this exception shall not be availed of more often than once every four (4) years."}},{"id":"PH-H5645-A82","no":82,"noLabel":{"en":"Section 82."},"chapter":{"en":"PART  E. Provisions of General Application"},"text":{"en":"Foreign Service Compensation Plan. – The provisions of Executive Order No. 495 and Presidential Decree No. 1285, both issued in 1978, as well as the provisions of other acts, decrees, orders, letters of implementation, letters of instruction, and rules and regulations which are not inconsistent with the aforementioned order and decree shall apply with respect to the foreign service compensation plan of the Department. For purposes of implementing this title the home office shall be considered a separate post.\nFINAL PROVISIONS"}},{"id":"PH-H5645-A83","no":83,"noLabel":{"en":"Section 83."},"chapter":{"en":"TITLE XIII"},"text":{"en":"Organization. – The Secretary shall effect the organization of the Department and the foreign service in accordance with the provisions of this Act and, for this purpose, he is hereby authorized to allot the funds provided for the Department in the General Appropriations Act."}},{"id":"PH-H5645-A84","no":84,"noLabel":{"en":"Section 84."},"chapter":{"en":"TITLE XIII"},"text":{"en":"Use of Savings. – The Secretary is hereby authorized the use of any savings in the appropriation for the Department for the payment of:\n(a) Expenses for the evacuation or repatriation to the Philippines, when necessary due to emergency, of members of the household of the personnel of any diplomatic or consular establishment as well as transportation of their personal effects;\n(b) Actual return passage by the most direct and economical means of transportation and the cost of shipment of the household effects to Manila of any officer or employee in the foreign service, including the immediate dependent members of his family, who resigns or is separated from the Service for cause;\n(c) The cost of preparing and transporting the remains of an officer or employee who is a citizen of the Philippines and the immediate members of his family who may die abroad or while on travel status; or\n(d) Contingent and unforeseen expenses that may arise in connection with the operation of the foreign service."}},{"id":"PH-H5645-A85","no":85,"noLabel":{"en":"Section 85."},"chapter":{"en":"TITLE XIII"},"text":{"en":"Pool of Foreign Service Officers. – In all appropriations acts providing funds for the operation and maintenance of the Department, the position of foreign service officers, including those who may serve in the home office, shall be in a pool grouped according to their classes with their salaries and allowances indicated in one lump-sum for each class, leaving to the head office the discretion to assign or commission those officers whenever their services may be utilized to advantage, subject to the limitations provided by law."}},{"id":"PH-H5645-A86","no":86,"noLabel":{"en":"Section 86."},"chapter":{"en":"TITLE XIII"},"text":{"en":"Passport Revolving Fund. – The Department is hereby authorized to charge a service fee of One hundred Philippine pesos (P100.00) or such appropriate amount as may be prescribed by the Secretary for each service rendered to private individuals relating to the processing and issuance of passports beyond regular office hours.\nThe fees received by the Department shall constitute a revolving fund to be called the Passport Revolving Fund which shall be directly utilized by the Department for the improvement of its passporting and consular services and other Department services.\nThe setting up, use and disbursement of funds shall be subject to review, accounting and auditing rules and regulations of the Commission on Audit.\nThe Fund shall be subject to an annual review by Congress."}},{"id":"PH-H5645-A87","no":87,"noLabel":{"en":"Section 87."},"chapter":{"en":"TITLE XIII"},"text":{"en":"Rules and Regulations. – The Secretary may issue such rules and regulations as may be necessary to implement the provisions of this Act as well as the provisions of acts, decrees and orders which are not inconsistent with this Act, including the formulation of a code of conduct and decorum for all officers and employees of the Department and other government attaches serving with the Department.\nThe Secretary shall review periodically all existing administrative rules and regulations embodied in the Foreign Service Code of 1983 with the end in view of updating such rules and regulations which may be inconsistent with national interest. Special reference is made to rules and regulations in the issuance of passports and visas which may need to be revised and updated."}},{"id":"PH-H5645-A88","no":88,"noLabel":{"en":"Section 88."},"chapter":{"en":"TITLE XIII"},"text":{"en":"Appropriations. – There is hereby authorized to be appropriated from the National Treasury such amounts as may be necessary to provide for any salary and allowances of ambassadors extraordinary and plenipotentiary appointed by the President outside of the Career Foreign Service Corps. Thereafter, such amounts shall be incorporated in the General Appropriations Act under the annual budget of the Department of Foreign Affairs."}},{"id":"PH-H5645-A89","no":89,"noLabel":{"en":"Section 89."},"chapter":{"en":"TITLE XIII"},"text":{"en":"Separability Clause. – If any section or any part of this Act shall be declared unconstitutional by competent authority, the remaining sections or parts of this Act shall not thereby be affected."}},{"id":"PH-H5645-A90","no":90,"noLabel":{"en":"Section 90."},"chapter":{"en":"TITLE XIII"},"text":{"en":"Repealing Clause. – The Foreign Service Act of 1952 (Republic Act No. 708, as amended), all other acts, presidential decrees, executive orders, letters of implementation, letters of instruction, and rules and regulations which are inconsistent with any of the provisions of this Act are hereby repealed or amended accordingly."}},{"id":"PH-H5645-A91","no":91,"noLabel":{"en":"Section 91."},"chapter":{"en":"TITLE XIII"},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days after the completion of its publication in the Official Gazette or in any newspaper of general circulation."}}],"pack":"ph-p80"};
  FT["PH-H5646"] = {"id":"PH-H5646","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1991/ra_7158_1991.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":"授予 Rinconada 广播公司在菲律宾为商业目的建设、安装、运营和维护无线电广播站与电视站并为其他目的法案","en":"An Act Granting the Rinconada Broadcasting Corporation a Franchise to Construct, Install, Operate and Maintain for Commercial Purposes Radio Broadcasting Stations and Television Stations in the Philippines and for Other Purposes","orig":"An Act Granting the Rinconada Broadcasting Corporation a Franchise to Construct, Install, Operate and Maintain for Commercial Purposes Radio Broadcasting Stations and Television Stations in the Philippines and for Other Purposes"},"level":"law","status":"active","topics":["investment","trade"],"docNumber":"Republic Act No. 7158","issuingBody":"Congress of the Philippines","promulgatedDate":"1991-09-28","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1991/ra_7158_1991.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5646-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise – Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Rinconada Broadcasting Corporation, hereunder referred to as the grantee, its successors or assigns a franchise to construct, install, operate and maintain for commercial purposes and in the public interest radio broadcasting stations and television stations in the Philippines with the corresponding technological auxiliaries or facilities, special broadcast and other program and distribution services and relay stations, and to install radio communication facilities for the grantees private use in its broadcast services."}},{"id":"PH-H5646-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities – The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in minimum interference on the wavelengths or frequencies of the other existing stations or stations which may be established by law without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H5646-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission – The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the radio/television spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H5646-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public – The grantee shall provide reasonable public service time to enable the Government, through the said broadcasting stations, to reach the population on important public issues; provide at all times sound and balanced programming; promote public participation such as in community programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public interest, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H5646-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government – A special right is hereby reserved to the President of the Philippines, in times of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the stations of the grantee, to temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or to authorize the temporary use and operation thereof by any agency of the Government, upon due compensation to the grantee, for the use of said stations during the period when they shall be so operating."}},{"id":"PH-H5646-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise – This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act, unless sooner revoked or cancelled. In the event the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H5646-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance – Acceptance of this franchise shall be given in writing within sixty (60) days after the effectivity of this Act. The grantee shall construct, complete and operate the television stations within four (4) years from the date of its acceptance in writing of this franchise. Refusal or failure to accept the franchise or to operate within the prescribed period shall render the franchise void."}},{"id":"PH-H5646-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tax Provisions – The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to five percent (5%) of all gross receipts of the radio/television business transacted under this franchise by the grantee, its successors, or assigns and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof: Provided , That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and play the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H5646-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Public Offering – In compliance with the constitutional mandate to democratize ownership of public utilities, the herein grantee shall make offering through the stock exchanges of at least thirty percent (30%) of its common stocks within a period of three (3) years from the date of effectivity of this Act: Provided , that no single person or entity shall be allowed to own more than five percent (5%) of the stock offerings."}},{"id":"PH-H5646-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments – The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H5646-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc – The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise nor the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor shall the controlling interest in the grantee be transferred to any such private person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H5646-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Separability Clause – If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H5646-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Repealability Clause – This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H5646-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Effectivity Clause – This Act shall take effect upon its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p80","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Rinconada Broadcasting Corporation a Franchise to Construct, Install, Operate and Maintain for Commercial Purposes Radio Broadcasting Stations and Television Stations in the Philippines and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5647"] = {"id":"PH-H5647","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1991/ra_7159_1991.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"在南三宝颜省设立 Guipos 市镇的法案","en":"An Act Creating the Municipality of Guipos in the Province of Zamboanga del Sur","orig":"An Act Creating the Municipality of Guipos in the Province of Zamboanga del Sur"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7159","issuingBody":"Congress of the Philippines","promulgatedDate":"1991-10-07","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1991/ra_7159_1991.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5647-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Barangays Guipos, Katipunan, Bagong Oroquieta, and Dalapang, all in the Municipality of San Miguel; Barangays Datagan, Dagohoy, Balongating, Baguitan, Magting, Sikatuna, Dacsol, Guling, and Canunan, all in the Municipality of Dumalinao; Barangays Lintum, Singclot and Litan, all in the Municipality of Dinas; and Barangay Regla in the Municipality of San Pablo, all in the Province of Zamboanga del Sur, are hereby separated from their respective municipalities and constituted into a distinct and independent Municipality of Guipos."}},{"id":"PH-H5647-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The technical description of the new municipality shall be as follows:\nLINE\nBEARING\nDISTANCE 1–2 123º15’3\"E–7º47’42\"N 5,350M 2–3 123º18’33\"E–7º47’30\"N following the downstream course of the Dinas River until it reaches point 3 3–4 123º20’26\"E–7º45’59\"N 4,000M 4–5 123º22’36\"E–7º42’30\"N 4,600M 5–6 123º22’36\"E–7º42’30\"N following the downstream course of the Dinas River until it reaches point 6 6–7 123º21’27\"E–7º41’38\"N following the upstream course of the creek until it reaches point 7 7–8 123º20’50\"E–7º42’15\"N 2,200M 8–9 123º20’00\"E–7º43’08\"N 2,200M 9–10 123º19’06\"E–7º42’39\"N 1,840M 10–11 123º17’10\"E–7º42’39\"N 3,550M 11–1 123º15’40\"E–7º46’03\"N 3,000M."}},{"id":"PH-H5647-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The seat of government of the new municipality shall be in Barangay Guipos."}},{"id":"PH-H5647-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"After ratification by a majority of the votes cast in a plebiscite to be conducted in the areas affected within a period of one hundred eighty (180) days from the approval of this Act, the mayor, vice-mayor and members of the sangguniang bayan of the new municipality shall be elected in the next regular election of local officials. The new municipality shall be considered duly organized upon the assumption of office of the first set of elected officials."}},{"id":"PH-H5647-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Commission on Elections shall conduct and supervise the plebiscite. The expenses in holding the plebiscite shall be taken out of the Contingent Fund under the current fiscal year appropriations."}},{"id":"PH-H5647-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p80","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Municipality of Guipos in the Province of Zamboanga del Sur","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5648"] = {"id":"PH-H5648","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1991/ra_7160_1991.html","fetchedAt":"2026-10-06","articleCount":331,"structureMode":"ARTICLE","title":{"zh":"1991 年地方政府法典","en":"Local Government Code of 1991","orig":"Local Government Code of 1991 An Act Providing for a Local Government Code of 1991"},"level":"code","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 7160","issuingBody":"Congress of the Philippines","promulgatedDate":"1991-10-10","completenessNote":"全文，共 331 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1991/ra_7160_1991.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 536 条，缺 219、220、221、222、223、224、225、226、227、228、229、230、231、232、233、234、235、236、237、238、239、240、241、242、243、244、245、246、247、248、249、250、251、252、253、254、255、256、257、258 等）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5648-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title. - This Act shall be known and cited as the \"Local Government Code of 1991\"."}},{"id":"PH-H5648-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. -\n(a) It is hereby declared the policy of the State that the territorial and political subdivisions of the State shall enjoy genuine and meaningful local autonomy to enable them to attain their fullest development as self-reliant communities and make them more effective partners in the attainment of national goals. Toward this end, the State shall provide for a more responsive and accountable local government structure instituted through a system of decentralization whereby local government units shall be given more powers, authority, responsibilities, and resources. The process of decentralization shall proceed from the national government to the local government units.\n(b) It is also the policy of the State to ensure the accountability of local government units through the institution of effective mechanisms of recall, initiative and referendum.\n(c) It is likewise the policy of the State to require all national agencies and offices to conduct periodic consultations with appropriate local government units, nongovernmental and people's organizations, and other concerned sectors of the community before any project or program is implemented in their respective jurisdictions."}},{"id":"PH-H5648-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Operative Principles of Decentralization. - The formulation and implementation of policies and measures on local autonomy shall be guided by the following operative principles:\n(a) There shall be an effective allocation among the different local government units of their respective powers, functions, responsibilities, and resources;\n(b) There shall be established in every local government unit an accountable, efficient, and dynamic organizational structure and operating mechanism that will meet the priority needs and service requirements of its communities;\n(c) Subject to civil service law, rules and regulations, local officials and employees paid wholly or mainly from local funds shall be appointed or removed, according to merit and fitness, by the appropriate appointing authority;\n(d) The vesting of duty, responsibility, and accountability in local government units shall be accompanied with provision for reasonably adequate resources to discharge their powers and effectively carry out their functions: hence, they shall have the power to create and broaden their own sources of revenue and the right to a just share in national taxes and an equitable share in the proceeds of the utilization and development of the national wealth within their respective areas;\n(e) Provinces with respect to component cities and municipalities, and cities and municipalities with respect to component barangays, shall ensure that the acts of their component units are within the scope of their prescribed powers and functions;\n(f) Local government units may group themselves, consolidate or coordinate their efforts, services, and resources commonly beneficial to them;\n(g) The capabilities of local government units, especially the municipalities and barangays, shall be enhanced by providing them with opportunities to participate actively in the implementation of national programs and projects;\n(h) There shall be a continuing mechanism to enhance local autonomy not only by legislative enabling acts but also by administrative and organizational reforms;\n(i) Local government units shall share with the national government the responsibility in the management and maintenance of ecological balance within their territorial jurisdiction, subject to the provisions of this Code and national policies;\n(j) Effective mechanisms for ensuring the accountability of local government units to their respective constituents shall be strengthened in order to upgrade continually the quality of local leadership;\n(k) The realization of local autonomy shall be facilitated through improved coordination of national government policies and programs an extension of adequate technical and material assistance to less developed and deserving local government units;\n(l) The participation of the private sector in local governance, particularly in the delivery of basic services, shall be encouraged to ensure the viability of local autonomy as an alternative strategy for sustainable development; and\n(m) The national government shall ensure that decentralization contributes to the continuing improvement of the performance of local government units and the quality of community life."}},{"id":"PH-H5648-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Scope of Application. - This Code shall apply to all provinces, cities, municipalities, barangays, and other political subdivisions as may be created by law, and, to the extent herein provided, to officials, offices, or agencies of the national government."}},{"id":"PH-H5648-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Rules of Interpretation. - In the interpretation of the provisions of this Code, the following rules shall apply:\n(a) Any provision on a power of a local government unit shall be liberally interpreted in its favor, and in case of doubt, any question thereon shall be resolved in favor of devolution of powers and of the lower local government unit. Any fair and reasonable doubt as to the existence of the power shall be interpreted in favor of the local government unit concerned;\n(b) In case of doubt, any tax ordinance or revenue measure shall be construed strictly against the local government unit enacting it, and liberally in favor of the taxpayer. Any tax exemption, incentive or relief granted by any local government unit pursuant to the provisions of this Code shall be construed strictly against the person claiming it.\n(c) The general welfare provisions in this Code shall be liberally interpreted to give more powers to local government units in accelerating economic development and upgrading the quality of life for the people in the community;\n(d) Rights and obligations existing on the date of effectivity of this Code and arising out of contracts or any other source of presentation involving a local government unit shall be governed by the original terms and conditions of said contracts or the law in force at the time such rights were vested; and\n(e) In the resolution of controversies arising under this Code where no legal provision or jurisprudence applies, resort may be had to the customs and traditions in the place where the controversies take place.\nGeneral Powers and Attributes of Local Government Units"}},{"id":"PH-H5648-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Authority to Create Local Government Units. - A local government unit may be created, divided, merged, abolished, or its boundaries substantially altered either by law enacted by Congress in the case of a province, city, municipality, or any other political subdivision, or by ordinance passed by the sangguniang panlalawigan or sangguniang panlungsod concerned in the case of a barangay located within its territorial jurisdiction, subject to such limitations and requirements prescribed in this Code."}},{"id":"PH-H5648-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Creation and Conversion. - As a general rule, the creation of a local government unit or its conversion from one level to another level shall be based on verifiable indicators of viability and projected capacity to provide services, to wit:\n(a) Income. - It must be sufficient, based on acceptable standards, to provide for all essential government facilities and services and special functions commensurate with the size of its population, as expected of the local government unit concerned;\n(b) Population. - It shall be determined as the total number of inhabitants within the territorial jurisdiction of the local government unit concerned; and\n(c) Land Area. - It must be contiguous, unless it comprises two or more islands or is separated by a local government unit independent of the others; properly identified by metes and bounds with technical descriptions; and sufficient to provide for such basic services and facilities to meet the requirements of its populace.\nCompliance with the foregoing indicators shall be attested to by the Department of Finance (DOF), the National Statistics Office (NSO), and the Lands Management Bureau (LMB) of the Department of Environment and Natural Resources (DENR)."}},{"id":"PH-H5648-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Division and Merger. - Division and merger of existing local government units shall comply with the same requirements herein prescribed for their creation: Provided, however, That such division shall not reduce the income, population, or land area of the local government unit or units concerned to less than the minimum requirements prescribed in this Code: Provided, further, That the income classification of the original local government unit or units shall not fall below its current classification prior to such division.\nThe income classification of local government units shall be updated within six (6) months from the effectivity of this Code to reflect the changes in their financial position resulting from the increased revenues as provided herein."}},{"id":"PH-H5648-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Abolition of Local Government Units. - A local government unit may be abolished when its income, population, or land area has been irreversibly reduced to less than the minimum standards prescribed for its creation under Book III of this Code, as certified by the national agencies mentioned in Section 7 hereof to Congress or to the sangguniang concerned, as the case may be.\nThe law or ordinance abolishing a local government unit shall specify the province, city, municipality, or barangay with which the local government unit sought to be abolished will be incorporated or merged."}},{"id":"PH-H5648-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Plebiscite Requirement. - No creation, division, merger, abolition, or substantial alteration of boundaries of local government units shall take effect unless approved by a majority of the votes cast in a plebiscite called for the purpose in the political unit or units directly affected. Said plebiscite shall be conducted by the Commission on Elections (COMELEC) within one hundred twenty (120) days from the date of effectivity of the law or ordinance effecting such action, unless said law or ordinance fixes another date."}},{"id":"PH-H5648-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Selection and Transfer of Local Government Site, Offices and Facilities. -\n(a) The law or ordinance creating or merging local government units shall specify the seat of government from where governmental and corporate services shall be delivered. In selecting said site, factors relating to geographical centrality, accessibility, availability of transportation and communication facilities, drainage and sanitation, development and economic progress, and other relevant considerations shall be taken into account.\n(b) When conditions and developments in the local government unit concerned have significantly changed subsequent to the establishment of the seat of government, its sanggunian may, after public hearing and by a vote of two-thirds (2/3) of all its members, transfer the same to a site better suited to its needs. Provided, however, That no such transfer shall be made outside the territorial boundaries of the local government unit concerned.\nThe old site, together with the improvements thereon, may be disposed of by the sale or lease or converted to such other use as the sangguniang concerned may deem beneficial to the local government unit concerned and its inhabitants.\n(c) Local government offices and facilities shall not be transferred, relocated, or converted to other uses unless public hearings are first conducted for the purpose and the concurrence of the majority of all the members of the sanggunian concerned is obtained."}},{"id":"PH-H5648-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Government Centers. - Provinces, cities, and municipalities shall endeavor to establish a government center where offices, agencies, or branches of the national government, local government units, or government-owned or controlled corporations may, as far as practicable, be located. In designating such a center, the local government unit concerned shall take into account the existing facilities of national and local agencies and offices which may serve as the government center as contemplated under this Section. The national government, local government unit or government-owned or controlled corporation concerned shall bear the expenses for the construction of its buildings and facilities in the government center."}},{"id":"PH-H5648-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Naming of Local Government Units and Public Places, Streets and Structures. -\n(a) The sangguniang panlalawigan may, in consultation with the Philippine Historical Commission (PHC), change the name of the following within its territorial jurisdiction:\n(1) Component cities and municipalities, upon the recommendation of the sanggunian concerned;\n(2) Provincial roads, avenues, boulevards, thoroughfares, and bridges;\n(3) Public vocational or technical schools and other post-secondary and tertiary schools;\n(4) Provincial hospitals, health centers, and other health facilities; and\n(5) Any other public place or building owned by the provincial government.\n(b) The sanggunian of highly urbanized cities and of component cities whose charters prohibit their voters from voting for provincial elective officials, hereinafter referred to in this Code as independent component cities, may, in consultation with the Philippine Historical Commission, change the name of the following within its territorial jurisdiction:\n(1) City barangays, upon the recommendation of the sangguniang barangay concerned;\n(2) City roads, avenues, boulevards, thoroughfares, and bridges;\n(3) Public elementary, secondary and vocational or technical schools, community colleges and non-chartered colleges;\n(4) City hospitals, health centers and other health facilities; and\n(5) Any other public place or building owned by the city government.\n(c) The sanggunians of component cities and municipalities may, in consultation with the Philippine Historical Commission, change the name of the following within its territorial jurisdiction:\n(1) City and municipal barangays, upon recommendation of the sangguniang barangay concerned;\n(2) City, municipal and barangay roads, avenues, boulevards, thoroughfares, and bridges;\n(3) City and municipal public elementary, secondary and vocational or technical schools, post- secondary and other tertiary schools;\n(4) City and municipal hospitals, health centers and other health facilities; and\n(5) Any other public place or building owned by the municipal government.\n(d) None of the foregoing local government units, institutions, places, or buildings shall be named after a living person, nor may a change of name be made unless for a justifiable reason and, in any case, not oftener than once every ten (10) years. The name of a local government unit or a public place, street or structure with historical, cultural, or ethnic significance shall not be changed, unless by a unanimous vote of the sanggunian concerned and in consultation with the PHC.\n(e) A change of name of a public school shall be made only upon the recommendation of the local school board concerned.\n(f) A change of name of public hospitals, health centers, and other health facilities shall be made only upon the recommendation of the local health board concerned.\n(g) The change of name of any local government unit shall be effective only upon ratification in a plebiscite conducted for the purpose in the political unit directly affected.\n(h) In any change of name, the Office of the President, the representative of the legislative district concerned, and the Bureau of Posts shall be notified."}},{"id":"PH-H5648-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Beginning of Corporate Existence. - When a new local government unit is created, its corporate existence shall commence upon the election and qualification of its chief executive and a majority of the members of its sanggunian, unless some other time is fixed therefor by the law or ordinance creating it."}},{"id":"PH-H5648-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Political and Corporate Nature of Local Government Units. - Every local government unit created or recognized under this Code is a body politic and corporate endowed with powers to be exercised by it in conformity with law. As such, it shall exercise powers as a political subdivision of the national government and as a corporate entity representing the inhabitants of its territory."}},{"id":"PH-H5648-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"CHAPTER II"},"text":{"en":"General Welfare. - Every local government unit shall exercise the powers expressly granted, those necessarily implied therefrom, as well as powers necessary, appropriate, or incidental for its efficient and effective governance, and those which are essential to the promotion of the general welfare. Within their respective territorial jurisdictions, local government units shall ensure and support, among other things, the preservation and enrichment of culture, promote health and safety, enhance the right of the people to a balanced ecology, encourage and support the development of appropriate and self-reliant scientific and technological capabilities, improve public morals, enhance economic prosperity and social justice, promote full employment among their residents, maintain peace and order, and preserve the comfort and convenience of their inhabitants."}},{"id":"PH-H5648-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Basic Services and Facilities. -\n(a) Local government units shall endeavor to be self-reliant and shall continue exercising the powers and discharging the duties and functions currently vested upon them. They shall also discharge the functions and responsibilities of national agencies and offices devolved to them pursuant to this Code. Local government units shall likewise exercise such other powers and discharge such other functions and responsibilities as are necessary, appropriate, or incidental to efficient and effective provisions of the basic services and facilities enumerated herein.\n(b) Such basic services and facilities include, but are not limited to, the following:\n(1) For Barangay:\n(i) Agricultural support services which include planting materials distribution system and operation of farm produce collection and buying stations;\n(ii) Health and social welfare services which include maintenance of barangay health center and day-care center;\n(iii) Services and facilities related to general hygiene and sanitation, beautification, and solid waste collection;\n(iv) Maintenance of katarungang pambarangay;\n(v) Maintenance of barangay roads and bridges and water supply systems;\n(vi) Infrastructure facilities such as multi-purpose hall, multipurpose pavement, plaza, sports center, and other similar facilities;\n(vii) Information and reading center; and\n(viii) Satellite or public market, where viable;\n(2) For a Municipality:\n(i) Extension and on-site research services and facilities related to agriculture and fishery activities which include dispersal of livestock and poultry, fingerlings, and other seedling materials for aquaculture; palay, corn, and vegetable seed farms; medicinal plant gardens; fruit tree, coconut, and other kinds of seedling nurseries; demonstration farms; quality control of copra and improvement and development of local distribution channels, preferably through cooperatives; interbarangay irrigation system; water and soil resource utilization and conservation projects; and enforcement of fishery laws in municipal waters including the conservation of mangroves;\n(ii) Pursuant to national policies and subject to supervision, control and review of the DENR, implementation of community-based forestry projects which include integrated social forestry programs and similar projects; management and control of communal forests with an area not exceeding fifty (50) square kilometers; establishment of tree parks, greenbelts, and similar forest development projects;\n(iii) Subject to the provisions of Title Five, Book I of this Code, health services which include the implementation of programs and projects on primary health care, maternal and child care, and communicable and non-communicable disease control services, access to secondary and tertiary health services; purchase of medicines, medical supplies, and equipment needed to carry out the services herein enumerated;\n(iv) Social welfare services which include programs and projects on child and youth welfare, family and community welfare, women's welfare, welfare of the elderly and disabled persons; community-based rehabilitation programs for vagrants, beggars, street children, scavengers, juvenile delinquents, and victims of drug abuse; livelihood and other pro-poor projects; nutrition services; and family planning services;\n(v) Information services which include investments and job placement information systems, tax and marketing information systems, and maintenance of a public library;\n(vi) Solid waste disposal system or environmental management system and services or facilities related to general hygiene and sanitation;\n(vii) Municipal buildings, cultural centers, public parks including freedom parks, playgrounds, and other sports facilities and equipment, and other similar facilities;\n(viii) Infrastructure facilities intended primarily to service the needs of the residents of the municipality and which are funded out of municipal funds including but not limited to, municipal roads and bridges; school buildings and other facilities for public elementary and secondary schools; clinics, health centers and other health facilities necessary to carry out health services; communal irrigation, small water impounding projects and other similar projects; fish ports; artesian wells, spring development, rainwater collectors and water supply systems; seawalls, dikes, drainage and sewerage, and flood control; traffic signals and road signs; and similar facilities;\n(ix) Public markets, slaughterhouses and other municipal enterprises;\n(x) Public cemetery;\n(xi) Tourism facilities and other tourist attractions, including the acquisition of equipment, regulation and supervision of business concessions, and security services for such facilities; and\n(xii) Sites for police and fire stations and substations and municipal jail;\n(3) For a Province:\n(i) Agricultural extension and on-site research services and facilities which include the prevention and control of plant and animal pests and diseases; dairy farms, livestock markets, animal breeding stations, and artificial insemination centers; and assistance in the organization of farmers and fishermen's cooperatives, and other collective organizations, as well as the transfer of appropriate technology;\n(ii) Industrial research and development services, as well as the transfer of appropriate technology;\n(iii) Pursuant to national policies and subject to supervision, control and review of the DENR, enforcement of forestry laws limited to community-based forestry projects, pollution control law, small-scale mining law, and other laws on the protection of the environment; and mini-hydroelectric projects for local purposes;\n(iv) Subject to the provisions of Title Five, Book I of this Code, health services which include hospitals and other tertiary health services;\n(v) Social welfare services which include programs and projects on rebel returnees and evacuees; relief operations; and population development services;\n(vi) Provincial buildings, provincial jails, freedom parks and other public assembly areas and similar facilities;\n(vii) Infrastructure facilities intended to service the needs of the residence of the province and which are funded out of provincial funds including, but not limited to, provincial roads and bridges; inter-municipal waterworks, drainage and sewerage, flood control, and irrigation systems; reclamation projects; and similar facilities;\n(viii) Programs and projects for low-cost housing and other mass dwellings, except those funded by the Social Security System (SSS), Government Service Insurance System p. 172 (GSIS), and the Home Development Mutual Fund (HDMF): Provided, That national funds for these programs and projects shall be equitably allocated among the regions in proportion to the ratio of the homeless to the population;\n(ix) Investment support services, including access to credit financing;\n(x) Upgrading and modernization of tax information and collection services through the use of computer hardware and software and other means;\n(xi) Inter-municipal telecommunications services, subject to national policy guidelines; and\n(xii) Tourism development and promotion programs;\n(4) For a City:\nAll the services and facilities of the municipality and province, and in addition thereto, the following:\n(1) Adequate communication and transportation facilities;\n(c) Notwithstanding the provisions of subsection (b) hereof, public works and infrastructure projects and other facilities, programs and services funded by the national government under the annual General Appropriations Act, other special laws, pertinent executive orders, and those wholly or partially funded from foreign sources, are not covered under this Section, except in those cases where the local government unit concerned is duly designated as the implementing agency for such projects, facilities, programs, and services.\n(d) The designs, plans, specifications, testing of materials, and the procurement of equipment and materials at P170 from both foreign and local sources necessary for the provision of the foregoing services and facilities shall be undertaken by the local government unit concerned, based on national policies, standards and guidelines.\n(e) National agencies or offices concerned shall devolve to local government units the responsibility for the provision of basic services and facilities enumerated in this Section within six (6) months after the effectivity of this Code.\nAs used in this Code, the term \"devolution\" refers to the act by which the national government confers power and authority upon the various local government units to perform specific functions and responsibilities.\n(f) The national government or the next higher level of local government unit may provide or augment the basic services and facilities assigned to a lower level of local government unit when such services or facilities are not made available or, if made available, are inadequate to meet the requirements of its inhabitants.\n(g) The basic services and facilities hereinabove enumerated shall be funded from the share of local government units in the proceeds of national taxes and other local revenues and funding support from the national government, its instrumentalities and government-owned or controlled corporations which are tasked by law to establish and maintain such services or facilities. Any fund or resource available for the use of local government units shall be first allocated for the provision of basic services or facilities enumerated in subsection (b) hereof before applying the same for other purposes, unless otherwise provided in this Code.\n(h) Regional offices of national agencies or offices whose functions are devolved to local government units as provided herein shall be phased out within one (1) year from the approval of this Code. Said national agencies and offices may establish such field units as may be necessary for monitoring purposes and providing technical assistance to local government units. The properties, equipment, and other assets of these regional offices shall be distributed to the local government units in the region in accordance with the rules and regulations issued by the oversight committee created under this Code.\n(i) The devolution contemplated in this Code shall include the transfer to local government units of the records, equipment, and other assets and personnel of national agencies and offices corresponding to the devolved powers, functions, and responsibilities.\nPersonnel of said national agencies or offices shall be absorbed by the local government units to which they belong or in whose areas they are assigned to the extent that it is administratively viable as determined by the said oversight committee: Provided, That the rights accorded to such personnel pursuant to civil service law, rules and regulations shall not be impaired: Provided, further, That regional directors who are career executive service officers and other officers of similar rank in the said regional offices who cannot be absorbed by the local government unit shall be retained by the national government, without any diminution of rank, salary or tenure.\n(j) To ensure the active participation of the private sector in local governance, local government units may, by ordinance, sell, lease, encumber, or otherwise dispose of public economic enterprises owned by them in their proprietary capacity.\nCosts may also be charged for the delivery of basic services or facilities enumerated in this Section."}},{"id":"PH-H5648-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Power to Generate and Apply Resources. - Local government units shall have the power and authority to establish an organization that shall be responsible for the efficient and effective implementation of their development plans, program objectives and priorities; to create their own sources of revenues and to levy taxes, fees, and charges which shall accrue exclusively for their use and disposition and which shall be retained by them; to have a just share in national taxes which shall be automatically and directly released to them without need of any further action; to have an equitable share in the proceeds from the utilization and development of the national wealth and resources within their respective territorial jurisdictions including sharing the same with the inhabitants by way of direct benefits; to acquire, develop, lease, encumber, alienate, or otherwise dispose of real or personal property held by them in their proprietary capacity and to apply their resources and assets for productive, developmental, or welfare purposes, in the exercise or furtherance of their governmental or proprietary powers and functions and thereby ensure their development into self-reliant communities and active participants in the attainment of national goals."}},{"id":"PH-H5648-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Eminent Domain. - A local government unit may, through its chief executive and acting pursuant to an ordinance, exercise the power of eminent domain for public use, or purpose or welfare for the benefit of the poor and the landless, upon payment of just compensation, pursuant to the provisions of the Constitution and pertinent laws: Provided, however, That the power of eminent domain may not be exercised unless a valid and definite offer has been previously made to the owner, and such offer was not accepted: Provided, further, That the local government unit may immediately take possession of the property upon the filing of the expropriation proceedings and upon making a deposit with the proper court of at least fifteen percent (15%) of the fair market value of the property based on the current tax declaration of the property to be expropriated: Provided, finally, That, the amount to be paid for the expropriated property shall be determined by the proper court, based on the fair market value at the time of the taking of the property."}},{"id":"PH-H5648-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Reclassification of Lands. -\n(a) A city or municipality may, through an ordinance passed by the sanggunian after conducting public hearings for the purpose, authorize the reclassification of agricultural lands and provide for the manner of their utilization or disposition in the following cases: (1) when the land ceases to be economically feasible and sound for agricultural purposes as determined by the Department of Agriculture or (2) where the land shall have substantially greater economic value for residential, commercial, or industrial purposes, as determined by the sanggunian concerned: Provided, That such reclassification shall be limited to the following percentage of the total agricultural land area at the time of the passage of the ordinance:\n(1) For highly urbanized and independent component cities, fifteen percent (15%);\n(2) For component cities and first to the third class municipalities, ten percent (10%); and\n(3) For fourth to sixth class municipalities, five percent (5%): Provided, further, That agricultural lands distributed to agrarian reform beneficiaries pursuant to Republic Act Numbered Sixty-six hundred fifty-seven (R.A. No. 6657). otherwise known as \"The Comprehensive Agrarian Reform Law\", shall not be affected by the said reclassification and the conversion of such lands into other purposes shall be governed by Section 65 of said Act.\n(b) The President may, when public interest so requires and upon recommendation of the National Economic and Development Authority, authorize a city or municipality to reclassify lands in excess of the limits set in the next preceding paragraph.\n(c) The local government units shall, in conformity with existing laws, continue to prepare their respective comprehensive land use plans enacted through zoning ordinances which shall be the primary and dominant bases for the future use of land resources: Provided. That the requirements for food production, human settlements, and industrial expansion shall be taken into consideration in the preparation of such plans.\n(d) Where approval by a national agency is required for reclassification, such approval shall not be unreasonably withheld. Failure to act on a proper and complete application for reclassification within three (3) months from receipt of the same shall be deemed as approval thereof.\n(e) Nothing in this Section shall be construed as repealing, amending, or modifying in any manner the provisions of R.A. No. 6657."}},{"id":"PH-H5648-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Closure and Opening of Roads. -\n(a) A local government unit may, pursuant to an ordinance, permanently or temporarily close or open any local road, alley, park, or square falling within its jurisdiction: Provided, however, That in case of permanent closure, such ordinance must be approved by at least two-thirds (2/3) of all the members of the sanggunian, and when necessary, an adequate substitute for the public facility that is subject to closure is provided.\n(b) No such way or place or any part thereof shall be permanently closed without making provisions for the maintenance of public safety therein. A property thus permanently withdrawn from public use may be used or conveyed for any purpose for which other real property belonging to the local government unit concerned may be lawfully used or conveyed: Provided, however, That no freedom park shall be closed permanently without provision for its transfer or relocation to a new site.\n(c) Any national or local road, alley, park, or square may be temporarily closed during an actual emergency, or fiesta celebrations, public rallies, agricultural or industrial fairs, or an undertaking of public works and highways, telecommunications, and waterworks projects, the duration of which shall be specified by the local chief executive concerned in a written order: Provided, however, That no national or local road, alley, park, or square shall be temporarily closed for athletic, cultural, or civic activities not officially sponsored, recognized, or approved by the local government unit concerned.\n(d) Any city, municipality, or barangay may, by a duly enacted ordinance, temporarily close and regulate the use of any local street, road, thoroughfare, or any other public place where shopping malls, Sunday, flea or night markets, or shopping areas may be established and where goods, merchandise, foodstuffs, commodities, or articles of commerce may be sold and dispensed to the general public."}},{"id":"PH-H5648-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Corporate Powers. -\n(a) Every local government unit, as a corporation, shall have the following powers:\n(1) To have continuous succession in its corporate name;\n(2) To sue and be sued;\n(3) To have and use a corporate seal;\n(4) To acquire and convey real or personal property;\n(5) To enter into contracts; and\n(6) To exercise such other powers as are granted to corporations, subject to the limitations provided in this Code and other laws.\n(b) Local government units may continue using, modify, or change their existing corporate seals: Provided, That newly established local government units or those without corporate seals may create their own corporate seals which shall be registered with the Department of the Interior and Local Government: Provided, further, That any change of corporate seal shall also be registered as provided hereon.\n(c) Unless otherwise provided in this Code, no contract may be entered into by the local chief executive in behalf of the local government unit without prior authorization by the sanggunian concerned. A legible copy of such contract shall be posted at a conspicuous place in the provincial capitol or the city, municipal or barangay hall.\n(d) Local government units shall enjoy full autonomy in the exercise of their proprietary functions and in the limitations provided in this Code and other applicable laws,"}},{"id":"PH-H5648-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Authority to Negotiate and Secure Grants. - Local chief executives may, upon authority of the sanggunian, negotiate and secure financial grants or donations in kind, in support of the basic services or facilities enumerated under Section 17 hereof, from local and foreign assistance agencies without necessity of securing clearance or approval therefor from any department, agency, or office of the national government of from any higher local government unit: Provided, That projects financed by such grants or assistance with national security implications shall be approved by the national agency concerned: Provided, further, That when such national agency fails to act on the request for approval within thirty (30) days from receipt thereof, the same shall be deemed approved.\nThe local chief executive shall, within thirty (30) days upon signing of such grant agreement or deed of donation, report the nature, amount, and terms of such assistance to both Houses of Congress and the President."}},{"id":"PH-H5648-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Liability for Damages. - Local government units and their officials are not exempt from liability for death or injury to persons or damage to property.\nIntergovernmental Relations\nNational Government and Local Government Units"}},{"id":"PH-H5648-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"ARTICLE I"},"text":{"en":"National Supervision over Local Government Units. -\n(a) Consistent with the basic policy on local autonomy, the President shall exercise general supervision over local government units to ensure that their acts are within the scope of their prescribed powers and functions.\nThe President shall exercise supervisory authority directly over provinces, highly urbanized cities, and independent component cities; through the province with respect to component cities and municipalities; and through the city and municipality with respect to barangays.\n(b) National agencies and offices with project implementation functions shall coordinate with one another and with the local government units concerned in the discharge of these functions. They shall ensure the participation of local government units both in the planning and implementation of said national projects.\n(c) The President may, upon request of the local government unit concerned, direct the appropriate national agency to provide financial, technical, or other forms of assistance to the local government unit. Such assistance shall be extended at no extra cost to the local government unit concerned.\n(d) National agencies and offices including government-owned or controlled corporations with field units or branches in a province, city, or municipality shall furnish the local chief executive concerned, for his information and guidance, monthly reports including duly certified budgetary allocations and expenditures."}},{"id":"PH-H5648-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Duty of National Government Agencies in the Maintenance of Ecological Balance. - It shall be the duty of every national agency or government-owned or controlled corporation authorizing or involved in the planning and implementation of any project or program that may cause pollution, climatic change, depletion of non-renewable resources, loss of crop land, rangeland, or forest cover, and extinction of animal or plant species, to consult with the local government units, nongovernmental organizations, and other sectors concerned and explain the goals and objectives of the project or program, its impact upon the people and the community in terms of environmental or ecological balance, and the measures that will be undertaken to prevent or minimize the adverse effects thereof."}},{"id":"PH-H5648-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Prior Consultations Required. - No project or program shall be implemented by government authorities unless the consultations mentioned in Sections 2 (c) and 26 hereof are complied with, and prior approval of the sanggunian concerned is obtained: Provided, That occupants in areas where such projects are to be implemented shall not be evicted unless appropriate relocation sites have been provided, in accordance with the provisions of the Constitution.\nRelations with the Philippine National Police"}},{"id":"PH-H5648-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Powers of Local Chief Executives over the Units of the Philippine National Police. - The extent of operational supervision and control of local chief executives over the police force, fire protection unit, and jail management personnel assigned in their respective jurisdictions shall be governed by the provisions of Republic Act Numbered Sixty-nine hundred seventy-five (R.A. No. 6975), otherwise known as \"The Department of the Interior and Local Government Act of 1990\", and the rules and regulations issued pursuant thereto.\nInter-Local Government Relations"}},{"id":"PH-H5648-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Provincial Relations with Component Cities and Municipalities. - The province, through the governor, shall ensure that every component city and municipality within its territorial jurisdiction acts within the scope of its prescribed powers and functions. Highly urbanized cities and independent component cities shall be independent of the province."}},{"id":"PH-H5648-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Review of Executive Orders. -\n(a) Except as otherwise provided under the Constitution and special statutes, the governor shall review all executive orders promulgated by the component city or municipal mayor within his jurisdiction. The city or municipal mayor shall review all executive orders promulgated by the punong barangay within his jurisdiction. Copies of such orders shall be forwarded to the governor or the city or municipal mayor, as the case may be, within three (3) days from their issuance. In all instances of review, the local chief executive concerned shall ensure that such executive orders are within the powers granted by law and in conformity with provincial, city, or municipal ordinances.\n(b) If the governor or the city or municipal mayor fails to act on said executive orders within thirty (30) days after their submission, the same shall be deemed consistent with law and therefore valid."}},{"id":"PH-H5648-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Submission of Municipal Questions to the Provincial Legal Officer or Prosecutor. - In the absence of a municipal legal officer, the municipal government may secure the opinion of the provincial legal officer, and in the absence of the latter, that of the provincial prosecutor on any legal question affecting the municipality."}},{"id":"PH-H5648-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"en":"ARTICLE III"},"text":{"en":"City and Municipal Supervision over Their Respective Barangays. - The city or municipality, through the city or municipal mayor concerned, shall exercise general supervision over component barangays to ensure that said barangays act within the scope of their prescribed powers and functions."}},{"id":"PH-H5648-A33","no":33,"noLabel":{"en":"Section 33."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Cooperative Undertakings Among Local Government Units. - Local government units may, through appropriate ordinances, group themselves, consolidate, or coordinate their efforts, services, and resources for purposes commonly beneficial to them. In support of such undertakings, the local government units involved may, upon approval by the sanggunian concerned after a public hearing conducted for the purpose, contribute funds, real estate, equipment, and other kinds of property and appoint or assign personnel under such terms and conditions as may be agreed upon by the participating local units through Memoranda of Agreement.\nRelations With People's and Non-Governmental Organizations"}},{"id":"PH-H5648-A34","no":34,"noLabel":{"en":"Section 34."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Role of People's and Non-governmental Organizations. - Local government units shall promote the establishment and operation of people's and non-governmental organizations to become active partners in the pursuit of local autonomy."}},{"id":"PH-H5648-A35","no":35,"noLabel":{"en":"Section 35."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Linkages with People's and Non-governmental Organizations. - Local government units may enter into joint ventures and such other cooperative arrangements with people's and non-governmental organizations to engage in the delivery of certain basic services, capability-building and livelihood projects, and to develop local enterprises designed to improve productivity and income, diversity agriculture, spur rural industrialization, promote ecological balance, and enhance the economic and social well-being of the people."}},{"id":"PH-H5648-A36","no":36,"noLabel":{"en":"Section 36."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Assistance to People's and Non-governmental Organizations. - A local government unit may, through its local chief executive and with the concurrence of the sanggunian concerned, provide assistance, financial or otherwise, to such people's and non-governmental organizations for economic, socially-oriented, environmental, or cultural projects to be implemented within its territorial jurisdiction.\nLocal Prequalification, Bids and Awards Committee"}},{"id":"PH-H5648-A37","no":37,"noLabel":{"en":"Section 37."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Local Prequalification, Bids and Awards Committee (Local PBAC). -\n(a) There is hereby created a local prequalification, bids and awards committee in every province, city, and municipality, which shall be primarily responsible for the conduct of prequalification of contractors, bidding, evaluation of bids, and the recommendation of awards concerning local infrastructure projects. The governor or the city or municipal mayor shall act as the chairman with the following as members:\n(1) The chairman of the appropriations committee of the sanggunian concerned;\n(2) A representative of the minority party in the sanggunian concerned, if any, or if there be none, one (1) chosen by said sanggunian from among its members;\n(3) The local treasurer;\n(4) Two (2) representatives of non-governmental organizations that are represented in the local development council concerned, to be chosen by the organizations themselves; and\n(5) Any practicing certified public accountant from the private sector, to be designated by the local chapter of the Philippine Institute of Certified Public Accountants, if any.\nRepresentatives of the Commission on Audit shall observe the proceedings of such committee and shall certify that the rules and procedures for prequalification, bids and awards have been complied with.\n(b) The agenda and other information relevant to the meetings of such committee shall be deliberated upon by the committee at least one (1) week before the holding of such meetings.\n(c) All meetings of the committee shall be held in the provincial capitol or the city or municipal hall. The minutes of such meetings of the committee and any decision made therein shall be duly recorded, posted at a prominent place in the provincial capitol or the city or municipal hall, and delivered by the most expedient means to elective local officials concerned."}},{"id":"PH-H5648-A38","no":38,"noLabel":{"en":"Section 38."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Local Technical Committee. -\n(a) There is hereby created a local technical committee in every province, city and municipality to provide technical assistance to the local prequalification, bids and awards committees. It shall be composed of the provincial, city or municipal engineer, the local planning and development coordinator, and such other officials designated by the local prequalification, bids and awards committee.\n(b) The chairman of the local technical committee shall be designated by the local prequalification, bids and awards committee and shall attend its meeting in order to present the reports and recommendations of the local technical committee.\nELECTIVE OFFICIALS\nQualifications and Election"}},{"id":"PH-H5648-A39","no":39,"noLabel":{"en":"Section 39."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Qualifications. -\n(a) An elective local official must be a citizen of the Philippines; a registered voter in the barangay, municipality, city, or province or, in the case of a member of the sangguniang panlalawigan, sangguniang panlungsod, or sangguniang bayan, the district where he intends to be elected; a resident therein for at least one (1) year immediately preceding the day of the election; and able to read and write Filipino or any other local language or dialect.\n(b) Candidates for the position of governor, vice-governor, or member of the sangguniang panlalawigan, or mayor, vice-mayor or member of the sangguniang panlungsod of highly urbanized cities must be at least twenty-one (21) years of age on election day.\n(c) Candidates for the position of mayor or vice-mayor of independent component cities, component cities, or municipalities must be at least twenty-one (21) years of age on election day.\n(d) Candidates for the position of member of the sangguniang panlungsod or sangguniang bayan must be at least eighteen (18) years of age on election day.\n(e) Candidates for the position of punong barangay or member of the sangguniang barangay must be at least eighteen (18) years of age on election day.\n(f) Candidates for the sangguniang kabataan must be at least fifteen (15) years of age but not more than twenty-one (21) years of age on election day."}},{"id":"PH-H5648-A40","no":40,"noLabel":{"en":"Section 40."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Disqualifications. - The following persons are disqualified from running for any elective local position:\n(a) Those sentenced by final judgment for an offense involving moral turpitude or for an offense punishable by one (1) year or more of imprisonment, within two (2) years after serving sentence;\n(b) Those removed from office as a result of an administrative case;\n(c) Those convicted by final judgment for violating the oath of allegiance to the Republic;\n(d) Those with dual citizenship;\n(e) Fugitives from justice in criminal or non-political cases here or abroad;\n(f) Permanent residents in a foreign country or those who have acquired the right to reside abroad and continue to avail of the same right after the effectivity of this Code; and\n(g) The insane or feeble-minded."}},{"id":"PH-H5648-A41","no":41,"noLabel":{"en":"Section 41."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Manner of Election. -\n(a) The governor, vice-governor, city mayor, city vice-mayor, municipal mayor, municipal vice-mayor, and punong barangay shall be elected at large in their respective units by the qualified voters therein. However, the sangguniang kabataan chairman for each barangay shall be elected by the registered voters of the katipunan ng kabataan, as provided in this Code.\n(b) The regular members of the sangguniang panlalawigan, sangguniang panlungsod, and sangguniang bayan shall be elected by district, as may be provided for by law. Sangguniang barangay members shall be elected at large. The presidents of the leagues of sanggunian members of component cities and municipalities shall serve as ex officio members of the sangguniang panlalawigan concerned. The presidents of the \"liga ng mga barangay and the pederasyon ng mga sangguniang kabataan\" elected by their respective chapters, as provided in this Code, shall serve as ex officio members of the sangguniang panlalawigan, sangguniang panlungsod, and sangguniang bayan.\n(c) In addition thereto, there shall be one (1) sectoral representative from the women, one (1) from the workers, and one (1) from any of the following sectors: the urban poor, indigenous cultural communities, disabled persons, or any other sector as may be determined by the sanggunian concerned within ninety (90) days prior to the holding of the next local elections as may be provided for by law. The COMELEC shall promulgate the rules and regulations to effectively provide for the election of such sectoral representatives."}},{"id":"PH-H5648-A42","no":42,"noLabel":{"en":"Section 42."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Date of Election. - Unless otherwise provided by law, the elections for local officials shall be held every three (3) years on the second Monday of May."}},{"id":"PH-H5648-A43","no":43,"noLabel":{"en":"Section 43."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Term of Office. -\n(a) The term of office of all local elective officials elected after the effectivity of this Code shall be three (3) years, starting from noon of June 30, 1992 or such date as may be provided for by law, except that of elective barangay officials: Provided, That all local officials first elected during the local elections immediately following the ratification of the 1987 Constitution shall serve until noon of June 30, 1992.\n(b) No local elective official shall serve for more than three (3) consecutive terms in the same position. Voluntary renunciation of the office for any length of time shall not be considered as an interruption in the continuity of service for the full term for which the elective official concerned was elected.\n(c) The term of office of barangay officials and members of the sangguniang kabataan shall be for three (3) years, which shall begin after the regular election of barangay officials on the second Monday of May 1994.\nVacancies and Succession"}},{"id":"PH-H5648-A44","no":44,"noLabel":{"en":"Section 44."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Permanent Vacancies in the Offices of the Governor, Vice-Governor, Mayor, and Vice-Mayor. - If a permanent vacancy occurs in the office of the governor or mayor, the vice-governor or vice-mayor concerned shall become the governor or mayor. If a permanent vacancy occurs in the offices of the governor, vice-governor, mayor, or vice-mayor, the highest ranking sanggunian member or, in case of his permanent inability, the second highest ranking sanggunian member, shall become the governor, vice-governor, mayor or vice-mayor, as the case may be. Subsequent vacancies in the said office shall be filled automatically by the other sanggunian members according to their ranking as defined herein.\n(b) If a permanent vacancy occurs in the office of the punong barangay, the highest ranking sanggunian barangay member or, in case of his permanent inability, the second highest ranking sanggunian member, shall become the punong barangay.\n(c) A tie between or among the highest ranking sanggunian members shall be resolved by the drawing of lots.\n(d) The successors as defined herein shall serve only the unexpired terms of their predecessors.\nFor purposes of this Chapter, a permanent vacancy arises when an elective local official fills a higher vacant office, refuses to assume office, fails to qualify, dies, is removed from office, voluntarily resigns, or is otherwise permanently incapacitated to discharge the functions of his office.\nFor purposes of succession as provided in the Chapter, ranking in the sanggunian shall be determined on the basis of the proportion of votes obtained by each winning candidate to the total number of registered voters in each district in the immediately preceding local election."}},{"id":"PH-H5648-A45","no":45,"noLabel":{"en":"Section 45."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Permanent Vacancies in the Sanggunian. -\n(a) Permanent vacancies in the sanggunian where automatic succession provided above do not apply shall be filled by appointment in the following manner:\n(1) The President, through the Executive Secretary, in the case of the sangguniang panlalawigan and the sangguniang panlungsod of highly urbanized cities and independent component cities;\n(2) The governor, in the case of the sangguniang panlungsod of component cities and the sangguniang bayan;\n(3) The city or municipal mayor, in the case of sangguniang barangay, upon recommendation of the sangguniang barangay concerned.\n(b) Except for the sangguniang barangay, only the nominee of the political party under which the sanggunian member concerned had been elected and whose elevation to the position next higher in rank created the last vacancy in the sanggunian shall be appointed in the manner hereinabove provided. The appointee shall come from the same political party as that of the sanggunian member who caused the vacancy and shall serve the unexpired term of the vacant office. In the appointment herein mentioned, a nomination and a certificate of membership of the appointee from the highest official of the political party concerned are conditions sine qua non, and any appointment without such nomination and certification shall be null and void ab initio and shall be a ground for administrative action against the official responsible therefore.\n(c) In case or permanent vacancy is caused by a sanggunian member who does not belong to any political party, the local chief executive shall, upon recommendation of the sanggunian concerned, appoint a qualified person to fill the vacancy.\n(d) In case of vacancy in the representation of the youth and the barangay in the sanggunian, said vacancy shall be filled automatically by the official next in rank of the organization concerned."}},{"id":"PH-H5648-A46","no":46,"noLabel":{"en":"Section 46."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Temporary Vacancy in the Office of the Local Chief Executive. -\n(a) When the governor, city or municipal mayor, or punong barangay is temporarily incapacitated to perform his duties for physical or legal reasons such as, but not limited to, leave of absence, travel abroad, and suspension from office, the vice-governor, city or municipal vice-mayor, or the highest ranking sangguniang barangay member shall automatically exercise the powers and perform the duties and functions of the local chief executive concerned, except the power to appoint, suspend, or dismiss employees which can only be exercised if the period of temporary incapacity exceeds thirty (30) working days.\n(b) Said temporary incapacity shall terminate upon submission to the appropriate sanggunian of a written declaration by the local chief executive concerned that he has reported back to office. In cases where the temporary incapacity is due to legal causes, the local chief executive concerned shall also submit necessary documents showing that said legal causes no longer exist.\n(c) When the incumbent local chief executive is traveling within the country but outside his territorial jurisdiction for a period not exceeding three (3) consecutive days, he may designate in writing the officer-in-charge of the said office. Such authorization shall specify the powers and functions that the local official concerned shall exercise in the absence of the local chief executive except the power to appoint, suspend, or dismiss employees.\n(d) In the event, however, that the local chief executive concerned fails or refuses to issue such authorization, the vice-governor, the city or municipal vice-mayor, or the highest ranking sangguniang barangay member, as the case may be, shall have the right to assume the powers, duties, and functions of the said office on the fourth (4th) day of absence of the said local chief executive, subject to the limitations provided in subsection (c) hereof.\n(e) Except as provided above, the local chief executive shall in no case authorize any local official to assume the powers, duties, and functions of the office, other than the vice-governor, the city or municipal vice-mayor, or the highest ranking sangguniang barangay member, as the case may be."}},{"id":"PH-H5648-A47","no":47,"noLabel":{"en":"Section 47."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Approval of Leaves of Absence. -\n(a) Leaves of absence of local elective officials shall be approved as follows:\n(1) Leaves of absence of the governor and the mayor of a highly urbanized city or an independent component city shall be approved by the President or his duly authorized representative;\n(2) Leaves of absence of vice-governor or a city or municipal vice-mayor shall be approved by the local chief executive concerned: Provided, That the leaves of absence of the members of the sanggunian and its employees shall be approved by the vice-governor or city or municipal vice-mayor concerned;\n(3) Leaves of absence of the component city or municipal mayor shall be approved by the governor; and\n(4) Leaves of absence of a punong barangay shall be approved by the city or municipal mayor: Provided, That leaves of absence of sangguniang barangay members shall be approved by the punong barangay.\n(b) Whenever the application for leave of absence hereinabove specified is not acted upon within five (5) working days after receipt thereof, the application for leave of absence shall be deemed approved.\nLocal Legislation"}},{"id":"PH-H5648-A48","no":48,"noLabel":{"en":"Section 48."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Local Legislative Power. - Local legislative power shall be exercised by the sangguniang panlalawigan for the province; the sangguniang panlungsod for the city; the sangguniang bayan for the municipality; and the sangguniang barangay for the barangay."}},{"id":"PH-H5648-A49","no":49,"noLabel":{"en":"Section 49."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Presiding Officer. -\n(a) The vice-governor shall be the presiding officer of the sangguniang panlalawigan; the city vice-mayor, of the sangguniang panlungsod; the municipal vice-mayor, of the sangguniang bayan; and the punong barangay, of the sangguniang barangay. The presiding officer shall vote only to break a tie.\n(b) In the event of the inability of the regular presiding officer to preside at a sanggunian session, the members present and constituting a quorum shall elect from among themselves a temporary presiding officer. He shall certify within ten (10) days from the passage of ordinances enacted and resolutions adopted by the sanggunian in the session over which he temporarily presided."}},{"id":"PH-H5648-A50","no":50,"noLabel":{"en":"Section 50."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Internal Rules of Procedure. -\n(a) On the first regular session following the election of its members and within ninety (90) days thereafter, the sanggunian concerned shall adopt or update its existing rules of procedure.\n(b) The rules of procedure shall provided for the following:\n(1) The organization of the sanggunian and the election of its officers as well as the creation of standing committees which shall include, but shall not be limited to, the committees on appropriations, women and family, human rights, youth and sports development, environmental protection, and cooperatives; the general jurisdiction of each committee; and the election of the chairman and members of each committee;\n(2) The order and calendar of business for each session;\n(3) The legislative process;\n(4) The parliamentary procedures which include the conduct of members during sessions;\n(5) The discipline of members for disorderly behavior and absences without justifiable cause for four (4) consecutive sessions, for which they may be censured, reprimanded, or excluded from the session, suspended for not more than sixty (60) days, or expelled: Provided, That the penalty of suspension or expulsion shall require the concurrence of at least two-thirds (2/3) vote of all the sanggunian members: Provided, further, That a member convicted by final judgment to imprisonment of at least one (1) year for any crime involving moral turpitude shall be automatically expelled from the sanggunian; and\n(6) Such other rules as the sanggunian may adopt."}},{"id":"PH-H5648-A51","no":51,"noLabel":{"en":"Section 51."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Full Disclosure of Financial and Business Interests of Sanggunian Members . -\n(a) Every sanggunian member shall, upon assumption to office, make a full disclosure of his business and financial interests, or professional relationship or any relation by affinity or consanguinity within the fourth civil degree, which he may have with any person, firm, or entity affected by any ordinance or resolution under consideration by the sanggunian of which he is a member, which relationship may result in conflict of interest. Such relationship shall include:\n(1) Ownership of stock or capital, or investment, in the entity or firm to which the ordinance or resolution may apply; and\n(2) Contracts or agreements with any person or entity which the ordinance or resolution under consideration may affect.\nIn the absence of a specific constitutional or statutory provision applicable to this situation, \"conflict of interest\" refers in general to one where it may be reasonably deduced that a member of a sanggunian may not act in the public interest due to some private, pecuniary, or other personal considerations that may tend to affect his judgment to the prejudice of the service or the public.\n(b) The disclosure required under this Act shall be made in writing and submitted to the secretary of the sanggunian or the secretary of the committee of which he is a member. The disclosure shall, in all cases, form part of the record of the proceedings and shall be made in the following manner:\n(1) Disclosure shall be made before the member participates in the deliberations on the ordinance or resolution under consideration: Provided, That, if the member did not participate during the deliberations, the disclosure shall be made before voting on the ordinance or resolution on second and third readings; and\n(2) Disclosure shall be made when a member takes a position or makes a privilege speech on a matter that may affect the business interest, financial connection, or professional relationship described herein."}},{"id":"PH-H5648-A52","no":52,"noLabel":{"en":"Section 52."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Sessions. -\n(a) On the first day of the session immediately following the election of its members, the sanggunian shall, by resolution, fix the day, time, and place of its regular sessions. The minimum numbers of regular sessions shall be once a week for the sangguniang panlalawigan, sangguniang panlungsod, and sangguniang bayan, and twice a month for the sangguniang barangay.\n(b) When public interest so demands, special sessions may be called by the local chief executive or by a majority of the members of the sanggunian.\n(c) All sanggunian sessions shall be open to the public unless a closed-door session is ordered by an affirmative vote of a majority of the members present, there being a quorum, in the public interest or for reasons of security, decency, or morality. No two (2) sessions, regular or special, may be held in a single day.\n(d) In the case of special sessions of the sanggunian, a written notice to the members shall be served personally at the member's usual place of residence at least twenty-four (24) hours before the special session is held.\nUnless otherwise concurred in by two-thirds (2/3) vote of the sanggunian members present, there being a quorum, no other matters may be considered at a special session except those stated in the notice.\n(e) Each sanggunian shall keep a journal and record of its proceedings which may be published upon resolution of the sanggunian concerned."}},{"id":"PH-H5648-A53","no":53,"noLabel":{"en":"Section 53."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Quorum. -\n(a) A majority of all the members of the sanggunian who have been elected and qualified shall constitute a quorum to transact official business. Should a question of quorum be raised during a session, the presiding officer shall immediately proceed to call the roll of the members and thereafter announce the results.\n(b) Where there is no quorum, the presiding officer may declare a recess until such time as a quorum is constituted, or a majority of the members present may adjourn from day to day and may compel the immediate attendance of any member absent without justifiable cause by designating a member of the sanggunian to be assisted by a member or members of the police force assigned in the territorial jurisdiction of the local government unit concerned, to arrest the absent member and present him at the session.\n(c) If there is still no quorum despite the enforcement of the immediately preceding subsection, no business shall be transacted. The presiding officer, upon proper motion duly approved by the members present, shall then declare the session adjourned for lack of quorum."}},{"id":"PH-H5648-A54","no":54,"noLabel":{"en":"Section 54."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Approval of Ordinances. -\n(a) Every ordinance enacted by the sangguniang panlalawigan, sangguniang panlungsod, or sangguniang bayan shall be presented to the provincial governor or city or municipal mayor, as the case may be. If the local chief executive concerned approves the same, he shall affix his signature on each and every page thereof; otherwise, he shall veto it and return the same with his objections to the sanggunian, which may proceed to reconsider the same. The sanggunian concerned may override the veto of the local chief executive by two-thirds (2/3) vote of all its members, thereby making the ordinance or resolution effective for all legal intents and purposes.\n(b) The veto shall be communicated by the local chief executive concerned to the sanggunian within fifteen (15) days in the case of a province, and ten (10) days in the case of a city or a municipality; otherwise, the ordinance shall be deemed approved as if he had signed it.\n(c) Ordinances enacted by the sangguniang barangay shall, upon approval by the majority of all its members, be signed by the punong barangay."}},{"id":"PH-H5648-A55","no":55,"noLabel":{"en":"Section 55."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Veto Power of the Local Chief Executive. -\n(a) The local chief executive may veto any ordinance of the sanggunian panlalawigan, sangguniang panlungsod, or sanggunian bayan on the ground that it is ultra vires or prejudicial to the public welfare, stating his reasons therefor in writing.\n(b) The local chief executive, except the punong barangay, shall have the power to veto any particular item or items of an appropriations ordinance, an ordinance or resolution adopting a local development plan and public investment program, or an ordinance directing the payment of money or creating liability. In such a case, the veto shall not affect the item or items which are not objected to. The vetoed item or items shall not take effect unless the sanggunian overrides the veto in the manner herein provided; otherwise, the item or items in the appropriations ordinance of the previous year corresponding to those vetoed, if any, shall be deemed reenacted.\n(c) The local chief executive may veto an ordinance or resolution only once. The sanggunian may override the veto of the local chief executive concerned by two-thirds (2/3) vote of all its members, thereby making the ordinance effective even without the approval of the local chief executive concerned."}},{"id":"PH-H5648-A56","no":56,"noLabel":{"en":"Section 56."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Review of Component City and Municipal Ordinances or Resolutions by the Sangguniang Panlalawigan.\n(a) Within three (3) days after approval, the secretary to the sanggunian panlungsod or sangguniang bayan shall forward to the sangguniang panlalawigan for review, copies of approved ordinances and the resolutions approving the local development plans and public investment programs formulated by the local development councils.\n(b) Within thirty (30) days after the receipt of copies of such ordinances and resolutions, the sangguniang panlalawigan shall examine the documents or transmit them to the provincial attorney, or if there be none, to the provincial prosecutor for prompt examination. The provincial attorney or provincial prosecutor shall, within a period of ten (10) days from receipt of the documents, inform the sangguniang panlalawigan in writing of his comments or recommendations, which may be considered by the sangguniang panlalawigan in making its decision.\n(c) If the sangguniang panlalawigan finds that such an ordinance or resolution is beyond the power conferred upon the sangguniang panlungsod or sangguniang bayan concerned, it shall declare such ordinance or resolution invalid in whole or in part. The sangguniang panlalawigan shall enter its action in the minutes and shall advise the corresponding city or municipal authorities of the action it has taken.\n(d) If no action has been taken by the sangguniang panlalawigan within thirty (30) days after submission of such an ordinance or resolution, the same shall be presumed consistent with law and therefore valid."}},{"id":"PH-H5648-A57","no":57,"noLabel":{"en":"Section 57."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Review of Barangay Ordinances by the Sangguniang Panlungsod or Sangguniang Bayan. -\n(a) Within ten (10) days after its enactment, the sangguniang barangay shall furnish copies of all barangay ordinances to the sangguniang panlungsod or sangguniang bayan concerned for review as to whether the ordinance is consistent with law and city or municipal ordinances.\n(b) If the sangguniang panlungsod or sangguniang bayan, as the case may be, fails to take action on barangay ordinances within thirty (30) days from receipt thereof, the same shall be deemed approved.\n(c) If the sangguniang panlungsod or sangguniang bayan, as the case may be, finds the barangay ordinances inconsistent with law or city or municipal ordinances, the sanggunian concerned shall, within thirty (30) days from receipt thereof, return the same with its comments and recommendations to the sangguniang barangay concerned for adjustment, amendment, or modification; in which case, the effectivity of the barangay ordinance is suspended until such time as the revision called for is effected."}},{"id":"PH-H5648-A58","no":58,"noLabel":{"en":"Section 58."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Enforcement of Disapproved Ordinances or Resolutions. - Any attempt to enforce any ordinance or any resolution approving the local development plan and public investment program, after the disapproval thereof, shall be sufficient ground for the suspension or dismissal of the official or employee concerned."}},{"id":"PH-H5648-A59","no":59,"noLabel":{"en":"Section 59."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Effectivity of Ordinances or Resolutions. -\n(a) Unless otherwise stated in the ordinance or the resolution approving the local development plan and public investment program, the same shall take effect after ten (10) days from the date a copy thereof is posted in a bulletin board at the entrance of the provincial capitol or city, municipal, or barangay hall, as the case may be, and in at least two (2) other conspicuous places in the local government unit concerned.\n(b) The secretary to the sanggunian concerned shall cause the posting of an ordinance or resolution in the bulletin board at the entrance of the provincial capitol and the city, municipal, or barangay hall in at least two (2) conspicuous places in the local government unit concerned not later than five (5) days after approval thereof.\nThe text of the ordinance or resolution shall be disseminated and posted in Filipino or English and in the language understood by the majority of the people in the local government unit concerned, and the secretary to the sanggunian shall record such fact in a book kept for the purpose, stating the dates of approval and posting.\n(c) The gist of all ordinances with penal sanctions shall be published in a newspaper of general circulation within the province where the local legislative body concerned belongs. In the absence of any newspaper of general circulation within the province, posting of such ordinances shall be made in all municipalities and cities of the province where the sanggunian of origin is situated.\n(d) In the case of highly urbanized and independent component cities, the main features of the ordinance or resolution duly enacted or adopted shall, in addition to being posted, be published once in a local newspaper of general circulation within the city: Provided, That in the absence thereof the ordinance or resolution shall be published in any newspaper of general circulation.\nDisciplinary Actions"}},{"id":"PH-H5648-A60","no":60,"noLabel":{"en":"Section 60."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Grounds for Disciplinary Actions. - An elective local official may be disciplined, suspended, or removed from office on any of the following grounds:\n(a) Disloyalty to the Republic of the Philippines;\n(b) Culpable violation of the Constitution;\n(c) Dishonesty, oppression, misconduct in office, gross negligence, or dereliction of duty;\n(d) Commission of any offense involving moral turpitude or an offense punishable by at least prision mayor;\n(e) Abuse of authority;\n(f) Unauthorized absence for fifteen (15) consecutive working days, except in the case of members of the sangguniang panlalawigan, sangguniang panlungsod, sangguniang bayan, and sangguniang barangay;\n(g) Application for, or acquisition of, foreign citizenship or residence or the status of an immigrant of another country; and\n(h) Such other grounds as may be provided in this Code and other laws.\nAn elective local official may be removed from office on the grounds enumerated above by order of the proper court."}},{"id":"PH-H5648-A61","no":61,"noLabel":{"en":"Section 61."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Form and Filing of Administrative Complaints. - A verified complaint against any erring local elective official shall be prepared as follows:\n(a) A complaint against any elective official of a province, a highly urbanized city, an independent component city or component city shall be filed before the Office of the President;\n(b) A complaint against any elective official of a municipality shall be filed before the sangguniang panlalawigan whose decision may be appealed to the Office of the President; and\n(c) A complaint against any elective barangay official shall be filed before the sangguniang panlungsod or sangguniang bayan concerned whose decision shall be final and executory."}},{"id":"PH-H5648-A62","no":62,"noLabel":{"en":"Section 62."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Notice of hearing. -\n(a) Within seven (7) days after the administrative complaint is filed, the Office of the President or the sanggunian concerned, as the case may be, shall require the respondent to submit his verified answer within fifteen (15) days from receipt thereof, and commence the investigation of the case within ten (10) days after receipt of such answer of the respondent.\n(b) When the respondent is an elective official of a province or highly urbanized city, such hearing and investigation shall be conducted in the place where he renders or holds office. For all other local elective officials, the venue shall be the place where the sanggunian concerned is located.\n(c) However, no investigation shall be held within ninety (90) days immediately prior to any local election, and no preventive suspension shall be imposed within the said period. If preventive suspension has been imposed prior to the 90-day period immediately preceding local election, it shall be deemed automatically lifted upon the start of aforesaid period."}},{"id":"PH-H5648-A63","no":63,"noLabel":{"en":"Section 63."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Preventive Suspension. -\n(a) Preventive suspension may be imposed:\n(1) By the President, if the respondent is an elective official of a province, a highly urbanized or an independent component city;\n(2) By the governor, if the respondent is an elective official of a component city or municipality; or\n(3) By the mayor, if the respondent is an elective official of the barangay.\n(b) Preventive suspension may be imposed at any time after the issues are joined, when the evidence of guilt is strong, and given the gravity of the offense, there is great probability that the continuance in office of the respondent could influence the witnesses or pose a threat to the safety and integrity of the records and other evidence: Provided, That, any single preventive suspension of local elective officials shall not extend beyond sixty (60) days: Provided, further, That in the event that several administrative cases are filed against an elective official, he cannot be preventively suspended for more than ninety (90) days within a single year on the same ground or grounds existing and known at the time of the first suspension.\n(c) Upon expiration of the preventive suspension, the suspended elective official shall be deemed reinstated in office without prejudice to the continuation of the proceedings against him, which shall be terminated within one hundred twenty (120) days from the time he was formally notified of the case against him. However, if the delay in the proceedings of the case is due to his fault, neglect, or request, other than the appeal duly filed, the duration of such delay shall not be counted in computing the time of termination of the case.\n(d) Any abuse of the exercise of the power of preventive suspension shall be penalized as abuse of authority."}},{"id":"PH-H5648-A64","no":64,"noLabel":{"en":"Section 64."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Salary of Respondent Pending Suspension. - The respondent official preventively suspended from office shall receive no salary or compensation during such suspension; but upon subsequent exoneration and reinstatement, he shall be paid full salary or compensation including such emoluments accruing during such suspension."}},{"id":"PH-H5648-A65","no":65,"noLabel":{"en":"Section 65."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Rights of Respondent. - The respondent shall be accorded full opportunity to appear and defend himself in person or by counsel, to confront and cross-examine the witnesses against him, and to require the attendance of witnesses and the production of documentary process of subpoena or subpoena duces tecum."}},{"id":"PH-H5648-A66","no":66,"noLabel":{"en":"Section 66."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Form and Notice of Decision. -\n(a) The investigation of the case shall be terminated within ninety (90) days from the start thereof. Within thirty (30) days after the end of the investigation, the Office of the President or the sanggunian concerned shall render a decision in writing stating clearly and distinctly the facts and the reasons for such decision. Copies of said decision shall immediately be furnished the respondent and all interested parties.\n(b) The penalty of suspension shall not exceed the unexpired term of the respondent or a period of six (6) months for every administrative offense, nor shall said penalty be a bar to the candidacy of the respondent so suspended as long as he meets the qualifications required for the office.\n(c) The penalty of removal from office as a result of an administrative investigation shall be considered a bar to the candidacy of the respondent for any elective position."}},{"id":"PH-H5648-A67","no":67,"noLabel":{"en":"Section 67."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Administrative Appeals. - Decisions in administrative cases may, within thirty (30) days from receipt thereof, be appealed to the following:\n(a) The sangguniang panlalawigan, in the case of decisions of the sangguniang panlungsod of component cities and the sangguniang bayan; and\n(b) The Office of the President, in the case of decisions of the sangguniang panlalawigan and the sangguniang panlungsod of highly urbanized cities and independent component cities.\nDecisions of the Office of the President shall be final and executory."}},{"id":"PH-H5648-A68","no":68,"noLabel":{"en":"Section 68."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Execution Pending Appeal. - An appeal shall not prevent a decision from becoming final or executory. The respondent shall be considered as having been placed under preventive suspension during the pendency of an appeal in the event he wins such appeal. In the event the appeal results in an exoneration, he shall be paid his salary and such other emoluments during the pendency of the appeal.\nRecall"}},{"id":"PH-H5648-A69","no":69,"noLabel":{"en":"Section 69."},"chapter":{"en":"CHAPTER V"},"text":{"en":"By Whom Exercised. - The power of recall for loss of confidence shall be exercised by the registered voters of a local government unit to which the local elective official subject to such recall belongs."}},{"id":"PH-H5648-A70","no":70,"noLabel":{"en":"Section 70."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Initiation of the Recall Process. -\n(a) Recall may be initiated by a preparatory recall assembly or by the registered voters of the local government unit to which the local elective official subject to such recall belongs.\n(b) There shall be a preparatory recall assembly in every province, city, district, and municipality which shall be composed of the following:\n(1) Provincial level. - All mayors, vice-mayors, and sanggunian members of the municipalities and component cities;\n(2) City level. - All punong barangay and sanggunian barangay members in the city;\n(3) Legislative District level. - In case where sangguniang panlalawigan members are elected by district, all elective municipal officials in the district; and in cases where sangguniang panlungsod members are elected by district, all elective barangay officials in the district; and\n(4) Municipal level. - All punong barangay and sangguniang barangay members in the municipality.\n(c) A majority of all the preparatory recall assembly members may convene in session in a public place and initiate a recall proceedings against any elective official in the local government unit concerned. Recall of provincial, city, or municipal officials shall be validly initiated through a resolution adopted by a majority of all the members of the preparatory recall assembly concerned during its session called for the purpose.\n(d) Recall of any elective provincial, city, municipal, or barangay official may also be validly initiated upon petition of at least twenty-five percent (25%) of the total number of registered voters in the local government unit concerned during the election in which the local official sought to be recalled was elected.\n(1) A written petition for recall duly signed before the election registrar or his representative, and in the presence of a representative of the petitioner and a representative of the official sought to be recalled and, and in a public place in the province, city, municipality, or barangay, as the case may be, shall be filed with the COMELEC through its office in the local government unit concerned. The COMELEC or its duly authorized representative shall cause the publication of the petition in a public and conspicuous place for a period of not less than ten (10) days nor more than twenty (20) days, for the purpose of verifying the authenticity and genuineness of the petition and the required percentage of voters.\n(2) Upon the lapse of the aforesaid period, the COMELEC or its duly authorized representative shall announce the acceptance of candidates to the position and thereafter prepare the list of candidates which shall include the name of the official sought to be recalled."}},{"id":"PH-H5648-A71","no":71,"noLabel":{"en":"Section 71."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Election on Recall. - Upon the filing of a valid resolution or petition for recall with the appropriate local office of the COMELEC, the Commission or its duly authorized representative shall set the date of the election on recall, which shall not be later than thirty (30) days after the filing of the resolution or petition for recall in the case of the barangay, city, or municipal officials. and forty-five (45) days in the case of provincial officials. The official or officials sought to be recalled shall automatically be considered as duly registered candidate or candidates to the pertinent positions and, like other candidates, shall be entitled to be voted upon."}},{"id":"PH-H5648-A72","no":72,"noLabel":{"en":"Section 72."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Effectivity of Recall. - The recall of an elective local official shall be effective only upon the election and proclamation of a successor in the person of the candidate receiving the highest number of votes cast during the election on recall. Should the official sought to be recalled receive the highest number of votes, confidence in him is thereby affirmed, and he shall continue in office."}},{"id":"PH-H5648-A73","no":73,"noLabel":{"en":"Section 73."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Prohibition from Resignation. - The elective local official sought to be recalled shall not be allowed to resign while the recall process is in progress."}},{"id":"PH-H5648-A74","no":74,"noLabel":{"en":"Section 74."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Limitations on Recall. -\n(a) Any elective local official may be the subject of a recall election only once during his term of office for loss of confidence.\n(b) No recall shall take place within one (1) year from the date of the official's assumption to office or one (1) year immediately preceding a regular local election."}},{"id":"PH-H5648-A75","no":75,"noLabel":{"en":"Section 75."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Expenses Incident to Recall Elections. - All expenses incident to recall elections shall be borne by the COMELEC. For this purpose, there shall be included in the annual General Appropriations Act a contingency fund at the disposal of the COMELEC for the conduct of recall elections.\nHUMAN RESOURCES AND DEVELOPMENT"}},{"id":"PH-H5648-A76","no":76,"noLabel":{"en":"Section 76."},"chapter":{"en":"TITLE III"},"text":{"en":"Organizational Structure and Staffing Pattern. - Every local government unit shall design and implement its own organizational structure and staffing pattern taking into consideration its service requirements and financial capability, subject to the minimum standards and guidelines prescribed by the Civil Service Commission."}},{"id":"PH-H5648-A77","no":77,"noLabel":{"en":"Section 77."},"chapter":{"en":"TITLE III"},"text":{"en":"Responsibility for Human Resources and Development. - The chief executive of every local government unit shall be responsible for human resources and development in his unit and shall take all personnel actions in accordance with the Constitutional provisions on civil service, pertinent laws, and rules and regulations thereon, including such policies, guidelines and standards as the Civil Service Commission may establish: Provided, That the local chief executive may employ emergency or casual employees or laborers paid on a daily wage or piecework basis and hired through job orders for local projects authorized by the sanggunian concerned, without need of approval or attestation by the Civil Service Commission: Provided, further, That the period of employment of emergency or casual laborers as provided in this Section shall not exceed six (6) months.\nThe Joint Commission on Local Government Personnel Administration organized pursuant to Presidential Decree Numbered Eleven Hundred thirty-six (P.D. No. 1136) is hereby abolished and its personnel, records, equipment and other assets transferred to the appropriate office in the Civil Service Commission."}},{"id":"PH-H5648-A78","no":78,"noLabel":{"en":"Section 78."},"chapter":{"en":"TITLE III"},"text":{"en":"Civil Service Law, Rules and Regulations, and Other Related Issuances. - All matters pertinent to human resources and development in local government units shall be governed by the civil service law and such rules and regulations and other issuances promulgated pursuant thereto, unless otherwise specified in this Code."}},{"id":"PH-H5648-A79","no":79,"noLabel":{"en":"Section 79."},"chapter":{"en":"TITLE III"},"text":{"en":"Limitation to Appointments. - No person shall be appointed in the career service of the local government if he is related within the fourth civil degree of consanguinity or affinity to the appointing or recommending authority."}},{"id":"PH-H5648-A80","no":80,"noLabel":{"en":"Section 80."},"chapter":{"en":"TITLE III"},"text":{"en":"Public Notice of Vacancy; Personnel Selection Board. -\n(a) Whenever a local executive decides to fill a vacant career position, there shall be posted notices of the vacancy in at least three (3) conspicuous public places in the local government unit concerned for a period of not less than fifteen (15) days.\n(b) There shall be established in every province, city or municipality a personnel selection board to assist the local chief executive in the judicious and objective selection or personnel for employment as well as for promotion, and in the formulation of such policies as would contribute to employee welfare.\n(c) The personnel selection board shall be headed by the local chief executive, and its members shall be determined by resolution of the sanggunian concerned. A representative of the Civil Service Commission, if any, and the personnel officer of the local government unit concerned shall be ex officio members of the board."}},{"id":"PH-H5648-A81","no":81,"noLabel":{"en":"Section 81."},"chapter":{"en":"TITLE III"},"text":{"en":"Compensation of Local Officials and Employees. - The compensation of local officials and personnel shall be determined by the sanggunian concerned: Provided, That the increase in compensation of elective local officials shall take effect only after the terms of office of those approving such increase shall have expired: Provided, further, That the increase in compensation of the appointive officials and employees shall take effect as provided in the ordinance authorizing such increase: Provided, however, That said increases shall not exceed the limitations on budgetary allocations for personal services provided under Title Five, Book II of this Code: Provided, finally, That such compensation may be based upon the pertinent provisions of Republic Act Numbered Sixty-seven fifty-eight (R.A. No 6758), otherwise known as the \"Compensation and Position Classification Act of 1989\".\nThe punong barangay, the sangguniang barangay member, the sangguniang kabataan chairman, the barangay treasurer, and the barangay secretary shall be entitled to such compensation, allowances, emoluments, and such other privileges as provided under Title One Book III of this Code.\nElective local officials shall be entitled to the same leave privileges as those enjoyed by appointive local officials, including the cumulation and commutation thereof."}},{"id":"PH-H5648-A82","no":82,"noLabel":{"en":"Section 82."},"chapter":{"en":"TITLE III"},"text":{"en":"Resignation of Elective Local Officials. -\n(a) Resignations by elective local officials shall be deemed effective only upon acceptance by the following authorities:\n(1) The President, in the case of governors, vice-governors, and mayors and vice-mayors of highly urbanized cities and independent component cities;\n(2) The governor, in the case of municipal mayors, municipal vice-mayors, city mayors and city vice-mayors of component cities;\n(3) The sanggunian concerned, in the case of sanggunian members; and\n(4) The city or municipal mayor, in the case of barangay officials.\n(b) Copies of the resignation letters of elective local officials, together with the action taken by the aforesaid authorities, shall be furnished the Department of the Interior and Local Government.\n(c) The resignation shall be deemed accepted if not acted upon by the authority concerned within fifteen (15) days from receipt thereof.\n(d) Irrevocable resignations by sanggunian members shall be deemed accepted upon presentation before an open session of the sanggunian concerned and duly entered in its records: Provided, however, That this subsection does not apply to sanggunian members who are subject to recall elections or to cases where existing laws prescribed the manner of acting upon such resignations."}},{"id":"PH-H5648-A83","no":83,"noLabel":{"en":"Section 83."},"chapter":{"en":"TITLE III"},"text":{"en":"Grievance Procedure. - In every local government unit, the local chief executive shall establish a procedure to inquire into, act upon, resolve or settle complaints and grievances presented by local government employees."}},{"id":"PH-H5648-A84","no":84,"noLabel":{"en":"Section 84."},"chapter":{"en":"TITLE III"},"text":{"en":"Administrative Discipline. - Investigation and adjudication of administrative complaints against appointive local officials and employees as well as their suspension and removal shall be in accordance with the civil service law and rules and other pertinent laws. The results of such administrative investigations shall be reported to the Civil Service Commission."}},{"id":"PH-H5648-A85","no":85,"noLabel":{"en":"Section 85."},"chapter":{"en":"TITLE III"},"text":{"en":"Preventive Suspension of Appointive Local Officials and Employees. -\n(a) The local chief executives may preventively suspend for a period not exceeding sixty (60) days and subordinate official or employee under his authority pending investigation if the charge against such official or employee involves dishonesty, oppression or grave misconduct or neglect in the performance of duty, or if there is reason to believe that the respondent is guilty of the charges which would warrant his removal from the service.\n(b) Upon expiration of the preventive suspension, the suspended official or employee shall be automatically reinstated in office without prejudice to the continuation of the administrative proceedings against him until its termination. If the delay in the proceedings of the case is due to the fault, neglect or request of the respondent, the time of the delay shall not be counted in computing the period of suspension herein provided."}},{"id":"PH-H5648-A86","no":86,"noLabel":{"en":"Section 86."},"chapter":{"en":"TITLE III"},"text":{"en":"Administrative Investigation. - In any local government unit, administrative investigation may be conducted by a person or a committee duly authorized by the local chief executive. Said person or committee shall conduct hearings on the cases brought against appointive local officials and employees and submit their findings and recommendations to the local chief executive concerned within fifteen (15) days from the conclusion of the hearings. The administrative cases herein mentioned shall be decided within ninety (90) days from the time the respondent is formally notified of the charges."}},{"id":"PH-H5648-A87","no":87,"noLabel":{"en":"Section 87."},"chapter":{"en":"TITLE III"},"text":{"en":"Disciplinary Jurisdiction. - Except as otherwise provided by law, the local chief executive may impose the penalty of removal from service, demotion in rank, suspension for not more than one (1) year without pay, fine in an amount not exceeding six (6) months salary, or reprimand and otherwise discipline subordinate officials and employees under his jurisdiction. If the penalty imposed is suspension without pay for not more than thirty (30) days, his decision shall be final. If the penalty imposed is heavier than suspension of thirty (30) days, the decision shall be appealable to the Civil Service Commission, which shall decide the appeal within thirty (30) days from receipt thereof."}},{"id":"PH-H5648-A88","no":88,"noLabel":{"en":"Section 88."},"chapter":{"en":"TITLE III"},"text":{"en":"Execution Pending Appeal. - An appeal shall not prevent the execution of a decision of removal or suspension of a respondent-appellant. In case the respondent-appellant is exonerated, he shall be reinstated to his position with all the rights and privileges appurtenant thereto from the time he had been deprived thereof."}},{"id":"PH-H5648-A89","no":89,"noLabel":{"en":"Section 89."},"chapter":{"en":"TITLE III"},"text":{"en":"Prohibited Business and Pecuniary Interest. -\n(a) It shall be unlawful for any local government official or employee, directly or indirectly, to:\n(1) Engage in any business transaction with the local government unit in which he is an official or employee or over which he has the power of supervision, or with any of its authorized boards, officials, agents, or attorneys, whereby money is to be paid, or property or any other thing of value is to be transferred, directly or indirectly, out of the resources of the local government unit to such person or firm;\n(2) Hold such interests in any cockpit or other games licensed by a local government unit;\n(3) Purchase any real estate or other property forfeited in favor of such local government unit for unpaid taxes or assessment, or by virtue of a legal process at the instance of the said local government unit;\n(4) Be a surety for any person contracting or doing business with the local government unit for which a surety is required; and\n(5) Possess or use any public property of the local government unit for private purposes.\n(b) All other prohibitions governing the conduct of national public officers relating to prohibited business and pecuniary interest so provided for under Republic Act Numbered Sixty-seven thirteen (R.A. No. 6713) otherwise known as the \"Code of Conduct and Ethical Standards for Public Officials and Employees\" and other laws shall also be applicable to local government officials and employees."}},{"id":"PH-H5648-A90","no":90,"noLabel":{"en":"Section 90."},"chapter":{"en":"TITLE III"},"text":{"en":"Practice of Profession. -\n(a) All governors, city and municipal mayors are prohibited from practicing their profession or engaging in any occupation other than the exercise of their functions as local chief executives.\n(b) Sanggunian members may practice their professions, engage in any occupation, or teach in schools except during session hours: Provided, That sanggunian members who are also members of the Bar shall not:\n(1) Appear as counsel before any court in any civil case wherein a local government unit or any office, agency, or instrumentality of the government is the adverse party;\n(2) Appear as counsel in any criminal case wherein an officer or employee of the national or local government is accused of an offense committed in relation to his office.\n(3) Collect any fee for their appearance in administrative proceedings involving the local government unit of which he is an official; and\n(4) Use property and personnel of the government except when the sanggunian member concerned is defending the interest of the government.\n(c) Doctors of medicine may practice their profession even during official hours of work only on occasions of emergency: Provided, That the officials concerned do not derive monetary compensation therefrom."}},{"id":"PH-H5648-A91","no":91,"noLabel":{"en":"Section 91."},"chapter":{"en":"TITLE III"},"text":{"en":"Statement of Assets and Liabilities. - (a) Officials and employees of local government units shall file sworn statements of assets, liabilities and net worth, lists of relatives within the fourth civil degree of consanguinity or affinity in government service, financial and business interests, and personnel data sheets as required by law."}},{"id":"PH-H5648-A92","no":92,"noLabel":{"en":"Section 92."},"chapter":{"en":"TITLE III"},"text":{"en":"Oath of Office. - (a) All elective and appointive local officials and employees shall, upon assumption to office, subscribe to an oath or affirmation of office in the prescribed form. The oath or affirmation of office shall be filed with the office of the local chief executive concerned. A copy of the oath or affirmation of office of all elective and appointive local officials and employees shall be preserved in the individual personal records file under the custody of the personnel office, division, or section of the local government unit concerned."}},{"id":"PH-H5648-A93","no":93,"noLabel":{"en":"Section 93."},"chapter":{"en":"TITLE III"},"text":{"en":"Partisan Political Activity. - No local official or employee in the career civil service shall engage directly or indirectly in any partisan political activity or take part in any election, initiative, referendum, plebiscite, or recall, except to vote, nor shall he use his official authority or influence to cause the performance of any political activity by any person or body. He may, however, express his views on current issues, or mention the names of certain candidates for public office whom he supports. Elective local officials may take part in partisan political and electoral activities, but it shall be unlawful for them to solicit contributions from their subordinates or subject these subordinates to any of the prohibited acts under the Omnibus Election Code."}},{"id":"PH-H5648-A94","no":94,"noLabel":{"en":"Section 94."},"chapter":{"en":"TITLE III"},"text":{"en":"Appointment of Elective and Appointive Local Officials; Candidates Who Lost in an Election. - (a) No elective or appointive local official shall be eligible for appointment or designation in any capacity to any public office or position during his tenure.\nUnless otherwise allowed by law or by the primary functions of his position, no elective or appointive local official shall hold any other office or employment in the government or any subdivision, agency or instrumentality thereof, including government-owned or controlled corporations or their subsidiaries."}},{"id":"PH-H5648-A95","no":95,"noLabel":{"en":"Section 95."},"chapter":{"en":"TITLE III"},"text":{"en":"Additional or Double Compensation. - No elective or appointive local official or employee shall receive additional, double, or indirect compensation, unless specifically authorized by law, nor accept without the consent of Congress, any present, emoluments, office, or title of any kind from any foreign government. Pensions or gratuities shall not be considered as additional, double, or indirect compensation."}},{"id":"PH-H5648-A96","no":96,"noLabel":{"en":"Section 96."},"chapter":{"en":"TITLE III"},"text":{"en":"Permission to Leave Station. -\n(a) Provincial, city, municipal, and barangay appointive officials going on official travel shall apply and secure written permission from their respective local chief executives before departure. The application shall specify the reasons for such travel, and the permission shall be given or withheld based on considerations of public interest, financial capability of the local government unit concerned and urgency of the travel.\nShould the local chief executive concerned fall to act upon such application within four (4) working days from receipt thereof, it shall be deemed approved.\n(b) Mayors of component cities and municipalities shall secure the permission of the governor concerned for any travel outside the province.\n(c) Local government officials traveling abroad shall notify their respective sanggunian: Provided, That when the period of travel extends to more than three (3) months, during periods of emergency or crisis or when the travel involves the use of public funds, permission from the Office of the President shall be secured.\n(d) Field officers of national agencies or offices assigned in provinces, cities, and municipalities shall not leave their official stations without giving prior written notice to the local chief executive concerned. Such notice shall state the duration of travel and the name of the officer whom he shall designate to act for and in his behalf during his absence."}},{"id":"PH-H5648-A97","no":97,"noLabel":{"en":"Section 97."},"chapter":{"en":"TITLE III"},"text":{"en":"Annual Report. - On or before March 31 of each year, every local chief executive shall submit an annual report to the sanggunian concerned on the socio-economic, political and peace and order conditions, and other matters concerning the local government unit, which shall cover the immediately preceding calendar year. A copy of the report shall be forwarded to the Department of the Interior and Local Government. Component cities and municipalities shall likewise provide the sangguniang panlalawigan copies of their respective annual reports.\nLOCAL SCHOOL BOARDS"}},{"id":"PH-H5648-A98","no":98,"noLabel":{"en":"Section 98."},"chapter":{"en":"TITLE IV"},"text":{"en":"Creation, Composition, and Compensation. -\n(a) There shall be established in every province, city, or municipality a provincial, city, or municipal school board, respectively.\n(b) The composition of local school boards shall be as follows:\n(1) The provincial school board shall be composed of the governor and the division superintendent of schools as co-chairman; the chairman of the education committee of the sangguniang panlalawigan, the provincial treasurer, the representative of the \"pederasyon ng mga sangguniang kabataan\" in the sangguniang panlalawigan, the duly elected president of the provincial federation of parents-teachers associations, the duly elected representative of the teachers' organizations in the province, and the duly elected representative of the non-academic personnel of public schools in the province, as members;\n(2) The city school board shall be composed of the city mayor and the city superintendent of schools as co-chairmen; the chairman of the education committee of the sangguniang panlungsod, the city treasurer, the representative of the \"pederasyon ng mga sangguniang kabataan\" in the sangguniang panlungsod, the duly elected president of the city federation of parents- teachers associations, the duly elected representative of the teachers' organizations in the city, and the duly elected representative of the non-academic personnel of public schools in the city, as members; and\n(3) The municipal school board shall be composed of the municipal mayor and the district supervisor of schools as co-chairmen; the chairman of the education committee of the sangguniang bayan, the municipal treasurer, the representative of the \"pederasyon ng mga sangguniang kabataan\" in the sangguniang bayan, the duly elected president of the municipal federation of parent-teacher associations, the duly elected representative of the teachers' organizations in the municipality, and the duly elected representative of the non-academic personnel of public schools in the municipality, as members.\n(c) In the event that a province or city has two (2) or more school superintendents, and in the event that a municipality has two (2) or more district supervisors, the co-chairman of the local school board shall be determined as follows:\n(1) The Department of Education, Culture and Sports shall designate the co-chairman for the provincial and city school boards; and\n(2) The division superintendent of schools shall designate the district supervisor who shall serve as co-chairman of the municipal school board.\n(d) The performance of the duties and responsibilities of the abovementioned officials in their respective local school boards shall not be delegated."}},{"id":"PH-H5648-A99","no":99,"noLabel":{"en":"Section 99."},"chapter":{"en":"TITLE IV"},"text":{"en":"Functions of Local School Boards. - The provincial, city or municipal school board shall:\n(a) Determine, in accordance with the criteria set by the Department of Education, Culture and Sports, the annual supplementary budgetary needs for the operation and maintenance of public schools within the province, city, or municipality, as the case may be, and the supplementary local cost of meeting such as needs, which shall be reflected in the form of an annual school board budget corresponding to its share of the proceeds of the special levy on real property constituting the Special Education Fund and such other sources of revenue as this Code and other laws or ordinances may provide;\n(b) Authorize the provincial, city or municipal treasurer, as the case may be, to disburse funds from the Special Education Fund pursuant to the budget prepared and in accordance with existing rules and regulations;\n(c) Serve as an advisory committee to the sanggunian concerned on educational matters such as, but not limited to, the necessity for and the uses of local appropriations for educational purposes; and\n(d) Recommend changes in the names of public schools within the territorial jurisdiction of the local government unit for enactment by the sanggunian concerned.\nThe Department of Education, Culture and Sports shall consult the local school board on the appointment of division superintendents, district supervisors, school principals, and other school officials."}},{"id":"PH-H5648-A100","no":100,"noLabel":{"en":"Section 100."},"chapter":{"en":"TITLE IV"},"text":{"en":"Meetings and Quorum; Budget. -\n(a) The local school board shall meet at least once a month or as often as may be necessary.\n(b) Any of the co-chairmen may call a meeting. A majority of all its members shall constitute a quorum. However, when both co-chairmen are present in a meeting, the local chief executive concerned, as a matter of protocol, shall be given preference to preside over the meeting. The division superintendent, city superintendent or district supervisor, as the case may be, shall prepare the budget of the school board concerned. Such budget shall be supported by programs, projects, and activities of the school board for the ensuing fiscal year. The affirmative vote of the majority of all the members shall be necessary to approve the budget.\n(c) The annual school board budget shall give priority to the following:\n(1) Construction, repair, and maintenance of school buildings and other facilities of public elementary and secondary schools;\n(2) Establishment and maintenance of extension classes where necessary; and\n(3) Sports activities at the division, district, municipal, and barangay levels."}},{"id":"PH-H5648-A101","no":101,"noLabel":{"en":"Section 101."},"chapter":{"en":"TITLE IV"},"text":{"en":"Compensation and Remuneration. - The co-chairmen and members of the provincial, city or municipal school board shall perform their duties as such without compensation or remuneration. Members thereof who are not government officials or employees shall be entitled to necessary traveling expenses and allowances chargeable against the funds of the local school board concerned, subject to existing accounting and auditing rules and regulations.\nLOCAL HEALTH BOARDS"}},{"id":"PH-H5648-A102","no":102,"noLabel":{"en":"Section 102."},"chapter":{"en":"TITLE V"},"text":{"en":"Creation and Composition. -\n(a) There shall be established a local health board in every province, city, or municipality. The composition of the local health boards shall be as follows:\n(1) The provincial health board shall be headed by the governor as chairman, the provincial health officer as vice-chairman, and the chairman of the committee on health of the sangguniang panlalawigan, a representative from the private sector or non-governmental organizations involved in health services, and a representative of the Department of Health in the province, as members;\n(2) The city health board shall be headed by the city mayor as chairman, the city health officer as vice-chairman, and the chairman of the committee on health of the sangguniang panlungsod, a representative from the private sector or non-governmental organizations involved in health services, and a representative of the Department of Health in the city, as members; and\n(3) The municipal health board shall be headed by the municipal mayor as chairman, the municipal health officer as vice-chairman, and the chairman of the committee on health of the sangguniang bayan, a representative from the private sector or non-governmental organizations involved in health services, and a representative of the Department of Health in the municipality, as members.\n(b) The functions of the local health board shall be:\n(1) To propose to the sanggunian concerned, in accordance with standards and criteria set by the Department of Health, annual budgetary allocations for the operation and maintenance of health facilities and services within the municipality, city or province, as the case may be;\n(2) To serve as an advisory committee to the sanggunian concerned on health matters such as, but not limited to, the necessity for, and application of local appropriations for public health purposes; and\n(3) Consistent with the technical and administrative standards of the Department of Health, create committees which shall advise local health agencies on matters such as, but not limited to, personnel selection and promotion, bids and awards, grievance and complaints, personnel discipline, budget review, operations review and similar functions."}},{"id":"PH-H5648-A103","no":103,"noLabel":{"en":"Section 103."},"chapter":{"en":"TITLE V"},"text":{"en":"Meetings and Quorum. -\n(a) The board shall meet at least once a month or as may be necessary.\n(b) A majority of the members of the board shall constitute a quorum, but the chairman or the vice- chairman must be present during meetings where budgetary proposals are being prepared or considered. The affirmative vote of all the majority of the members shall be necessary to approve such proposals."}},{"id":"PH-H5648-A104","no":104,"noLabel":{"en":"Section 104."},"chapter":{"en":"TITLE V"},"text":{"en":"Compensation and Remuneration. - The chairman, vice-chairman, and members of the provincial, city or municipal health board shall perform their duties as such without compensation or remuneration. Members thereof who are not government officials or employees shall be entitled to necessary traveling expenses and allowances chargeable against the funds of the local health board concerned, subject to existing accounting and auditing rules and regulations."}},{"id":"PH-H5648-A105","no":105,"noLabel":{"en":"Section 105."},"chapter":{"en":"TITLE V"},"text":{"en":"Direct National Supervision and Control by the Secretary of Health. - In cases of epidemics, pestilence, and other widespread public health dangers, the Secretary of Health may, upon the direction of the President and in consultation with the local government unit concerned, temporarily assume direct supervision and control over health operations in any local government unit for the duration of the emergency, but in no case exceeding a cumulative period of six (6) months. With the concurrence of the government unit concerned, the period for such direct national control and supervision may be further extended.\nLOCAL DEVELOPMENT COUNCILS"}},{"id":"PH-H5648-A106","no":106,"noLabel":{"en":"Section 106."},"chapter":{"en":"TITLE VI"},"text":{"en":"Local Development Councils. - (a) Each local government unit shall have a comprehensive multi-sectoral development plan to be initiated by its development council and approved by its sanggunian. For this purpose, the development council at the provincial, city, municipal, or barangay level, shall assist the corresponding sanggunian in setting the direction of economic and social development, and coordinating development efforts within its territorial jurisdiction."}},{"id":"PH-H5648-A107","no":107,"noLabel":{"en":"Section 107."},"chapter":{"en":"TITLE VI"},"text":{"en":"Composition of Local Development Councils. - The composition of the local development council shall be as follows:\n(1) Members of the sangguniang barangay;\n(2) Representatives of non-governmental organizations operating in the barangay who shall constitute not less than one fourth (¼) of the members of the fully organized council;\n(3) A representative of the congressman.\n(b) The city or municipal development council shall be headed by the mayor and shall be composed of the following members:\n(1) All punong barangays in the city or municipality;\n(2) The chairman of the committee on appropriations of the sangguniang panlungsod or sangguniang bayan concerned;\n(3) The congressman or his representative; and\n(4) Representatives of non-governmental organizations operating in the city or municipality, as the case may be, who shall constitute not less than one-fourth (¼) of the members of the fully organized council.\n(c) The provincial development council shall be headed by the governor and shall be composed of the following members:\n(1) All mayors of component cities and municipalities;\n(2) The chairman of the committee on appropriations of the sangguniang panlalawigan;\n(3) The congressman or his representative; and\n(4) Representatives of non-governmental organizations operating in the province, who shall constitute not less than one-fourth (¼) of the members of the fully organized council.\n(d) The local development councils may call upon any local official concerned or any official of national agencies or offices in the local government unit to assist in the formulation of their respective development plans and public investment programs."}},{"id":"PH-H5648-A108","no":108,"noLabel":{"en":"Section 108."},"chapter":{"en":"TITLE VI"},"text":{"en":"Representation of Non-governmental Organizations. - Within a period of sixty (60) days from the start of organization of local development councils, the non-governmental organizations shall choose from among themselves their representatives to said councils. The local sanggunian concerned shall accredit non-governmental organizations subject to such criteria as may be provided by law."}},{"id":"PH-H5648-A109","no":109,"noLabel":{"en":"Section 109."},"chapter":{"en":"TITLE VI"},"text":{"en":"Functions of Local Development Councils. -\n(a) The provincial, city, and municipal development councils shall exercise the following functions:\n(1) Formulate long-term, medium-term, and annual socio-economic development plans and policies;\n(2) Formulate the medium-term and annual public investment programs;\n(3) Appraise and prioritize socio-economic development programs and projects;\n(4) Formulate local investment incentives to promote the inflow and direction of private investment capital;\n(5) Coordinate, monitor, and evaluate the implementation of development programs and projects; and\n(6) Perform such other functions as may be provided by law or component authority.\n(b) The barangay development council shall exercise the following functions:\n(1) Mobilize people's participation in local development efforts;\n(2) Prepare barangay development plans based on local requirements;\n(3) Monitor and evaluate the implementation of national or local programs and projects; and\n(4) Perform such other functions as may be provided by law or competent authority."}},{"id":"PH-H5648-A110","no":110,"noLabel":{"en":"Section 110."},"chapter":{"en":"TITLE VI"},"text":{"en":"Meetings and Quorum. - The local development council shall meet at least once every six (6) months or as often as may be necessary."}},{"id":"PH-H5648-A111","no":111,"noLabel":{"en":"Section 111."},"chapter":{"en":"TITLE VI"},"text":{"en":"Executive Committee. - The local development council shall create an executive committee to represent it and act in its behalf when it is not in session. The composition of the executive committee shall be as follows:\n(1) The executive committee of the provincial development council shall be composed of the governor as chairman, the representative of component city and municipal mayors to be chosen from among themselves, the chairman of the committee on appropriations of the sangguniang panlalawigan, the president of the provincial league of barangays, and a representative of non-governmental organizations that are represented in the council, as members;\n(2) The executive committee of the city or municipal development council shall be composed of the mayor as chairman, the chairman of the committee on appropriations of the sangguniang panlalawigan, the president of the city or municipal league of barangays, and a representative of non-governmental organizations that are represented in the council, as members; and\n(3) The executive committee of the barangay development council shall be composed of the punong barangay as chairman, a representative of the sangguniang barangay to be chosen from among its members, and a representative of non-governmental organizations that are represented in the council, as members.\n(b) The executive committee shall exercise the following powers and functions:\n(1) Ensure that the decision of the council are faithfully carried out and implemented;\n(2) Act on matters requiring immediate attention or action by the council;\n(3) Formulate policies, plans, and programs based on the general principles laid down by the council; and\n(4) Act on other matters that may be authorized by the council."}},{"id":"PH-H5648-A112","no":112,"noLabel":{"en":"Section 112."},"chapter":{"en":"TITLE VI"},"text":{"en":"Sectoral or Functional Committees. - The local development councils may form sectoral or functional committees to assist them in the performance of their functions."}},{"id":"PH-H5648-A113","no":113,"noLabel":{"en":"Section 113."},"chapter":{"en":"TITLE VI"},"text":{"en":"Secretariat. - There is hereby constituted for each local development council a secretariat which shall be responsible for providing technical support, documentation of proceedings, preparation of reports and such other assistance as may be required in the discharge of its functions. The local development council may avail of the services of any non-governmental organization or educational or research institution for this purpose.\nThe secretariats of the provincial, city, and municipal development councils shall be headed by their respective planning and development coordinators. The secretariat of the barangay development council shall be headed by the barangay secretary who shall be assisted by the city or municipal planning and development coordinator concerned."}},{"id":"PH-H5648-A114","no":114,"noLabel":{"en":"Section 114."},"chapter":{"en":"TITLE VI"},"text":{"en":"Relation of Local Development Councils to the Sanggunian and the Regional Development Council. -\n(a) The policies, programs, and projects proposed by local development councils shall be submitted to the sanggunian concerned for appropriate action.\n(b) The approved development plans of provinces, highly-urbanized cities, and independent component cities shall be submitted to the regional development council, which shall be integrated into the regional development plan for submission to the National Economic and Development Authority, in accordance with existing laws."}},{"id":"PH-H5648-A115","no":115,"noLabel":{"en":"Section 115."},"chapter":{"en":"TITLE VI"},"text":{"en":"Budget Information. - The Department of Budget and Management shall furnish the various local development councils information on financial resources and budgetary allocations applicable to their respective jurisdictions to guide them in their planning functions.\nLOCAL PEACE AND ORDER COUNCIL"}},{"id":"PH-H5648-A116","no":116,"noLabel":{"en":"Section 116."},"chapter":{"en":"TITLE VII"},"text":{"en":"Organization. - There is hereby established in every province, city and municipality a local peace and order council, pursuant to Executive Order Numbered Three hundred nine (E.O. No. 309), as amended, Series of 1988. The local peace and order councils shall have the same composition and functions as those prescribed by said executive order.\nAUTONOMOUS SPECIAL ECONOMIC ZONES"}},{"id":"PH-H5648-A117","no":117,"noLabel":{"en":"Section 117."},"chapter":{"en":"TITLE VIII"},"text":{"en":"Establishment of Autonomous Special Economic Zones. - The establishment by law of autonomous special economic zones in selected areas of the country shall be subject to concurrence by the local government units included therein.\nOTHER PROVISIONS APPLICABLE TO LOCAL GOVERNMENT UNITS\nCHAPTER I\nSettlement of Boundary Disputes"}},{"id":"PH-H5648-A118","no":118,"noLabel":{"en":"Section 118."},"chapter":{"en":"TITLE IX"},"text":{"en":"Jurisdictional Responsibility for Settlement of Boundary Dispute. - Boundary disputes between and among local government units shall, as much as possible, be settled amicably. To this end:\n(a) Boundary disputes involving two (2) or more barangays in the same city or municipality shall be referred for settlement to the sangguniang panlungsod or sangguniang bayan concerned.\n(b) Boundary disputes involving two (2) or more municipalities within the same province shall be referred for settlement to the sangguniang panlalawigan concerned.\n(c) Boundary disputes involving municipalities or component cities of different provinces shall be jointly referred for settlement to the sanggunians of the province concerned.\n(d) Boundary disputes involving a component city or municipality on the one hand and a highly urbanized city on the other, or two (2) or more highly urbanized cities, shall be jointly referred for settlement to the respective sanggunians of the parties.\n(e) In the event the sanggunian fails to effect an amicable settlement within sixty (60) days from the date the dispute was referred thereto, it shall issue a certification to that effect. Thereafter, the dispute shall be formally tried by the sanggunian concerned which shall decide the issue within sixty (60) days from the date of the certification referred to above."}},{"id":"PH-H5648-A119","no":119,"noLabel":{"en":"Section 119."},"chapter":{"en":"TITLE IX"},"text":{"en":"Appeal. - Within the time and manner prescribed by the Rules of Court, any party may elevate the decision of the sanggunian concerned to the proper Regional Trial Court having jurisdiction over the area in dispute. The Regional Trial Court shall decide the appeal within one (1) year from the filing thereof. Pending final resolution of the disputed area prior to the dispute shall be maintained and continued for all legal purposes.\nLocal Initiative and Referendum"}},{"id":"PH-H5648-A120","no":120,"noLabel":{"en":"Section 120."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Local Initiative Defined. - Local initiative is the legal process whereby the registered voters of a local government unit may directly propose, enact, or amend any ordinance."}},{"id":"PH-H5648-A121","no":121,"noLabel":{"en":"Section 121."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Who May Exercise. - The power of local initiative and referendum may be exercised by all registered voters of the provinces, cities, municipalities, and barangays."}},{"id":"PH-H5648-A122","no":122,"noLabel":{"en":"Section 122."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Procedure in Local Initiative. -\n(a) Not less than one thousand (1,000) registered voters in case of provinces and cities, one hundred (100) in case of municipalities, and fifty (50) in case of barangays, may file a petition with the sanggunian concerned proposing the adoption, enactment, repeal, or amendment of an ordinance.\n(b) If no favorable action thereon is taken by the sanggunian concerned within thirty (30) days from its presentation, the proponents, through their duly authorized and registered representatives, may invoke their power of initiative, giving notice thereof to the sanggunian concerned.\n(c) The proposition shall be numbered serially starting from Roman numeral I. The COMELEC or its designated representative shall extend assistance in the formulation of the proposition.\n(d) Two (2) or more propositions may be submitted in an initiative.\n(e) Proponents shall have ninety (90) days in case of provinces and cities, sixty (60) days in case of municipalities, and thirty (30) days in case of barangays, from notice mentioned in subsection (b) hereof to collect the required number of signatures. (f) The petition shall be signed before the election registrar. or his designated representatives, in the presence of a representative of the proponent, and a representative of the sanggunian concerned in a public place in the local government unit, as the case may be. Stations for collecting signatures may be established in as many places as may be warranted.\n(g) Upon the lapse of the period herein provided, the COMELEC, through its office in the local government unit concerned, shall certify as to whether or not the required number of signatures has been obtained. Failure to obtain the required number defeats the proposition.\n(h) If the required number of signatures is obtained, the COMELEC shall then set a date for the initiative during which the proposition shall be submitted to the registered voters in the local government unit concerned for their approval within sixty (60) days from the date of certification by the COMELEC, as provided in subsection (g) hereof, in case of provinces and cities, forty-five (45) days in case of municipalities, and thirty (30) days in case of barangays. The initiative shall then be held on the date set, after which the results thereof shall be certified and proclaimed by the COMELEC."}},{"id":"PH-H5648-A123","no":123,"noLabel":{"en":"Section 123."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Effectivity of Local Propositions. - If the proposition is approved by a majority of the votes cast, it shall take effect fifteen (15) days after certification by the COMELEC as if affirmative action thereon had been made by the sanggunian and local chief executive concerned. If it fails to obtain said number of votes, the proposition is considered defeated."}},{"id":"PH-H5648-A124","no":124,"noLabel":{"en":"Section 124."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Limitations on Local Initiative. -\n(a) The power of local initiative shall not be exercised more than once a year.\n(b) Initiative shall extend only to subjects or matters which are within the legal powers of the sanggunian to enact.\n(c) If at any time before the initiative is held, the sanggunian concerned adopts in toto the proposition presented and the local chief executive approves the same, the initiative shall be cancelled. However, those against such action may, if they so desire, apply for initiative in the manner herein provided."}},{"id":"PH-H5648-A125","no":125,"noLabel":{"en":"Section 125."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Limitations upon Sanggunians. - Any proposition or ordinance approved through the system of initiative and referendum as herein provided shall not be repealed, modified or amended by the sanggunian concerned within six (6) months from the date of the approval thereof, and may be amended, modified or repealed by the sanggunian within three (3) years thereafter by a vote of three-fourths (3/4) of all its members: Provided, That in case of barangays, the period shall be eighteen (18) months after the approval thereof."}},{"id":"PH-H5648-A126","no":126,"noLabel":{"en":"Section 126."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Local Referendum Defined. - Local referendum is the legal process whereby the registered voters of the local government units may approve, amend or reject any ordinance enacted by the sanggunian.\nThe local referendum shall be held under the control and direction of the COMELEC within sixty (60) days in case of provinces and cities, forty-five (45) days in case of municipalities and thirty (30) days in case of barangays.\nThe COMELEC shall certify and proclaim the results of the said referendum."}},{"id":"PH-H5648-A127","no":127,"noLabel":{"en":"Section 127."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Authority of Courts. - Nothing in this Chapter shall prevent or preclude the proper courts from declaring null and void any proposition approved pursuant to this Chapter for violation of the Constitution or want of capacity of the sanggunian concerned to enact the said measure.\nLOCAL TAXATION AND FISCAL MATTERS\nLOCAL GOVERNMENT TAXATION\nCHAPTER I\nGeneral Provisions"}},{"id":"PH-H5648-A128","no":128,"noLabel":{"en":"Section 128."},"chapter":{"en":"TITLE I"},"text":{"en":"Scope. - The provisions herein shall govern the exercise by provinces, cities, municipalities, and barangays of their taxing and other revenue-raising powers."}},{"id":"PH-H5648-A129","no":129,"noLabel":{"en":"Section 129."},"chapter":{"en":"TITLE I"},"text":{"en":"Power to Create Sources of Revenue. - Each local government unit shall exercise its power to create its own sources of revenue and to levy taxes, fees, and charges subject to the provisions herein, consistent with the basic policy of local autonomy. Such taxes, fees, and charges shall accrue exclusively to the local government units."}},{"id":"PH-H5648-A130","no":130,"noLabel":{"en":"Section 130."},"chapter":{"en":"TITLE I"},"text":{"en":"Fundamental Principles. - The following fundamental principles shall govern the exercise of the taxing and other revenue-raising powers of local government units:\n(a) Taxation shall be uniform in each local government unit;\n(b) Taxes, fees, charges and other impositions shall:\n(1) be equitable and based as far as practicable on the taxpayer's ability to pay;\n(2) be levied and collected only for public purposes;\n(3) not be unjust, excessive, oppressive, or confiscatory;\n(4) not be contrary to law, public policy, national economic policy, or in the restraint of trade;\n(c) The collection of local taxes, fees, charges and other impositions shall in no case be let to any private person;\n(d) The revenue collected pursuant to the provisions of this Code shall inure solely to the benefit of, and be subject to the disposition by, the local government unit levying the tax, fee, charge or other imposition unless otherwise specifically provided herein; and,\n(e) Each local government unit shall, as far as practicable, evolve a progressive system of taxation."}},{"id":"PH-H5648-A131","no":131,"noLabel":{"en":"Section 131."},"chapter":{"en":"TITLE I"},"text":{"en":"Definition of Terms. - When used in this Title, the term:\n(a) \"Agricultural Product\" includes the yield of the soil, such as corn, rice, wheat, rye, hay. coconuts, sugarcane, tobacco, root crops, vegetables, fruits, flowers, and their by-products; ordinary salt; all kinds of fish; poultry; and livestock and animal products, whether in their original form or not.\nThe phrase \"whether in their original form or not\" refers to the transformation of said products by the farmer, fisherman, producer or owner through the application of processes to preserve or otherwise to prepare said products for market such as freezing, drying, salting, smoking, or stripping for purposes of preserving or otherwise preparing said products for market;\n(b) \"Amusement\" is a pleasurable diversion and entertainment. It is synonymous to relaxation, avocation, pastime, or fun;\n(c) \"Amusement Places\" include theaters, cinemas, concert halls, circuses and other places of amusement where one seeks admission to entertain oneself by seeing or viewing the show or performances;\n(d) \"Business\" means trade or commercial activity regularly engaged in as a means of livelihood or with a view to profit;\n(e) \"Banks and other financial institutions\" include non-bank financial intermediaries, lending investors, finance and investment companies, pawnshops, money shops, insurance companies, stock markets, stock brokers and dealers in securities and foreign exchange, as defined under applicable laws, or rules and regulations thereunder;\n(f) \"Capital Investment\" is the capital which a person employs in any undertaking, or which he contributes to the capital of a partnership, corporation, or any other juridical entity or association in a particular taxing jurisdiction;\n(g) \"Charges\" refers to pecuniary liability, as rents or fees against persons or property;\n(h) \"Contractor\" includes persons, natural or juridical, not subject to professional tax under Section 139 of this Code, whose activity consists essentially of the sale of all kinds of services for a fee, regardless of whether or not the performance of the service calls for the exercise or use of the physical or mental faculties of such contractor or his employees.\nAs used in this Section, the term \"contractor\" shall include general engineering, general building and specialty contractors as defined under applicable laws; filling, demolition and salvage works contractors; proprietors or operators of mine drilling apparatus; proprietors or operators of dockyards; persons engaged in the installation of water system, and gas or electric light, heat, or power; proprietors or operators of smelting plants, engraving, plating, and plastic lamination establishments; proprietors or operators of establishments for repairing, repainting, upholstering, washing or greasing of vehicles, heavy equipment, vulcanizing, recapping and battery charging; proprietors or operators of furniture shops and establishments for planing or surfacing and recutting of lumber, and sawmills under contract to saw or cut logs belonging to others; proprietors or operators of dry cleaning or dyeing establishments, steam laundries, and laundries using washing machines; proprietors or owners of shops for the repair of any kind of mechanical and electrical devices, instruments, apparatus, or furniture and shoe repairing by machine or any mechanical contrivance; proprietors or operators of establishments or lots for parking purposes; proprietors or operators of tailor shops, dress shops, milliners and hatters, beauty parlors, barbershops, massage clinics, sauna, Turkish and Swedish baths, slenderizing and building salons and similar establishments; photographic studios; funeral parlors; proprietors or operators of hotels, motels, and lodging houses; proprietors or operators of arrastre and stevedoring, warehousing, or forwarding establishments; master plumbers, smiths, and house or sign painters; printers, bookbinders, lithographers; publishers except those engaged in the publication or printing of any newspaper, magazine, review or bulletin which appears at regular intervals with fixed prices for subscription and sale and which is not devoted principally to the publication and advertisements; business agents, private detective or watchman agencies, commercial and immigration brokers, and cinematographic film owners, lessors and distributors.\n(i) \"Corporation\" includes partnerships, no matter how created or organized, joint-stock companies, joint accounts (cuentas en participacion), associations or insurance companies but does not include general professional partnerships and a joint venture or consortium formed for the purpose of undertaking construction projects or engaging in petroleum, coal, geothermal, and other energy operations pursuant to an operating or consortium agreement under a service contract with the government. General professional partnership are partnerships formed by persons for the sole purpose of exercising their common profession, no part of the income of which is derived from engaging in any trade or business.\nThe term \"resident foreign\" when applied to a corporation means a foreign corporation not otherwise organized under the laws of the Philippines but engaged in trade or business within the Philippines;\n(j) \"Countryside and Barangay Business Enterprise\" refers to any business entity, association, or cooperative registered under the provisions of Republic Act Numbered Sixty-eight hundred ten (R.A. No. 6810), otherwise known as \"Magna Carta For Countryside And Barangay Business Enterprises (Kalakalan 20)\";\n(k) \"Dealer\" means one whose business is to buy and sell merchandise, goods, and chattels as a merchant. He stands immediately between the producer or manufacturer and the consumer and depends for his profit not upon the labor he bestows upon his commodities but upon the skill and foresight with which he watches the market;\n(l) \"Fee\" means a charge fixed by law or ordinance for the regulation or inspection of a business or activity;\n(m) \"Franchise\" is a right or privilege, affected with public interest which is conferred upon private persons or corporations, under such terms and conditions as the government and its political subdivisions may impose in the interest of public welfare, security, and safety;\n(n) \"Gross Sales or Receipts\" include the total amount of money or its equivalent representing the contract price, compensation or service fee, including the amount charged or materials supplied with the services and deposits or advance payments actually or constructively received during the taxable quarter for the services performed or to be performed for another person excluding discounts if determinable at the time of sales, sales return, excise tax, and value-added tax (VAT);\n(o) \"Manufacturer\" includes every person who, by physical or chemical process, alters the exterior texture or form or inner substance of any raw material or manufactured or partially manufactured product in such manner as to have been put in its original condition, or who by any such process alters the quality of any such raw material or manufactured or partially manufactured products so as to reduce it to marketable shape or prepare it for any of the use of industry, or who by any such process combines any such raw material or manufactured or partially manufactured products with other materials or products of the same or of different kinds and in such manner that the finished products of such process or manufacture can be put to a special use or uses to which such raw material or manufactured or partially manufactured products in their original condition could not have been put, and who in addition alters such raw material or manufactured or partially manufactured products, or combines the same to produce such finished products for the purpose of their sale or distribution to others and not for his own use or consumption;\n(p) \"Marginal Farmer or Fisherman\" refers to an individual engaged in subsistence farming or fishing which shall be limited to the sale, barter or exchange of agricultural or marine products produced by himself and his immediate family;\n(q) \"Motor Vehicle\" means any vehicle propelled by any power other than muscular power using the public roads, but excluding road rollers, trolley cars, street-sweepers, sprinklers, lawn mowers, bulldozers, graders, fork-lifts, amphibian trucks, and cranes if not used on public roads, vehicles which run only on rails or tracks, and tractors, trailers, and traction engines of all kinds used exclusively for agricultural purposes;\n(r) \"Municipal Waters\" includes not only streams, lakes, and tidal waters within the municipality, not being the subject of private ownership and not comprised within the national parks, public forest, timber lands, forest reserves or fishery reserves, but also marine waters included between two lines drawn perpendicularly to the general coastline from points where the boundary lines of the municipality or city touch the sea at low tide and a third line parallel with the general coastline and fifteen (15) kilometers from it. Where two (2) municipalities are so situated on the opposite shores that there is less than fifteen (15) kilometers of marine waters between them, the third line shall be equally distant from opposite shores of their respective municipalities;\n(s) \"Operator\" includes the owner, manager, administrator, or any other person who operates or is responsible for the operation of a business establishment or undertaking;\n(t) \"Peddler\" means any person who, either for himself or on commission, travels from place to place and sells his goods or offers to sell and deliver the same. Whether a peddler is a wholesale peddler or a retail peddler of a particular commodity shall be determined from the definition of wholesale dealer or retail dealer as provided in this Title;\n(u) \"Persons\" means every natural or juridical being, susceptible of rights and obligations or of being the subject of legal relations;\n(v) \"Residents\" refer to natural persons who have their habitual residence in the province, city, or municipality where they exercise their civil rights and fulfill their civil obligations, and to juridical persons for which the law or any other provisions creating or recognizing them fixes their residence in a particular province, city, or municipality. In the absence of such law, juridical persons are residents of the province, city, or municipality where they have their legal residence or principal place of business or where they conduct their principal business or occupation;\n(w) \"Retail\" means a sale where the purchaser buys the commodity for his own consumption, irrespective of the quantity of the commodity sold;\n(x) \"Vessel\" includes every type of boat, craft, or other artificial contrivance used, or capable of being used, as a means of transportation on water;\n(y) \"Wharfage\" means a fee assessed against the cargo of a vessel engaged in foreign or domestic trade based on quantity, weight, or measure received and/or discharged by vessel; and\n(z) \"Wholesale\" means a sale where the purchaser buys or imports the commodities for resale to persons other than the end user regardless of the quantity of the transaction."}},{"id":"PH-H5648-A132","no":132,"noLabel":{"en":"Section 132."},"chapter":{"en":"TITLE I"},"text":{"en":"Local Taxing Authority. - The power to impose a tax, fee, or charge or to generate revenue under this Code shall be exercised by the sanggunian of the local government unit concerned through an appropriate ordinance."}},{"id":"PH-H5648-A133","no":133,"noLabel":{"en":"Section 133."},"chapter":{"en":"TITLE I"},"text":{"en":"Common Limitations on the Taxing Powers of Local Government Units. - Unless otherwise provided herein, the exercise of the taxing powers of provinces, cities, municipalities, and barangays shall not extend to the levy of the following:\n(a) Income tax, except when levied on banks and other financial institutions;\n(b) Documentary stamp tax;\n(c) Taxes on estates, inheritance, gifts, legacies and other acquisitions mortis causa, except as otherwise provided herein;\n(d) Customs duties, registration fees of vessel and wharfage on wharves, tonnage dues, and all other kinds of customs fees, charges and dues except wharfage on wharves constructed and maintained by the local government unit concerned;\n(e) Taxes, fees, and charges and other impositions upon goods carried into or out of, or passing through, the territorial jurisdictions of local government units in the guise of charges for wharfage, tolls for bridges or otherwise, or other taxes, fees, or charges in any form whatsoever upon such goods or merchandise;\n(f) Taxes, fees or charges on agricultural and aquatic products when sold by marginal farmers or fishermen;\n(g) Taxes on business enterprises certified to by the Board of Investments as pioneer or non-pioneer for a period of six (6) and four (4) years, respectively from the date of registration;\n(h) Excise taxes on articles enumerated under the national Internal Revenue Code, as amended, and taxes, fees or charges on petroleum products;\n(i) Percentage or value-added tax (VAT) on sales, barters or exchanges or similar transactions on goods or services except as otherwise provided herein;\n(j) Taxes on the gross receipts of transportation contractors and persons engaged in the transportation of passengers or freight by hire and common carriers by air, land or water, except as provided in this Code;\n(k) Taxes on premiums paid by way or reinsurance or retrocession;\n(l) Taxes, fees or charges for the registration of motor vehicles and for the issuance of all kinds of licenses or permits for the driving thereof, except tricycles;\n(m) Taxes, fees, or other charges on Philippine products actually exported, except as otherwise provided herein;\n(n) Taxes, fees, or charges, on Countryside and Barangay Business Enterprises and cooperatives duly registered under R.A. No. 6810 and Republic Act Numbered Sixty-nine hundred thirty-eight (R.A. No. 6938) otherwise known as the \"Cooperative Code of the Philippines\" respectively; and\n(o) Taxes, fees or charges of any kind on the National Government, its agencies and instrumentalities, and local government units.\nSpecific Provisions on the Taxing and Other Revenue-Raising Powers of Local Government Units Provinces"}},{"id":"PH-H5648-A134","no":134,"noLabel":{"en":"Section 134."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Scope of Taxing Powers. - Except as otherwise provided in this Code, the province may levy only the taxes, fees, and charges as provided in this Article."}},{"id":"PH-H5648-A135","no":135,"noLabel":{"en":"Section 135."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Tax on Transfer of Real Property Ownership.\n(a) The province may impose a tax on the sale , donation, barter, or on any other mode of transferring ownership or title of real property at the rate of not more than fifty percent (50%) of the one percent (1%) of the total consideration involved in the acquisition of the property or of the fair market value in case the monetary consideration involved in the transfer is not substantial, whichever is higher. The sale, transfer or other disposition of real property pursuant to R.A. No. 6657 shall be exempt from this tax.\n(b) For this purpose, the Register of Deeds of the province concerned shall, before registering any deed, require the presentation of the evidence of payment of this tax. The provincial assessor shall likewise make the same requirement before cancelling an old tax declaration and issuing a new one in place thereof, Notaries public shall furnish the provincial treasurer with a copy of any deed transferring ownership or title to any real property within thirty (30) days from the date of notarization.\nIt shall be the duty of the seller, donor, transferor, executor or administrator to pay the tax herein imposed within sixty (60) days from the date of the execution of the deed or from the date of the decedent's death."}},{"id":"PH-H5648-A136","no":136,"noLabel":{"en":"Section 136."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Tax on Business of Printing and Publication. - The province may impose a tax on the business of persons engaged in the printing and/or publication of books, cards, posters, leaflets, handbills, certificates, receipts, pamphlets, and others of similar nature, at a rate not exceeding fifty percent (50%) of one percent (1%) of the gross annual receipts for the preceding calendar year.\nIn the case of a newly started business, the tax shall not exceed one-twentieth (1/20) of one percent (1%) of the capital investment. In the succeeding calendar year, regardless of when the business started to operate, the tax shall be based on the gross receipts for the preceding calendar year, or any fraction thereof, as provided herein.\nThe receipts from the printing and/or publishing of books or other reading materials prescribed by the Department of Education, Culture and Sports as school texts or references shall be exempt from the tax herein imposed."}},{"id":"PH-H5648-A137","no":137,"noLabel":{"en":"Section 137."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Franchise Tax. - Notwithstanding any exemption granted by any law or other special law, the province may impose a tax on businesses enjoying a franchise, at the rate not exceeding fifty percent (50%) of one percent (1%) of the gross annual receipts for the preceding calendar year based on the incoming receipt, or realized, within its territorial jurisdiction.\nIn the case of a newly started business, the tax shall not exceed one-twentieth (1/20) of one percent (1%) of the capital investment. In the succeeding calendar year, regardless of when the business started to operate, the tax shall be based on the gross receipts for the preceding calendar year, or any fraction thereon, as provided herein."}},{"id":"PH-H5648-A138","no":138,"noLabel":{"en":"Section 138."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Tax on Sand, Gravel and Other Quarry Resources. - The province may levy and collect not more than ten percent (10%) of fair market value in the locality per cubic meter of ordinary stones, sand, gravel, earth, and other quarry resources, as defined under the National Internal Revenue Code, as amended, extracted from public lands or from the beds of seas, lakes, rivers, streams, creeks, and other public waters within its territorial jurisdiction.\nThe permit to extract sand, gravel and other quarry resources shall be issued exclusively by the provincial governor, pursuant to the ordinance of the sangguniang panlalawigan.\nThe proceeds of the tax on sand, gravel and other quarry resources shall be distributed as follows:\n(1) Province - Thirty percent (30%);\n(2) Component City or Municipality where the sand, gravel, and other quarry resources are extracted - Thirty percent (30%); and\n(3) Barangay where the sand, gravel, and other quarry resources are extracted - Forty percent (40%)."}},{"id":"PH-H5648-A139","no":139,"noLabel":{"en":"Section 139."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Professional Tax. -\n(a) The province may levy an annual professional tax on each person engaged in the exercise or practice of his profession requiring government examination at such amount and reasonable classification as the sangguniang panlalawigan may determine but shall in no case exceed Three hundred pesos (P300.00).\n(b) Every person legally authorized to practice his profession shall pay the professional tax to the province where he practices his profession or where he maintains his principal office in case he practices his profession in several places: Provided, however, That such person who has paid the corresponding professional tax shall be entitled to practice his profession in any part of the Philippines without being subjected to any other national or local tax, license, or fee for the practice of such profession.\n(c) Any individual or corporation employing a person subject to professional tax shall require payment by that person of the tax on his profession before employment and annually thereafter.\n(d) The professional tax shall be payable annually, on or before the thirty-first (31st) day of January. Any person first beginning to practice a profession after the month of January must, however, pay the full tax before engaging therein. A line of profession does not become exempt even if conducted with some other profession for which the tax has been paid. Professionals exclusively employed in the government shall be exempt from the payment of this tax.\n(e) Any person subject to the professional tax shall write in deeds, receipts, prescriptions, reports, books of account, plans and designs, surveys and maps, as the case may be, the number of the official receipt issued to him."}},{"id":"PH-H5648-A140","no":140,"noLabel":{"en":"Section 140."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Amusement Tax. -\n(a) The province may levy an amusement tax to be collected from the proprietors, lessees, or operators of theaters, cinemas, concert halls, circuses, boxing stadia, and other places of amusement at a rate of not more than thirty percent (30%) of the gross receipts from admission fees.\n(b) In the case of theaters or cinemas, the tax shall first be deducted and withheld by their proprietors, lessees, or operators and paid to the provincial treasurer before the gross receipts are divided between said proprietors, lessees, or operators and the distributors of the cinematographic films.\n(c) The holding of operas, concerts, dramas, recitals, painting and art exhibitions, flower shows, musical programs, literary and oratorical presentations, except pop, rock, or similar concerts shall be exempt from the payment of the tax hereon imposed.\n(d) The sangguniang panlalawigan may prescribe the time, manner, terms and conditions for the payment of tax. In case of fraud or failure to pay the tax, the sangguniang panlalawigan may impose such surcharges, interest and penalties as it may deem appropriate.\n(e) The proceeds from the amusement tax shall be shared equally by the province and the municipality where such amusement places are located."}},{"id":"PH-H5648-A141","no":141,"noLabel":{"en":"Section 141."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Annual Fixed Tax For Every Delivery Truck or Van of Manufacturers or Producers, Wholesalers of, Dealers, or Retailers in, Certain Products. -\n(a) The province may levy an annual fixed tax for every truck, van or any vehicle used by manufacturers, producers, wholesalers, dealers or retailers in the delivery or distribution of distilled spirits, fermented liquors, soft drinks, cigars and cigarettes, and other products as may be determined by the sangguniang panlalawigan, to sales outlets, or consumers, whether directly or indirectly, within the province in an amount not exceeding Five hundred pesos (P500.00).\n(b) The manufacturers, producers, wholesalers, dealers and retailers referred to in the immediately foregoing paragraph shall be exempt from the tax on peddlers prescribed elsewhere in this Code.\nMunicipalities"}},{"id":"PH-H5648-A142","no":142,"noLabel":{"en":"Section 142."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Scope of Taxing Powers. - Except as otherwise provided in this Code, municipalities may levy taxes, fees, and charges not otherwise levied by provinces."}},{"id":"PH-H5648-A143","no":143,"noLabel":{"en":"Section 143."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Tax on Business. - The municipality may impose taxes on the following businesses:\n(a) On manufacturers, assemblers, repackers, processors, brewers, distillers, rectifiers, and compounders of liquors, distilled spirits, and wines or manufacturers of any article of commerce of whatever kind or nature, in accordance with the following schedule:\nWith gross sales or receipts for the preceding calendar year in the amount of:\nAmount of Tax Per Annum\nLess than 10,000.00\n165.00 P 10,000.00 or more but less than 15,000.00\n220.00 15,000.00 or more but less than 20,000.00\n202.00 20,000.00 or more but less than 30,000.00\n440.00 30,000.00 or more but less than 40,000.00\n660.00 40,000.00 or more but less than 50,000.00\n825.00 50,000.00 or more but less than 75,000.00 1,320.00 75,000.00 or more but less than 100,000.00 1,650.00 100,000.00 or more but less than 150,000.00 2,200.00 150,000.00 or more but less than 200,000.00 2,750.00 200,000.00 or more but less than 300,000.00 3,850.00 300,000.00 or more but less than 500,000.00 5,500.00 500,000.00 or more but less than 750,000.00 8,000.00 750,000.00 or more but less than 1,000,000.00 10,000.00 1,000,000.00 or more but less than 2,000,000.00 13,750.00 2,000,000.00 or more but less than 3,000,000.00 16,500.00 3,000,000.00 or more but less than 4,000,000.00 19,000.00 4,000,000.00 or more but less than 5,000,000.00 23,100.00 5,000,000.00 or more but less than 6,500,000.00 24,375.00 6,000,000.00 or more at a rate not exceeding thirty-seven and a half percent (37½%) of one percent (1%)\n(b) On wholesalers, distributors, or dealers in any article of commerce of whatever kind or nature in accordance with the following schedule:\nWith gross sales or receipts for the preceding calendar year in the amount of:\nAmount of Tax Per Annum\nLess than 1,000.00\n18.00 P 1,000.00 or more but less than 2,000.00\n33.00 2,000.00 or more but less than 3,000.00\n50.00 3,000.00 or more but less than 4,000.00\n72.00 4,000.00 or more but less than 5,000.00\n100.00 5,000.00 or more but less than 6,000.00\n121.00 6,000.00 or more but less than 7,000.00\n143.00 7,000.00 or more but less than 8,000.00\n165.00 8,000.00 or more but less than 10,000.00\n187.00 10,000.00 or more but less than 15,000.00\n220.00 15,000.00 or more but less than 20,000.00\n275.00 20,000.00 or more but less than 30,000.00\n330.00 30,000.00 or more but less than 40,000.00\n440.00 40,000.00 or more but less than 50,000.00\n660.00 50,000.00 or more but less than 75,000.00\n990.00 75,000.00 or more but less than 100,000.00 1,320.00 100,000.00 or more but less than 150,000.00 1,870.00 150,000.00 or more but less than 200,000.00 2,420.00 200,000.00 or more but less than 300,000.00 3,300.00 300,000.00 or more but less than 500,000.00 4,400.00 500,000.00 or more but less than 750,000.00 6,600.00 750,000.00 or more but less than 1,000,000.00 8,800.00 1,000,000.00 or more but less than 2,000,000.00 10,000.00 2,000,000.00 or more at a rate not exceeding fifty percent (50%) of one percent (1%).\n(c) On exporters, and on manufacturers , millers, producers, wholesalers, distributors, dealers or retailers of essential commodities enumerated hereunder at a rate not exceeding one-half (½) of the rates prescribed under subsection (a), (b) and (d) of this Section:\n(1) Rice and corn;\n(2) Wheat or cassava flour, meat, dairy products, locally manufactured, processed or preserved food, sugar, salt and other agricultural, marine, and fresh water products, whether in their original state or not;\n(3) Cooking oil and cooking gas;\n(4) Laundry soap, detergents, and medicine;\n(5) Agricultural implements. equipment and post-harvest facilities, fertilizers, pesticides, insecticides, herbicides and other farm inputs;\n(6) Poultry feeds and other animal feeds;\n(7) School supplies; and\n(8) Cement.\n(d) On retailers.\nWith gross sales or receipts for the preceding calendar year in the amount of:\nRate of Tax Per Annum\nP400,000.00 or less 2% more than P400,000.00 1% Provided, however, That barangays shall have the exclusive power to levy taxes, as provided under Section 152 hereof, on gross sales or receipts of the preceding calendar year of Fifty thousand pesos (P50,000.00) or less, in the case of cities, and Thirty thousand pesos (P30,000.00) or less, in the case of municipalities.\n(e) On contractors and other independent contractors, in accordance with the following schedule:\nWith gross sales or receipts for the preceding calendar year in the amount of:\nAmount of Tax Per Annum\nLess than 5,000.00\n27.50 P 5,000.00 or more but less than P 10,000.00\n61.60 10,000.00 or more but less than 15,000.00\n104.50 15,000.00 or more but less than 20,000.00\n165.00 20,000.00 or more but less than 30,000.00\n275.00 30,000.00 or more but less than 40,000.00\n385.00 40,000.00 or more but less than 50,000.00\n550.00 50,000.00 or more but less than 75,000.00\n880.00 75,000.00 or more but less than 100,000.00 1,320.00 100,000.00 or more but less than 150,000.00 1,980.00 150,000.00 or more but less than 200,000.00 2,640.00 200,000.00 or more but less than 250,000.00 3,630.00 250,000.00 or more but less than 300,000.00 4,620.00 300,000.00 or more but less than 400,000.00 6,160.00 400,000.00 or more but less than 500,000.00 8,250.00 500,000.00 or more but less than 750,000.00 9,250.00 750,000.00 or more but less than 1,000,000.00 10,250.00 1,000,000.00 or more but less than 2,000,000.00 11,500.00 2,000,000.00 or more at a rate not exceeding fifty percent (50%) of one percent (1%)\n(f) On banks and other financial institutions, at a rate not exceeding fifty percent (50%) of one percent (1%) on the gross receipts of the preceding calendar year derived from interest, commissions and discounts from lending activities, income from financial leasing, dividends, rentals on property and profit from exchange or sale of property, insurance premium.\n(g) On peddlers engaged in the sale of any merchandise or article of commerce, at a rate not exceeding Fifty pesos (P50.00) per peddler annually.\n(h) On any business, not otherwise specified in the preceding paragraphs, which the sanggunian concerned may deem proper to tax: Provided, That on any business subject to the excise, value-added or percentage tax under the National Internal Revenue Code, as amended, the rate of tax shall not exceed two percent (2%) of gross sales or receipts of the preceding calendar year.\nThe sanggunian concerned may prescribe a schedule of graduated tax rates but in no case to exceed the rates prescribed herein."}},{"id":"PH-H5648-A144","no":144,"noLabel":{"en":"Section 144."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Rates of Tax within the Metropolitan Manila Area. - The municipalities within the Metropolitan Manila Area may levy taxes at rates which shall not exceed by fifty percent (50%) the maximum rates prescribed in the preceding Section."}},{"id":"PH-H5648-A145","no":145,"noLabel":{"en":"Section 145."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Retirement of Business. - A business subject to tax pursuant to the preceding sections shall, upon termination thereof, submit a sworn statement of its gross sales or receipts for the current year. If the tax paid during the year be less than the tax due on said gross sales or receipts of the current year, the difference shall be paid before the business is considered officially retired."}},{"id":"PH-H5648-A146","no":146,"noLabel":{"en":"Section 146."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Payment of Business Taxes. -\n(a) The taxes imposed under Section 143 shall be payable for every separate or distinct establishment or place where business subject to the tax is conducted and one line of business does not become exempt by being conducted with some other business for which such tax has been paid. The tax on a business must be paid by the person conducting the same.\n(b) In cases where a person conducts or operates two (2) or more of the businesses mentioned in Section 143 of this Code which are subject to the same rate of tax, the tax shall be computed on the combined total gross sales or receipts of the said two (2) or more related businesses.\n(c) In cases where a person conducts or operates two (2) or more businesses mentioned in Section 143 of this Code which are subject to different rates of tax, the gross sales or receipts of each business shall be separately reported for the purpose of computing the tax due from each business."}},{"id":"PH-H5648-A147","no":147,"noLabel":{"en":"Section 147."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Fees and Charges. - The municipality may impose and collect such reasonable fees and charges on business and occupation and, except as reserved to the province in Section 139 of this Code, on the practice of any profession or calling, commensurate with the cost of regulation, inspection and licensing before any person may engage in such business or occupation, or practice such profession or calling."}},{"id":"PH-H5648-A148","no":148,"noLabel":{"en":"Section 148."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Fees for Sealing and Licensing of Weights and Measures. -\n(a) The municipality may levy fees for the sealing and licensing of weights and measures at such reasonable rates as shall be prescribed by the sangguniang bayan.\n(b) The sangguniang bayan shall prescribe the necessary regulations for the use of such weights and measures, subject to such guidelines as shall be prescribed by the Department of Science and Technology. The sanggunian concerned shall, by appropriate ordinance, penalize fraudulent practices and unlawful possession or use of instruments of weights and measures and prescribe the criminal penalty therefor in accordance with the provisions of this Code. Provided, however, That the sanggunian concerned may authorize the municipal treasurer to settle an offense not involving the commission of fraud before a case therefor is filed in court, upon payment of a compromise penalty of not less than Two hundred pesos (P200.00)."}},{"id":"PH-H5648-A149","no":149,"noLabel":{"en":"Section 149."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Fishery Rentals, Fees and Charges. -\n(a) Municipalities shall have the exclusive authority to grant fishery privileges in the municipal waters and impose rentals, fees or charges therefor in accordance with the provisions of this Section.\n(b) The sangguniang bayan may:\n(1) Grant fishery privileges to erect fish corrals, oysters, mussels or other aquatic beds or bangus fry areas, within a definite zone of the municipal waters, as determined by it: Provided, however, That duly registered organizations and cooperatives of marginal fishermen shall have the preferential right to such fishery privileges: Provided, further, That the sangguniang bayan may require a public bidding in conformity with and pursuant to an ordinance for the grant of such privileges: Provided, finally, That in the absence of such organizations and cooperatives or their failure to exercise their preferential right, other parties may participate in the public bidding in conformity with the above cited procedure.\n(2) Grant the privilege to gather, take or catch bangus fry, prawn fry or kawag-kawag or fry of other species and fish from the municipal waters by nets, traps or other fishing gears to marginal fishermen free of any rental, fee, charge or any other imposition whatsoever.\n(3) Issue licenses for the operation of fishing vessels of three (3) tons or less for which purpose the sangguniang bayan shall promulgate rules and regulations regarding the issuances of such licenses to qualified applicants under existing laws.\nProvided, however, That the sanggunian concerned shall, by appropriate ordinance, penalize the use of explosives, noxious or poisonous substances, electricity, muro-ami, and other deleterious methods of fishing and prescribe a criminal penalty therefor in accordance with the provisions of this Code: Provided, finally, That the sanggunian concerned shall have the authority to prosecute any violation of the provisions of applicable fishery laws."}},{"id":"PH-H5648-A150","no":150,"noLabel":{"en":"Section 150."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Situs of the Tax. -\n(a) For purposes of collection of the taxes under Section 143 of this Code, manufacturers, assemblers, repackers, brewers, distillers, rectifiers and compounders of liquor, distilled spirits and wines, millers, producers, exporters, wholesalers, distributors, dealers, contractors, banks and other financial institutions, and other businesses, maintaining or operating branch or sales outlet elsewhere shall record the sale in the branch or sales outlet making the sale or transaction, and the tax thereon shall accrue and shall be paid to the municipality where such branch or sales outlet is located. In cases where there is no such branch or sales outlet in the city or municipality where the sale or transaction is made, the sale shall be duly recorded in the principal office and the taxes due shall accrue and shall be paid to such city or municipality.\n(b) The following sales allocation shall apply to manufacturers, assemblers, contractors, producers, and exporters with factories, project offices, plants, and plantations in the pursuit of their business:\n(1) Thirty percent (30%) of all sales recorded in the principal office shall be taxable by the city or municipality where the principal office is located; and\n(2) Seventy percent (70%) of all sales recorded in the principal office shall be taxable by the city or municipality where the factory, project office, plant, or plantation is located.\n(c) In case of a plantation located at a place other than the place where the factory is located, said seventy percent (70%) mentioned in subparagraph (b) of subsection (2) above shall be divided as follows:\n(1) Sixty percent (60%) to the city or municipality where the factory is located; and\n(2) Forty percent (40%) to the city or municipality where the plantation is located.\n(d) In cases where a manufacturer, assembler, producer, exporter or contractor has two (2) or more factories, project offices, plants, or plantations located in different localities, the seventy percent (70%) sales allocation mentioned in subparagraph (b) of subsection (2) above shall be prorated among the localities where the factories, project offices, plants, and plantations are located in proportion to their respective volumes of production during the period for which the tax is due.\n(e) The foregoing sales allocation shall be applied irrespective of whether or not sales are made in the locality where the factory, project office, plant, or plantation is located.\nCities"}},{"id":"PH-H5648-A151","no":151,"noLabel":{"en":"Section 151."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Scope of Taxing Powers. - Except as otherwise provided in this Code, the city, may levy the taxes, fees, and charges which the province or municipality may impose: Provided, however, That the taxes, fees and charges levied and collected by highly urbanized and independent component cities shall accrue to them and distributed in accordance with the provisions of this Code.\nThe rates of taxes that the city may levy may exceed the maximum rates allowed for the province or municipality by not more than fifty percent (50%) except the rates of professional and amusement taxes.\nBarangays"}},{"id":"PH-H5648-A152","no":152,"noLabel":{"en":"Section 152."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Scope of Taxing Powers. - The barangays may levy taxes, fees, and charges, as provided in this Article, which shall exclusively accrue to them:\n(a) Taxes - On stores or retailers with fixed business establishments with gross sales of receipts of the preceding calendar year of Fifty thousand pesos (P50,000.00) or less, in the case of cities and Thirty thousand pesos (P30,000.00) or less, in the case of municipalities, at a rate not exceeding one percent (1%) on such gross sales or receipts.\n(b) Service Fees or Charges. - Barangays may collect reasonable fees or charges for services rendered in connection with the regulations or the use of barangay-owned properties or service facilities such as palay, copra, or tobacco dryers.\n(c) Barangay Clearance. - No city or municipality may issue any license or permit for any business or activity unless a clearance is first obtained from the barangay where such business or activity is located or conducted. For such clearance, the sangguniang barangay may impose a reasonable fee. The application for clearance shall be acted upon within seven (7) working days from the filing thereof. In the event that the clearance is not issued within the said period, the city or municipality may issue the said license or permit.\n(d) Other fees and Charges. - The barangay may levy reasonable fees and charges:\n(1) On commercial breeding of fighting cocks, cockfights and cockpits;\n(2) On places of recreation which charge admission fees; and\n(3) On billboards, signboards, neon signs, and outdoor advertisements.\nCommon Revenue-Raising Powers"}},{"id":"PH-H5648-A153","no":153,"noLabel":{"en":"Section 153."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Service Fees and Charges. - Local government units may impose and collect such reasonable fees and charges for services rendered."}},{"id":"PH-H5648-A154","no":154,"noLabel":{"en":"Section 154."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Public Utility Charges. - Local government units may fix the rates for the operation of public utilities owned, operated and maintained by them within their jurisdiction."}},{"id":"PH-H5648-A155","no":155,"noLabel":{"en":"Section 155."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Toll Fees or Charges. - The sanggunian concerned may prescribe the terms and conditions and fix the rates for the imposition of toll fees or charges for the use of any public road, pier, or wharf, waterway, bridge, ferry or telecommunication system funded and constructed by the local government unit concerned: Provided, That no such toll fees or charges shall be collected from officers and enlisted men of the Armed Forces of the Philippines and members of the Philippine National Police on mission, post office personnel delivering mail, physically-handicapped, and disabled citizens who are sixty-five (65) years or older.\nWhen public safety and welfare so requires, the sanggunian concerned may discontinue the collection of the tolls, and thereafter the said facility shall be free and open for public use.\nCommunity Tax"}},{"id":"PH-H5648-A156","no":156,"noLabel":{"en":"Section 156."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Community Tax. - Cities or municipalities may levy a community tax in accordance with the provisions of this Article."}},{"id":"PH-H5648-A157","no":157,"noLabel":{"en":"Section 157."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Individuals Liable to Community Tax. - Every inhabitant of the Philippines eighteen (18) years of age or over who has been regularly employed on a wage or salary basis for at least thirty (30) consecutive working days during any calendar year, or who is engaged in business or occupation, or who owns real property with an aggregate assessed value of One thousand pesos (P1,000.00) or more, or who is required by law to file an income tax return shall pay an annual additional tax of Five pesos (P5.00) and an annual additional tax of One peso (P1.00) for every One thousand pesos (P1,000.00) of income regardless of whether from business, exercise of profession or from property which in no case shall exceed Five thousand pesos (P5,000.00).\nIn the case of husband and wife, the additional tax herein imposed shall be based upon the total property owned by them and the total gross receipts or earnings derived by them."}},{"id":"PH-H5648-A158","no":158,"noLabel":{"en":"Section 158."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Juridical Persons Liable to Community Tax. - Every corporation no matter how created or organized, whether domestic or resident foreign, engaged in or doing business in the Philippines shall pay an annual community tax of Five hundred pesos (P500.00) and an annual additional tax, which, in no case, shall exceed Ten thousand pesos (P10,000.00) in accordance with the following schedule:\n(1) For every Five thousand pesos (P5,000.00) worth of real property in the Philippines owned by it during the preceding year based on the valuation used for the payment of real property tax under existing laws, found in the assessment rolls of the city or municipality where the real property is situated - Two pesos (P2.00); and\n(2) For every Five thousand pesos (P5,000.00) of gross receipts or earnings derived by it from its business in the Philippines during the preceding year - Two pesos (P2.00).\nThe dividends received by a corporation from another corporation however shall, for the purpose of the additional tax, be considered as part of the gross receipts or earnings of said corporation."}},{"id":"PH-H5648-A159","no":159,"noLabel":{"en":"Section 159."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Exemptions. - The following are exempt from the community tax:\n(1) Diplomatic and consular representatives; and\n(2) Transient visitors when their stay in the Philippines does not exceed three (3) months."}},{"id":"PH-H5648-A160","no":160,"noLabel":{"en":"Section 160."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Place of Payment. - The community tax shall be paid in the place of residence of the individual, or in the place where the principal office of the juridical entity is located."}},{"id":"PH-H5648-A161","no":161,"noLabel":{"en":"Section 161."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Time for Payment; Penalties for Delinquency. -\n(a) The community tax shall accrue on the first (1st) day of January of each year which shall be paid not later than the last day of February of each year. If a person reaches the age of eighteen (18) years or otherwise loses the benefit of exemption on or before the last day of June, he shall be liable for the community tax on the day he reaches such age or upon the day the exemption ends. However, if a person reaches the age of eighteen (18) years or loses the benefit of exemption on or before the last day of March, he shall have twenty (20) days to pay the community tax without becoming delinquent.\nPersons who come to reside in the Philippines or reach the age of eighteen (18) years on or after the first (1st) day of July of any year, or who cease to belong to an exempt class or after the same date, shall not be subject to the community tax for that year.\n(b) Corporations established and organized on or before the last day of June shall be liable for the community tax for that year. But corporations established and organized on or before the last day of March shall have twenty (20) days within which to pay the community tax without becoming delinquent. Corporations established and organized on or after the first day of July shall not be subject to the community tax for that year.\nIf the tax is not paid within the time prescribed above, there shall be added to the unpaid amount an interest of twenty-four percent (24%) per annum from the due date until it is paid."}},{"id":"PH-H5648-A162","no":162,"noLabel":{"en":"Section 162."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Community Tax Certificate. - A community tax certificate shall be issued to every person or corporation upon payment of the community tax. A community tax certificate may also be issued to any person or corporation not subject to the community tax upon payment of One peso (P1.00)."}},{"id":"PH-H5648-A163","no":163,"noLabel":{"en":"Section 163."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Presentation of Community Tax Certificate On Certain Occasions. -\n(a) When an individual subject to the community tax acknowledges any document before a notary public, takes the oath of office upon election or appointment to any position in the government service; receives any license, certificate. or permit from any public authority; pays any tax or free; receives any money from any public fund; transacts other official business; or receives any salary or wage from any person or corporation with whom such transaction is made or business done or from whom any salary or wage is received to require such individual to exhibit the community tax certificate.\nThe presentation of community tax certificate shall not be required in connection with the registration of a voter.\n(b) When, through its authorized officers, any corporation subject to the community tax receives any license, certificate, or permit from any public authority, pays any tax or fee, receives money from public funds, or transacts other official business, it shall be the duty of the public official with whom such transaction is made or business done, to require such corporation to exhibit the community tax certificate.\n(c) The community tax certificate required in the two preceding paragraphs shall be the one issued for the current year, except for the period from January until the fifteenth (15th) of April each year, in which case, the certificate issued for the preceding year shall suffice."}},{"id":"PH-H5648-A164","no":164,"noLabel":{"en":"Section 164."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Printing of Community Tax Certificates and Distribution of Proceeds. -\n(a) The Bureau of Internal Revenue shall cause the printing of community tax certificates and distribute the same to the cities and municipalities through the city and municipal treasurers in accordance with prescribed regulations.\nThe proceeds of the tax shall accrue to the general funds of the cities, municipalities and barangays except a portion thereof which shall accrue to the general fund of the national government to cover the actual cost of printing and distribution of the forms and other related expenses. The city or municipal treasurer concerned shall remit to the national treasurer the said share of the national government in the proceeds of the tax within ten (10) days after the end of each quarter.\n(b) The city or municipal treasurer shall deputize the barangay treasurer to collect the community tax in their respective jurisdictions: Provided, however, That said barangay treasurer shall be bonded in accordance with existing laws.\n(c) The proceeds of the community tax actually and directly collected by the city or municipal treasurer shall accrue entirely to the general fund of the city or municipality concerned. However, proceeds of the community tax collected through the barangay treasurers shall be apportioned as follows:\n(1) Fifty percent (50%) shall accrue to the general fund of the city or municipality concerned; and\n(2) Fifty percent (50%) shall accrue to the barangay where the tax is collected.\nCollection of Taxes"}},{"id":"PH-H5648-A165","no":165,"noLabel":{"en":"Section 165."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Tax Period and Manner of Payment. - Unless otherwise provided in this Code, the tax period of all local taxes, fees and charges shall be the calendar year. Such taxes, fees and charges may be paid in quarterly installments."}},{"id":"PH-H5648-A166","no":166,"noLabel":{"en":"Section 166."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Accrual of Tax. - Unless otherwise provided in this Code, all local taxes, fees, and charges shall accrue on the first (1st) day of January of each year. However, new taxes, fees or charges, or changes in the rates thereof, shall accrue on the first (1st) day of the quarter next following the effectivity of the ordinance imposing such new levies or rates."}},{"id":"PH-H5648-A167","no":167,"noLabel":{"en":"Section 167."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Time of Payment. - Unless otherwise provided in this Code, all local taxes, fees, and charges shall be paid within the first twenty (20) days of January or of each subsequent quarter, as the case may be. The sanggunian concerned may, for a justifiable reason or cause, extend the time for payment of such taxes, fees, or charges without surcharges or penalties, but only for a period not exceeding six (6) months."}},{"id":"PH-H5648-A168","no":168,"noLabel":{"en":"Section 168."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Surcharges and Penalties on Unpaid Taxes, Fees, or Charges. - The sanggunian may impose a surcharge not exceeding twenty-five (25%) of the amount of taxes, fees or charges not paid on time and an interest at the rate not exceeding two percent (2%) per month of the unpaid taxes, fees or charges including surcharges, until such amount is fully paid but in no case shall the total thirty-six (36%) months."}},{"id":"PH-H5648-A169","no":169,"noLabel":{"en":"Section 169."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Interests on Other Unpaid Revenues. - Where the amount of any other revenue due a local government unit, except voluntary contributions or donations, is not paid on the date fixed in the ordinance, or in the contract, expressed or implied, or upon the occurrence of the event which has given rise to its collection, there shall be collected as part of that amount an interest thereon at the rate not exceeding two percent (2%) per month from the date it is due until it is paid, but in no case shall the total interest on the unpaid amount or a portion thereof exceed thirty-six (36) months."}},{"id":"PH-H5648-A170","no":170,"noLabel":{"en":"Section 170."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Collection of Local Revenue by Treasurer. - All local taxes, fees, and charges shall be collected by the provincial, city, municipal, or barangay treasurer, or their duly authorized deputies.\nThe provincial, city or municipal treasurer may designate the barangay treasurer as his deputy to collect local taxes, fees, or charges. In case a bond is required for the purpose, the provincial, city or municipal government shall pay the premiums thereon in addition to the premiums of bond that may be required under this Code."}},{"id":"PH-H5648-A171","no":171,"noLabel":{"en":"Section 171."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Examination of Books of Accounts and Pertinent Records of Businessmen by Local Treasurer. - The provincial, city, municipal or barangay treasurer may, by himself or through any of his deputies duly authorized in writing, examine the books, accounts, and other pertinent records of any person, partnership, corporation, or association subject to local taxes, fees and charges in order to ascertain. assess, and collect the correct amount of the tax, fee, or charge. Such examination shall be made during regular business hours, only once for every tax period, and shall be certified to by the examining official. Such certificate shall be made of record in the books of accounts of the taxpayer examined.\nIn case the examination herein authorized is made by a duly authorized deputy of the local treasurer, the written authority of the deputy concerned shall specifically state the name, address, and business of the taxpayer whose books, accounts, and pertinent records are to be examined, the date and place of such examination and the procedure to be followed in conducting the same.\nFor this purpose, the records of the revenue district office of the Bureau of Internal Revenue shall be made available to the local treasurer, his deputy or duly authorized representative.\nCivil Remedies for Collection of Revenues"}},{"id":"PH-H5648-A172","no":172,"noLabel":{"en":"Section 172."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Application of Chapter. - The provisions of this Chapter and the remedies provided hereon may be availed of for the collection of any delinquent local tax, fee, charge, or other revenue."}},{"id":"PH-H5648-A173","no":173,"noLabel":{"en":"Section 173."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Local Government's Lien. - Local taxes, fees, charges and other revenues constitute a lien, superior to all liens, charges or encumbrances in favor of any person, enforceable by appropriate administrative or judicial action, not only upon any property or rights therein which may be subject to the lien but also upon property used in business, occupation, practice of profession or calling, or exercise of privilege with respect to which the lien is imposed. The lien may only be extinguished upon full payment of the delinquent local taxes fees and charges including related surcharges and interest."}},{"id":"PH-H5648-A174","no":174,"noLabel":{"en":"Section 174."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Civil Remedies. - The civil remedies for the collection of local taxes, fees, or charges, and related surcharges and interest resulting from delinquency shall be:\n(a) By administrative action thru distraint of goods, chattels, or effects, and other personal property of whatever character, including stocks and other securities, debts, credits, bank accounts, and interest in and rights to personal property, and by levy upon real property and interest in or rights to real property;\n(b) By judicial action.\nEither of these remedies or all may be pursued concurrently or simultaneously at the discretion of the local government unit concerned."}},{"id":"PH-H5648-A175","no":175,"noLabel":{"en":"Section 175."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Distraint of Personal Property. - The remedy by distraint shall proceed as follows:\n(a) Seizure - Upon failure of the person owing any local tax, fee, or charge to pay the same at the time required, the local treasurer or his deputy may, upon written notice, seize or confiscate any personal property belonging to that person or any personal property subject to the lien in sufficient quantity to satisfy the tax, fee, or charge in question, together with any increment thereto incident to delinquency and the expenses of seizure. In such case, the local treasurer or his deputy shall issue a duly authenticated certificate based upon the records of his office showing the fact of delinquency and the amounts of the tax, fee, or charge and penalty due. Such certificate shall serve as sufficient warrant for the distraint of personal property aforementioned, subject to the taxpayer's right to claim exemption under the provisions of existing laws. Distrained personal property shall be sold at public auction in the manner hereon provided for.\n(b) Accounting of distrained goods. - The officer executing the distraint shall make or cause to be made an account of the goods, chattels or effects distrained, a copy of which signed by himself shall be left either with the owner or person from whose possession the goods, chattels or effects are taken, or at the dwelling or place or business of that person and with someone of suitable age and discretion, to which list shall be added a statement of the sum demanded and a note of the time and place of sale.\n(c) Publication - The officer shall forthwith cause a notification to be exhibited in not less than three (3) public and conspicuous places in the territory of the local government unit where the distraint is made, specifying the time and place of sale, and the articles distrained. The time of sale shall not be less than twenty (20) days after the notice to the owner or possessor of the property as above specified and the publication or posting of the notice. One place for the posting of the notice shall be at the office of the chief executive of the local government unit in which the property is distrained.\n(d) Release of distrained property upon payment prior to sale - If at any time prior to the consummation of the sale, all the proper charges are paid to the officer conducting the sale, the goods or effects distrained shall be restored to the owner.\n(e) Procedure of sale - At the time and place fixed in the notice, the officer conducting the sale shall sell the goods or effects so distrained at public auction to the highest bidder for cash. Within five (5) days after the sale, the local treasurer shall make a report of the proceedings in writing to the local chief executive concerned.\nShould the property distrained be not disposed of within one hundred and twenty (120) days from the date of distraint, the same shall be considered as sold to the local government unit concerned for the amount of the assessment made thereon by the Committee on Appraisal and to the extent of the same amount, the tax delinquencies shall be cancelled.\nSaid Committee on Appraisal shall be composed of the city or municipal treasurer as chairman, with a representative of the Commission on Audit and the city or municipal assessor as members.\n(f) Disposition of proceeds - The proceeds of the sale shall be applied to satisfy the tax, including the surcharges, interest, and other penalties incident to delinquency, and the expenses of the distraint and sale. The balance over and above what is required to pay the entire claim shall be returned to the owner of the property sold. The expenses chargeable upon the seizure and sale shall embrace only the actual expenses of seizure and preservation of the property pending the sale, and no charge shall be imposed for the services of the local officer or his deputy. Where the proceeds of the sale are insufficient to satisfy the claim, other property may, in like manner, be distrained until the full amount due, including all expenses, is collected."}},{"id":"PH-H5648-A176","no":176,"noLabel":{"en":"Section 176."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Levy on Real Property. - After the expiration of the time required to pay the delinquent tax, fee, or charge, real property may be levied on before, simultaneously, or after the distraint of personal property belonging to the delinquent taxpayer. To this end, the provincial, city or municipal treasurer, as the case may be, shall prepare a duly authenticated certificate showing the name of the taxpayer and the amount of the tax, fee, or charge, and penalty due from him. Said certificate shall operate with the force of a legal execution throughout the Philippines. Levy shall be effected by writing upon said certificate the description of the property upon which levy is made. At the same time, written notice of the levy shall be mailed to or served upon the assessor and the Register of Deeds of the province or city where the property is located who shall annotate the levy on the tax declaration and certificate of title of the property, respectively, and the delinquent taxpayer or, if he be absent from the Philippines, to his agent or the manager of the business in respect to which the liability arose, or if there be none, to the occupant of the property in question.\nIn case the levy on real property is not issued before or simultaneously with the warrant of distraint on personal property, and the personal property of the taxpayer is not sufficient to satisfy his delinquency, the provincial, city or municipal treasurer, as the case may be, shall within thirty (30) days after execution of the distraint, proceed with the levy on the taxpayer's real property.\nA report on any levy shall, within ten (10) days after receipt of the warrant, be submitted by the levying officer to the sanggunian concerned."}},{"id":"PH-H5648-A177","no":177,"noLabel":{"en":"Section 177."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Penalty for Failure to Issue and Execute Warrant. - Without prejudice to criminal prosecution under the Revised Penal Code and other applicable laws, any local treasurer who fails to issue or execute the warrant of distraint or levy after the expiration of the time prescribed, or who is found guilty of abusing the exercise thereof by competent authority shall be automatically dismissed from the service after due notice and hearing."}},{"id":"PH-H5648-A178","no":178,"noLabel":{"en":"Section 178."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Advertisement and Sale. - Within thirty (30) days after the levy, the local treasurer shall proceed to publicly advertise for sale or auction the property or a usable portion thereof as may be necessary to satisfy the claim and cost of sale; and such advertisement shall cover a period of at least thirty (30) days. It shall be effected by posting a notice at the main entrance of the municipal building or city hall, and in a public and conspicuous place in the barangay where the real property is located, and by publication once a week for three (3) weeks in a newspaper of general circulation in the province, city or municipality where the property is located. The advertisement shall contain the amount of taxes, fees or charges, and penalties due thereon, and the time and place of sale, the name of the taxpayer against whom the taxes, fees, or charges are levied, and a short description of the property to be sold. At any time before the date fixed for the sale, the taxpayer may stay they proceedings by paying the taxes, fees, charges, penalties and interests. If he fails to do so, the sale shall proceed and shall be held either at the main entrance of the provincial, city or municipal building, or on the property to be sold, or at any other place as determined by the local treasurer conducting the sale and specified in the notice of sale.\nWithin thirty (30) days after the sale, the local treasurer or his deputy shall make a report of the sale to the sanggunian concerned, and which shall form part of his records. After consultation with the sanggunian, the local treasurer shall make and deliver to the purchaser a certificate of sale, showing the proceeding of the sale, describing the property sold, stating the name of the purchaser and setting out the exact amount of all taxes, fees, charges, and related surcharges, interests, or penalties: Provided, however, That any excess in the proceeds of the sale over the claim and cost of sales shall be turned over to the owner of the property.\nThe local treasurer may, by ordinance duly approved, advance an amount sufficient to defray the costs of collection by means of the remedies provided for in this Title, including the preservation or transportation in case of personal property, and the advertisement and subsequent sale, in cases of personal and real property including improvements thereon."}},{"id":"PH-H5648-A179","no":179,"noLabel":{"en":"Section 179."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Redemption of Property Sold. - Within one (1) year from the date of sale, the delinquent taxpayer or his representative shall have the right to redeem the property upon payment to the local treasurer of the total amount of taxes, fees, or charges, and related surcharges, interests or penalties from the date of delinquency to the date of sale, plus interest of not more than two percent (2%) per month on the purchase price from the date of purchase to the date of redemption. Such payment shall invalidate the certificate of sale issued to the purchaser and the owner shall be entitled to a certificate of redemption from the provincial, city or municipal treasurer or his deputy.\nThe provincial, city or municipal treasurer or his deputy, upon surrender by the purchaser of the certificate of sale previously issued to him, shall forthwith return to the latter the entire purchase price paid by him plus the interest of not more than two percent (2%) per month herein provided for, the portion of the cost of sale and other legitimate expenses incurred by him, and said property thereafter shall be free from the lien of such taxes, fees, or charges, related surcharges, interests, and penalties.\nThe owner shall not, however, be deprived of the possession of said property and shall be entitled to the rentals and other income thereof until the expiration of the time allowed for its redemption."}},{"id":"PH-H5648-A180","no":180,"noLabel":{"en":"Section 180."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Final Deed to Purchaser. - In case the taxpayer fails to redeem the property as provided herein, the local treasurer shall execute a deed conveying to the purchaser so much of the property as has been sold, free from liens of any taxes, fees, charges, related surcharges, interests, and penalties. The deed shall succinctly recite all the proceedings upon which the validity of the sale depends."}},{"id":"PH-H5648-A181","no":181,"noLabel":{"en":"Section 181."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Purchase of Property By the Local Government Units for Want of Bidder. - In case there is no bidder for the real property advertised for sale as provided herein, or if the highest bid is for an amount insufficient to pay the taxes, fees, or charges, related surcharges, interests, penalties and costs, the local treasurer conducting the sale shall purchase the property in behalf of the local government unit concerned to satisfy the claim and within two (2) days thereafter shall make a report of his proceedings which shall be reflected upon the records of his office. It shall be the duty of the Registrar of Deeds concerned upon registration with his office of any such declaration of forfeiture to transfer the title of the forfeited property to the local government unit concerned without the necessity of an order from a competent court.\nWithin one (1) year from the date of such forfeiture, the taxpayer or any of his representative, may redeem the property by paying to the local treasurer the full amount of the taxes, fees, charges, and related surcharges, interests, or penalties, and the costs of sale. If the property is not redeemed as provided herein, the ownership thereof shall be fully vested on the local government unit concerned."}},{"id":"PH-H5648-A182","no":182,"noLabel":{"en":"Section 182."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Resale of Real Estate Taken for Taxes, Fees, or Charges. - The sanggunian concerned may, by ordinance duly approved, and upon notice of not less than twenty (20) days, sell and dispose of the real property acquired under the preceding section at public auction. The proceeds of the sale shall accrue to the general fund of the local government unit concerned."}},{"id":"PH-H5648-A183","no":183,"noLabel":{"en":"Section 183."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Collection of Delinquent Taxes, Fees, Charges or other Revenues through Judicial Action. - The local government unit concerned may enforce the collection of delinquent taxes, fees, charges or other revenues by civil action in any court of competent jurisdiction. The civil action shall be filed by the local treasurer within the period prescribed in Section 194 of this Code."}},{"id":"PH-H5648-A184","no":184,"noLabel":{"en":"Section 184."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Further Distraint or Levy. - The remedies by distraint and levy may be repeated if necessary until the full amount due, including all expenses, is collected."}},{"id":"PH-H5648-A185","no":185,"noLabel":{"en":"Section 185."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Personal Property Exempt from Distraint or Levy. - The following property shall be exempt from distraint and the levy, attachment or execution thereof for delinquency in the payment of any local tax, fee or charge, including the related surcharge and interest:\n(a) Tools and implements necessarily used by the delinquent taxpayer in his trade or employment;\n(b) One (1) horse, cow, carabao, or other beast of burden, such as the delinquent taxpayer may select, and necessarily used by him in his ordinary occupation;\n(c) His necessary clothing, and that of all his family;\n(d) Household furniture and utensils necessary for housekeeping and used for that purpose by the delinquent taxpayer, such as he may select, of a value not exceeding Ten thousand pesos (P10,000.00);\n(e) Provisions, including crops, actually provided for individual or family use sufficient for four (4) months;\n(f) The professional libraries of doctors, engineers, lawyers and judges;\n(g) One fishing boat and net, not exceeding the total value of Ten thousand pesos (P10,000.00), by the lawful use of which a fisherman earns his livelihood; and\n(h) Any material or article forming part of a house or improvement of any real property.\nMiscellaneous Provisions"}},{"id":"PH-H5648-A186","no":186,"noLabel":{"en":"Section 186."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Power To Levy Other Taxes, Fees or Charges. - Local government units may exercise the power to levy taxes, fees or charges on any base or subject not otherwise specifically enumerated herein or taxed under the provisions of the National Internal Revenue Code, as amended, or other applicable laws: Provided, That the taxes, fees, or charges shall not be unjust, excessive, oppressive, confiscatory or contrary to declared national policy: Provided, further, That the ordinance levying such taxes, fees or charges shall not be enacted without any prior public hearing conducted for the purpose."}},{"id":"PH-H5648-A187","no":187,"noLabel":{"en":"Section 187."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Procedure for Approval and Effectivity of Tax, Ordinances and Revenue Measures; Mandatory Public Hearings. - The procedure for approval of local tax ordinances and revenue measures shall be in accordance with the provisions of this Code: Provided, That public hearings shall be conducted for the purpose prior to the enactment thereof: Provided, further, That any question on the constitutionality or legality of tax ordinances or revenue measures may be raised on appeal within thirty (30) days from the effectivity thereof to the Secretary of Justice who shall render a decision within sixty (60) days from the date of receipt of the appeal: Provided, however, That such appeal shall not have the effect of suspending the effectivity of the ordinance and the accrual and payment of the tax, fee, or charge levied therein: Provided, finally, That within thirty (30) days after receipt of the decision or the lapse of the sixty-day period without the Secretary of Justice acting upon the appeal, the aggrieved party may file appropriate proceedings with a court of competent jurisdiction."}},{"id":"PH-H5648-A188","no":188,"noLabel":{"en":"Section 188."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Publication of Tax Ordinances and Revenue Measures. - Within ten (10) days after their approval, certified true copies of all provincial, city, and municipal tax ordinances or revenue measures shall be published in full for three (3) consecutive days in a newspaper of local circulation: Provided, however, That in provinces, cities and municipalities where there are no newspapers of local circulation, the same may be posted in at least two (2) conspicuous and publicly accessible places."}},{"id":"PH-H5648-A189","no":189,"noLabel":{"en":"Section 189."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Furnishing of Copies of Tax Ordinances and Revenue Measures. - Copies of all provincial, city, and municipal and barangay tax ordinances and revenue measures shall be furnished the respective local treasurers for public dissemination."}},{"id":"PH-H5648-A190","no":190,"noLabel":{"en":"Section 190."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Attempt to Enforce Void or Suspended Tax Ordinances and revenue measures. - The enforcement of any tax ordinance or revenue measure after due notice of the disapproval or suspension thereof shall be sufficient ground for administrative disciplinary action against the local officials and employees responsible therefor."}},{"id":"PH-H5648-A191","no":191,"noLabel":{"en":"Section 191."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Authority of Local Government Units to Adjust Rates of Tax Ordinances. - Local government units shall have the authority to adjust the tax rates as prescribed herein not oftener than once every five (5) years, but in no case shall such adjustment exceed ten percent (10%) of the rates fixed under this Code."}},{"id":"PH-H5648-A192","no":192,"noLabel":{"en":"Section 192."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Authority to Grant Tax Exemption Privileges. - Local government units may, through ordinances duly approved, grant tax exemptions, incentives or reliefs under such terms and conditions as they may deem necessary."}},{"id":"PH-H5648-A193","no":193,"noLabel":{"en":"Section 193."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Withdrawal of Tax Exemption Privileges. - Unless otherwise provided in this Code, tax exemptions or incentives granted to, or presently enjoyed by all persons, whether natural or juridical, including government-owned or controlled corporations, except local water districts, cooperatives duly registered under R.A. No. 6938, non-stock and non-profit hospitals and educational institutions, are hereby withdrawn upon the effectivity of this Code.\nTaxpayer's Remedies"}},{"id":"PH-H5648-A194","no":194,"noLabel":{"en":"Section 194."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Periods of Assessment and Collection. -\n(a) Local taxes, fees, or charges shall be assessed within five (5) years from the date they became due. No action for the collection of such taxes, fees, or charges, whether administrative or judicial, shall be instituted after the expiration of such period: Provided, That. taxes, fees or charges which have accrued before the effectivity of this Code may be assessed within a period of three (3) years from the date they became due.\n(b) In case of fraud or intent to evade the payment of taxes, fees, or charges, the same may be assessed within ten (10) years from discovery of the fraud or intent to evade payment.\n(c) Local taxes, fees, or charges may be collected within five (5) years from the date of assessment by administrative or judicial action. No such action shall be instituted after the expiration of said period: Provided, however, That, taxes, fees or charges assessed before the effectivity of this Code may be collected within a period of three (3) years from the date of assessment.\n(d) The running of the periods of prescription provided in the preceding paragraphs shall be suspended for the time during which:\n(1) The treasurer is legally prevented from making the assessment of collection;\n(2) The taxpayer requests for a reinvestigation and executes a waiver in writing before expiration of the period within which to assess or collect; and\n(3) The taxpayer is out of the country or otherwise cannot be located."}},{"id":"PH-H5648-A195","no":195,"noLabel":{"en":"Section 195."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Protest of Assessment. - When the local treasurer or his duly authorized representative finds that correct taxes, fees, or charges have not been paid, he shall issue a notice of assessment stating the nature of the tax, fee, or charge, the amount of deficiency, the surcharges, interests and penalties. Within sixty (60) days from the receipt of the notice of assessment, the taxpayer may file a written protest with the local treasurer contesting the assessment; otherwise, the assessment shall become final and executory. The local treasurer shall decide the protest within sixty (60) days from the time of its filing. If the local treasurer finds the protest to be wholly or partly meritorious, he shall issue a notice cancelling wholly or partially the assessment. However, if the local treasurer finds the assessment to be wholly or partly correct, he shall deny the protest wholly or partly with notice to the taxpayer. The taxpayer shall have thirty (30) days from the receipt of the denial of the protest or from the lapse of the sixty (60) day period prescribed herein within which to appeal with the court of competent jurisdiction otherwise the assessment becomes conclusive and unappealable."}},{"id":"PH-H5648-A196","no":196,"noLabel":{"en":"Section 196."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Claim for Refund of Tax Credit. - No case or proceeding shall be maintained in any court for the recovery of any tax, fee, or charge erroneously or illegally collected until a written claim for refund or credit has been filed with the local treasurer. No case or proceeding shall be entertained in any court after the expiration of two (2) years from the date of the payment of such tax, fee, or charge, or from the date the taxpayer is entitled to a refund or credit.\nREAL PROPERTY TAXATION\nGeneral Provisions"}},{"id":"PH-H5648-A197","no":197,"noLabel":{"en":"Section 197."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Scope. - This Title shall govern the administration, appraisal, assessment, levy and collection of real property tax."}},{"id":"PH-H5648-A198","no":198,"noLabel":{"en":"Section 198."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Fundamental Principles. - The appraisal, assessment, levy and collection of real property tax shall be guided by the following fundamental principles:\n(a) Real property shall be appraised at its current and fair market value;\n(b) Real property shall be classified for assessment purposes on the basis of its actual use;\n(c) Real property shall be assessed on the basis of a uniform classification within each local government unit;\n(d) The appraisal, assessment, levy and collection of real property tax shall not be let to any private person; and\n(e) The appraisal and assessment of real property shall be equitable."}},{"id":"PH-H5648-A199","no":199,"noLabel":{"en":"Section 199."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Definitions. - When used in this Title:\n(a) \"Acquisition Cost\" for newly-acquired machinery not yet depreciated and appraised within the year of its purchase, refers to the actual cost of the machinery to its present owner, plus the cost of transportation, handling, and installation at the present site;\n(b) \"Actual Use\" refers to the purpose for which the property is principally or predominantly utilized by the person in possession thereof;\n(c) \"Ad Valorem Tax\" is a levy on real property determined on the basis of a fixed proportion of the value of the property;\n(d) \"Agricultural Land\" is land devoted principally to the planting of trees, raising of crops, livestock and poultry, dairying, salt making, inland fishing and similar aquacultural activities, and other agricultural activities, and is not classified as mineral, timber, residential, commercial or industrial land;\n(e) \"Appraisal\" is the act or process of determining the value of property as of a specified date for a specific purpose;\n(f) \"Assessment\" is the act or process of determining the value of a property, or proportion thereof subject to tax, including the discovery, listing, classification, and appraisal of properties;\n(g) \"Assessment Level\" is the percentage applied to the fair market value to determine the taxable value of the property;\n(h) \"Assessed Value\" is the fair market value of the real property multiplied by the assessment level. It is synonymous to taxable value;\n(i) \"Commercial Land\" is land devoted principally for the object of profit and is not classified as agricultural, industrial, mineral, timber, or residential land;\n(j) \"Depreciated Value\" is the value remaining after deducting depreciation from the acquisition cost;\n(k) \"Economic Life\" is the estimated period over which it is anticipated that a machinery or equipment may be profitably utilized;\n(l) \"Fair Market Value\" is the price at which a property may be sold by a seller who is not compelled to sell and bought by a buyer who is not compelled to buy;\n(m) \"Improvement\" is a valuable addition made to a property or an amelioration in its condition, amounting to more than a mere repair or replacement of parts involving capital expenditures and labor, which is intended to enhance its value, beauty or utility or to adapt it for new or further purposes;\n(n) \"Industrial Land\" is land devoted principally to industrial activity as capital investment and is not classified as agricultural, commercial, timber, mineral or residential land;\n(o) \"Machinery\" embraces machines, equipment, mechanical contrivances, instruments, appliances or apparatus which may or may not be attached, permanently or temporarily, to the real property. It includes the physical facilities for production, the installations and appurtenant service facilities, those which are mobile, self-powered or self-propelled, and those not permanently attached to the real property which are actually, directly, and exclusively used to meet the needs of the particular industry, business or activity and which by their very nature and purpose are designed for, or necessary to its manufacturing, mining, logging, commercial, industrial or agricultural purposes;\n(p) \"Mineral Lands\" are lands in which minerals, metallic or non-metallic, exist in sufficient quantity or grade to justify the necessary expenditures to extract and utilize such materials;\n(q) \"Reassessment\" is the assigning of new assessed values to property, particularly real estate, as the result of a general, partial, or individual reappraisal of the property;\n(r) \"Remaining Economic Life\" is the period of time expressed in years from the date of appraisal to the date when the machinery becomes valueless;\n(s) \"Remaining Value\" is the value corresponding to the remaining useful life of the machinery;\n(t) \"Replacement or Reproduction Cost\" is the cost that would be incurred on the basis of current prices, in acquiring an equally desirable substitute property, or the cost of reproducing a new replica of the property on the basis of current prices with the same or closely similar material; and\n(u) \"Residential Land\" is land principally devoted to habitation."}},{"id":"PH-H5648-A200","no":200,"noLabel":{"en":"Section 200."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Administration of the Real Property Tax. - The provinces and cities, including the municipalities within the Metropolitan Manila Area, shall be primarily responsible for the proper, efficient and effective administration of the real property tax.\nAppraisal and Assessment of Real Property"}},{"id":"PH-H5648-A201","no":201,"noLabel":{"en":"Section 201."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Appraisal of Real Property. - All real property, whether taxable or exempt, shall be appraised at the current and fair market value prevailing in the locality where the property is situated. The Department of Finance shall promulgate the necessary rules and regulations for the classification, appraisal, and assessment of real property pursuant to the provisions of this Code."}},{"id":"PH-H5648-A202","no":202,"noLabel":{"en":"Section 202."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Declaration of real Property by the Owner or Administrator. - It shall be the duty of all persons, natural or juridical, owning or administering real property, including the improvements therein, within a city or municipality, or their duly authorized representative, to prepare, or cause to be prepared, and file with the provincial, city or municipal assessor, a sworn statement declaring the true value of their property, whether previously declared or undeclared, taxable or exempt, which shall be the current and fair market value of the property, as determined by the declarant. Such declaration shall contain a description of the property sufficient in detail to enable the assessor or his deputy to identify the same for assessment purposes. The sworn declaration of real property herein referred to shall be filed with the assessor concerned once every three (3) years during the period from January first (1st) to June thirtieth (30th) commencing with the calendar year 1992."}},{"id":"PH-H5648-A203","no":203,"noLabel":{"en":"Section 203."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Duty of Person Acquiring Real Property or Making Improvement Thereon. - It shall also be the duty of any person, or his authorized representative, acquiring at any time real property in any municipality or city or making any improvement on real property, to prepare, or cause to be prepared, and file with the provincial, city or municipal assessor, a sworn statement declaring the true value of subject property, within sixty (60) days after the acquisition of such property or upon completion or occupancy of the improvement, whichever comes earlier."}},{"id":"PH-H5648-A204","no":204,"noLabel":{"en":"Section 204."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Declaration of Real Property by the Assessor. - When any person, natural or juridical, by whom real property is required to be declared under Section 202 hereof, refuses or fails for any reason to make such declaration within the time prescribed, the provincial, city or municipal assessor shall himself declare the property in the name of the defaulting owner, if known, or against an unknown owner, as the case may be, and shall assess the property for taxation in accordance with the provision of this Title. No oath shall be required of a declaration thus made by the provincial, city or municipal assessor."}},{"id":"PH-H5648-A205","no":205,"noLabel":{"en":"Section 205."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Listing of Real Property in the Assessment Rolls. -\n(a) In every province and city, including the municipalities within the Metropolitan Manila Area, there shall be prepared and maintained by the provincial, city or municipal assessor an assessment roll wherein shall be listed all real property, whether taxable or exempt, located within the territorial jurisdiction of the local government unit concerned. Real property shall be listed, valued and assessed in the name of the owner or administrator, or anyone having legal interest in the property.\n(b) The undivided real property of a deceased person may be listed, valued and assessed in the name of the estate or of the heirs and devisees without designating them individually; and undivided real property other than that owned by a deceased may be listed, valued and assessed in the name of one or more co-owners: Provided, however, That such heir, devisee, or co-owner shall be liable severally and proportionately for all obligations imposed by this Title and the payment of the real property tax with respect to the undivided property.\n(c) The real property of a corporation, partnership, or association shall be listed, valued and assessed in the same manner as that of an individual.\n(d) Real property owned by the Republic of the Philippines, its instrumentalities and political subdivisions, the beneficial use of which has been granted, for consideration or otherwise, to a taxable person, shall be listed, valued and assessed in the name of the possessor, grantee or of the public entity if such property has been acquired or held for resale or lease."}},{"id":"PH-H5648-A206","no":206,"noLabel":{"en":"Section 206."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Proof of Exemption of Real Property from Taxation. - Every person by or for whom real property is declared, who shall claim tax exemption for such property under this Title shall file with the provincial, city or municipal assessor within thirty (30) days from the date of the declaration of real property sufficient documentary evidence in support of such claim including corporate charters, title of ownership, articles of incorporation, by-laws, contracts, affidavits, certifications and mortgage deeds, and similar documents.\nIf the required evidence is not submitted within the period herein prescribed, the property shall be listed as taxable in the assessment roll. However, if the property shall be proven to be tax exempt, the same shall be dropped from the assessment roll."}},{"id":"PH-H5648-A207","no":207,"noLabel":{"en":"Section 207."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Real Property Identification System. - All declarations of real property made under the provisions of this Title shall be kept and filed under a uniform classification system to be established by the provincial, city or municipal assessor."}},{"id":"PH-H5648-A208","no":208,"noLabel":{"en":"Section 208."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Notification of Transfer of Real Property Ownership. - Any person who shall transfer real property ownership to another shall notify the provincial, city or municipal assessor concerned within sixty (60) days from the date of such transfer. The notification shall include the mode of transfer, the description of the property alienated, the name and address of the transferee."}},{"id":"PH-H5648-A209","no":209,"noLabel":{"en":"Section 209."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Duty of Registrar of Deeds to Appraise Assessor of Real Property Listed in Registry. -\n(a) To ascertain whether or not any real property entered in the Registry of Property has escaped discovery and listing for the purpose of taxation, the Registrar of Deeds shall prepare and submit to the provincial, city or municipal assessor, within six (6) months from the date of effectivity of this Code and every year thereafter, an abstract of his registry, which shall include brief but sufficient description of the real properties entered therein, their present owners, and the dates of their most recent transfer or alienation accompanied by copies of corresponding deeds of sale, donation, or partition or other forms of alienation.\n(b) It shall also be the duty of the Registrar of Deeds to require every person who shall present for registration a document of transfer, alienation, or encumbrance of real property to accompany the same with a certificate to the effect that the real property subject of the transfer, alienation, or encumbrance, as the case may be, has been fully paid of all real property taxes due thereon. Failure to provide such certificate shall be a valid cause for the Registrar of Deeds to refuse the registration of the document."}},{"id":"PH-H5648-A210","no":210,"noLabel":{"en":"Section 210."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Duty of Official Issuing Building Permit or Certificate of Registration of Machinery to Transmit Copy to Assessor. - Any public official or employee who may now or hereafter be required by law or regulation to issue to any person a permit for the construction, addition, repair, or renovation of a building, or permanent improvement on land, or a certificate of registration for any machinery, including machines, mechanical contrivances, and apparatus attached or affixed on land or to another real property, shall transmit a copy of such permit or certificate within thirty (30) days of its issuance, to the assessor of the province, city or municipality where the property is situated."}},{"id":"PH-H5648-A211","no":211,"noLabel":{"en":"Section 211."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Duty of Geodetic Engineers to Furnish Copy of Plans to Assessor. - It shall be the duty of all geodetic engineers, public or private, to furnish free of charge to the assessor of the province, city or municipality where the land is located with a white or blue print copy of each of all approved original or subdivision plans or maps of surveys executed by them within thirty (30) days from receipt of such plans from the Lands Management Bureau, the Land Registration Authority, or the Housing and Land Use Regulatory Board, as the case may be."}},{"id":"PH-H5648-A212","no":212,"noLabel":{"en":"Section 212."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Preparation of Schedule of Fair Market Values. - Before any general revision of property assessment is made pursuant to the provisions of this Title, there shall be prepared a schedule of fair market values by the provincial, city and municipal assessor of the municipalities within the Metropolitan Manila Area for the different classes of real property situated in their respective local government units for enactment by ordinance of the sanggunian concerned. The schedule of fair market values shall be published in a newspaper of general circulation in the province, city or municipality concerned or in the absence thereof, shall be posted in the provincial capitol, city or municipal hall and in two other conspicuous public places therein."}},{"id":"PH-H5648-A213","no":213,"noLabel":{"en":"Section 213."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Authority of Assessor to Take Evidence. - For the purpose of obtaining information on which to base the market value of any real property, the assessor of the province, city or municipality or his deputy may summon the owners of the properties to be affected or persons having legal interest therein and witnesses, administer oaths, and take deposition concerning the property, its ownership, amount, nature, and value."}},{"id":"PH-H5648-A214","no":214,"noLabel":{"en":"Section 214."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Amendment of Schedule of Fair Market Values. - The provincial, city or municipal assessor may recommend to the sanggunian concerned amendments to correct errors in valuation in the schedule of fair market values. The sanggunian concerned shall, by ordinance, act upon the recommendation within ninety (90) days from receipt thereof."}},{"id":"PH-H5648-A215","no":215,"noLabel":{"en":"Section 215."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Classes of Real Property for Assessment Purposes. - For purposes of assessment, real property shall be classified as residential, agricultural, commercial, industrial, mineral, timberland or special.\nThe city or municipality within the Metropolitan Manila Area, through their respective sanggunian, shall have the power to classify lands as residential, agricultural, commercial, industrial, mineral, timberland, or special in accordance with their zoning ordinances."}},{"id":"PH-H5648-A216","no":216,"noLabel":{"en":"Section 216."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Special Classes of Real Property. - All lands, buildings, and other improvements thereon actually, directly and exclusively used for hospitals, cultural, or scientific purposes, and those owned and used by local water districts, and government-owned or controlled corporations rendering essential public services in the supply and distribution of water and/or generation and transmission of electric power shall be classified as special."}},{"id":"PH-H5648-A217","no":217,"noLabel":{"en":"Section 217."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Actual Use of Real Property as Basis for Assessment. - Real property shall be classified, valued and assessed on the basis of its actual use regardless of where located, whoever owns it, and whoever uses it."}},{"id":"PH-H5648-A218","no":218,"noLabel":{"en":"Section 218."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Assessment Levels. - The assessment levels to be applied to the fair market value of real property to determine its assessed value shall be fixed by ordinances of the sangguniang panlalawigan, sangguniang panlungsod or sangguniang bayan of a municipality within the Metropolitan Manila Area, at the rates not exceeding the following:\n(a) On Lands:\nCLASS\nASSESSMENT LEVELS\nResidential 20% Agricultural 40% Commercial 50% Industrial 50% Mineral 50% Timberland 20%\n(b) On Buildings and Other Structures:\n(1) Residential Fair market Value Over Not Over Assessment Levels P175,000.00 0% P175,000.00 300,000.00 10% 300,000.00 500,000.00 20% 500,000.00 750,000.00 25% 750,000.00 1,000,000.00 30% 1,000,000.00 2,000,000.00 35% 2,000,000.00 5,000,000.00 40% 5,000,000.00 10,000,000.00 50% 10,000,000.00 60%\n(2) Agricultural Fair Market Value Over Not Over Assessment Levels P300,000.00 25% P300,000.00 500,000.00 30% 500,000.00 750,000.00 35% 750,000.00 1,000,000.00 40% 1,000,000.00 2,000,000.00 45% 2,000,000.00 50%\n(3) Commercial / Industrial Fair Market Value Over Not Over Assessment Levels P300,000.00 30% P300,000.00 500,000.00 35% 500,000.00 750,000.00 40% 750,000.00 1,000,000.00 50% 1,000,000.00 2,000,000.00 60% 2,000,000.00 5,000,000.00 70% 5,000,000.00 10,000,000.00 75% 10,000,000.00 80%\n(4) Timberland Fair Market Value Over Not Over Assessment Levels P300,000.00 45% P300,000.00 500,000.00 50% 500,000.00 750,000.00 55% 750,000.00 1,000,000.00 60% 5,000,000.00 2,000,000.00 65% 2,000,000.00"}},{"id":"PH-H5648-A424","no":424,"noLabel":{"en":"Section 424."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Katipunan ng Kabataan. - The katipunan ng kabataan shall be composed of all citizens of the Philippines actually residing in the barangay for at least six (6) months, who are fifteen (15) but not more than twenty-one (21) years of age, and who are duly registered in the list of the sangguniang kabataan or in the official barangay list in the custody of the barangay secretary."}},{"id":"PH-H5648-A425","no":425,"noLabel":{"en":"Section 425."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Meetings of the Katipunan ng Kabataan. - The katipunan ng kabataan shall meet at least once every three (3) months, or at the call of the chairman of the sangguniang kabataan or upon written petition of at least one-twentieth (1/20) of its members, to decide on important issues affecting the youth of the barangay."}},{"id":"PH-H5648-A426","no":426,"noLabel":{"en":"Section 426."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Powers and Functions of the Sangguniang Kabataan. - The sangguniang kabataan shall:\n(a) Promulgate resolutions necessary to carry out the objectives of the youth in the barangay in accordance with the applicable provisions of this Code;\n(b) Initiate programs designed to enhance the social, political, economic, cultural, intellectual, moral, spiritual, and physical development of the members;\n(c) Hold fund-raising activities, the proceeds of which shall be tax-exempt and shall accrue to the general fund of the sangguniang kabataan: Provided, however, That in the appropriation thereof, the specific purpose for which such activity has been held shall be first satisfied;\n(d) Create such bodies or committees as it may deem necessary to effectively carry out its programs and activities;\n(e) Submit annual and end-of-term reports to the sangguniang barangay on their projects and activities for the survival and development of the youth in the barangay;\n(f) Consult and coordinate with all youth organizations in the barangay for policy formulation and program implementation;\n(g) Coordinate with the appropriate national agency for the implementation of youth development projects and programs at the national level;\n(h) Exercise such other powers and perform such other duties and functions as the sangguniang barangay may determine or delegate; and\n(i) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance."}},{"id":"PH-H5648-A427","no":427,"noLabel":{"en":"Section 427."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Meetings of the Sangguniang Kabataan. - The sangguniang kabataan shall meet regularly once a month on the date, time, and place to be fixed by the said sanggunian. Special meetings may be called by the sangguniang kabataan chairman or any three (3) of its members by giving written notice to all members of the date, time, place and agenda of the meeting at least one (1) day in advance. Notices of regular or special meetings shall be furnished the punong barangay and the sangguniang barangay.\nA majority of the members of the sangguniang kabataan shall constitute a quorum."}},{"id":"PH-H5648-A428","no":428,"noLabel":{"en":"Section 428."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Qualifications. - An elective official of the sangguniang kabataan must be a citizen of the Philippines, a qualified voter of the katipunan ng kabataan, a resident of the barangay for at least one (1) year immediately prior to election, at least fifteen (15) years but not more than twenty- one (21) years of age on the day of his election, able to read and write Filipino, English, or the local dialect, and must not have been convicted of any crime involving moral turpitude."}},{"id":"PH-H5648-A429","no":429,"noLabel":{"en":"Section 429."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Term of Office. - The sangguniang kabataan chairman and members shall hold office for a period of three (3) years, unless sooner removed for cause as provided by law, permanently incapacitated, die or resign from office."}},{"id":"PH-H5648-A430","no":430,"noLabel":{"en":"Section 430."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Sangguniang Kabataan Chairman. - The registered voters of the katipunan ng kabataan shall elect the chairman of the sangguniang kabataan who shall automatically serve as an ex officio member of the sangguniang barangay upon his assumption to office. As such, he shall exercise the same powers, discharge the same duties and functions, and enjoy the same privileges as the regular sangguniang barangay members, and shall be the chairman of the committee on youth and sports development in the said sanggunian."}},{"id":"PH-H5648-A431","no":431,"noLabel":{"en":"Section 431."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Powers and Duties of the Sangguniang Kabataan Chairman. - In addition to the duties which may be assigned to him by the sangguniang barangay, the sangguniang kabataan chairman shall:\n(a) Call and preside over all meetings of the katipunan ng kabataan and the sangguniang kabataan;\n(b) Implement policies, programs, and projects within his jurisdiction in coordination with the sangguniang barangay;\n(c) Exercise general supervision over the affairs and activities of the sangguniang kabataan and the official conduct of its members, and such other officers of the sangguniang kabataan within his jurisdiction;\n(d) With the concurrence of the sangguniang kabataan, appoint from among the members of the sangguniang kabataan, the secretary and treasurer and such other officers as may be deemed necessary; and\n(e) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance."}},{"id":"PH-H5648-A432","no":432,"noLabel":{"en":"Section 432."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Sangguniang Kabataan Secretary. - The sangguniang kabataan secretary shall:\n(a) Keep all records of the katipunan ng kabataan and sangguniang kabataan;\n(b) Prepare and keep the minutes of all meetings of the katipunan ng kabataan and sangguniang kabataan;\n(c) Prepare all forms necessary for the conduct of registrations, elections, initiatives, referenda, or plebiscites, in coordination with the barangay secretary and the COMELEC; and\n(d) Perform such other duties and discharge such other functions as the chairman of the sangguniang kabataan may prescribe or direct."}},{"id":"PH-H5648-A433","no":433,"noLabel":{"en":"Section 433."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Sangguniang Kabataan Treasurer. - The sangguniang kabataan treasurer shall:\n(a) Take custody of all sangguniang kabataan property and funds not otherwise deposited with the city or municipal treasurer;\n(b) Collect and receive contributions, monies, materials, and all other sources intended for the sangguniang kabataan and katipunan ng kabataan;\n(c) Disburse funds in accordance with an approved budget of the sangguniang kabataan;\n(d) Certify to the availability of funds whenever necessary;\n(e) Submit to the sangguniang kabataan and to the sangguniang barangay certified and detailed statements of actual income and expenditures at the end of every month; and\n(f) Perform such other duties and discharge such other functions as the chairman of the sangguniang kabataan may direct."}},{"id":"PH-H5648-A434","no":434,"noLabel":{"en":"Section 434."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Privileges of Sangguniang Kabataan Officials. - The sangguniang kabataan chairman shall have the same privileges enjoyed by other sangguniang barangay officials under this Code subject to such requirements and limitations provided herein. During their incumbency, sangguniang kabataan officials shall be exempt from payment of tuition and matriculation fees while enrolled in public tertiary schools, including state colleges and universities. The national government shall reimburse said college or university the amount of the tuition and matriculation fees: Provided, That, to qualify for the privilege, the said officials shall enroll in a state college or university within or nearest their area of jurisdiction."}},{"id":"PH-H5648-A435","no":435,"noLabel":{"en":"Section 435."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Succession and Filling of Vacancies. -\n(a) In case a sangguniang kabataan chairman refuses to assume office, fails to qualify, is convicted of a felony, voluntarily resigns, dies, is permanently incapacitated, is removed from office, or has been absent without leave for more than three (3) consecutive months, the sangguniang kabataan member who obtained the next highest number of votes in the election immediately preceding shall assume the office of the chairman for the unexpired portion of the term, and shall discharge the powers and duties, and enjoy the rights and privileges appurtenant to the office. In case the said member refuses to assume the position or fails to qualify, the sangguniang member obtaining the next highest number of votes shall assume the position of the chairman for the unexpired portion of the term.\n(b) Where two (2) or more sangguniang kabataan members obtained the same next highest number of votes, the other sangguniang kabataan members shall conduct an election to choose the successor to the chairman from among the said members.\n(c) After the vacancy shall have been filled, the sangguniang kabataan chairman shall call a special election to complete the membership of said sanggunian. Such sangguniang kabataan member shall hold office for the unexpired portion of the term of the vacant seat.\n(d) In case of suspension of the sangguniang kabataan chairman, the successor, as determined in subsections (a) and (b) of this Section shall assume the position during the period of such suspension.\nPederasyon ng mga Sangguniang Kabataan"}},{"id":"PH-H5648-A436","no":436,"noLabel":{"en":"Section 436."},"chapter":{"en":"CHAPTER IX"},"text":{"en":"Pederasyon ng mga Kabataan . -\n(a) There shall be an organization of all the pederasyon ng mga sangguniang kabataan to be known as follows:\n(1) in municipalities pambayang pederasyon ng mga sangguniang kabataan;\n(2) in cities, panlungsod na pederasyon ng mga sangguniang kabataan;\n(3) in provinces, panlalawigang pederasyon ng mga kabataan;\n(4) in special metropolitan political subdivisions, pangmetropolitan pederasyon ng mga sangguniang kabataan; and\n(5) on the national level pambansang pederasyon ng mga sangguniang kabataan.\n(b) The pederasyon ng mga sangguniang kabataan shall, at all levels, elect from among themselves the president, vice- president and such other officers as may be necessary and shall be organized in the following manner:\n(1) The panlungsod and pambayang pederasyon shall be composed of the sangguniang kabataan chairmen of barangays in the city or municipality, respectively;\n(2) The panlalawigang pederasyon shall be composed of presidents of the panlungsod and pambayang pederasyon;\n(3) The pangmetropolitang pederasyon shall be composed of presidents of the panlungsod and pambayan pederasyon;\n(c) The elected presidents of the pederasyon at the provincial, highly urbanized city, and metropolitan political subdivision levels shall constitute the pambansang katipunan ng mga sangguniang kabataan."}},{"id":"PH-H5648-A437","no":437,"noLabel":{"en":"Section 437."},"chapter":{"en":"CHAPTER IX"},"text":{"en":"Constitution and By-Laws. - The term of office, manner of election, removal and suspension of the officers of the pederasyon ng mga sangguniang kabataan at all levels shall be governed by the constitution and by-laws of the pederasyon in conformity with the provisions of this Code and national policies on youth."}},{"id":"PH-H5648-A438","no":438,"noLabel":{"en":"Section 438."},"chapter":{"en":"CHAPTER IX"},"text":{"en":"Membership in the Sanggunian. -\n(a) A sangguniang kabataan chairman shall, upon certification of his election by the COMELEC and during his tenure of office is elected as pederasyon president, serve as an ex-officio member of the sangguniang panlalawigan, sangguniang panlungsod, and sangguniang bayan, as the case may be, without need of further appointment.\n(b) The vice-president of the pederasyon whose president has been elected as president of a higher pederasyon shall serve as ex-officio member of the sanggunian concerned without need of further appointment.\n(c) The pederasyon president or vice-president, as the case may be, shall be the chairman of the committee on youth and sports development of the sanggunian concerned.\nLinggo ng Kabataan"}},{"id":"PH-H5648-A439","no":439,"noLabel":{"en":"Section 439."},"chapter":{"en":"CHAPTER X"},"text":{"en":"Observance of Linggo ng Kabataan. -\n(a) Every barangay, municipality, city and province shall, in coordination with the pederasyon ng mga sangguniang kabataan at all levels, conduct an annual activity to be known as the Linggo ng Kabataan on such date as shall be determined by the Office of the President.\n(b) The observance of the Linggo ng Kabataan shall include the election of the counterparts of all local elective and appointive officials, as well as heads of national offices or agencies stationed or assigned in the territorial jurisdiction of the local government unit, among in-school and community youth residing in the local government unit concerned from ages thirteen (13) to seventeen (17). During said week, they shall hold office as boy and girl officials and shall perform such duties and conduct such activities as may be provided in the ordinance enacted pursuant to this Chapter.\nTHE MUNICIPALITY\nRole and Creation of the Municipality"}},{"id":"PH-H5648-A440","no":440,"noLabel":{"en":"Section 440."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Role of the Municipality. - The municipality, consisting of a group of barangays, serves primarily as a general purpose government for the coordination and delivery of basic, regular and direct services and effective governance of the inhabitants within its territorial jurisdiction."}},{"id":"PH-H5648-A441","no":441,"noLabel":{"en":"Section 441."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Manner of Creation. - A municipality may be created, divided, merged, abolished, or its boundary substantially altered only by an Act of Congress and subject to the approval by a majority of the votes cast in a plebiscite to be conducted by the COMELEC in the local government unit or units directly affected. Except as may otherwise be provided in the said Act, the plebiscite shall be held within one hundred twenty (120) days from the date of its effectivity."}},{"id":"PH-H5648-A442","no":442,"noLabel":{"en":"Section 442."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Requisites for Creation. -\n(a) A municipality may be created if it has an average annual income, as certified by the provincial treasurer, of at least Two million five hundred thousand pesos (P2,500,000.00) for the last two (2) consecutive years based on the 1991 constant prices; a population of at least twenty-five thousand (25,000) inhabitants as certified by the National Statistics Office; and a contiguous territory of at least fifty (50) square kilometers as certified by the Lands Management Bureau: Provided, That the creation thereof shall not reduce the land area, population or income of the original municipality or municipalities at the time of said creation to less than the minimum requirements prescribed herein.\n(b) The territorial jurisdiction of a newly-created municipality shall be properly identified by metes and bounds. The requirement on land area shall not apply where the municipality proposed to be created is composed of one (1) or more islands. The territory need not be contiguous if it comprises two (2) or more islands.\n(c) The average annual income shall include the income accruing to the general fund of the municipality concerned, exclusive of special funds, transfers and non-recurring income.\n(d) Municipalities existing as of the date of the effectivity of this Code shall continue to exist and operate as such. Existing municipal districts organized pursuant to presidential issuances or executive orders and which have their respective set of elective municipal officials holding office at the time of the effectivity of this Code shall henceforth be considered as regular municipalities.\nMunicipal Officials in General"}},{"id":"PH-H5648-A443","no":443,"noLabel":{"en":"Section 443."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Officials of the Municipal Government. -\n(a) There shall be in each municipality a municipal mayor, a municipal vice-mayor, sangguniang bayan members, a secretary to the sangguniang bayan, a municipal treasurer, a municipal assessor, a municipal accountant, a municipal budget officer, a municipal planning and development coordinator, a municipal engineer/building official, a municipal health officer and a municipal civil registrar.\n(b) In addition thereto, the mayor may appoint a municipal administrator, a municipal legal officer, a municipal agriculturist, a municipal environment and natural resources officer, a municipal social welfare and development officer, a municipal architect, and a municipal information officer.\n(c) The sangguniang bayan may:\n(1) Maintain existing offices not mentioned in subsections (a) and (b) hereof;\n(2) Create such other offices as may be necessary to carry out the purposes of the municipal government; or\n(3) Consolidate the functions of any office with those of another in the interest of efficiency and economy.\n(d) Unless otherwise provided herein, heads of departments and offices shall be appointed by the municipal mayor with the concurrence of the majority of all the sangguniang bayan members, subject to civil service law, rules and regulations. The sangguniang bayan shall act on the appointment within fifteen (15) days from the date of its submission; otherwise, the same shall be deemed confirmed.\n(e) Elective and appointive municipal officials shall receive such compensation, allowances and other emoluments as may be determined by law or ordinance, subject to the budgetary limitations on personal services as prescribed in Title Five, Book Two of this Code: Provided, That no increase in compensation of the mayor, vice-mayor, and sangguniang bayan members shall take effect until after the expiration of the full term of all the elective local officials approving such increase.\nOfficials and Offices Common to All Municipalities\nThe Municipal Mayor"}},{"id":"PH-H5648-A444","no":444,"noLabel":{"en":"Section 444."},"chapter":{"en":"ARTICLE I"},"text":{"en":"The Chief Executive: Powers, Duties, Functions and Compensation. -\n(a) The municipal mayor, as the chief executive of the municipal government, shall exercise such powers and performs such duties and functions as provided by this Code and other laws.\n(b) For efficient, effective and economical governance the purpose of which is the general welfare of the municipality and its inhabitants pursuant to Section 16 of this Code, the municipal mayor shall:\n(1) Exercise general supervision and control over all programs, projects, services, and activities of the municipal government, and in this connection, shall:\n(i) Determine the guidelines of municipal policies and be responsible to the sangguniang bayan for the program of government;\n(ii) Direct the formulation of the municipal development plan, with the assistance of the municipal development council, and upon approval thereof by the sangguniang bayan, implement the same;\n(iii) At the opening of the regular session of the sangguniang bayan for every calendar year and, as may be deemed necessary, present the program of government and propose policies and projects for the consideration of the sangguniang bayan as the general welfare of the inhabitants and the needs of the municipal government may require;\n(iv) Initiate and propose legislative measures to the sangguniang bayan and, from time to time as the situation may require, provide such information and data needed or requested by said sanggunian in the performance of its legislative functions;\n(v) Appoint all officials and employees whose salaries and wages are wholly or mainly paid out of municipal funds and whose appointments are not otherwise provided for in this Code, as well as those he may be authorized by law to appoint;\n(vi) Upon authorization by the sangguniang bayan, represent the municipality in all its business transactions and sign on its behalf all bonds, contracts, and obligations, and such other documents made pursuant to law or ordinance;\n(vii) Carry out such emergency measures as may be necessary during and in the aftermath of man-made and natural disasters and calamities;\n(viii) Determine, according to law or ordinance, the time, manner and place of payment of salaries or wages of the officials and employees of the municipality;\n(ix) Allocate and assign office space to municipal and other officials and employees who, by law or ordinance, are entitled to such space in the municipal hall and other buildings owned or leased by the municipal government;\n(x) Ensure that all executive officials and employees of the municipality faithfully discharge their duties and functions as provided by law and this Code, and cause to be instituted administrative or judicial proceedings against any official or employee of the municipality who may have committed as offense in the performance of his official duties;\n(xi) Examine the books, records and other documents of all offices, officials, agents or employees of the municipality and in aid of his executive powers and authority, require all national officials and employees stationed in or assigned to the municipality to make available to him such books, records, and other documents in their custody, except those classified by law as confidential;\n(xii) Furnish copies of executive orders issued by him to the provincial governor within seventy-two (72) hours after their issuance: Provided, That municipalities of Metropolitan Manila Area and that of any metropolitan political subdivision shall furnish copies of said executive orders to the metropolitan authority council chairman and to the Office of the President;\n(xiii) Visit component barangays of the municipality at least once every six (6) months to deepen his understanding of problems and conditions therein, listen and give appropriate counsel to local officials and inhabitants, inform the component barangay officials and inhabitants of general laws and ordinances which especially concern them, and otherwise conduct visits and inspections to the end that the governance of the municipality will improve the quality of life of the inhabitants;\n(xiv) Act on leave applications of officials and employees appointed by him and the commutation of the monetary value of leave credits according to law;\n(xv) Authorize official trips outside of the municipality of municipal officials and employees for a period not exceeding thirty (30) days;\n(xvi) Call upon any national official or employee stationed in or assigned to the municipality to advise him on matters affecting the municipality and to make recommendations thereon, or to coordinate in the formulation and implementation of plans, programs and projects, and when appropriate, initiate an administrative or judicial action against a national government official or employee who may have committed an offense in the performance of his official duties while stationed in or assigned to the local government unit concerned;\n(xvii) Subject to availability of funds, authorize payment of medical care, necessary transportation, subsistence, hospital or medical fees of municipal officials and employees who are injured while in the performance of their official duties and functions;\n(xviii) Solemnize marriages, any provision of law to the contrary notwithstanding;\n(xix) Conduct a palarong bayan, in coordination with the Department of Education, Culture and Sports, as an annual activity which shall feature traditional sports and disciplines included in national and international games; and\n(xx) Submit to the provincial governor the following reports: an annual report containing a summary of all matters pertaining to the management, administration and development of the municipality and all information and data relative to its political, social and economic conditions; and supplemental reports when unexpected events and situations arise at any time during the year, particularly when man-made or natural disasters or calamities affect the general welfare of the municipality, province, region or country. mayors of municipalities of the Metropolitan Manila Area and other metropolitan political subdivisions shall submit said reports to their respective metropolitan council chairmen and to the Office of the President;\n(2) Enforce all laws and ordinances relative to the governance of the municipality and the exercise of its corporate powers provided for under Section 22 of this Code implement all approved policies, programs, projects, services and activities of the municipality and, in addition to the foregoing, shall:\n(i) Ensure that the acts of the municipality's component barangays and of its officials and employees are within the scope of their prescribed powers, functions, duties and responsibilities;\n(ii) Call conventions, conferences, seminars or meetings of any elective and appointive officials of the municipality, including provincial officials and national officials and employees stationed in or assigned to the municipality at such time and place and on such subject as he may deem important for the promotion of the general welfare of the local government unit and its inhabitants;\n(iii) Issue such executive orders as are necessary for the proper enforcement and execution of laws and ordinances;\n(iv) Be entitled to carry the necessary firearm within his territorial jurisdiction;\n(v) Act as the deputized representative of the National Police Commission, formulate the peace and order plan of the municipality and upon its approval implement the same and exercise general and operational control and supervision over the local police in the municipality in accordance with R.A. No 6975;\n(vi) Call upon the appropriate law enforcement agencies to suppress disorder, riot, lawless violence, rebellion or sedition or to apprehend violators of the law when public interest so requires and the municipal police forces are inadequate to cope with the situation or the violators;\n(3) Initiate and maximize the generation of resources and revenues, and apply the same to the implementation of development plans, program objectives and priorities as provided for under Section 18 of this Code, particularly those resources and revenues programmed for gro-industrial development and country-wide growth and progress, and relative thereto, shall:\n(i) Require each head of an office or department to prepare and submit an estimate of appropriations for the ensuing calendar year, in accordance with the budget preparation process under Title Five, Book II of this Code;\n(ii) Prepare and submit to the sanggunian for approval the executive and supplemental budgets of the municipality for the ensuing calendar year in the manner provided for under Title Five, Book II of this Code;\n(iii) Ensure that all taxes and other revenues of the municipality are collected and that municipal funds are applied in accordance with law or ordinance to the payment of expenses and settlement of obligations of the municipality;\n(iv) Issue licenses and permits and suspend or revoke the same for any violation of the conditions upon which said licenses or permits had been issued, pursuant to law or ordinance;\n(v) Issue permits, without need of approval therefor from any national agency, for the holding of activities for any charitable or welfare purpose, excluding prohibited games of chance or shows contrary to law, public policy and public morals;\n(vi) Require owners of illegally constructed houses, buildings or other structures to obtain the necessary permit, subject to such fines and penalties as may be imposed by law or ordinance, or to make necessary changes in the construction of the same when said construction violates any law or ordinance, or to order the demolition or removal of said house, building or structure within the period prescribed by law or ordinance;\n(vii) Adopt adequate measures to safeguard and conserve land, mineral, marine, forest, and other resources of the municipality; provide efficient and effective property and supply management in the municipality; and protect the funds, credits, rights and other properties of the municipality; and\n(viii) Institute or cause to be instituted administrative or judicial proceedings for violation of ordinances in the collection of taxes, fees or charges, and for the recovery of funds and property; and cause the municipality to be defended against all suits to ensure that its interests, resources and rights shall be adequately protected;\n(4) Ensure the delivery of basic services and the provision of adequate facilities as provided for under Section 17 of this Code and, in addition thereto, shall:\n(i) Ensure that the construction and repair of roads and highways funded by the national government shall be, as far as practicable, carried out in a spatially contiguous manner and in coordination with the construction and repair of the roads and bridges of the municipality and the province; and\n(ii) Coordinate the implementation of technical services rendered by national and provincial offices, including public works and infrastructure programs in the municipality; and\n(5) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance.\n(c) During his incumbency, the municipal mayor shall hold office in the municipal hall.\n(d) The municipal mayor shall receive a minimum monthly compensation corresponding to Salary Grade twenty-seven (27) as prescribed under R.A. No. 6758 and the implementing guidelines issued pursuant thereto.\nThe Vice Mayor"}},{"id":"PH-H5648-A445","no":445,"noLabel":{"en":"Section 445."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Powers, Duties and Compensation. -\n(a) The vice-mayor shall:\n(1) Be the presiding officer of the sangguniang bayan and sign all warrants drawn on the municipal treasury for all expenditures appropriated for the operation of the sangguniang bayan;\n(2) Subject to civil service law, rules and regulations, appoint all officials and employees of the sangguniang bayan, except those whose manner of appointment is specifically provided in this Code;\n(3) Assume the office of the municipal mayor for the unexpired term of the latter in the event of permanent vacancy as provided for in Section 44, Book I of this Code;\n(4) Exercise the powers and perform the duties and functions of the municipal mayor in cases of temporary vacancy as provided for in Section 46, Book I of this Code; and\n(5) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance.\n(b) The vice-mayor shall receive a monthly compensation corresponding to Salary Grade twenty five (25) as prescribed under R.A. No. 6758 and the implementing guidelines issued pursuant thereto.\nThe Sangguniang Bayan"}},{"id":"PH-H5648-A446","no":446,"noLabel":{"en":"Section 446."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Composition. -\n(a) The sangguniang bayan, the legislative body of the municipality, shall be composed of the municipal vice mayor as the presiding officer, the regular sanggunian members, the president of the municipal chapter of the liga ng mga barangay, the president of the pambayang pederasyon ng mga sangguniang kabataan, and the sectoral representatives, as members.\n(b) In addition thereto, there shall be three (3) sectoral representatives: one (1) from the women; and as shall be determined by the sanggunian concerned within ninety (90) days prior to the holding of local elections, one (1) from the agricultural or industrial workers, and one (1) from other sectors, including the urban poor, indigenous cultural communities, or disabled persons.\n(c) The regular members of the sangguniang bayan and the sectoral representatives shall be elected in the manner as may be provided for by law."}},{"id":"PH-H5648-A447","no":447,"noLabel":{"en":"Section 447."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Powers, Duties, Functions and Compensation. -\n(a) The sangguniang bayan, as the legislative body of the municipality, shall enact ordinances, approve resolutions and appropriate funds for the general welfare of the municipality and its inhabitants pursuant to Section 16 of this Code and in the proper exercise of the corporate powers of the municipality as provided for under Section 22 of this Code, and shall:\n(1) Approve ordinances and pass resolutions necessary for an efficient and effective municipal government, and in this connection shall:\n(i) Review all ordinances approved by the sangguniang barangay and executive orders issued by the punong barangay to determine whether these are within the scope of the prescribed powers of the sanggunian and of the punong barangay;\n(ii) Maintain peace and order by enacting measures to prevent and suppress lawlessness, disorder, riot, violence, rebellion or sedition and impose penalties for the violation of said ordinances;\n(iii) Approve ordinances imposing a fine not exceeding Two thousand five hundred pesos (P2,500.00) or an imprisonment for a period not exceeding six (6) months, or both in the discretion of the court, for the violation of a municipal ordinance;\n(iv) Adopt measures to protect the inhabitants of the municipality from the harmful effects of man-made or natural disasters and calamities and to provide relief services and assistance for victims during and in the aftermath of said disasters or calamities and their return to productive livelihood following said events;\n(v) Enact ordinances intended to prevent, suppress and impose appropriate penalties for habitual drunkenness in public places, vagrancy, mendicancy, prostitution, establishment and maintenance of houses of ill repute, gambling and other prohibited games of chance, fraudulent devices and ways to obtain money or property, drug addiction, maintenance of drug dens, drug pushing, juvenile delinquency, the printing, distribution or exhibition of obscene or pornographic materials or publications, and such other activities inimical to the welfare and morals of the inhabitants of the municipality;\n(vi) Protect the environment and impose appropriate penalties for acts which endanger the environment, such as dynamite fishing and other forms of destructive fishing, illegal logging and smuggling of logs, smuggling of natural resources products and of endangered species of flora and fauna, slash and burn farming, and such other activities which result in pollution, acceleration of eutrophication of rivers and lakes, or of ecological imbalance;\n(vii) Subject to the provisions of this Code and pertinent laws, determine the powers and duties of officials and employees of the municipality;\n(viii) Determine the positions and salaries, wages, allowances and other emoluments and benefits of officials and employees paid wholly or mainly from municipal funds and provide for expenditures necessary for the proper conduct of programs. projects, services, and activities of the municipal government;\n(ix) Authorize the payment of compensation to a qualified person not in the government service who fills up a temporary vacancy or grant honorarium to any qualified official or employee designated to fill a temporary vacancy in a concurrent capacity, at the rate authorized by law;\n(x) Provide a mechanism and the appropriate funds therefor, to ensure the safety and protection of all municipal government property, public documents, or records such as those relating to property inventory, land ownership, records of births, marriages, deaths, assessments, taxation, accounts, business permits, and such other records and documents of public interest in the offices and departments of the municipal government;\n(xi) When the finances of the municipal government allow, provide for additional allowances and other benefits to judges, prosecutors, public elementary and high school teachers, and other national government officials stationed in or assigned to the municipality;\n(xii) Provide for legal assistance to barangay officials who, in the performance of their official duties or on the occasion thereof, have to initiate judicial proceedings or defend themselves against legal action; and\n(xii) Provide for group insurance or additional insurance coverage for barangay officials, including members of barangay tanod brigades and other service units, with public or private insurance companies, when the finances of the municipal government allow said coverage.\n(2) Generate and maximize the use of resources and revenues for the development plans, program objectives and priorities of the municipality as provided for under Section 18 of this Code with particular attention to agro-industrial development and countryside growth and progress, and relative thereto, shall:\n(i) Approve the annual and supplemental budgets of the municipal government and appropriate funds for specific programs, projects, services and activities of the municipality, or for other purposes not contrary to law, in order to promote the general welfare of the municipality and its inhabitants;\n(ii) Subject to the provisions of Book II of this Code and applicable laws and upon the majority vote of all the members of the sangguniang bayan, enact ordinances levying taxes, fees and charges, prescribing the rates thereof for general and specific purposes, and granting tax exemptions, incentives or reliefs;\n(iii) Subject to the provisions of Book II of this Code and upon the majority vote of all the members of the sangguniang bayan, authorize the municipal mayor to negotiate and contract loans and other forms of indebtedness;\n(iv) Subject to the provisions of Book II of this Code and applicable laws and upon the majority vote of all the members of the sangguniang bayan, enact ordinances authorizing the floating of bonds or other instruments of indebtedness, for the purpose of raising funds to finance development projects;\n(v) Appropriate funds for the construction and maintenance or the rental of buildings for the use of the municipality and, upon the majority vote of all the members of the sangguniang bayan, authorize the municipal mayor to lease to private parties such public buildings held in a proprietary capacity, subject to existing laws, rules and regulations;\n(vi) Prescribe reasonable limits and restraints on the use of property within the jurisdiction of the municipality:\n(vii) Adopt a comprehensive land use plan for the municipality: Provided, That the formulation, adoption, or modification of said plan shall be in coordination with the approved provincial comprehensive land use plan;\n(viii) Reclassify land within the jurisdiction of the municipality, subject to the pertinent provisions of this Code;\n(ix) Enact integrated zoning ordinances in consonance with the approved comprehensive land use plan, subject to existing laws, rules and regulations; established fire limits or zones, particularly in populous centers; and regulate the construction, repair or modification of buildings within said fire limits or zones in accordance with the provisions of this Code;\n(x) Subject to national law, process and approve subdivision plans for residential, commercial, or industrial purposes and other development purposes, and collect processing fees and other charges the proceeds of which shall accrue entirely to the municipality: Provided, however, That, where approval by a national agency or office is required, said approval shall not be withheld for more than thirty (30) days from receipt of the application. Failure to act on the application within the period stated above shall be deemed as approval thereof;\n(xi) Subject to the provisions of Book II of this Code, grant the exclusive privilege of constructing fish corrals or fish pens, or the taking or catching of bangus fry, prawn fry or kawag-kawag of fry of any species or fish within the municipal waters;\n(xii) With the concurrence of at least two-thirds (2/3) of all the members of the sangguniang bayan, grant tax exemptions, incentives or reliefs to entities engaged in community growth-inducing industries, subject to the provisions of Chapter 5, Title I, Book II of this Code.\n(xiii) Grant loans or provide grants to other local government units or to national, provincial and municipal charitable, benevolent or educational institutions: Provided, That said institutions are operated and maintained within the municipality;\n(xiv) Regulate the numbering of residential, commercial and other buildings; and\n(xv) Regulate the inspection, weighing and measuring of articles of commerce.\n(3) Subject to the provisions of Book II of this Code, grant franchises, enact ordinances authorizing the issuance of permits or licenses, or enact ordinances levying taxes, fees and charges upon such conditions and for such purposes intended to promote the general welfare of the inhabitants of the municipality, and pursuant to this legislative authority shall:\n(i) Fix and impose reasonable fees and charges for all services rendered by the municipal government to private persons or entities;\n(ii) Regulate any business, occupation, or practice of profession or calling which does not require government examination within the municipality and the conditions under which the license for said business or practice of profession may be issued or revoked;\n(iii) Prescribe the terms and conditions under which public utilities owned by the municipality shall be operated by the municipal government or leased to private persons or entities, preferably cooperatives;\n(iv) Regulate the display of and fix the license fees for signs, signboards, or billboards at the place or places where the profession or business advertised thereby is, in whole or in part, conducted;\n(v) Any law to the contrary notwithstanding, authorize and license the establishment, operation, and maintenance of cockpits, and regulate cockfighting and commercial breeding of gamecocks: Provided, That existing rights should not be prejudiced;\n(vi) Subject to the guidelines prescribed by the Department of Transportation and Communications, regulate the operation of tricycles and grant franchises for the operation thereof within the territorial jurisdiction of the municipality;\n(vii) Upon approval by a majority vote of all the members of the sangguniang bayan, grant a franchise to any person, partnership, corporation, or cooperative to establish, construct, operate and maintain ferries, wharves, markets or slaughterhouses, or such other similar activities within the municipality as may be allowed by applicable laws: Provided, That, cooperatives shall be given preference in the grant of such a franchise.\n(4) Regulate activities relative to the use of land, buildings and structures within the municipality in order to promote the general welfare and for said purpose shall:\n(i) Declare, prevent or abate any nuisance;\n(ii) Require that buildings and the premises thereof and any land within the municipality be kept and maintained in a sanitary condition; impose penalties for any violation thereof, or upon failure to comply with said requirement, have the work done and require the owner, administrator or tenant concerned to pay the expenses of the same; or require the filling up of any land or premises to a grade necessary for proper sanitation;\n(iii) Regulate the disposal of clinical and other wastes from hospitals, clinics and other similar establishments;\n(iv) Regulate the establishment, operation and maintenance of cafes, restaurants, beerhouses, hotels, motels, inns, pension houses, lodging houses, and other similar establishments, including tourist guides and transports;\n(v) Regulate the sale, giving away or dispensing of any intoxicating malt, vino, mixed or fermented liquors at any retail outlet;\n(vi) Regulate the establishment and provide for the inspection of steam boilers or any heating device in buildings and the storage of inflammable and highly combustible materials within the municipality;\n(vii) Regulate the establishment, operation, and maintenance of entertainment or amusement facilities, including theatrical performances, circuses, billiards pools, public dancing schools, public dance halls, sauna baths, massage parlors, and other places of entertainment or amusement; regulate such other events or activities for amusement or entertainment, particularly those which tend to disturb the community or annoy the inhabitants, or require the suspension or suppression of the same; or, prohibit certain forms of amusement or entertainment in order to protect the social and moral welfare of the community;\n(viii) Provide for the impounding of stray animals; regulate the keeping of animals in homes or as part of a business, and the slaughter, sale or disposition of the same; and adopt measures to prevent and penalize cruelty to animals; and\n(ix) Regulate the establishment, operation, and maintenance of funeral parlors and the burial or cremation of the dead, subject to existing laws, rules and regulations.\n(5) Approve ordinances which shall ensure the efficient and effective delivery of the basic services and facilities as provided for under Section 17 of this Code, and in addition to said services and facilities, shall:\n(i) Provide for the establishment, maintenance, protection, and conservation of communal forests and watersheds, tree parks, greenbelts, mangroves, and other similar forest development projects;\n(ii) Establish markets, slaughterhouses or animal corrals and authorize the operation thereof, and regulate the construction and operation of private markets, talipapas or other similar buildings and structures;\n(iii) Authorize the establishment, maintenance and operation of ferries, wharves, and other structures, and marine and seashore or offshore activities intended to accelerate productivity;\n(iv) Regulate the preparation and sale of meat, poultry, fish, vegetables, fruits, fresh dairy products, and other foodstuffs for public consumption;\n(v) Regulate the use of streets, avenues, alleys, sidewalks, bridges, parks and other public places and approve the construction, improvement, repair and maintenance of the same; establish bus and vehicle stops and terminals or regulate the use of the same by privately-owned vehicles which serve the public; regulate garages and the operation of conveyances for hire; designate stands to be occupied by public vehicles when not in use; regulate the putting up of signs, signposts, awnings and awning posts on the streets; provide for the lighting, cleaning and sprinkling of streets and public places;\n(vi) Regulate traffic on all streets and bridges, prohibit the putting up of encroachments or obstacles thereon, and, when necessary in the interest of public welfare, authorize the removal of encroachments and illegal constructions in public places;\n(vii) Subject to existing laws, provide for the establishment, operation, maintenance, and repair of an efficient waterworks system to supply water for the inhabitants; regulate the construction, maintenance, repair and use of hydrants, pumps, cisterns and reservoirs; protect the purity and quantity of the water supply of the municipality and, for this purpose, extend the coverage of appropriate ordinances over all territory within the drainage area of said water supply and within one hundred (100) meters of the reservoir, conduit, canal, aqueduct, pumping station, or watershed used in connection with the water service; and regulate the consumption, use or wastage of water;\n(viii) Regulate the drilling and excavation of the ground for laying of water, gas, sewer, and other pipes and the construction, repair and maintenance of public drains, sewers, cesspools, tunnels and similar structures; regulate the placing of poles and the use of crosswalks, curbs, and gutters; adopt measures to ensure public safety against open canals, manholes, live wires and other similar hazards to life and property; and regulate the construction and use of private water closets, privies and other similar structures in buildings and homes;\n(ix) Regulate the placing, stringing, attaching, installing, repair and construction of all gas mains, electric, telegraph and telephone wires, conduits, meters and other apparatus; and, provide for the correction, condemnation or removal of the same when found to be dangerous, defective or otherwise hazardous to the welfare of the inhabitants;\n(x) Subject to the availability of funds and to existing laws, rules and regulations, establish and provide for the operation of vocational and technical schools and similar post-secondary institutions and, with the approval of the Department of Education. Culture and Sports, fix and collect reasonable fees and other school charges on said institutions, subject to existing laws on tuition fees;\n(xi) Establish a scholarship fund for poor but deserving students residing within the municipality in schools located within its jurisdiction;\n(xii) Approve measures and adopt quarantine regulations to prevent the introduction and spread of diseases;\n(xiii) Provide for an efficient and effective system of solid waste and garbage collection disposal and prohibit littering and the placing or throwing of garbage, refuse and other filth and wastes;\n(xiv) Provide for the care of paupers, the aged, the sick, persons of unsound mind, disabled persons, abandoned minors, juvenile delinquents, drug dependents, abused children and other needy and disadvantaged persons, particularly children and youth below eighteen (18) years of age and, subject to availability of funds, establish and provide for the operation of centers and facilities for said needy and disadvantaged persons;\n(xv) Establish and provide for the maintenance and improvement of jails and detention centers, institute sound jail management programs, and appropriate funds for the subsistence of detainees and convicted prisoners in the municipality;\n(xvi) Establish a municipal council whose purpose is the promotion of culture and the arts, coordinate with government agencies and non-governmental organizations and, subject to the availability of funds, appropriate funds for the support and development of the same; and\n(xvi) Establish a municipal council for the orderly which shall formulate policies and adopt measures mutually beneficial to the elderly and to the community; provide incentives for non-governmental agencies and entities and, subject to the availability of funds, appropriate funds to support programs and projects for the benefit of the elderly; and\n(6) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance.\n(b) The members of the sangguniang bayan shall receive a minimum monthly compensation corresponding to Salary Grade twenty-four (24) as prescribed under R.A. No. 6758 and the implementing guidelines issued pursuant thereto: Provided, That, in municipalities in Metropolitan Manila Area and other metropolitan political subdivisions, members of the sangguniang bayan shall receive a minimum monthly compensation corresponding to Salary grade twenty-five (25).\nTHE CITY\nRole and Creation of the City"}},{"id":"PH-H5648-A448","no":448,"noLabel":{"en":"Section 448."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Role of the City. - The city, consisting of more urbanized and developed barangays. serves as a general purpose government for the coordination and delivery of basic, regular, and direct services and effective governance of the inhabitants within its territorial jurisdiction."}},{"id":"PH-H5648-A449","no":449,"noLabel":{"en":"Section 449."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Manner of Creation. - A city may be created, divided, merged, abolished, or its boundary substantially altered, only by an Act of Congress, and subject to approval by a majority of the votes cast in a plebiscite to be conducted by the COMELEC in the local government unit or units directly affected. Except as may otherwise be provided in such Act. the plebiscite shall be held within one hundred twenty (120) days from the date of its effectivity."}},{"id":"PH-H5648-A450","no":450,"noLabel":{"en":"Section 450."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Requisites for Creation.\n(a) A municipality or a cluster of barangays may be converted into a component city if it has an average annual income, as certified by the Department of Finance, of at least Twenty million (P20,000,000.00) for the last two (2) consecutive years based on 1991 constant prices, and if it has either of the following requisites:\n(i) a contiguous territory of at least one hundred (100) square kilometers, as certified by the Lands Management Bureau; or\n(ii) a population of not less than one hundred fifty thousand (150,000) inhabitants, as certified by the National Statistics Office:\nProvided, That, the creation thereof shall not reduce the land area, population, and income of the original unit or units at the time of said creation to less than the minimum requirements prescribed herein.\n(b) The territorial jurisdiction of a newly-created city shall be properly identified by metes and bounds. The requirement on land area shall not apply where the city proposed to be created is composed of one (1) or more islands. The territory need not be contiguous if it comprises two (2) or more islands.\n(c) The average annual income shall include the income accruing to the general fund, exclusive of specific funds, transfers, and non-recurring income."}},{"id":"PH-H5648-A451","no":451,"noLabel":{"en":"Section 451."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Cities, Classified. - A city may either be component or highly urbanized: Provided, however, That the criteria established in this Code shall not affect the classification and corporate status of existing cities. component cities whose charters prohibit their voters from voting for provincial elective officials. Independent component cities shall be independent of the province. Independent component cities are those"}},{"id":"PH-H5648-A452","no":452,"noLabel":{"en":"Section 452."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Highly Urbanized Cities.\n(a) Cities with a minimum population of two hundred thousand (200,000) inhabitants as certified by the National Statistics Office, and within the latest annual income of at least Fifty Million Pesos (P50,000,000.00) based on 1991 constant prices, as certified by the city treasurer, shall be classified as highly urbanized cities.\n(b) Cities which do not meet above requirements shall be considered component cities of the province in which they are geographically located. If a component city is located within the boundaries of two (2) or more provinces, such city shall be considered a component of the province of which it used to be a municipality.\n(c) Qualified voters of highly urbanized cities shall remain excluded from voting for elective provincial officials.\nUnless otherwise provided in the Constitution or this Code, qualified voters of independent component cities shall be governed by their respective charters, as amended, on the participation of voters in provincial elections.\nQualified voters of cities who acquired the right to vote for elective provincial officials prior to the classification of said cities as highly-urbanized after the ratification of the Constitution and before the effectivity of this Code, shall continue to exercise such right."}},{"id":"PH-H5648-A453","no":453,"noLabel":{"en":"Section 453."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Duty to Declare Highly Urbanized Status. - It shall be the duty of the President to declare a city as highly urbanized within thirty (30) days after it shall have met the minimum requirements prescribed in the immediately preceding section, upon proper application therefor and ratification in a plebiscite by the qualified voters therein.\nCity Officials in General"}},{"id":"PH-H5648-A454","no":454,"noLabel":{"en":"Section 454."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Officials of the City Government.\n(a) There shall be in each city a mayor, a vice-mayor, sangguniang panlungsod members, a secretary to the sangguniang panlungsod, a city treasurer, a city assessor, a city accountant, a city budget officer, a city planning and development coordinator, a city engineer, a city health officer, a city civil registrar, a city administrator, a city legal officer, a city veterinarian, a city social welfare and development officer, and a city general services officer.\n(b) In addition thereto, the city mayor may appoint a city architect, a city information officer, a city agriculturist, a city population officer, a city environment and natural resources officer, and a city cooperatives officer.\nThe appointment of a city population officer shall be optional in the city: Provided, however, That cities which have existing population offices shall continue to maintain such offices for a period of five (5) years from the date of the effectivity of this Code, after which said offices shall become optional.\n(c) The sangguniang panlungsod may:\n(1) Maintain existing offices not mentioned in subsections (a) and (b) hereof;\n(2) Create such other offices as may be necessary to carry out the purposes of the city government; or\n(3) Consolidate the functions of any office with those of another in the interest of efficiency and economy.\n(d) Unless otherwise provided herein, heads of departments and offices shall be appointed by the city mayor with the concurrence of the majority of all the sangguniang panlungsod members, subject to civil service law, rules and regulations. The sangguniang panlungsod shall act on the appointment within fifteen (15) days from the date of its submission, otherwise the same shall be deemed confirmed.\n(e) Elective and appointive city officials shall receive such compensation, allowances, and other emoluments as may be determined by law or ordinance, subject to the budgetary limitations on personal services prescribed under Title Five, Book II of this Code: Provided, That, no increase in compensation of the mayor, vice-mayor and sangguniang panlungsod members shall take effect until after the expiration of the full term of the said local officials approving such increase.\nOfficials and Offices Common to All Cities\nThe City Mayor"}},{"id":"PH-H5648-A455","no":455,"noLabel":{"en":"Section 455."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Chief Executive; Powers, Duties and Compensation.\n(a) The city mayor, as chief executive of the city government, shall exercise such powers and perform such duties and functions as provided by this Code and other laws.\n(b) For efficient, effective and economical governance the purpose of which is the general welfare of the city and its inhabitants pursuant to Section 16 of this Code, the city mayor shall:\n(1) Exercise general supervision and control over all programs, projects, services, and activities of the city government. and in this connection, shall:\n(i) Determine the guidelines of city policies and be responsible to the sangguniang panlungsod for the program of government;\n(ii) Direct the formulation of the city development plan, with the assistance of the city development council, and upon approval thereof by the sangguniang panlungsod, implement the same;\n(iii) Present the program of government and propose policies and projects for the consideration of the sangguniang panlungsod at the opening of the regular session of the sangguniang panlungsod every calendar year and as often as may be deemed necessary as the general welfare of the inhabitants and the needs of the city government may require;\n(iv) Initiate and propose legislative measures to the sangguniang panlungsod and as often as may be deemed necessary, provide such information and data needed or requested by said sanggunian in the performance of its legislative functions;\n(v) Appoint all officials and employees whose salaries and wages are wholly or mainly paid out of city funds and whose appointments are not otherwise provided for in this Code, as well as those he may be authorized by law to appoint;\n(vi) Represent the city in all its business transactions and sign in its behalf all bonds, contracts, and obligations, and such other documents upon authority of the sangguniang panlungsod or pursuant to law or ordinance;\n(vii) Carry out such emergency measures as may be necessary during and in the aftermath of man-made and natural disasters and calamities;\n(viii) Determine the time, manner and place of payment of salaries or wages of the officials and employees of the city, in accordance with law or ordinance;\n(ix) Allocate and assign office space to city and other officials and employees who, by law or ordinance, are entitled to such space in the city hall and other buildings owned or leased by the city government;\n(x) Ensure that all executive officials and employees of the city faithfully discharge their duties and functions as provided by law and this Code, and cause to be instituted administrative or judicial proceedings against any official or employee of the city who may have committed an offense in the performance of his official duties;\n(xi) Examine the books, records and other documents of all offices, officials, agents or employees of the city and, in aid of his executive powers and authority, require all national officials and employees stationed in or assigned to the city to make available to him such books, records, and other documents in their custody, except those classified by law as confidential;\n(xii) Furnish copies of executive orders issued by him, to the provincial governor in the case of component city mayors, to the Office of the President in the case of highly-urbanized city mayors and to their respective metropolitan council chairmen in the case of mayors of cities in the Metropolitan Manila Area and other metropolitan political subdivisions, within seventy-two (72) hours after their issuances;\n(xiii) Visit component barangays of the city at least once every six (6) months to deepen his understanding of problems and conditions, listen and give appropriate counsel to, local officials and inhabitants, inform the component barangay officials and inhabitants of general laws and ordinances which especially concern them, and otherwise conduct visits and inspections to ensure that the governance of the city will improve the quality of life of the inhabitants;\n(xiv) Act on leave applications of officials and employees appointed by him and the commutation of the monetary value of their leave credits in accordance with law;\n(xv) Authorize official trips of city officials and employees outside of the city for a period not exceeding thirty (30) days;\n(xvi) Call upon any national official or employee stationed in or assigned to the city to advise him on matters affecting the city and to make recommendations thereon; coordinate with said official or employee in the formulation and implementation of plans, programs and projects; and, when appropriate, initiate an administrative or judicial action against a national government official or employee who may have committed an offense in the performance of his official duties while stationed in or assigned to the city;\n(xvii) Authorize payment for medical care, necessary transportation, subsistence, hospital or medical fees of city officials and employees who are injured while in the performance of their duties and functions, subject to availability of funds;\n(xviii) Solemnize marriage, any provision of law to the contrary notwithstanding;\n(xix) Conduct an annual palarong panlungsod, which shall feature traditional sports and disciplines included in national and international games, in coordination with the Department of Education, Culture and Sports; and\n(xx) Submit to the provincial governor, in case of component cities; to the Office of the President, in the case of highly-urbanized cities; to their respective metropolitan authority council chairmen and to the Office of the President, in case of cities of the Metropolitan Manila Area and other metropolitan political subdivisions, the following reports: an annual report containing a summary of all matters pertinent to the management, administration and development of the city and all information and data relative to its political, social and economic conditions; and supplemental reports when unexpected events and situations arise at any time during the year, particularly when man-made or natural disasters or calamities affect the general welfare of the city, province, region or country;\n(2) Enforce all laws and ordinances relative to the governance of the city and in the exercise of the appropriate corporate powers provided for under Section 22 of this Code, implement all approved policies, programs, projects, services and activities of the city and, in addition to the foregoing, shall:\n(i) Ensure that the acts of the city's component barangays and of its officials and employees are within the scope of their prescribed powers, duties and functions;\n(ii) Call conventions, conferences, seminars, or meetings of any elective and appointive officials of the city, including provincial officials and national officials and employees stationed in or assigned to the city, at such time and place and on such subject as he may deem important for the promotion of the general welfare of the local government unit and its inhabitants;\n(ii) Issue such executive orders for the faithful and appropriate enforcement and execution of laws and ordinances;\n(iv) Be entitled to carry the necessary firearm within his territorial jurisdiction;\n(v) Act as the deputized representative of the National Police Commission, formulate the peace and order plan of the city and upon its approval, implement the same; and as such exercise general and operational control and supervision over the local police forces in the city, in accordance with R.A. No. 6975;\n(vi) Call upon the appropriate law enforcement agencies to suppress disorder, riot, lawless violence, rebellion or sedition, or to apprehend violators of the law when public interest so requires and the city police forces are inadequate to cope with the situations or the violators;\n(3) Initiate and maximize the generation of resources and revenues, and apply the same to the implementation of development plans, program objectives and priorities as provided for under Section 18 of this Code, particularly those resources and revenues programmed for agro-industrial development and countryside growth and progress and, relative thereto, shall:\n(i) Require each head of an office or department to prepare and submit an estimate of appropriations for the ensuing calendar year, in accordance with the budget preparations process under Title Five, Book II of this Code;\n(ii) Prepare and submit to the sanggunian for approval the executive and supplemental budgets of the city for the ensuing calendar year in the manner provided for under Title Five, Book II of this Code;\n(iii) Ensure that all taxes and other revenues of the city are collected, and that city funds are applied to the payment of expenses and settlement of obligations of the city, in accordance with law or ordinance;\n(iv) Issue licenses and permits and suspend or revoke the same for any violation of the conditions upon which said licenses or permits had been issued, pursuant to law or ordinance;\n(v) Issue permits, without need of approval therefor from any national agency, for the holding of activities for any charitable or welfare purpose, excluding prohibited games of chance or shows contrary to law, public policy and public morals;\n(vi) Require owners of illegally constructed houses, buildings or other structures to obtain the necessary permit, subject to such fines and penalties as may be imposed by law or ordinance, or to make necessary changes in the construction of the same when said construction violates any law or ordinance, or to order the demolition or removal of said house, building or structure within the period prescribed by law or ordinance;\n(vii) Adopt adequate measures to safeguard and conserve land, mineral, marine, forest, and other resources of the city; provide efficient and effective property and supply management in the city; and protect the funds, credits, rights and other properties of the city; and\n(viii) Institute or cause to be instituted administrative or judicial proceedings for violation of ordinances in the collection of taxes, fees or charges, and for the recovery of funds and property; and cause the city to be defended against all suits to ensure that its interests, resources and rights shall be adequately protected;\n(4) Ensure the delivery of basic services and the provision of adequate facilities as provided for under Section 17 of this Code and, in addition thereto, shall:\n(i) Ensure that the construction and repair of roads and highways funded by the national government shall be, as far as practicable, carried out in a spatially contiguous manner and in coordination with the construction and repair of the roads and bridges of the city, and in the case of component cities, of the city and of the province; and\n(ii) Coordinate the implementation of technical services, including public works and infrastructure programs, rendered by national offices in the case of highly urbanized and independent component cities, and by national and provincial offices in the case of component cities; and\n(5) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance.\n(c) During his incumbency, the city mayor shall hold office in the city hall.\n(d) The city mayor shall receive a minimum monthly compensation corresponding to Salary Grade Thirty (30) as prescribed under R.A. No. 6758 and the implementing guidelines issued pursuant thereto.\nThe City Vice-Mayor"}},{"id":"PH-H5648-A456","no":456,"noLabel":{"en":"Section 456."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Powers, Duties and Compensation.\n(a) The city vice-mayor shall:\n(1) Be the presiding officer of the sangguniang panlungsod and sign all warrants drawn on the city treasury for all expenditures appropriated for the operation of the sangguniang panlungsod;\n(2) Subject to civil service law, rules and regulations, appoint all officials and employees of the sangguniang panlungsod, except those whose manner of appointment is specifically provided in this Code;\n(3) Assume the office of the city mayor for the unexpired term of the latter in the event of permanent vacancy as provided for in Section 44, Book I of this Code;\n(4) Exercise the powers and perform the duties and functions of the city mayor in cases of temporary vacancy as provided for in Section 46, Book I of this Code; and\n(5) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance.\n(b) The city vice-mayor shall receive a monthly compensation corresponding to Salary Grade twenty eight (28) for a highly urbanized city and Salary Grade twenty-six (26) for a component city, as prescribed under R.A. No. 6758 and the implementing guidelines issued pursuant thereto.\nThe Sangguniang Panlungsod"}},{"id":"PH-H5648-A457","no":457,"noLabel":{"en":"Section 457."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Composition\n(a) The sangguniang panlungsod, the legislative body of the city, shall be composed of the city vice-mayor as presiding officer, the regular sanggunian members, the president of the city chapter of the liga ng mga barangay, the president of the panlungsod na pederasyon ng mga sangguniang kabataan, and the sectoral representatives, as members.\n(b) In addition thereto, there shall be three (3) sectoral representatives: one (1) from the women; and as shall be determined by the sanggunian concerned within ninety (90) days prior to the holding of the local elections, one (1) from agricultural or industrial workers; and one (1) from the other sectors, including the urban poor, indigenous cultural communities, or disabled persons.\n(c) The regular members of the sangguniang panlungsod and the sectoral representatives shall be elected in the manner as may be provided for by law."}},{"id":"PH-H5648-A458","no":458,"noLabel":{"en":"Section 458."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Powers, Duties, Functions and Compensation.\n(a) The sangguniang panlungsod, as the legislative body of the city, shall enact ordinances, approve resolutions and appropriate funds for the general welfare of the city and its inhabitants pursuant to Section 16 of this Code and in the proper exercise of the corporate powers of the city as provided for under Section 22 of this Code, and shall:\n(1) Approve ordinances and pass resolutions necessary for an efficient and effective city government, and in this connection, shall:\n(i) Review all ordinances approved by the sangguniang barangay and executive orders issued by the punong barangay to determine whether these are within the scope of the prescribed powers of the sanggunian and of the punong barangay;\n(ii) Maintain peace and order by enacting measures to prevent and suppress lawlessness, disorder, riot, violence, rebellion or sedition and impose penalties for violation of said ordinances;\n(iii) Approve ordinances imposing a fine not exceeding Five thousand pesos (P5,000.00) or an imprisonment for a period not exceeding one (1) year, or both in the discretion of the court, for the violation of a city ordinance;\n(iv) Adopt measures to protect the inhabitants of the city from the harmful effects of man-made or natural disasters and calamities, and to provide relief services and assistance for victims during and in the aftermath of said disasters or calamities and their return to productive livelihood following said events;\n(v) Enact ordinances intended to prevent, suppress and impose appropriate penalties for habitual drunkenness in public places, vagrancy, mendicancy, prostitution, establishment and maintenance of houses of ill repute, gambling and other prohibited games of chance, fraudulent devices and ways to obtain money or property, drug addiction, maintenance of drug dens, drug pushing, juvenile delinquency, the printing, distribution or exhibition of obscene or pornographic materials or publications, and such other activities inimical to the welfare and morals of the inhabitants of the city.\n(vi) Protect the environment and impose appropriate penalties for acts which endanger the environment, such as dynamite fishing and other forms of destructive fishing, illegal logging and smuggling of logs, smuggling of natural resources products and of endangered species of flora and fauna, slash and burn farming, and such other activities which result in pollution, acceleration of eutrophication of rivers and lakes, or of ecological imbalance;\n(vii) Subject to the provisions of this Code and pertinent laws, determine the powers and duties of officials and employees of the city;\n(viii) Determine the positions and the salaries, wages, allowances and other emoluments and benefits of officials and employees paid wholly or mainly from city funds and provide for expenditures necessary for the proper conduct of programs, projects, services, and activities of the city government;\n(ix) Authorize the payment of compensation to a qualified person not in the government service who fills up a temporary vacancy or grant honorarium to any qualified official or employee designated to fill a temporary vacancy in a concurrent capacity, at the rate authorized by law;\n(x) Provide a mechanism and the appropriate funds therefor, to ensure the safety and protection of all city government property, public documents, or records such as those relating to property inventory, land ownership, records of births, marriages, deaths, assessments, taxation, accounts, business permits, and such other records and documents of public interest in the offices and departments of the city government;\n(xi) When the finances of the city government allow, provide for additional allowances and other benefits to judges, prosecutors, public elementary and high school teachers, and other national government officials stationed in or assigned to the city;\n(xii) Provide legal assistance to barangay officials who, in the performance of their official duties or on the occasion thereof, have to initiate judicial proceedings or defend themselves against legal action; and\n(xiii) Provide for group insurance or additional insurance coverage for all barangay officials, including members of barangay tanod brigades and other service units, with public or private insurance companies, when the finances of the city government allow said coverage;\n(2) Generate and maximize the use of resources and revenues for the development plans, program objectives and priorities of the city as provided for under Section 18 of this Code, with particular attention to agro-industrial development and city-wide growth and progress, and relative thereto, shall:\n(i) Approve the annual and supplemental budgets of the city government and appropriate funds for specific programs, projects, services and activities of the city, or for other purposes not contrary to law, in order to promote the general welfare of the city and its inhabitants;\n(ii) Subject to the provisions of Book II of this Code and applicable laws and upon the majority vote of all the members of the sangguniang panlungsod, enact ordinances levying taxes, fees and charges, prescribing the rates thereof for general and specific purposes, and granting tax exemptions, incentives or reliefs;\n(iii) Subject to the provisions of Book II of this Code and upon the majority vote of all the members of the sangguniang panlungsod, authorize the city mayor to negotiate and contract loans and other forms of indebtedness;\n(iv) Subject to the provisions of Book II of this Code and applicable laws and upon the majority vote of all the members of the sangguniang panlungsod, enact ordinances authorizing the floating of bonds or other instruments of indebtedness, for the purpose of raising funds to finance development projects;\n(v) Appropriate funds for the construction and maintenance or the rental of buildings for the use of the city; and, upon the majority vote of all the members of the sangguniang panlungsod, authorize the city mayor to lease to private parties such public buildings held in a proprietary capacity, subject to existing laws, rules and regulations;\n(vi) Prescribe reasonable limits and restraints on the use of property within the jurisdiction of the city;\n(vii) Adopt a comprehensive land use plan for the city: Provided, That in the case of component cities, the formulation, adoption or modification of said plan shall be in coordination with the approved provincial comprehensive land use plan;\n(viii) Reclassify land within the jurisdiction of the city, subject to the pertinent provisions of this Code;\n(ix) Enact integrated zoning ordinances in consonance with the approved comprehensive land use plan, subject to existing laws, rules and regulations; establish fire limits or zones, particularly in populous centers; and regulate the construction, repair or modification of buildings within said fire limits or zones in accordance with the provisions of the Fire Code;\n(x) Subject to national law, process and approve subdivision plans for residential, commercial, or industrial purposes and other development purposes, and to collect processing fees and other charges, the proceeds of which shall accrue entirely to the city: Provided, however, That where approval of a national agency or office is required, said approval shall not be withheld for more than thirty (30) days from receipt of the application. Failure to act on the application within the period stated above shall be deemed as approval thereof;\n(xi) Subject to the provisions of Book II of this Code, grant the exclusive privilege of constructing fish corrals or fish pens, or the taking or catching of bangus fry, prawn fry or kawag-kawag, or fry of any species or fish within the city waters;\n(xii) With the concurrence of at least two-thirds (2/3) of all the members of the sangguniang panlungsod, grant tax exemptions, incentives or reliefs to entities engaged in community growth-inducing industries, subject to the provisions of Chapter 5, Title I, Book II of this Code;\n(xiii) Grant loans or provide grants to other local government units or to national, provincial, and city charitable, benevolent or educational institutions: Provided, That, said institutions are operated and maintained within the city;\n(xiv) Regulate the numbering of residential, commercial and other buildings; and\n(xv) Regulate the inspection, weighing and measuring of articles of commerce.\n(3) Subject to the provisions of Book II of this Code, enact ordinances granting franchises and authorizing the issuance of permits or licenses, upon such conditions and for such purposes intended to promote the general welfare of the inhabitants of the city and pursuant to this legislative authority shall:\n(i) Fix and impose reasonable fees and charges for all services rendered by the city government to private persons or entities;\n(ii) Regulate or fix license fees for any business or practice of profession within the city and the conditions under which the license for said business or practice of profession may be revoked and enact ordinances levying taxes thereon;\n(iii) Provide for and set the terms and conditions under which public utilities owned by the city shall be operated by the city government, and prescribe the conditions under which the same may be leased to private persons or entities, preferably cooperatives;\n(iv) Regulate the display of and fix the license fees for signs, signboards, or billboards at the place or places where the profession or business advertised thereby is, in whole or in part, conducted;\n(v) Any law to the contrary notwithstanding, authorize and license the establishment, operation, and maintenance of cockpits, and regulate cockfighting and commercial breeding of gamecocks: Provided, That existing rights should not be prejudiced;\n(vi) Subject to the guidelines prescribed by the Department of Transportation and Communications, regulate the operation of tricycles and grant franchises for the operation thereof within the territorial jurisdiction of the city;\n(vii) Upon approval by a majority vote of all the members of the sangguniang panlungsod: grant a franchise to any person, partnership, corporation, or cooperative to do business within the city; establish, construct, operate and maintain ferries, wharves, markets or slaughterhouses; or undertake such other activities within the city as may be allowed by existing laws: Provided, That, cooperatives shall be given preference in the grant of such a franchise.\n(4) Regulate activities relative to the use of land, buildings and structures within the city in order to promote the general welfare and for said purpose shall:\n(i) Declare, prevent or abate any nuisance;\n(ii) Require that buildings and the premises thereof and any land within the city be kept and maintained in a sanitary condition; impose penalties for any violation thereof; or, upon failure to comply with said requirement, have the work done at the expense of the owner, administrator or tenant concerned; or require the filling up of any land or premises to a grade necessary for proper sanitation;\n(iii) Regulate the disposal of clinical and other wastes from hospitals, clinics and other similar establishments;\n(iv) Regulate the establishment, operation and maintenance of cafes, restaurants, beerhouses, hotels, motels, inns, pension houses, lodging houses, and other similar establishments, including tourist guides and transports;\n(v) Regulate the sale, giving away or dispensing of any intoxicating malt, vino, mixed or fermented liquors at any retail outlet;\n(vi) Regulate the establishment and provide for the inspection of steam boilers or any heating device in buildings and the storage of inflammable and highly combustible materials within the city;\n(vii) Regulate the establishment, operation, and maintenance of any entertainment or amusement facilities, including theatrical performances, circuses, billiard pools, public dancing schools, public dance halls, sauna baths, massage parlors, and other places for entertainment or amusement; regulate such other events or activities for amusement or entertainment, particularly those which tend to disturb the community or annoy the inhabitants, or require the suspension or suppression of the same; or, prohibit certain forms of amusement or entertainment in order to protect the social and moral welfare of the community;\n(viii) Provide for the impounding of stray animals; regulate the keeping of animals in homes or as part of a business, and the slaughter, sale or disposition of the same; and adopt measures to prevent and penalize cruelty to animals; and\n(ix) Regulate the establishment, operation and maintenance of funeral parlors and the burial or cremation of the dead, subject to existing laws, rules and regulations.\n(5) Approve ordinances which shall ensure the efficient and effective delivery of the basic services and facilities as provided for under Section 17 of this Code, and in addition to said services and facilities, shall:\n(i) Provide for the establishment, maintenance, protection, and conservation of communal forests and watersheds, tree parks, greenbelts, mangroves, and other similar forest development projects;\n(ii) Establish markets, slaughterhouses or animal corrals and authorize the operation thereof by the city government; and regulate the construction and operation of private markets, talipapas or other similar buildings and structures;\n(iii) Authorize the establishment, maintenance and operation by the city government of ferries, wharves, and other structures intended to accelerate productivity related to marine and seashore or offshore activities;\n(iv) Regulate the preparation and sale of meat, poultry, fish, vegetables, fruits, fresh dairy products, and other foodstuffs for public consumption;\n(v) Regulate the use of streets, avenues, alleys, sidewalks, bridges, parks and other public places and approve the construction, improvement repair and maintenance of the same; establish bus and vehicle stops and terminals or regulate the use of the same by privately-owned vehicles which serve the public; regulate garages and the operation of conveyances for hire; designate stands to be occupied by public vehicles when not in use; regulate the putting up of signs, signposts, awnings and awning posts on the streets; and provide for the lighting, cleaning and sprinkling of streets; and public places;\n(vi) Regulate traffic on all streets and bridges; prohibit encroachments or obstacles thereon, and when necessary in the interest of public welfare, authorize the removal or encroachments and illegal constructions in public places;\n(vii) Subject to existing laws, establish and provide for the maintenance, repair and operation of an efficient waterworks system to supply water for the inhabitants and to purify the source of the water supply; regulate the construction, maintenance, repair and use of hydrants, pumps, cisterns and reservoirs; protect the purity and quantity of the water supply of the city and, for this purpose, extend the coverage of appropriate ordinances over all territory within the drainage area of said water supply and within one hundred (100) meters of the reservoir, conduit, canal, aqueduct, pumping station, or watershed used in connection with the water service; and regulate the consumption, use or wastage of water and fix and collect charges therefor;\n(viii) Regulate the drilling and excavation of the ground for the laying of water, gas, sewer, and other pipes and the construction, repair and maintenance of public drains, sewers, cesspools, tunnels and similar structures; regulate the placing of poles and the use of crosswalks, curbs, and gutters; adopt measures to ensure public safety against open canals, manholes. live wires and other similar hazards to life and property; and regulate the construction and use of private water closets, privies and other similar structures in buildings and homes;\n(ix) Regulate the placing, stringing, attaching, installing, repair and construction of all gas mains, electric, telegraph and telephone wires, conduits, meters and other apparatus; and provide for the correction, condemnation or removal of the same when found to be dangerous, defective, or otherwise hazardous to the welfare of the inhabitants;\n(x) Subject to the availability of funds and to existing laws, rules and regulations, establish and provide for the operation of vocational and technical schools and similar post-secondary institutions and, with the approval of the Department of Education, Culture and Sports and subject to existing law on tuition fees, fix and collect reasonable tuition fees and other school charges in educational institutions supported by the city government;\n(xi) Establish a scholarship fund for the poor but deserving students in schools located within its jurisdiction or for students residing within the city;\n(xii) Approve measures and adopt quarantine regulations to prevent the introduction and spread of diseases;\n(xiii) Provide for an efficient and effective system of solid waste and garbage collection and disposal; prohibit littering and the placing or throwing of garbage, refuse and other filth and wastes;\n(xiv) Provide for the care of disabled persons, paupers, the aged, the sick, persons of unsound mind, abandoned minors, juvenile delinquents, drug dependents, abused children and other needy and disadvantaged persons, particularly children and youth below eighteen (18) years of age; and subject to availability of funds, establish and provide for the operation of centers and facilities for said needy and disadvantaged persons;\n(xv) Establish and provide for the maintenance and improvement of jails and detention centers, institute a sound jail management program, and appropriate funds for the subsistence of detainees and convicted prisoners in the city;\n(xvi) Establish a city council whose purpose is the promotion of culture and the arts, coordinate with government agencies and non-governmental organizations and, subject to the availability of funds, appropriate funds for the support and development of the same; and\n(xvii) Establish a city council for the elderly which shall formulate policies and adopt measures mutually beneficial to the elderly and to the community; provide incentives for non-governmental agencies and entities and, subject to the availability of funds, appropriate funds to support programs and projects for the benefit of the elderly; and\n(6) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance.\n(b) The members of the sangguniang panlungsod of component cities shall receive a minimum monthly compensation corresponding to Salary Grade twenty-five (25) and members of the sangguniang panlungsod of highly-urbanized cities shall receive a minimum monthly compensation corresponding to Salary Grade twenty-seven (27), as prescribed under R.A. 6758 and the implementing guidelines issued pursuant thereto.\nTHE PROVINCE\nRole and Creation of the Province"}},{"id":"PH-H5648-A459","no":459,"noLabel":{"en":"Section 459."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Role of the Province. - The province, composed of cluster of municipalities, or municipalities and component cities, and as a political and corporate unit of government, serves as dynamic mechanism for developmental processes and effective governance of local government units within its territorial jurisdiction."}},{"id":"PH-H5648-A460","no":460,"noLabel":{"en":"Section 460."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Manner of Creation. - A province may be created, divided, merged, abolished, or its boundary substantially altered, only by an Act of Congress and subject to approval by a majority of the votes cast in a plebiscite to be conducted by the COMELEC in the local government unit or units directly affected. The plebiscite shall be held within one hundred twenty (120) days from the date of effectivity of said Act, unless otherwise provided therein."}},{"id":"PH-H5648-A461","no":461,"noLabel":{"en":"Section 461."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Requisites for Creation.\n(a) A province may be created if it has an average annual income, as certified by the Department of Finance, of not less than Twenty million pesos (P20,000,000.00) based on 1991 constant prices and either of the following requisites:\n(i) a contiguous territory of at least two thousand (2,000) square kilometers, as certified by the Lands Management Bureau; or\n(ii) a population of not less than two hundred fifty thousand (250,000) inhabitants as certified by the National Statistics Office:\nProvided, That, the creation thereof shall not reduce the land area, population, and income of the original unit or units at the time of said creation to less than the minimum requirements prescribed herein.\n(b) The territory need not be contiguous if it comprise two (2) or more islands or is separated by a chartered city or cities which do not contribute to the income of the province.\n(c) The average annual income shall include the income accruing to the general fund, exclusive of special funds, trust funds, transfers and non-recurring income."}},{"id":"PH-H5648-A462","no":462,"noLabel":{"en":"Section 462."},"chapter":{"en":"CHAPTER I"},"text":{"en":"Existing Sub-Provinces. - Existing sub-provinces are hereby converted into regular provinces upon approval by a majority of the votes cast in a plebiscite to be held in the said subprovinces and the original provinces directly affected. The plebiscite shall be conducted by the COMELEC simultaneously with the national elections following the effectivity of this Code.\nThe new legislative districts created as a result of such conversion shall continue to be represented in Congress by the duly-elected representatives of the original districts out of which said new provinces or districts were created until their own representatives shall have been elected in the next regular congressional elections and qualified.\nThe incumbent elected officials of the said subprovinces converted into regular provinces shall continue to hold office until June 30, 1992. Any vacancy occurring in the offices occupied by said incumbent elected officials, or resulting from expiration of their terms of office in case of a negative vote in the plebiscite results, shall be filled by appointment by the President. The appointees shall hold office until their successors shall have been elected in the regular local elections following the plebiscite mentioned herein and qualified. After effectivity of such conversion, the President shall fill up the position of governor of the newly-created province through appointment if none has yet been appointed to the same as hereinbefore provided, and shall also appoint a vice-governor and the other members of the sangguniang panlalawigan, all of whom shall likewise hold office until their successors shall have been elected in the next regular local elections and qualified.\nAll qualified appointive officials and employees in the career service of the said subprovinces at the time of their conversion into regular provinces shall continue in office in accordance with civil service law, rules and regulations.\nProvincial Officials in General"}},{"id":"PH-H5648-A463","no":463,"noLabel":{"en":"Section 463."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Officials of the Provincial Government.\n(a) There shall be in each province a governor, a vice-governor, members of the sangguniang panlalawigan, a secretary to the sangguniang panlalawigan, a provincial treasurer, a provincial assessor, a provincial accountant, a provincial engineer, a provincial budget officer, a provincial planning and development coordinator, a provincial legal officer, a provincial administrator, a provincial health officer, a provincial social welfare and development officer, a provincial general services officer, a provincial agriculturist, and a provincial veterinarian.\n(b) In addition thereto, the governor may appoint a provincial population officer, a provincial natural resources and environment officer, a provincial cooperative officer, a provincial architect, and a provincial information officer.\nThe appointment of a provincial population officer shall be optional in the province: Provided, however, That provinces which have existing population offices shall continue to maintain such offices for a period of five (5) years from the date of the effectivity of this Code, after which said offices shall become optional.\n(c) The sangguniang panlalawigan may:\n(1) Maintain existing offices not mentioned in subsections (a) and (b) hereof;\n(2) Create such other offices as may be necessary to carry out the purposes of the provincial government; or\n(3) Consolidate the functions of any office with those of another in the interest of efficiency and economy;\n(d) Unless otherwise provided herein, heads of departments and offices shall be appointed by the governor with the concurrence of the majority of all the sangguniang panlalawigan members, subject to civil service law, rules and regulations. The sangguniang panlalawigan shall act on the appointment within fifteen (15) days from the date of its submission; otherwise the same shall be deemed confirmed;\n(e) Elective and appointive provincial officials shall receive such compensation, allowances, and other emoluments as may be determined by law or ordinance, subject to the budgetary limitations on personal services prescribed under Title Five, Book II of this Code: Provided, That, no increase in compensation shall take effect until after the expiration of the full term of all the elective officials approving such increase."}},{"id":"PH-H5648-A464","no":464,"noLabel":{"en":"Section 464."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Residence and Office. - During the incumbency of the governor, he shall have his official residence in the capital of the province. All elective and appointive provincial officials shall hold office in the provincial capital: Provided, That, upon resolution of the sangguniang panlalawigan, elective and appointive provincial officials may hold office in any component city or municipality within the province for a period of not more than seven (7) days for any given month.\nOfficials and Offices Common to All Provinces\nThe Provincial Governor"}},{"id":"PH-H5648-A465","no":465,"noLabel":{"en":"Section 465."},"chapter":{"en":"ARTICLE I"},"text":{"en":"The Chief Executive: Powers, Duties, Functions, and Compensation.\n(a) The provincial governor, as the chief executive of the provincial government, shall exercise such powers and perform such duties and functions as provided by this Code and other laws.\n(b) For efficient, effective and economical governance the purpose of which is the general welfare of the province and its inhabitants pursuant to Section 16 of this Code, the provincial governor shall:\n(1) Exercise general supervision and control over all programs, projects, services, and activities of the provincial government, and in this connection, shall:\n(i) Determine the guidelines of provincial policies and be responsible to the sangguniang panlalawigan for the program of government;\n(ii) Direct the formulation of the provincial development plan, with the assistance of the provincial development council, and upon approval thereof by the sangguniang panlalawigan, implement the same;\n(iii) Present the program of government and propose policies and projects for the consideration of the sangguniang panlalawigan at the opening of the regular session of the sangguniang panlalawigan every calendar year and as after as may be deemed necessary as the general welfare of the inhabitants and the needs of the provincial government may require;\n(iv) Initiate and propose legislative measures to the sangguniang panlalawigan and as often as may be deemed necessary, provide such information and data needed or requested by said sanggunian in the performance of its legislative functions;\n(v) Appoint all officials and employees whose salaries and wages are wholly or mainly paid out of provincial funds and whose appointments are not otherwise provided for in this Code, as well as those he may be authorized by law to appoint;\n(vi) Represent the province in all its business transactions and sign in its behalf all bonds, contracts, and obligations, and such other documents upon authority of the sangguniang panlalawigan or pursuant to law or ordinance;\n(vii) Carry out such emergency measures as may be necessary during and in the aftermath of man-made and natural disasters and calamities;\n(viii) Determine the time, manner and place of payment of salaries or wages of the officials and employees of the province, in accordance with law or ordinance;\n(ix) Allocate and assign office space to provincial and other officials and employees who, by law or ordinance, are entitled to such space in the provincial capitol and other buildings owned or leased by the provincial government;\n(x) Ensure that all executive officials and employees of the province faithfully discharge their duties and functions as provided by law and this Code, and cause to be instituted administrative or judicial proceedings against any official or employee of the province who may have committed an offense in the performance of his official duties;\n(xi) Examine the books, records and other documents of all offices, officials, agents or employees of the province and, in aid of his executive powers and authority, require all national officials and employees stationed in the province to make available to him such books, records, and other documents in their custody, except those classified by law as confidential;\n(xii) Furnish copies of executive orders issued by him to the Office of the President within seventy-two (72) hours after their issuance;\n(xiii) Visit component cities and municipalities of the province at least once every six (6) months to deepen his understanding of problems and conditions, listen and give appropriate counsel to local officials and inhabitants, inform the officials and inhabitants of component cities and municipalities of general laws and ordinances which especially concern them, and otherwise conduct visits and inspections to ensure that the governance of the province will improve the quality of life of the inhabitants;\n(xiv) Act on leave applications of officials and employees appointed by him and the commutation of the monetary value of leave credits in accordance with law;\n(xv) Authorize official trips of provincial officials and employees outside of the province for a period not exceeding thirty (30) days;\n(xvi) Call upon any national official or employee stationed in or assigned to the province to advise him on matters affecting the province and to make recommendations thereon; coordinate with said official or employee in the formulation and implementation of plans, programs and projects; and when appropriate, initiate an administrative or judicial action against a national government official or employee who may have committed an offense in the performance of his official duties while stationed in or assigned to the province;\n(xvii) Authorize payment for medical care, necessary transportation, subsistence, hospital or medical fees of provincial officials and employees who are injured while in the performance of their official duties and functions, subject to availability of funds;\n(xviii) Represent the province in inter-provincial or regional sports councils or committees, and coordinate the efforts of component cities or municipalities in the regional or national palaro or sports development activities;\n(xix) Conduct an annual palarong panlalawigan, which shall feature traditional sports and disciplines included in national and international games in coordination with the Department of Education, Culture and Sports; and\n(xx) Submit to the Office of the President the following reports: an annual report containing a summary of all matters pertinent to the management, administration and development of the province and all information and data relative to its political, social and economic conditions; and supplemental reports when unexpected events and situations arise at any time during the year, particularly when man-made or natural disasters or calamities affect the general welfare of the province, region or country;\n(2) Enforce all laws and ordinances relative to the governance of the province and the exercise of the appropriate corporate powers provided for under Section 22 of this Code, implement all approved policies, programs, projects, services and activities of the province and, in addition to the foregoing, shall:\n(i) Ensure that the acts of the component cities and municipalities of the province and of its officials and employees are within the scope of their prescribed powers, duties and functions;\n(ii) Call conventions, conferences, seminars, or meetings of any elective and appointive officials of the province and its component cities and municipalities, including national officials and employees stationed in or assigned to the province, at such time and place and on such subject as he may deem important for the promotion of the general welfare of the province and its inhabitants;\n(iii) Issue such executive orders for the faithful and appropriate enforcement and execution of laws and ordinances;\n(iv) Be entitled to carry the necessary firearm within his territorial jurisdiction;\n(v) In coordination with the mayors of component cities and municipalities and the National Police Commission, formulate the peace and order plan of the province and upon its approval, implement the same in accordance with R.A. No. 6975;\n(vi) Call upon the appropriate national law enforcement agencies to suppress disorder, riot, lawless violence, rebellion or sedition or to apprehend violators of the law when public interest so requires and the police forces of the component city or municipality where the disorder or violation is happening are inadequate to cope with the situation or the violators;\n(3) Initiate and maximize the generation of resources and revenues, and apply the same to the implementation of development plans, program objectives and priorities as provided for under Section 18 of this Code, particularly those resources and revenues programmed for agro-industrial development and country-wide growth and progress and, relative thereto, shall:\n(i) Require each head of an office or department to prepare and submit an estimate of appropriations for the ensuing calendar year, in accordance with the budget preparation process under Title Five, Book II of this Code;\n(ii) Prepare and submit to the sanggunian for approval the executive and supplemental budgets of the province for the ensuing calendar year in the manner provided for under Title Five, Book II of this Code;\n(iii) Ensure that all taxes and other revenues of the province are collected, and that provincial funds are applied to the payment of expenses and settlement of obligations of the province, in accordance with law or ordinance;\n(iv) Issue licenses and permits and suspend or revoke the same for any violation of the conditions upon which said licenses or permits had been issued, pursuant to law or ordinance;\n(v) Adopt adequate measures to safeguard and conserve land, mineral, marine, forest and other resources of the province, in coordination with the mayors of component cities and municipalities; provide efficient and effective property and supply management in the province; and protect the funds, credits, rights, and other properties of the province; and\n(vi) Institute or cause to be instituted administrative or judicial proceedings for violation of ordinances in the collection of taxes, fees or charges, and for the recovery of funds and property, and cause the province to be defended against all suits to ensure that its interests, resources and rights shall be adequately protected.\n(4) Ensure the delivery of basic services and the provision of adequate facilities as provided for under Section 17 of this Code, and in addition thereto, shall:\n(i) Ensure that the construction and repair of roads and highways funded by the national government shall be, as far as practicable, carried out in a spatially contiguous manner and in coordination with the construction and repair of the roads and bridges of the province and of its component cities and municipalities; and\n(ii) Coordinate the implementation of technical services by national offices for the province and its component cities and municipalities, including public works and infrastructure programs of the provincial government and its component cities and municipalities;\n(5) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance.\n(c) The provincial governor shall receive a minimum monthly compensation corresponding to Salary Grade thirty (30) prescribed under R.A. No. 6758 and the implementing guidelines issued pursuant thereto.\nThe Provincial Vice-Governor"}},{"id":"PH-H5648-A466","no":466,"noLabel":{"en":"Section 466."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Powers, Duties, and Compensation.\n(a) The vice-governor shall:\n(1) Be the presiding officer of the sangguniang panlalawigan and sign all warrants drawn on the provincial treasury for all expenditures appropriated for the operation of the sangguniang panlalawigan;\n(2) Subject to civil service law, rules and regulations, appoint all officials and employees of the sangguniang panlalawigan, except those whose manner of appointment is specially provided in this Code;\n(3) Assume the office of the governor for the unexpired term of the latter in the event of permanent vacancy as provided for in Section 44, Book I of this Code;\n(4) Exercise the powers and perform the duties and functions of the governor in cases of temporary vacancy as provided for in Section 46, Book I of this Code; and\n(5) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance.\n(b) The vice-governor shall receive a monthly compensation corresponding to Salary Grade twenty-eight (28) as prescribed under R.A. No. 6758 and the implementing guidelines issued pursuant thereto.\nThe Sangguniang Panlalawigan"}},{"id":"PH-H5648-A467","no":467,"noLabel":{"en":"Section 467."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Composition.\n(a) The sangguniang panlalawigan, the legislative body of the province, shall be composed of the provincial vice-governor as presiding officer, the regular sanggunian members, the president of the provincial chapter of the liga ng mga barangay, the president of the panlalawigang pederasyon ng mga sangguniang kabataan, the president of the provincial federation of sanggunian members of municipalities and component cities and the sectoral representatives, as members.\n(b) In addition thereto, there shall be three (3) sectoral representatives: one (1) from the women; and as shall be determined by the sanggunian concerned within ninety (90) days prior to the holding of the local elections, one (1) from the agricultural or industrial workers; and one (1) from other sectors including the urban poor, indigenous cultural communities, or disabled persons.\n(c) The regular members of the sangguniang panlalawigan and the sectoral representatives shall be elected in the manner as may be provided for by law."}},{"id":"PH-H5648-A468","no":468,"noLabel":{"en":"Section 468."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Powers, Duties, Functions and Compensation.\n(a) The sangguniang panlalawigan, as the legislative body of the province, shall enact ordinances, approve resolutions and appropriate funds for the general welfare of the province and its inhabitants pursuant to Section 16 of this Code in the proper exercise of the corporate powers of the province as provided for under Section 22 of this Code, and shall:\n(1) Approve ordinances and pass resolutions necessary for an efficient and effective provincial government and, in this connection, shall:\n(i) Review all ordinances approved by the sangguniang of component cities and municipalities and executive orders issued by the mayors of said component units to determine whether these are within the scope of the prescribed powers of the sanggunian and of the mayor;\n(ii) Maintain peace and order by enacting measures to prevent and suppress lawlessness, disorder, riot, violence, rebellion or sedition and impose penalties for the violation of said ordinances;\n(iii) Approve ordinances imposing a fine not exceeding Five thousand pesos (P5,000.00) or imprisonment not exceeding one (1) year, or both in the discretion of the court, for the violation of a provincial ordinance;\n(iv) Adopt measures to protect the inhabitants of the province from harmful effects of man-made or natural disasters and calamities, and to provide relief services and assistance for victims during and in the aftermath of said disasters and calamities and their return to productive livelihood following said events;\n(v) Enact ordinances intended to prevent, suppress and impose appropriate penalties for habitual drunkenness in public places, vagrancy, mendicancy, prostitution, establishment and maintenance of houses of ill repute, gambling and other prohibited games of chance, fraudulent devices and ways to obtain money or property, drug addiction, maintenance of drug dens, drug pushing, juvenile delinquency, the printing, distribution or exhibition of obscene or pornographic materials or publications, and other activities inimical to the welfare and morals of the inhabitants of the province;\n(vi) Protect the environment and impose appropriate penalties for acts which endanger the environment, such as dynamite fishing and other forms of destructive fishing, illegal logging and smuggling of logs, smuggling of natural resources products and of endangered species of flora and fauna, slash and burn farming, and such other activities which result in pollution acceleration of eutrophication of rivers and lakes, or of ecological imbalance;\n(vii) Subject to the provisions of this Code and pertinent laws, determine the powers and duties of officials and employees of the province;\n(viii) Determine the positions and the salaries, wages, allowances and other emoluments and benefits of officials and employees paid wholly or mainly from provincial funds and provide for expenditures necessary for the proper conduct of programs, projects, services, and activities of the provincial government;\n(ix) Authorize the payment of compensation to a qualified person not in the government service who fills up a temporary vacancy, or grant honorarium to any qualified official or employee designated to fill a temporary vacancy in a concurrent capacity, at the rate authorized by law;\n(x) Provide a mechanism and the appropriate funds therefor, to ensure the safety and protection of all provincial government property, public documents, or records such as those relating to property inventory, land ownership, records of births, marriages, deaths, assessments, taxation, accounts, business permits, and such other records and documents of public interest in the offices and departments of the provincial government; and\n(xi) When the finances of the provincial government allow, provide for additional allowances and other benefits to judges, prosecutors, public elementary and high school teachers, and other national government officials stationed or assigned to the province.\n(2) Generate and maximize the use of resources and revenues for the development plans, program objectives and priorities of the province as provided for under Section 18 of this Code, with particular attention to agro-industrial development and country-wide growth and progress and relative thereto, shall:\n(i) Enact the annual and supplemental appropriations of the provincial government and appropriate funds for specific programs, projects, services and activities of the province, or for other purposes not contrary to law, in order to promote the general welfare of the province and its inhabitants;\n(ii) Subject to the provisions of Book II of this Code and applicable laws and upon the majority vote of all the members of the sangguniang panlalawigan, enact ordinances levying taxes, fees and charges, prescribing the rates thereof for general and specific purposes, and granting tax exemptions, incentives or reliefs;\n(iii) Subject to the provisions of Book II of this Code and applicable laws and upon the majority vote of all the members of the sangguniang panlalawigan, authorize the provincial governor to negotiate and contract loans and other forms of indebtedness;\n(iv) Subject to the provisions of Book II of this Code and applicable laws and upon the majority vote of all the members of the sangguniang panlalawigan, enact ordinances authorizing the floating of bonds or other instruments of indebtedness, for the purpose of raising funds to finance development projects;\n(v) Appropriate funds for the construction and maintenance or the rental of buildings for the use of the province; and upon the majority vote of all the members of the sangguniang panlalawigan, authorize the provincial governor to lease to private parties such public buildings held in a proprietary capacity, subject to existing laws, rules and regulations;\n(vi) Prescribe reasonable limits and restraints on the use of property within the jurisdiction of the province;\n(vii) Review the comprehensive land use plans and zoning ordinances of component cities and municipalities and adopt a comprehensive provincial land use plan, subject to existing laws; and\n(viii) Adopt measures to enhance the full implementation of the national agrarian reform program in coordination with the Department of Agrarian Reform;\n(3) Subject to the provisions of Book II of this Code, grant franchises, approve the issuance of permits or licenses, or enact ordinances levying taxes, fees and charges upon such conditions and for such purposes intended to promote the general welfare of the inhabitants of the province, and pursuant to this legislative authority, shall:\n(i) Fix and impose reasonable fees and charges for all services rendered by the provincial government to private persons or entities; and\n(ii) Regulate and fix the license fees for such activities as provided for under this Code.\n(4) Approve ordinances which shall ensure the efficient and effective delivery of basic services and facilities as provided for under Section 17 of this Code, and, in addition to said services and facilities, shall:\n(i) Adopt measures and safeguards against pollution and for the preservation of the natural ecosystem in the province, in consonance with approved standards on human settlements and environmental sanitation;\n(ii) Subject to applicable laws, facilitate or provide for the establishment and maintenance of waterworks system or district waterworks for supplying water to inhabitants of component cities and municipalities;\n(iii) Subject to the availability of funds and to existing laws, rules and regulations, provide for the establishment and operation of vocational and technical schools and similar post-secondary institutions; and, with the approval of the Department of Education, Culture and Sports and subject to existing laws on tuition fees, fix reasonable tuition fees and other school charges in educational institutions supported by the provincial government;\n(iv) Establish a scholarship fund for the poor but deserving students in schools located within its jurisdiction or for students residing within the province;\n(v) Approve measures and adopt quarantine regulations to prevent the introduction and spread of diseases within its territorial jurisdiction;\n(vi) Provide for the care of paupers, the aged, the sick, persons of unsound mind, abandoned minors, abused children, disabled persons, juvenile delinquents, drug dependents, and other needy and disadvantaged persons, particularly children and youth below eighteen (18) years of age; subject to availability of funds, establish and support the operation of centers and facilities for said needy and disadvantaged persons; and facilitate efforts to promote the welfare of families below the poverty threshold, the disadvantaged, and the exploited;\n(vii) Establish and provide the maintenance and improvement of jails and detention centers, institute a sound jail management program, and appropriate funds for the subsistence of detainees and convicted prisoners in the province;\n(viii) Establish a provincial council whose purpose is the promotion of culture and the arts, coordinate with government agencies and non-governmental organizations and, subject to the availability of funds, appropriate funds for the support and development of the same;\n(ix) Establish a provincial council for the elderly which shall formulate policies and adopt measures mutually beneficial to the elderly and to the province; and subject to the availability of funds, appropriate funds to support programs and projects for the elderly; and provide incentives for non-governmental agencies and entities to support the programs and projects of the elderly; and\n(5) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance.\n(b) The members of the sangguniang panlalawigan shall receive a minimum monthly compensation corresponding to Salary Grade twenty-seven (27) as prescribed under R.A. No. 6758 and the implementing guidelines issued pursuant thereto.\nAPPOINTED LOCAL OFFICIALS COMMON TO ALL MUNICIPALITIES, CITIES AND PROVINCES Secretary to the Sanggunian"}},{"id":"PH-H5648-A469","no":469,"noLabel":{"en":"Section 469."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Qualifications, Powers and Duties.\n(a) There shall be a secretary to the sanggunian who shall be a career official with the rank and salary equal to a head of department or office.\n(b) No person shall be appointed secretary to the sanggunian unless he is a citizen of the Philippines, a resident of the local government unit concerned, of good moral character, a holder of a college degree preferably in law, commerce or public administration from a recognized college or university, and a first grade civil service eligible or its equivalent.\nThe appointment of a secretary to the sanggunian is mandatory for provincial, city and municipal governments.\n(c) The secretary to the sanggunian shall take charge of the office of the secretary to the sanggunian and shall:\n(1) Attend meetings of the sanggunian and keep a journal of its proceedings;\n(2) Keep the seal of the local government unit and affix the same with his signature to all ordinances, resolutions, and other official acts of the sanggunian and present the same to the presiding officer for his signature;\n(3) Forward to the governor or mayor, as the case may be, for approval, copies of ordinances enacted by the sanggunian and duly certified by the presiding officer, in the manner provided in Section 54 under Book I of this Code;\n(4) Forward to the sanggunian panlungsod or bayan concerned, in the case of the sangguniang barangay, and to the sangguniang panlalawigan concerned, in the case of the sangguniang panlungsod of component cities or sangguniang bayan, copies of duly approved ordinances, in the manner provided in Sections 56 and 57 under Book I of this Code;\n(5) Furnish, upon request of any interested party, certified copies of records of public character in his custody, upon payment to the treasurer of such fees as may be prescribed by ordinance;\n(6) Record in a book kept for the purpose, all ordinances and resolutions enacted or adopted by the sanggunian, with the dates of passage and publication thereof;\n(7) Keep his office and all non-confidential records therein open to the public during the usual business hours;\n(8) Translate into the dialect used by the majority of the inhabitants all ordinances and resolutions immediately after their approval, and cause the publication of the same together with the original version in the manner provided under this Code; and\n(9) Take custody of the local archives and, where applicable, the local library and annually account for the same; and\n(d) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance relative to his position.\nThe Treasurer"}},{"id":"PH-H5648-A470","no":470,"noLabel":{"en":"Section 470."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Appointment, Qualifications, Powers, and Duties.\n(a) The treasurer shall be appointed by the Secretary of Finance from a list of at least three (3) ranking, eligible recommendees of the governor or mayor, as the case may be, subject to civil service law, rules and regulations.\n(b) The treasurer shall be under the administrative supervision of the governor or mayor, as the case may be, to whom he shall report regularly on the tax collection efforts in the local government unit;\n(c) No person shall be appointed treasurer unless he is a citizen of the Philippines, a resident of the local government unit concerned, of good moral character, a holder of a college degree preferably in commerce, public administration or law from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in treasury or accounting service for at least five (5) years in the case of the city or provincial treasurer, and three (3) years in the case of municipal treasurer.\nThe appointment of a treasurer shall be mandatory for provincial, city and municipal governments;\n(d) The treasurer shall take charge of the treasury office, perform the duties provided for under Book II of this Code, and shall:\n(1) Advise the governor or mayor, as the case may be, the sanggunian, and other local government and national officials concerned regarding disposition of local government funds, and on such other matters relative to public finance;\n(2) Take custody of and exercise proper management of the funds of the local government unit concerned;\n(3) Take charge of the disbursement of all local government funds and such other funds the custody of which may be entrusted to him by law or other competent authority;\n(4) Inspect private commercial and industrial establishments within the jurisdiction of the local government unit concerned in relation to the implementation of tax ordinances, pursuant to the provisions under Book II of this Code;\n(5) Maintain and update the tax information system of the local government unit;\n(6) In the case of the provincial treasurer, exercise technical supervision over all treasury offices of component cities and municipalities; and\n(e) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance."}},{"id":"PH-H5648-A471","no":471,"noLabel":{"en":"Section 471."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Assistant Treasurer.\n(a) An assistant treasurer may be appointed by the Secretary of Finance from a list of at least three (3) ranking, eligible recommendees of the governor or mayor, subject to civil service law, rules and regulations.\n(b) No person shall be appointed assistant treasurer unless he is a citizen of the Philippines, a resident of the local government unit concerned, of good moral character, a holder of a college degree preferably in commerce, public administration, or law from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired at least five (5) years experience in the treasury or accounting service in the case of the city or provincial assistant treasurer and three (3) years in the case of municipal assistant treasurer.\nThe appointment of an assistant treasurer shall be optional for provincial, city and municipal governments;\n(c) The assistant treasurer shall assist the treasurer and perform such duties as the latter may assign to him. He shall have authority to administer oaths concerning notices and notifications to those delinquent in the payment of real property tax and concerning official matters relating to the accounts of the treasurer or otherwise arising in the offices of the treasurer and the assessor.\nThe Assessor"}},{"id":"PH-H5648-A472","no":472,"noLabel":{"en":"Section 472."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Qualifications, Powers and Duties.\n(a) No person shall be appointed assessor unless he is a citizen of the Philippines, a resident of the local government unit concerned, of good moral character, a holder of a college degree preferably in civil or mechanical engineering, commerce, or any other related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in real property assessment work or in any related field for at least five (5) years in the case of the city or provincial assessor, and three (3) years in the case of the municipal assessor.\nThe appointment of an assessor shall be mandatory for provincial, city and municipal governments.\n(b) The assessor shall take charge of the assessor's office, perform the duties provided under Book II of this Code, and shall:\n(1) Ensure that all laws and policies governing the appraisal and assessment of real properties for taxation purposes are properly executed;\n(2) Initiate, review, and recommend changes in policies and objectives, plans and programs, techniques, procedures and practices in the valuation and assessment of real properties for taxation purposes;\n(3) Establish a systematic method of real property assessment;\n(4) Install and maintain a real property identification and accounting system;\n(5) Prepare, install and maintain a system of tax mapping, showing graphically all property subject to assessment and gather all data concerning the same;\n(6) Conduct frequent physical surveys to verify and determine whether all real property within the province are properly listed in the assessment rolls;\n(7) Exercise the functions of appraisal and assessment primarily for taxation purposes of all real properties in the local government unit concerned;\n(8) Prepare a schedule of the fair market value for the different classes of real properties, in accordance with Title Two under Book II of this Code;\n(9) Issue, upon request of any interested party, certified copies of assessment records of real property and all other records relative to its assessment, upon payment of a service charge or fee to the treasurer;\n(10) Submit every semester a report of all assessments, as well as cancellations and modifications of assessments to the local chief executive and the sanggunian concerned;\n(11) In the case of the assessor of a component city or municipality attend, personally or through an authorized representative, all sessions of the local board of assessment appeals whenever his assessment is the subject of the appeal, and present or submit any information or record in his possession as may be required by the board; and\n(12) In the case of the provincial assessor, exercise technical supervision and visitorial functions over all component city and municipal assessor, coordinate with component city or municipal assessors in the conduct of tax mapping operations and all other assessment activities, and provide all forms of assistance therefor: Provided, however, That, upon full provision by the component city or municipality concerned to its assessor's office of the minimum personnel, equipment, and funding requirements as may be prescribed by the Secretary of Finance, such functions shall be delegated to the said city or municipal assessor; and\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance."}},{"id":"PH-H5648-A473","no":473,"noLabel":{"en":"Section 473."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Assistant Assessor.\n(a) No person shall be appointed assistant assessor unless he is a citizen of the Philippines, a resident of the local government unit concerned, of good moral character, a holder of a college degree preferably in civil or mechanical engineering, commerce, or any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in assessment or in any related field for at least three (3) years in the case of the city or provincial assistant assessor, and one (1) year in the case of the city or provincial assistant assessor.\nThe appointment of an assistant assessor shall be optional for provincial, city and municipal governments.\n(b) The assistant assessor shall assist the assessor and perform such other duties as the latter may assign to him. He shall have the authority to administer oaths on all declarations of real property for purposes of assessments.\nThe Accountant"}},{"id":"PH-H5648-A474","no":474,"noLabel":{"en":"Section 474."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Qualifications, Powers and Duties.\n(a) No person shall be appointed accountant unless he is a citizen of the Philippines, a resident of the local government unit concerned, of good moral character, and a a certified public accountant. He must have acquired experience in the treasury or accounting service for at least five (5) years in the case of the provincial or city accountant, and three (3) years in the case of the municipal accountant.\nThe appointment of an accountant is mandatory for the provincial, city and municipal governments.\n(b) The accountant shall take charge of both the accounting and internal audit services of the local government unit concerned and shall:\n(1) Install and maintain an internal audit system in the local government unit concerned;\n(2) Prepare and submit financial statements to the governor or mayor, as the case may be, and to the sanggunian concerned;\n(3) Appraise the sanggunian and other local government officials on the financial condition and operations of the local government unit concerned;\n(4) Certify to the availability of budgetary allotment to which expenditures and obligations may be properly charged;\n(5) Review supporting documents before preparation of vouchers to determine completeness of requirements;\n(6) Prepare statements of cash advances, liquidation, salaries, allowances, reimbursements and remittances pertaining to the local government unit;\n(7) Prepare statements of journal vouchers and liquidation of the same and other adjustments related thereto;\n(8) Post individual disbursements to the subsidiary ledger and index cards;\n(9) Maintain individual ledgers for officials and employees of the local government unit pertaining to payrolls and deductions;\n(10) Record and post in index cards details of purchased furniture, fixtures, and equipment, including disposal thereof, if any;\n(11) Account for all issued requests for obligations and maintain and keep all records and reports related thereto;\n(12) Prepare journals and the analysis of obligations and maintain and keep all records and reports related thereto; and\n(13) Exercise such other powers and perform such other duties and functions as may be provided by law or ordinance.\n(c) The incumbent chief accountant in the office of the treasurer shall be given preference in the appointment to the position of accountant.\nThe Budget Officer"}},{"id":"PH-H5648-A475","no":475,"noLabel":{"en":"Section 475."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Qualifications, Powers and Duties.\n(a) No person shall be appointed budget officer unless he is a citizen of the Philippines, a resident of the local government unit concerned, of good moral character, a holder of a college degree preferably in accounting, economics, public administration or any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in government budgeting or in any related field for at least five (5) years in the case of the provincial or city budget officer, and at least three (3) years in the case of the municipal budget officer.\nThe appointment of a budget officer shall be mandatory for the provincial, city, and municipal governments.\n(b) The budget officer shall take charge of the budget office and shall:\n(1) Prepare forms, orders, and circulars embodying instructions on budgetary and appropriation matters for the signature of the governor or mayor, as the case may be;\n(2) Review and consolidate the budget proposals of different departments and offices of the local government unit;\n(3) Assist the governor or mayor, as the case may be, in the preparation of the budget and during budget hearings;\n(4) Study and evaluate budgetary implications of proposed legislation and submit comments and recommendations thereon;\n(5) Submit periodic budgetary reports to the Department of Budget and Management;\n(6) Coordinate with the treasurer, accountant, and the planning and development coordinator for the purpose of budgeting;\n(7) Assist the sanggunian concerned in reviewing the approved budgets of component local government units;\n(8) Coordinate with the planning and development coordinator in the formulation of the local government unit development plan; and\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance.\n(d) The appropriations for personal services of the budget officer provided under the Department of Budget and Management shall, upon effectivity of this Code, be transferred to the local government unit concerned. Thereafter, the appropriations for personal services of the budget officer shall be provided for in full in the budget of the local government unit.\nThe Planning and Development Coordinator"}},{"id":"PH-H5648-A476","no":476,"noLabel":{"en":"Section 476."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Qualifications, Powers and Duties.\n(a) No person shall be appointed planning and development coordinator unless he is a citizen of the Philippines, a resident of the local government unit concerned, of good moral character, a holder of a college degree preferably in urban planning, development studies, economics, public administration, or any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in development planning or in any related field for at least five (5) years in the case of the provincial or city planning and development coordinator, and three (3) years in the case of the municipal planning and development coordinator.\nThe appointment of a planning and development coordinator shall be mandatory for provincial, city and municipal governments.\n(b) The planning and development coordinator shall take charge of the planning and development office and shall:\n(1) Formulate integrated economic, social, physical, and other development plans and policies for consideration of the local government development council;\n(2) Conduct continuing studies, researches, and training programs necessary to evolve plans and programs for implementation;\n(3) Integrate and coordinate all sectoral plans and studies undertaken by the different functional groups or agencies;\n(4) Monitor and evaluate the implementation of the different development programs, projects, and activities in the local government unit concerned in accordance with the approved development plan;\n(5) Prepare comprehensive plans and other development planning documents for the consideration of the local development council;\n(6) Analyze the income and expenditure patterns, and formulate and recommend fiscal plans and policies for consideration of the finance committee of the local government unit concerned as provided under Title Five, Book II of this Code;\n(7) Promote people participation in development planning within the local government unit concerned;\n(8) Exercise supervision and control over the secretariat of the local development council; and\n(c) Exercise such other powers and perform such other functions and duties as may be prescribed by law or ordinance.\nThe Engineer"}},{"id":"PH-H5648-A477","no":477,"noLabel":{"en":"Section 477."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Qualifications, Powers and Duties.\n(a) No person shall be appointed engineer unless he is a citizen of the Philippines, a resident of the local government unit concerned, of good moral character, and a licensed civil engineer. He must have acquired experience in the practice of his profession for at least five (5) years in the case of the provincial or city engineer, and three (3) years in the case of the municipal engineer.\nThe appointment of an engineer shall be mandatory for the provincial, city and municipal governments. The city and municipal engineer shall also act as the local building official.\n(b) The engineer shall take charge of the engineering office and shall:\n(1) Initiate, review and recommend changes in policies and objectives, plans and programs, techniques, procedures and practices in infrastructure development and public works in general of the local government unit concerned;\n(2) Advise the governor or mayor, as the case may be, on infrastructure, public works, and other engineering matters;\n(3) Administer, coordinate, supervise, and control the construction, maintenance, improvement, and repair of roads, bridges, and other engineering and public works projects of the local government unit concerned;\n(4) Provide engineering services to the local government unit concerned, including investigation and survey, engineering designs, feasibility studies, and project management;\n(5) In the case of the provincial engineer, exercise technical supervision over all engineering offices of component cities and municipalities; and\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance.\nThe Health Officer"}},{"id":"PH-H5648-A478","no":478,"noLabel":{"en":"Section 478."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"Qualifications, Powers and Duties.\n(a) No person shall be appointed health officer unless he is a citizen of the Philippines, a resident of the local government unit concerned, of good moral character, and a licensed medical practitioner. He must have acquired experience in the practice of his profession for at least five (5) years in the case of the provincial or city health officer, and three (3) years in the case of the municipal health officer.\nThe appointment of a health officer shall be mandatory for provincial, city and municipal governments.\n(b) The health officer shall take charge of the office on health and shall:\n(1) Take charge of the office on health services, supervise the personnel and staff of said office, formulate program implementation guidelines and rules and regulations for the operation of the said office for the approval of the governor or mayor, as the case may be, in order to assist him in the efficient, effective and economical implementation of a health services program geared to implementation of health-related projects and activities;\n(2) Formulate measures for the consideration of the sanggunian and provide technical assistance and support to the governor or mayor, as the case may be, in carrying out activities to ensure the delivery of basic services and provisions of adequate facilities relative to health services provided under Section 17 of this Code;\n(3) Develop plans and strategies and upon approval thereof by the governor or mayor as the case may be, implement the same, particularly those which have to do with health programs and projects which the governor or mayor, is empowered to implement and which the sanggunian is empowered to provide for under this Code;\n(4) In addition to the foregoing duties and functions, the health officer shall:\n(i) Formulate and implement policies, plans, programs and projects to promote the health of the people in the local government unit concerned;\n(ii) Advise the governor or mayor, as the case may be, and the sanggunian on matters pertaining to health;\n(iii) Execute and enforce laws, ordinances and regulations relating to public health;\n(iv) Recommend to the sanggunian, through the local health board, the passage of such ordinances as he may deem necessary for the preservation of public health;\n(v) Recommend the prosecution of any violation of sanitary laws, ordinances or regulations;\n(vi) Direct the sanitary inspection of all business establishments selling food items or providing accommodations such as hotels, motels, lodging houses, pension houses, and the like, in accordance with the Sanitation Code;\n(vii) Conduct health information campaigns and render health intelligence services;\n(viii) Coordinate with other government agencies and non-governmental organizations involved in the promotion and delivery of health services; and\n(ix) In the case of the provincial health officer, exercise general supervision over health officers of component cities and municipalities; and\n(5) Be in the frontline of health services, delivery, particularly during and in the aftermath of man-made and natural disasters and calamities; and\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance.\nThe Civil Registrar"}},{"id":"PH-H5648-A479","no":479,"noLabel":{"en":"Section 479."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Qualifications, Powers and Duties.\n(a) No person shall be appointed civil registrar unless he is a citizen of the Philippines, a resident of the local government unit concerned, of good moral character, a holder of a college degree from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in civil registry work for at least five (5) years in the case of the city civil registrar and three (3) years in the case of the municipal civil registrar.\nThe appointment of a civil registrar shall be mandatory for city and municipal governments.\n(b) The civil registrar shall be responsible for the civil registration program in the local government unit concerned, pursuant to the Civil Registry Law, the Civil Code, and other pertinent laws, rules and regulations issued to implement them.\n(c) The Civil Registrar shall take charge of the office of the civil registry and shall:\n(1) Develop plans and strategies and upon approval thereof by the governor or mayor, as the case may be, implement the same, particularly those which have to do with civil registry programs and projects which the mayor is empowered to implement and which the sanggunian is empowered to provide for under this Code;\n(2) In addition to the foregoing duties and functions, the civil registrar shall:\n(i) Accept all registrable documents and judicial decrees affecting the civil status of persons;\n(ii) File, keep and preserve in a secure place the books required by law;\n(iii) Transcribe and enter immediately upon receipt all registrable documents and judicial decrees affecting the civil status of persons in the appropriate civil registry books;\n(iv) Transmit to the Office of the Civil Registrar-General, within the prescribed period, duplicate copies of registered documents required by law;\n(v) Issue certified transcripts or copies of any certificate or registered documents upon payment of the prescribed fees to the treasurer;\n(vi) Receive applications for the issuance of a marriage license and, after determining that the requirement and supporting certificates and publication thereof for the prescribed period have been complied with, issue the license upon payment of the authorized fee to the treasurer;\n(vii) Coordinate with the National Statistics Office in conducting educational campaigns for vital registration and assist in the preparation of demographic and other statistics for the local government unit concerned; and\n(3) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance.\nThe Administrator"}},{"id":"PH-H5648-A480","no":480,"noLabel":{"en":"Section 480."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Qualifications, Terms, Powers and Duties.\n(a) No person shall be appointed administrator unless he is a citizen of the Philippines, a resident of the local government unit concerned, of good moral character, a holder of a college degree preferably in public administration, law, or any other related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in management and administration work for at least five (5) years in the case of the provincial or city administrator, and three (3) years in the case of the municipal administrator.\nThe term of administrator is coterminous with that of his appointing authority.\nThe appointment of an administrator shall be mandatory for the provincial and city governments, and optional for the municipal government.\n(b) The administrator shall take charge of the office of the administrator and shall:\n(1) Develop plans and strategies and upon approval thereof by the governor or mayor, as the case may be, implement the same particularly those which have to do with the management and administration-related programs and projects which the governor or mayor is empowered to implement and which the sanggunian is empowered to provide for under this Code;\n(2) In addition to the foregoing duties and functions, the administrator shall:\n(i) Assist in the coordination of the work of all the officials of the local government unit, under the supervision, direction, and control of the governor or mayor, and for this purpose, he may convene the chiefs of offices and other officials of the local government unit;\n(ii) Establish and maintain a sound personnel program for the local government unit designed to promote career development and uphold the merit principle in the local government service;\n(iii) Conduct a continuing organizational development of the local government unit with the end in view of the instituting effective administrative reforms;\n(3) Be in the frontline of the delivery of administrative support services, particularly those related to the situations during and in the aftermath of man-made and natural disasters and calamities;\n(4) Recommend to the sanggunian and advise the governor and mayor, as the case may be, on all other matters relative to the management and administration of the local government unit; and\n(5) Exercise such other powers and perform such other duties and functions as may be prescribed by law or by ordinance.\nThe Legal Officer"}},{"id":"PH-H5648-A481","no":481,"noLabel":{"en":"Section 481."},"chapter":{"en":"ARTICLE XI"},"text":{"en":"Qualifications, Terms, Powers and Duties.\n(a) No person shall be appointed legal officer unless he is a citizen of the Philippines, a resident of the local government concerned, of good moral character, and a member of the Philippine Bar. He must have practiced his profession for at least five (5) years in the case of the provincial and city legal officer, and three (3) years in the case of the municipal legal officer.\nThe term of the legal officer shall be coterminous with that of his appointing authority.\nThe appointment of legal officer shall be mandatory for the provincial and city governments and optional for the municipal government.\n(b) The legal officer, the chief legal counsel of the local government unit, shall take charge of the office of legal services and shall:\n(1) Formulate measures for the consideration of the sanggunian and provide legal assistance and support to the governor or mayor, as the case may be, in carrying out the delivery of basic services and provisions of adequate facilities as provided for under Section 17 of this Code;\n(2) Develop plans and strategies and upon approval thereof by the governor or mayor, as the case may be, implement the same, particularly those which have to do with programs and projects related to legal services which the governor or mayor is empowered to implement and which the sanggunian is empowered to provide for under this Code;\n(3) In addition to the foregoing duties and functions, the legal officer shall:\n(i) Represent the local government unit in all civil actions and special proceedings wherein the local government unit or any official thereof, in his official capacity, is a party: Provided, That, in actions or proceedings where a component city or municipality is a party adverse to the provincial government or to another component city or municipality, a special legal officer may be employed to represent the adverse party;\n(ii) When required by the governor, mayor or sanggunian, draft ordinances, contracts, bonds, leases and other instruments, involving any interest of the local government unit and provide comments and recommendations on any instrument already drawn;\n(iii) Render his opinion in writing on any question of law when requested to do so by the governor, mayor or sanggunian;\n(iv) Investigate or cause to be investigated any local official or employee for administrative neglect or misconduct in office, and recommend appropriate action to the governor, mayor or sanggunian, as the case may be;\n(v) Investigate or cause to be investigated any person, firm or corporation holding any franchise or exercising any public privilege for failure to comply with any term or condition in the grant of such franchise or privilege, and recommending appropriate action to the governor, mayor or sanggunian, as the case may be;\n(vi) When directed by the governor, mayor, or sanggunian, initiate and prosecute in the interest of the local government unit concerned any civil action on any bond, lease or other contract upon any breach or violation thereof; and\n(vii) Review and submit recommendations on ordinances approved and execute orders issued by component units;\n(3) Recommend measures to the sanggunian and advise the governor or mayor as the case may be on all other matters related to upholding the rule of law;\n(4) Be in the frontline of protecting human rights and prosecuting any violations thereof, particularly those which occur during and in the aftermath of man-made or natural disasters or calamities; and\n(5) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance.\nThe Agriculturist"}},{"id":"PH-H5648-A482","no":482,"noLabel":{"en":"Section 482."},"chapter":{"en":"ARTICLE XII"},"text":{"en":"Qualifications, Powers and Duties.\n(a) No person shall be appointed agriculturist unless he is a citizen of the Philippines, a resident of the local government unit concerned, of good moral character, a holder of a college degree in agriculture or any related course from a recognized college or university and a first grade civil service eligible or its equivalent. He must have practiced his profession in agriculture or acquired experience in a related field for at least five (5) years in the case of the provincial and city agriculturist, and three (3) years in the case of the municipal agriculturist.\nThe position of the agriculturist shall be mandatory for the provincial government and optional for the city and municipal governments.\n(b) The agriculturist shall take charge of the office for agricultural services, and shall:\n(1) Formulate measures for the approval of the sanggunian and provide technical assistance and support to the governor or mayor, as the case may be, in carrying out said measures to ensure the delivery of basic services and provisions of adequate facilities relative to agricultural services as provided for under Section 17 of this Code;\n(2) Develop plans and strategies and upon approval thereof by the governor or mayor, as the case may be, implement the same, particularly those which have to do with agricultural programs and projects which the governor or mayor is empowered to implement and which the sanggunian is empowered to provide for under this Code;\n(3) In addition to the foregoing duties and functions, the agriculturist shall:\n(i) Ensure that maximum assistance and access to resources in the production, processing and marketing of agricultural and aqua-cultural and marine products are extended to farmers, fishermen and local entrepreneurs;\n(ii) Conduct or cause to be conducted location-specific agricultural researches and assist in making available the appropriate technology arising out of and disseminating information on basic research on crops, preventive and control of plant diseases and pests, and other agricultural matters which will maximize productivity;\n(iii) Assist the governor or mayor, as the case may be, in the establishment and extension services of demonstration forms or aqua-culture and marine products;\n(iv) Enforce rules and regulations relating to agriculture and aqua-culture;\n(v) Coordinate with government agencies and non-governmental organizations which promote agricultural productivity through appropriate technology compatible with environmental integrity;\n(4) Be in the frontline of delivery of basic agricultural services, particularly those needed for the survival of the inhabitants during and in the aftermath of man-made and natural disasters;\n(5) Recommend to the sanggunian and advise the governor or mayor, as the case may be, on all other matters related to agriculture and aqua-culture which will improve the livelihood and living conditions of the inhabitants; and\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance;\nThe Social Welfare and Development Officer"}},{"id":"PH-H5648-A483","no":483,"noLabel":{"en":"Section 483."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"Qualifications, Powers and Duties\n(a) No person shall be appointed social welfare and development officer unless he is a citizen of the Philippines, a resident of the local government concerned, of good moral character, a duly licensed social worker or a holder of a college degree preferably in sociology or any other related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in the practice of social work for at least five (5) years in the case of the provincial or city social welfare and development officer, and three (3) years in the case of the municipal social welfare and development officer.\nThe appointment of a social welfare and development officer is mandatory for provincial and city governments, and optional for municipal government.\n(b) The social welfare and development officer shall take charge of the office on social welfare and development services and shall:\n(1) Formulate measures for the approval of the sanggunian and provide technical assistance and support to the governor or mayor, as the case may be, in carrying out measures to endure the delivery of basic services and provisions of adequate facilities relative to social welfare and development services as provided for under Section 17 of this Code;\n(2) Develop plans and strategies and upon approval thereof by the governor or mayor, as the case may be, implement the same particularly those which have to do with social welfare programs and projects which the governor or mayor is empowered to implement and which the sanggunian is empowered to provide for under this Code;\n(3) In addition to the foregoing duties, the social welfare and development officer shall:\n(i) Identify the basic needs of the needy, the disadvantaged and the impoverished and develop and implement appropriate measures to alleviate their problems and improve their living conditions;\n(ii) Provide relief and appropriate crisis intervention for victims of abuse and exploitation and recommend appropriate measures to deter further abuse and exploitation;\n(iii) Assist the governor or mayor, as the case may be, in implementing the barangay level program for the total development and protection of children up to six (6) years of age;\n(iv) Facilitate the implementation of welfare programs for the disabled, elderly, and victims of drug addiction, the rehabilitation of prisoners and parolees, the prevention of juvenile delinquency and such other activities which would eliminate or minimize the ill-effects of poverty;\n(v) Initiate and support youth welfare programs that will enhance the role of the youth in nation-building;\n(vi) Coordinate with government agencies and non-governmental organizations which have for their purpose the promotion and the protection of all needy, disadvantaged, underprivileged or impoverished groups or individuals, particularly those identified to be vulnerable and high-risk to exploitation, abuse and neglect;\n(4) Be in the frontline or service delivery, particularly those which have to do with immediate relief during and assistance in the aftermath of man-made and natural disaster and natural calamities;\n(5) Recommend to the sanggunian and advise the governor or mayor, as the case may be, on all other matters related to social welfare and development services which will improve the livelihood and living conditions of the inhabitants; and\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance;\nThe Environment and Natural Resources Officer"}},{"id":"PH-H5648-A484","no":484,"noLabel":{"en":"Section 484."},"chapter":{"en":"ARTICLE XIV"},"text":{"en":"Qualifications, Powers and Duties.\n(a) No person shall be appointed environment and natural resources officer unless he is a citizen of the Philippines, a resident of the local government unit concerned, of good moral character, a holder of a college degree preferably in environment, forestry, agriculture or any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in environmental and natural resources management, conservation, and utilization, of at least five (5) years in the case of the provincial or city environment and natural resources officer, and three (3) years in the case of the municipal environment and natural resources officer.\nThe appointment of the environment and natural resources officer is optional for provincial, city, and municipal governments.\n(b) The environment and natural resources management officer shall take charge of the office on environment and natural resources and shall:\n(1) Formulate measures for the consideration of the sanggunian and provide technical assistance and support to the governor or mayor, as the case may be, in carrying out measures to ensure the delivery of basic services and provision of adequate facilities relative to environment and natural resources services as provided for under Section 17 of this Code;\n(2) Develop plans and strategies and upon approval thereof, by the governor or mayor, as the case may be, implement the same, particularly those which have to do with environment and natural resources programs and projects which the governor or mayor is empowered to implement and which the sanggunian is empowered to provide for under this Code;\n(3) In addition to the foregoing duties and functions, the environment and natural resources officer shall:\n(i) Establish, maintain, protect and preserve communal forests, watersheds, tree parks, mangroves, greenbelts and similar forest projects and commercial forest, like industrial tree farms and agro-forestry projects;\n(ii) Provide extension services to beneficiaries of forest development projects and technical, financial and infrastructure assistance;\n(iii) Manage and maintain seed banks and produce seedlings for forest and tree parks;\n(iv) Provide extension services to beneficiaries of forest development projects and render assistance for natural resources-related conservation and utilization activities consistent with ecological balance;\n(v) Promote the small-scale mining and utilization of mineral resources, particularly mining of gold;\n(vi) Coordinate with government agencies and non-governmental organizations in the implementation of measures to prevent and control land, air and water pollution with the assistance of the Department of Environment and Natural Resources;\n(4) Be in the frontline of the delivery of services concerning the environment and natural resources, particularly in the renewal and rehabilitation of the environment during and in the aftermath of man-made and natural calamities and disasters;\n(5) Recommend to the sanggunian and advise the governor or mayor, as the case may be, on all matters relative to the protection, conservation maximum utilization, application of appropriate technology and other matters related to the environment and natural resources; and\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance.\nThe Architect"}},{"id":"PH-H5648-A485","no":485,"noLabel":{"en":"Section 485."},"chapter":{"en":"ARTICLE XV"},"text":{"en":"Qualifications, Powers and Duties.\n(a) No person shall be appointed architect unless he is a citizen of the Philippines, a resident of the local government unit concerned, of good moral character, a duly licensed architect. He must have practiced his profession for at least five (5) years in the case of the provincial or city architect, and three (3) years in the case of the municipal architect.\nThe appointment of the architect is optional for provincial, city and municipal governments.\n(b) The Architect shall take charge of the office on architectural planning and design and shall:\n(1) Formulate measures for the consideration of the sanggunian and provide technical assistance and support to the governor or mayor, as the case may be, in carrying out measures to ensure the delivery of basic services and provision of adequate facilities relative to architectural planning and design as provided for under Section 17 of this Code;\n(2) Develop plans and strategies and upon approval thereof by the governor or mayor, as the case may be, implement the same, particularly those which have to do with architectural planning and design programs and projects which the governor or mayor is empowered to implement and which the sanggunian is empowered to provide for under this Code;\n(3) In addition to foregoing duties and functions, the architect shall:\n(i) Prepare and recommend for consideration of the sanggunian the architectural plan and design for the local government unit or a part thereof, including the renewal of slums and blighted areas, land reclamation activities, the greening of land, and appropriate planning of marine and foreshore areas;\n(ii) Review and recommend for appropriate action of the sanggunian, governor or mayor, as the case may be, the architectural plans and design submitted by governmental and non-governmental entities or individuals, particularly those for undeveloped, underdeveloped, and poorly-designed areas; and\n(iii) Coordinate with government and non-government entities and individuals involved in the aesthetics and the maximum utilization of the land and water within the jurisdiction of the local government unit, compatible with environmental integrity and ecology balance;\n(4) Be in the frontline of the delivery of services involving architectural planning and design, particularly those related to the redesigning of spatial distribution of basic facilities and physical structures during and in the aftermath of man-made and natural calamities and disasters;\n(5) Recommend to the sanggunian and advise the governor or mayor, as the case may be, on all matters relative to the architectural planning and design as it relates to the total socio-economic development of the local government units; and\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance.\nThe Information Officer"}},{"id":"PH-H5648-A486","no":486,"noLabel":{"en":"Section 486."},"chapter":{"en":"ARTICLE XVI"},"text":{"en":"Qualifications, Powers and Duties.\n(a) No person shall be appointed information officer unless he is a citizen of the Philippines, a resident of the local government unit concerned, of good moral character, a holder of a college degree preferably in journalism, mass communication or any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have experience in writing articles and research papers, or in writing for print, television or broadcast media of at least three (3) years in the case of the provincial or city information officer, and at least one (1) year in the case of municipal information officer.\nThe appointment of the information officer is optional for the provincial, city and municipal governments.\nThe term of the information officer is coterminous with that of his appointing authority.\n(b) The information officer shall take charge of the office on public information and shall:\n(1) Formulate measures for the consideration of the sanggunian and provide technical assistance and support to the governor or mayor, as the case may be, in providing the information and research data required for the delivery of basic services and provision of adequate facilities so that the public becomes aware of said services and may fully avail of the same;\n(2) Develop plans and strategies and, upon approval thereof by the governor or mayor, as the case may be, implement the same, particularly those which have to do with public information and research data to support programs and projects which the governor or mayor is empowered to implement and which the sanggunian is empowered to provide for under this Code;\n(3) In addition to the foregoing duties and functions, the information officer shall:\n(i) Provide relevant, adequate, and timely information to the local government unit and its residents;\n(ii) Furnish information and data on local government units to government agencies or offices as may be required by law or ordinance; and non-governmental organizations to be furnished to said agencies and organizations;\n(iii) Maintain effective liaison with the various sectors of the community on matters and issues that affect the livelihood and the quality of life of the inhabitants and encourage support for programs of the local and national government;\n(4) Be in the frontline in providing information during and in the aftermath of man-made and natural calamities and disasters, with special attention to the victims thereof, to help minimize injuries and casualties during and after the emergency, and to accelerate relief and rehabilitation;\n(5) Recommend to the sanggunian and advise the governor or mayor, as the case may be, on all matters relative to public information and research data as it relates to the total socio-economic development of the local government unit; and\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance.\nThe Cooperatives Officer"}},{"id":"PH-H5648-A487","no":487,"noLabel":{"en":"Section 487."},"chapter":{"en":"ARTICLE XVII"},"text":{"en":"Qualifications, Powers and Duties.\n(a) No person shall be appointed cooperative officer unless he is a citizen of the Philippines, a resident of the local government unit concerned, of good moral character, a holder of a college degree preferably in business administration with special training in cooperatives or any related course from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have experience in cooperatives organizations and management of at least five (5) years in the case of provincial or city cooperatives officer, and three (3) years in the case of municipal cooperatives officer.\nThe appointment of the cooperatives officer is optional for the provincial and city governments.\n(b) The cooperatives officer shall take charge of the office for the development of cooperatives and shall:\n(1) Formulate measures for the consideration of the sanggunian, and provide technical assistance and support to the governor or mayor, as the case may be, in carrying out measures to ensure the delivery of basic services and provision of facilities through the development of cooperatives, and in providing access to such services and facilities;\n(2) Develop plans and strategies and, upon approval thereof by the governor or mayor, as the case may be, implement the same, particularly those which have to do with the integration of cooperatives principles and methods in programs and projects which the governor or mayor is empowered to implement and which the sanggunian is empowered to provide for under this Code;\n(3) In addition to the foregoing duties and functions, the cooperatives officer shall:\n(i) Assist in the organization of cooperatives;\n(ii) Provide technical and other forms of assistance to existing cooperatives to enhance their viability as an economic enterprise and social organization;\n(iii) Assist cooperatives in establishing linkages with government agencies and non-government organizations involved in the promotion and integration of the concept of cooperatives in the livelihood of the people and other community activities;\n(4) Be in the frontline of cooperatives organization, rehabilitation or viability-enhancement, particularly during and in the aftermath of man-made and natural calamities and disasters, to aid in their survival and, if necessary subsequent rehabilitation;\n(5) Recommend to the sanggunian, and advise the governor or mayor, as the case may be, on all matters relative to cooperatives development and viability- enhancement which will improve the livelihood and quality of life of the inhabitants; and\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance.\nThe Population Officer"}},{"id":"PH-H5648-A488","no":488,"noLabel":{"en":"Section 488."},"chapter":{"en":"ARTICLE XVIII"},"text":{"en":"Qualification, Powers and Duties. -\n(a) No person shall be appointed population officer unless he is a citizen of the Philippines, a resident of the local government unit concerned, of good moral character, a holder of a college degree with specialized training in population development from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have experience in the implementation of programs on population development or responsible parenthood for at least five (5) years in the case of the provincial or city population officer, and three (3) years in the case of the municipal population officer.\nThe appointment of a population officer shall be optional in the local government unit: Provided, however, That provinces and cities which have existing population offices shall continue to maintain such offices for a period of five (5) years from the date of effectivity of this Code, after which said offices shall become optional.\n(b) The population officer shall take charge of the office on population development and shall:\n(1) Formulate measures for the consideration of the sanggunian and provide technical assistance and support to the governor or mayor, as the case may be, in carrying out measures to ensure the delivery of basic services and provision of adequate facilities relative to the integration of the population development principles and in providing access to said services and facilities;\n(2) Develop plans and strategies and upon approval thereof by the governor or mayor, as the case may be, implement the same, particularly those which have to do with the integration of population development principles and methods in programs and projects which the governor or mayor is empowered to implement and which the sanggunian is empowered to provide for under this Code;\n(3) In addition to the foregoing duties and functions, the population officer shall:\n(i) Assist the governor or mayor, as the case may be, in the implementation of the Constitutional provisions relative to population development and the promotion of responsible parenthood;\n(ii) Establish and maintain an updated data bank for program operations, development planning and an educational program to ensure the people's participation in and understanding of population development;\n(iii) Implement appropriate training programs responsive to the cultural heritage of the inhabitants; and\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance.\nThe Veterinarian"}},{"id":"PH-H5648-A489","no":489,"noLabel":{"en":"Section 489."},"chapter":{"en":"ARTICLE XIX"},"text":{"en":"Qualifications, Powers and Duties.\n(a) No person shall be appointed veterinarian unless he is a citizen of the Philippines, a resident of the local government unit concerned, of good moral character, a licensed doctor of veterinary medicine. He must have practiced his profession for at least three (3) years in the case of provincial or city veterinarian and at least one (1) year in the case of the municipal veterinarian.\nThe appointment of a veterinarian officer is mandatory for the provincial and city governments.\n(b) The veterinarian shall take charge of the office for veterinary services and shall:\n(1) Formulate measures for the consideration of the sanggunian, and provide technical assistance and support to the governor or mayor, as the case may be, in carrying out measures to ensure the delivery of basic services and provision of adequate facilities pursuant to Section 17 of this Code;\n(2) Develop plans and strategies and upon approval thereof by the governor or mayor, as the case may be, implement the same, particularly those which have to do with the veterinary-related activities which the governor or mayor is empowered to implement and which the sanggunian is empowered to provide for under this Code;\n(3) In addition to the foregoing duties and functions, the veterinarian shall:\n(i) Advise the governor or the mayor, as the case may be, on all matters pertaining to the slaughter of animals for human consumption and the regulation of slaughterhouses;\n(ii) Regulate the keeping of domestic animals;\n(iii) Regulate and inspect poultry, milk and dairy products for public consumption;\n(iv) Enforce all laws and regulations for the prevention of cruelty to animals; and\n(v) Take the necessary measures to eradicate, prevent or cure all forms of animal diseases;\n(4) Be in the frontline of veterinary related activities, such as in the outbreak of highly-contagious and deadly diseases, and in situations resulting in the depletion of animals for work and human consumption, particularly those arising from and in the aftermath of man-made and natural calamities and disasters;\n(5) Recommend to the sanggunian and advise the governor or mayor, as the case may be, on all other matters relative to veterinary services which will increase the number and improve the quality of livestock, poultry and other domestic animals used for work or human consumption; and\n(c) Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance.\nThe General Services Officer"}},{"id":"PH-H5648-A490","no":490,"noLabel":{"en":"Section 490."},"chapter":{"en":"ARTICLE XX"},"text":{"en":"Qualifications, Powers and Duties.\n(a) No person shall be appointed general services officer unless he is a citizen of the Philippines, a resident of the local government unit concerned, of good moral character, a holder of a college degree on public administration, business administration and management from a recognized college or university, and a first grade civil service eligible or its equivalent. He must have acquired experience in general services, including management of supply, property, solid waste disposal, and general sanitation, of at least five (5) years in the case of the provincial or city general services officer, and at least three (3) years in the case of the municipal general services officer.\nThe appointment of a general services officer is mandatory for the provincial and city governments,\n(b) The general services officer shall take charge of the office on general services and shall:\n(1) Formulate measures for the consideration of the sanggunian and provide technical assistance and support to the governor or mayor, as the case may be, in carrying out measures to ensure the delivery of basic services and provision of adequate facilities pursuant to Section 17 of this Code and which require general services expertise and technical support services;\n(2) Develop plans and strategies and upon approval thereof by the governor or mayor, as the case may be, implement the same, particularly those which have to do with the general services supportive of the welfare of the inhabitants which the governor or mayor is empowered to implement and which the sanggunian is empowered to provide for under this Code;\n(3) In addition to the foregoing duties and functions, the general services officer shall:\n(i) Take custody of and be accountable for all properties, real or personal, owned by the local government unit and those granted to it in the form of donation, reparation, assistance and counterpart of joint projects;\n(ii) With the approval of the governor or mayor, as the case may be, assign building or land space to local officials or other public officials, who by law, are entitled to such space;\n(iii) Recommend to the governor or mayor, as the case may be, the reasonable rental rates for local government properties, whether real or personal, which will be leased to public or private entities by the local government;\n(iv) Recommend to the governor or mayor, as the case may be, reasonable rental rates of private properties which may be leased for the official use of the local government unit;\n(v) Maintain and supervise janitorial, security, government public buildings and other real property, whether owned or leased by the local government unit;\n(vi) Collate and disseminate information regarding prices, shipping and other costs of supplies and other items commonly used by the local government unit;\n(vii) Perform archival and record management with respect to records of offices and departments of the local government unit; and\n(viii) Perform all other functions pertaining to supply and property management heretofore performed by the local government treasurer; and enforce policies on records creation, maintenance, and disposal;\n(4) Be in the frontline of general services related activities, such as the possible or imminent destruction or damage to records, supplies, properties, and structures and the orderly and sanitary clearing up of waste materials or debris, particularly during and in the aftermath of man-made and natural calamities and disasters;\n(5) Recommend to the sanggunian and advise the governor or mayor, as the case may be, on all matters relative to general services; and (c)Exercise such other powers and perform such other duties and functions as may be prescribed by law or ordinance.\nLEAGUES OF LOCAL GOVERNMENT UNITS AND ELECTIVE OFFICIALS\nLeagues of Local Government Units\nLiga ng Mga Barangay"}},{"id":"PH-H5648-A491","no":491,"noLabel":{"en":"Section 491."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Purpose of Organization. - There shall be an organization of all barangays to be known as the liga ng mga barangay for the primary purpose of determining the representation of the Liga in the sanggunians, and for ventilating, articulating and crystallizing issues affecting barangay government administration and securing, through proper and legal means, solutions thereto."}},{"id":"PH-H5648-A492","no":492,"noLabel":{"en":"Section 492."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Representation, Chapters, National Liga. - Every barangay shall be represented in said liga by the punong barangay, or in his absence or incapacity, by a sanggunian member duly elected for the purpose among its members, who shall attend all meetings or deliberations called by the different chapters of the liga.\nThe liga shall have chapters at the municipal, city, provincial and metropolitan political subdivision levels.\nThe municipal and city chapters of the liga shall be composed of the barangay representatives of municipal and city barangays respectively. The duly elected presidents of component municipal and city chapters shall constitute the provincial chapter or the metropolitan political subdivision chapter. The duly elected presidents of highly-urbanized cities, provincial chapters, the Metropolitan Manila chapter and metropolitan political subdivision chapters shall constitute the National Liga ng mga Barangay."}},{"id":"PH-H5648-A493","no":493,"noLabel":{"en":"Section 493."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Organization. - The liga at the municipal, city, provincial, metropolitan political subdivision, and national levels directly elect a president, a vice-president, and five (5) members of the board of directors. The board shall appoint its secretary and treasurer and create such other positions as it may deem necessary for the management of the chapter. A secretary-general shall be elected from among the members of the national liga and shall be charged with the overall operation of the liga on national level. The board shall coordinate the activities of the chapters of the liga."}},{"id":"PH-H5648-A494","no":494,"noLabel":{"en":"Section 494."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Ex-Officio Membership in Sanggunians. - The duly elected presidents of the liga at the municipal, city and provincial levels, including the component cities and municipalities of Metropolitan Manila, shall serve as ex-officio members of the sangguniang bayan, sangguniang panlungsod, sangguniang panlalawigan, respectively. They shall serve as such only during their term of office as presidents of the liga chapters, which in no case shall be beyond the term of office of the sanggunian concerned."}},{"id":"PH-H5648-A495","no":495,"noLabel":{"en":"Section 495."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Powers, Functions and Duties of the Liga. - The liga shall:\n(a) Give priority to programs designed for the total development of the barangays and in consonance with the policies, programs and projects of the national government;\n(b) Assist in the education of barangay residents for people's participation in local government administration in order to promote united and concerted action to achieve country-wide development goals;\n(c) Supplement the efforts of government in creating gainful employment within the barangay;\n(d) Adopt measures to promote the welfare of barangay officials;\n(e) Serve as a forum of the barangays in order to forge linkages with government and non-governmental organizations and thereby promote the social, economic and political well-being of the barangays; and\n(f) Exercise such other powers and perform such other duties and functions which will bring about stronger ties between barangays and promote the welfare of the barangay inhabitants.\nLeague of Municipalities"}},{"id":"PH-H5648-A496","no":496,"noLabel":{"en":"Section 496."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Purpose of Organization. - There shall be an organization of all municipalities to be known as league of municipalities for the primary purpose of ventilating, articulating and crystallizing issues affecting municipal government administration, and securing, through proper and legal means, solutions thereto.\nThe league shall form provincial chapters composed of the league presidents for all component municipalities of the province."}},{"id":"PH-H5648-A497","no":497,"noLabel":{"en":"Section 497."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Representation. - Every municipality shall be represented in the league by the municipal mayor of in his absence, by the vice-mayor or a sanggunian member duly elected for the purpose by the members, who shall attend all meetings and participate in the deliberations of the league."}},{"id":"PH-H5648-A498","no":498,"noLabel":{"en":"Section 498."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Powers, Functions and Duties of the League of Municipalities. - The league of municipalities shall:\n(a) Assist the national government in the formulation and implementation of the policies, programs and projects affecting municipalities as a whole;\n(b) Promote local autonomy at the municipal level;\n(c) Adopt measures for the promotion of the welfare of all municipalities and its officials and employees;\n(d) Encourage people's participation in local government administration in order to promote united and concerted action for the attainment of country-wide development goals;\n(e) Supplement the efforts of the national government in creating opportunities for gainful employment within the municipalities;\n(f) Give priority to programs designed for the total development of the municipalities in consonance with the policies, programs and projects of the national government;\n(g) Serve as a forum for crystallizing and expressing ideas, seeking the necessary assistance of the national government, and providing the private sector avenues for cooperation in the promotion of the welfare of the municipalities; and\n(h) Exercise such other powers and perform such other duties and functions as the league may prescribe for the welfare of the municipalities.\nLeague of Cities"}},{"id":"PH-H5648-A499","no":499,"noLabel":{"en":"Section 499."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Purpose of Organization . - There shall be an organization of all cities to be known as the League of Cities for the primary purpose of ventilating, articulating and crystallizing issues affecting city government administration, and securing, through proper and legal means, solutions thereto.\nThe league may form chapters at the provincial level for the component cities of a province. Highly-urbanized cities may also form a chapter of the League. The National League shall be composed of the presidents of the league of highly-urbanized cities and the presidents of the provincial chapters of the league of component cities."}},{"id":"PH-H5648-A500","no":500,"noLabel":{"en":"Section 500."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Representation. - Every city shall be represented in the league by the city mayor or in his absence, by the city vice-mayor or a sanggunian member duly elected for the purpose by the members, who shall attend all meetings and participate in the deliberations of the league."}},{"id":"PH-H5648-A501","no":501,"noLabel":{"en":"Section 501."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Powers, Functions and Duties of the League of City. - The league of cities shall:\n(a) Assist the national government in the formulation and implementation of the policies, programs and projects affecting cities as a whole;\n(b) Promote local autonomy at the city level;\n(c) Adopt measures for the promotion of the welfare of all cities and its officials and employees;\n(d) Encourage people's participation in local government administration in order to promote united and concerted action for the attainment of country-wide development goals;\n(e) Supplement the efforts of the national government in creating opportunities for gainful employment the cities;\n(f) Give priority to programs designed for the total development of cities in consonance with the policies, programs and projects of the national government;\n(g) Serve as a forum for crystallizing and expressing ideas, seeking the necessary assistance of the national government and providing the private sector avenues for cooperation in the promotion of the welfare of the cities; and\n(h) Exercise such other powers and perform such other duties and functions as the league may prescribe for the welfare of the cities.\nLeague of Provinces"}},{"id":"PH-H5648-A502","no":502,"noLabel":{"en":"Section 502."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Purpose of Organization. - There shall be an organization of all provinces to be known as the League of Provinces for the primary purpose of ventilating, articulating and crystallizing issues affecting provincial and metropolitan political subdivision government administration, and securing, through proper and legal means, solutions thereto. For this purpose, the Metropolitan Manila Area and any metropolitan political subdivision shall be considered as separate provincial units of the league."}},{"id":"PH-H5648-A503","no":503,"noLabel":{"en":"Section 503."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Representation. - Every province shall be represented in the league by the provincial governor or in his absence, by the provincial vice-governor or a sanggunian member duly elected for the purpose by the members, who shall attend all meetings and participate in the deliberations of the league."}},{"id":"PH-H5648-A504","no":504,"noLabel":{"en":"Section 504."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Powers, Functions and Duties of the League of Provinces. - The league of provinces shall:\n(a) Assist the national government in the formulation and implementation of the policies, programs and projects affecting provinces as a whole;\n(b) Promote local autonomy at the provincial level;\n(c) Adopt measures for the promotion of the welfare of all provinces and its officials and employees;\n(d) Encourage people's participation in local government administration in order to promote united and concerted action for the attainment of countrywide employment within the province;\n(e) Supplement the efforts of the national government in creating opportunities for gainful employment within the province;\n(f) Give priority to programs designed for the total development of the provinces in consonance with the policies, programs and projects of the national government;\n(g) Serve as a forum for crystallizing and expressing ideas, seeking the necessary assistance of the national government and providing the private sector avenues for cooperation in the promotion of the welfare of the provinces; and\n(h) Exercise such other powers and perform such other duties and functions as the league may prescribe for the welfare of the provinces and metropolitan political subdivisions.\nProvisions Common to All Leagues"}},{"id":"PH-H5648-A505","no":505,"noLabel":{"en":"Section 505."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Funding.\n(a) All leagues shall derive its funds from contributions of member local government units and from fund-raising projects and activities without the necessity of securing permits therefor: Provided, That the proceeds from said fund-raising projects and activities shall be used primarily to fund the projects for which the said proceeds have been raised, subject to the pertinent provision of this Code and the pertinent provisions of the Omnibus Election Code.\n(b) All funds of leagues shall be deposited as trust funds with its treasurer and shall be disbursed in accordance with the board of director's resolutions, subject to pertinent accounting and auditing rules and regulations: Provided, That the treasurer shall be bonded in an amount to be determined by the board of directors. The funds of a chapter shall be deposited as chapter funds and funds of the national league shall be deposited as national funds."}},{"id":"PH-H5648-A506","no":506,"noLabel":{"en":"Section 506."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Organizational Structure. - To ensure the effective and efficient administration, the leagues for municipalities, cities and provinces shall elect chapter-level and national-level boards of directors and a set of officers headed by the president. A secretary-general shall be chosen from among the national league members to manage the day to day operation and activities of the national league. The board of directors on the chapter or national level may create such other positions as may be deemed necessary for the management of the chapters and of the national league. The national board of directors of the leagues for municipalities, cities or provinces shall coordinate programs, projects and activities of chapter and the national-level league."}},{"id":"PH-H5648-A507","no":507,"noLabel":{"en":"Section 507."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Constitution and By-laws of the Liga and the Leagues. - All other matters not herein otherwise provided for affecting the internal organization of the leagues of local government units shall be governed by their respective constitution and by-laws which are hereby made suppletory to the provision of this Chapter: Provided, That said Constitution and By-laws shall always conform to the provisions of the Constitution and existing laws.\nLeagues and Federation of Local Elective Officials"}},{"id":"PH-H5648-A508","no":508,"noLabel":{"en":"Section 508."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Organization.\n(a) Vice-governors, vice-mayors, sanggunian members of barangays, municipalities, component cities, highly-urbanized cities and provinces, and other elective local officials of local government units, including those of the Metropolitan Manila Area and any metropolitan political subdivisions, may form their respective leagues or federation, subject to applicable provisions of this Title and pertinent provisions of this Code;\n(b) Sanggunian members of component cities and municipalities shall form a provincial federation and elect a board of directors and a set of officers headed by the president. The duly elected president of the provincial federation of sanggunian members of component cities and municipalities shall be an ex-officio member of the sangguniang panlalawigan concerned and shall serve as such only during his term of office as president of the provincial federation of sanggunian members of component cities and municipalities, which in no case shall be beyond the term of office of the sanggunian panlalawigan concerned."}},{"id":"PH-H5648-A509","no":509,"noLabel":{"en":"Section 509."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Constitution and By-laws. - The leagues or federations shall adopt a Constitution and by-laws which shall govern their internal organization and operation: Provided, That said Constitution and by-laws shall always conform to the provision of the Constitution and existing laws."}},{"id":"PH-H5648-A510","no":510,"noLabel":{"en":"Section 510."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Funding. - The leagues and federations may derive funds from contributions of individual league or federation members or from fund-raising projects or activities. The local government unit concerned may appropriate funds to support the leagues or federation organized pursuant to this Section, subject to the availability of funds.\nMISCELLANEOUS AND FINAL PROVISIONS\nPENAL PROVISIONS"}},{"id":"PH-H5648-A511","no":511,"noLabel":{"en":"Section 511."},"chapter":{"en":"TITLE I"},"text":{"en":"Posting and Publication of Ordinances with Penal Sanctions.\n(a) Ordinances with penal sanctions shall be posted at prominent places in the provincial capitol, city, municipal or barangay hall, as the case may be, for a minimum period of three (3) consecutive weeks. Such ordinances shall also be published in a newspaper of general circulation, where available, within the territorial jurisdiction of the local government unit concerned, except in the case of barangay ordinances. Unless otherwise provided therein, said ordinances shall take effect on the day following its publication, or at the end of the period of posting, whichever occurs later.\n(b) Any public officer or employee who violates an ordinance may be meted administrative disciplinary action, without prejudice to the filing of the appropriate civil or criminal action.\n(c) The secretary to the sanggunian concerned shall transmit official copies of such ordinances to the chief executive officer of the Office Gazette within seven (7) days following the approval of the said ordinance for publication purposes. The Official Gazette may publish ordinances with penal sanctions for archival and reference purposes."}},{"id":"PH-H5648-A512","no":512,"noLabel":{"en":"Section 512."},"chapter":{"en":"TITLE I"},"text":{"en":"Withholding of Benefits Accorded to Barangay Officials. - Willful and malicious withholding of any of the benefits accorded to barangay officials under Section 393 hereof shall be punished with suspension or dismissal from office of the official or employee responsible therefor."}},{"id":"PH-H5648-A513","no":513,"noLabel":{"en":"Section 513."},"chapter":{"en":"TITLE I"},"text":{"en":"Failure to Post and Publish the Itemized Monthly Collections and Disbursements. - Failure by the local treasurer of the local chief accountant to post the itemized monthly collections and disbursements of the local government unit concerned within ten (10) days following the end of every month and for at least two (2) consecutive weeks at prominent places in the main office building of the local government unit concerned, its plaza and main street, and to publish said itemization in a newspaper of general circulation, where available, in the territorial jurisdiction of such unit, shall be punished by a fine not exceeding Five hundred pesos (P500.00) or by imprisonment not exceeding one (1) month, or both such fine and imprisonment, at the discretion of the court."}},{"id":"PH-H5648-A514","no":514,"noLabel":{"en":"Section 514."},"chapter":{"en":"TITLE I"},"text":{"en":"Engaging in Prohibited Business Transactions or Possessing Illegal Pecuniary Interest. - Any local official and any person or persons dealing with him who violate the prohibitions provided in Section 89 of Book I hereof, shall be punished with imprisonment for six months and one day to six years, or a fine of not less than Three thousand pesos (P3,000.00) nor more than Ten thousand pesos (P10,000.00), or both such imprisonment and fine at the discretion of the court."}},{"id":"PH-H5648-A515","no":515,"noLabel":{"en":"Section 515."},"chapter":{"en":"TITLE I"},"text":{"en":"Refusal or Failure of Any Party or Witness to Appear before the Lupon or Pangkat. - Refusal or willful failure of any party or witness to appear before the lupon or pangkat in compliance with a summons issued pursuant to the provisions on the Katarungang Pambarangay under Chapter 7, Title III of this Code may be punished by the city or municipal court as for indirect contempt of court upon application filed therewith by the lupon chairman, the pangkat chairman, or by any of the contending parties. Such refusal or willful failure to appear shall be reflected in the records of the lupon secretary or in the minutes of the pangkat secretary and shall bar the complainant who fails to appear, from seeking judicial recourse for the same cause of action, and the respondent who refuses to appear, from filing any counterclaim arising out of, or necessarily connected with the complaint.\nA pangkat member who serves as such shall be entitled to an honorarium, the amount of which is to be determined by the sanggunian concerned subject to the provisions in this Code cited above."}},{"id":"PH-H5648-A516","no":516,"noLabel":{"en":"Section 516."},"chapter":{"en":"TITLE I"},"text":{"en":"Penalties for Violation of Tax Ordinances. - The sanggunian of a local government unit is authorized to prescribe fines or other penalties for violation of tax ordinances but in no case shall such fines be less than One thousand pesos (P1,000.00) nor more than Five thousand pesos (P5,000.00), nor shall imprisonment be less than one (1) month nor more than six (6) months. Such fine or other penalty, or both, shall be imposed at the discretion of the court. The sangguniang barangay may prescribe a fine of not less than One hundred pesos (P100.00) nor more than One thousand pesos (P1,000.00)."}},{"id":"PH-H5648-A517","no":517,"noLabel":{"en":"Section 517."},"chapter":{"en":"TITLE I"},"text":{"en":"Omission of Property from Assessment or Tax Rolls by Officers and Other Acts. - Any officer charged with the duty of assessing real property who willfully fails to assess, or who intentionally omits from the assessment or tax roll any real property which he knows to be taxable, or who willfully or negligently under assesses any real property, or who intentionally violates or fails to perform any duty imposed upon him by law relating to the assessment of taxable real property shall, upon conviction, be punished by a fine of not less than One thousand pesos (P1,000.00) nor more than Five thousand pesos (P5,000.00), or by imprisonment of not less than one (1) month nor more than six (6) months, or both such fine and imprisonment, at the discretion of the court.\nThe same penalty shall be imposed upon any officer charged with the duty of collecting the tax due on real property who willfully or negligently fails to collect the tax and institute the necessary proceedings for the collection of the same.\nAny other officer required by this Code to perform acts relating to the administration of the real property tax or to assist the assessor or treasurer in such administration, who willfully fails to discharge such duties shall, upon conviction be punished by a fine of not less than Five hundred pesos (P500.00) nor more than Five thousand pesos (P5,000.00) or imprisonment of not less than one (1) month nor more than six (6) months, or both such fine and imprisonment, at the discretion of the court."}},{"id":"PH-H5648-A518","no":518,"noLabel":{"en":"Section 518."},"chapter":{"en":"TITLE I"},"text":{"en":"Government Agents Delaying Assessment of Real Property and Assessment Appeals. - Any government official who intentionally and deliberately delays the assessment of real property or the filing of any appeal against its assessment shall, upon conviction, be punished by a fine of not less than Five hundred pesos (P500.00) nor more than Five thousand pesos (P5,000.00), or by imprisonment of not less than one (1) month nor more than six (6) months, or both such fine and imprisonment, at the discretion of the court."}},{"id":"PH-H5648-A519","no":519,"noLabel":{"en":"Section 519."},"chapter":{"en":"TITLE I"},"text":{"en":"Failure to Dispose of Delinquent Real Property at Public Auction. - The local treasurer concerned who fails to dispose of delinquent real property at public auction in compliance with the pertinent provisions of this Code, and any other local government official whose acts hinder the prompt disposition of delinquent real property at public auction shall, upon conviction, be subject to a fine of not less than One thousand pesos (P1,000.00) nor more than Five thousand pesos (P5,000.00), or imprisonment of not less than one (1) month nor more than six (6) months, or both such fine and imprisonment, at the discretion of the court."}},{"id":"PH-H5648-A520","no":520,"noLabel":{"en":"Section 520."},"chapter":{"en":"TITLE I"},"text":{"en":"Prohibited Acts Related to the Award of Contracts Under the Provisions on Credit Financing. - It shall be unlawful for any public official or employee in the provincial, city, or municipal government, or their relatives within the fourth civil degree of consanguinity or affinity, to enter into or have any pecuniary interest in any contract for the construction, acquisition, operation or maintenance of any project awarded pursuant to the provisions of Title Four in Book II hereof, or for the procurement of any supplies, materials, or equipment of any kind to be used in the said project. Any person convicted for violation of the provisions of said Title shall be removed from office and shall be punishable by imprisonment of not less than one (1) month, nor more than two (2) years, at the discretion of the court, without prejudice to prosecution under other laws.\nPROVISIONS FOR IMPLEMENTATION"}},{"id":"PH-H5648-A521","no":521,"noLabel":{"en":"Section 521."},"chapter":{"en":"TITLE II"},"text":{"en":"Mandatory Review Every Five Years. - Congress shall undertake a mandatory review of this Code at least once every five (5) years and as often as it may deem necessary, with the primary objective of providing a more responsive and accountable local government structure."}},{"id":"PH-H5648-A522","no":522,"noLabel":{"en":"Section 522."},"chapter":{"en":"TITLE II"},"text":{"en":"Insurance Coverage. - The Government Service Insurance System (GSIS) shall establish and administer an appropriate system under which the punong barangay, the members of the sangguniang barangay, the barangay secretary, the barangay treasurer, and the members of the barangay tanod shall enjoy insurance coverage as provided in this Code and other pertinent laws. For this purpose, the GSIS is hereby directed to undertake an actuarial study, issue rules and regulations, determine the premiums payable, and recommend to Congress the amount of appropriations needed to support the system. The amount needed for the implementation of the said insurance shall be included in the annual General Appropriations Act."}},{"id":"PH-H5648-A523","no":523,"noLabel":{"en":"Section 523."},"chapter":{"en":"TITLE II"},"text":{"en":"Personnel Retirement and/or Benefits. - An official or employee of the national government or local government unit separated from the service as a result of reorganization effected under this Code shall, if entitled under the laws then in force, receive the retirement and other benefits accruing thereunder: Provided, however, That such benefits shall be given funding priority by the Department of Budget and Management in the case of national officials and employees, and the local government unit concerned in the case of local officials and employees.\nWhere the employee concerned is not eligible for retirement, he shall be entitled to a gratuity from the national government or the local government unit concerned, as the case may be, equivalent to an amount not lower than one (1) month salary for every year of service over and above the monetary value of the leave credits said employee is entitled to receive pursuant to existing laws."}},{"id":"PH-H5648-A524","no":524,"noLabel":{"en":"Section 524."},"chapter":{"en":"TITLE II"},"text":{"en":"Inventory of Infrastructure and Other Community Facilities.\n(a) Each local government unit shall conduct a periodic inventory of infrastructure and other community facilities and undertake the maintenance, repair, improvement, or reconstruction of these facilities through a closer cooperation among the various agencies of the national government operating within the province, city, or municipality concerned.\n(b) No infrastructure or community project within the territorial jurisdiction of any local government unit shall be undertaken without informing the local chief executive and the sanggunian concerned."}},{"id":"PH-H5648-A525","no":525,"noLabel":{"en":"Section 525."},"chapter":{"en":"TITLE II"},"text":{"en":"Records and Properties. - All records, equipment, buildings, facilities, and other properties of any office or body of a local government unit abolished or reorganized under this Code shall be transferred to the office or body to which its powers, functions, and responsibilities are substantially devolved.\nTRANSITORY PROVISIONS"}},{"id":"PH-H5648-A526","no":526,"noLabel":{"en":"Section 526."},"chapter":{"en":"TITLE III"},"text":{"en":"Application of this Code to Local Government Units in the Autonomous Regions. - This Code shall apply to all provinces, cities, municipalities and barangays in the autonomous regions until such time as the regional government concerned shall have enacted its own local government code."}},{"id":"PH-H5648-A527","no":527,"noLabel":{"en":"Section 527."},"chapter":{"en":"TITLE III"},"text":{"en":"Prior Approval or Clearance on Regular and Recurring Transactions. - Six (6) months after effectivity of this Code, prior approval of or clearance from national agencies or offices shall no longer be required for regular and recurring transactions and activities of local government units."}},{"id":"PH-H5648-A528","no":528,"noLabel":{"en":"Section 528."},"chapter":{"en":"TITLE III"},"text":{"en":"Deconcentration of Requisite Authority and Power. - The national government shall, six (6) months after the effectivity of this Code, effect the deconcentration of requisite authority and power to the appropriate regional offices or field offices of national agencies or offices whose major functions are not devolved to local government units."}},{"id":"PH-H5648-A529","no":529,"noLabel":{"en":"Section 529."},"chapter":{"en":"TITLE III"},"text":{"en":"Tax Ordinances or Revenue Measures. - All existing tax ordinances or revenue measures of local government units shall continue to be in force and effect after the effectivity of this Code unless amended by the sanggunian concerned, or inconsistent with, or in violation of, the provisions of this Code."}},{"id":"PH-H5648-A530","no":530,"noLabel":{"en":"Section 530."},"chapter":{"en":"TITLE III"},"text":{"en":"Local Water Districts. - All powers, functions, and attributes granted by Presidential Decree Numbered One hundred ninety-eight (P.D. No. 198), otherwise known as \"The Provincial Water Utility Act of 1973,\" to the Local Water Utilities Administration (LWUA) may be devolved in toto to the existing local water districts should they opt or choose to exercise, in writing, such powers, functions and attributes: Provided, That all obligations of the local government unit concerned to the LWUA shall first be settled prior to said devolution."}},{"id":"PH-H5648-A531","no":531,"noLabel":{"en":"Section 531."},"chapter":{"en":"TITLE III"},"text":{"en":"Debt Relief for Local Government Units. -\n(a) Unremitted national collections and statutory contributions. - All debts owed by local government units to the national government in unremitted contributions to the Integrated National Police Fund, the Special Education Fund, and other statutory contributions as well as in unremitted national government shares of taxes, charges, and fees collected by the local government units, are hereby written off in full.\n(b) Program loans. -\n(1) Program loans secured by local government units which were relent to private persons, natural or juridical, shall likewise be written off from the books of the local government units concerned: Provided, however, That the national government agency tasked with the implementation of these programs shall continue to collect from the debtors belonging to the private sector concerned.\n(2) Program loans granted to local government units by national government agencies and which were utilized by the local units for community development, livelihood, and other small-scale projects are hereby written off in full.\n(c) Settlement of debts due to government financing institutions (GFIs), government-owned and controlled corporations (GOCCs), and private utilities. The national government shall assume all debts incurred or contracted by local government units from GFIs, GOCCs, and private utilities that are outstanding as of December 31, 1988, in accordance with the following schemes:\n(1) Debts due GFIs. - The national government may buy outstanding obligations incurred by local government units from government financing institutions at a discounted rate.\n(2) Debts due GOCCs. - The national government may settle such obligations at discounted rate through offsetting, only to the extent of the obligations of local governments against the outstanding advances made by the National Treasury in behalf of the government-owned and controlled corporations concerned.\n(3) Debts Due Private Utilities. - The national government may settle these obligations at a discounted rate by offsetting against the outstanding obligations of such private utilities to government-owned corporation. GOCCs may in turn offset these obligations against the outstanding advances made by the National Treasury in their behalf.\nIn the case of obligation owed by local government units to private utilities which are not indebted to any GOCC or national government agency, the national government may instead buy the obligations of the local government units from the private utilities at a discounted rate, upon concurrence by the private utilities concerned.\n(d) Limitations. - Obligations to the Home Development and Mutual Fund (Pag-ibig), Medicare, and those pertaining to premium contributions and amortization payments of salary and policy loans to the Government Service Insurance System are excluded from the coverage of this Section.\n(e) Recovery schemes for the national government. - Local government units shall pay back the national government whatever amounts were advanced or offset by the national government to settle their obligations to GFIs, GOCCs, and private utilities. The national government shall not charge interest or penalties on the outstanding balance owed by the local government units.\nThese outstanding obligations shall be restructured and an amortization schedule prepared, based on the capability of the local government unit to pay, taking into consideration the amount owed to the national government.\nThe national government is hereby authorized to deduct from the quarterly share of each local government unit in the internal revenue collections an amount to be determined on the basis of the amortization schedule of the local unit concerned: Provided, That such amount shall not exceed five percent (5%) of the monthly internal revenue allotment of the local government unit concerned.\nAs incentive to debtor-local government units to increase the efficiency of their fiscal administration, the national government shall write off the debt of the local government unit concerned at the rate of five percent (5%) for every one percent (1%) increase in revenues generated by such local government unit over that of the preceding year. For this purpose, the annual increase in local revenue collection shall be computed starting from the year 1988.\n(f) Appropriations. - Such amount as may be necessary to implement the provisions of this Section shall be included in the annual General Appropriations Act."}},{"id":"PH-H5648-A532","no":532,"noLabel":{"en":"Section 532."},"chapter":{"en":"TITLE III"},"text":{"en":"Elections for the Sangguniang Kabataan. -\n(a) The first elections for the sangguniang kabataan to be conducted under this Code shall be held thirty (30) days after the next local elections: Provided, That, the regular elections for the sangguniang kabataan shall be held one hundred twenty (120) days after the barangay elections thereafter.\n(b) The amount pertaining to the ten percent (10%) allocation for the kabataang barangay as provided for in Section 103 of Batas Pambansa Blg. 337 is hereby reappropriated for the purpose of funding the first elections mentioned above. The balance of said funds, if there by any after the said elections, shall be administered by the Presidential Council for Youth Affairs for the purpose of training the newly elected sangguniang kabataan officials in the discharge of their functions.\n(c) For the regular elections of the sangguniang kabataan, funds shall be taken from the ten percent (10%) of the barangay funds reserved for the sangguniang kabataan, as provided for in Section 328 of this Code.\n(d) All seats reserved for the pederasyon ng mga sangguniang kabataan in the different sanggunians shall be deemed vacant until such time that the sangguniang kabataan chairmen shall have been elected and the respective pederasyon presidents have been selected: Provided, That, elections for the kabataang barangay conducted under Batas Pambansa Blg. 337 at any time between January 1, 1988 and January 1, 1992 shall be considered as the first elections provided for in this Code. The term of office of the kabataang barangay officials elected within the said period shall be extended correspondingly to coincide with the term of office of those elected under this Code."}},{"id":"PH-H5648-A533","no":533,"noLabel":{"en":"Section 533."},"chapter":{"en":"TITLE III"},"text":{"en":"Formulation of Implementing Rules and Regulations. -\n(a) Within one (1) month after the approval of this Code, the President shall convene the Oversight shall formulate and issue the appropriate rules and regulations necessary for the efficient and effective implementation of any and all provisions of this Code, thereby ensuring compliance with the principles of local autonomy as defined under the Constitution.\n(b) The Committee shall be composed of the following:\n(1) The Executive Secretary, who shall be the Chairman;\n(2) Three (3) members of the Senate to be appointed by the President of the Senate, to include the Chairman of the Committee on Local Government;\n(3) Three (3) members of the House of Representatives to be appointed by the Speaker, to include the Chairman of the Committee on Local Government;\n(4) The Cabinet, represented by the following:\n(i) Secretary of the Interior and Local Government;\n(ii) Secretary of Finance;\n(iii) Secretary of Budget and Management; and\n(5) One (1) representative from each of the following:\n(i) The League of Provinces;\n(ii) The League of Cities;\n(iii) The League of Municipalities; and\n(iv) The Liga ng mga Barangay.\n(c) The Committee shall submit its report and recommendation to the President within two (2) months after its organization. If the President fails to act within thirty (30) days from receipt thereof, the recommendation of the Oversight Committee shall be deemed approved. Thereafter, the Committee shall supervise the transfer of such powers and functions mandated under this Code to the local government units, together with the corresponding personnel, properties, assets and liabilities of the offices or agencies concerned, with the least possible disruptions to existing programs and projects. The Committee shall likewise recommend the corresponding appropriations necessary to effect the said transfer.\nFor this purpose, the services of a technical staff shall be enlisted from among the qualified employees of Congress, the government offices, and the leagues constituting the Committee.\n(d) The funding requirements and the secretariat of the Committee shall be provided by the Office of the Executive Secretary.\n(e) The sum of Five million pesos (P5,000,000), which shall be charged against the Contingent Fund, is hereby allotted to the Committee to fund the undertaking of an information campaign on this Code. The Committee shall formulate the guidelines governing the conduct of said campaign, and shall determine the national agencies or offices to be involved for this purpose.\nFINAL PROVISIONS"}},{"id":"PH-H5648-A534","no":534,"noLabel":{"en":"Section 534."},"chapter":{"en":"TITLE IV"},"text":{"en":"Repealing Clause. -\n(a) Batas Pambansa Blg. 337, otherwise known as the Local Government Code, Executive Order No. 112 (1987), and Executive Order No. 319 (1988) are hereby repealed.\n(b) Presidential Decree Nos. 684, 1191, 1508 and such other decrees, orders, instructions, memoranda and issuances related to or concerning the barangay are hereby repealed.\n(c) The provisions of Sections 2, 3, and 4 of Republic Act No. 1939 regarding hospital fund; Section 3, a (3) and b (2) of Republic Act No. 5447 regarding the Special Education Fund; Presidential Decree No. 144 as amended by Presidential Decree Nos. 559 and 1741; Presidential Decree No. 231 as amended; Presidential Decree No. 436 as amended by Presidential Decree No. 558; and Presidential Decree Nos. 381, 436, 464, 477, 526, 632, 752, and 1136 are hereby repealed and rendered of no force and effect.\n(d) Presidential Decree No. 1594 is hereby repealed insofar as it governs locally-funded projects.\n(e) The following provisions are hereby repealed or amended insofar as they are inconsistent with the provisions of this Code: Sections 2, 16 and 29 of Presidential Decree No. 704; Section 12 of Presidential Decree No. 87, as amended; Section 52, 53, 66, 67, 68, 69, 70, 71, 72, 73, and 74 of Presidential Decree No. 463, as amended; and Section 16 of Presidential Decree No. 972, as amended, and\n(f) All general and special laws, acts, city charters, decrees, executive orders, proclamations and administrative regulations, or part or parts thereof which are inconsistent with any of the provisions of this Code are hereby repealed or modified accordingly."}},{"id":"PH-H5648-A535","no":535,"noLabel":{"en":"Section 535."},"chapter":{"en":"TITLE IV"},"text":{"en":"Separability Clause. - If, for any reason or reasons, any part or provision of this Code shall be held to be unconstitutional or invalid, other parts or provisions hereof which are not affected thereby shall continue to be in full force and effect."}},{"id":"PH-H5648-A536","no":536,"noLabel":{"en":"Section 536."},"chapter":{"en":"TITLE IV"},"text":{"en":"Effectivity Clause. - This Code shall take effect on January first, nineteen hundred ninety-two, unless otherwise provided herein, after its complete publication in at least one (1) newspaper of general circulation.\nApproved: October 10, 1991"}}],"pack":"ph-p80"};
  FT["PH-H5649"] = {"id":"PH-H5649","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1991/ra_7161_1991.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"菲律宾修订林业法典","en":"Revised Forestry Code of the Philippines","orig":"An Act Incorporating Certain Sections of the National Internal Revenue Code of 1977, as Amended, to Presidential Decree No. 705, as Amended, otherwise known as the \"Revised Forestry Code of the Philippines\", and providing amendments thereto by increasing the forest charges on timber and other forest products."},"level":"law","status":"active","topics":["tax","environment"],"docNumber":"Republic Act No. 7161","issuingBody":"Congress of the Philippines","promulgatedDate":"1991-10-10","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1991/ra_7161_1991.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5649-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Pursuant to Executive Order No. 273, Sections 230 to 297 of the National Internal Revenue Code of 1977, as amended, are hereby incorporated into Presidential Decree No. 705, as amended, otherwise known as the \"Revised Forestry Code of the Philippines\" and numbered as follows:\nNational Internal Revenue Code of 1977\nSection 230\nSection 231\nSection 232\nSection 233\nSection 234\nSection 235\nSection 236\nSection 237\nSection 238\nSection 297 Revised Forestry Code\nSection 68\nSection 69\nSection 70\nSection 71\nSection 72\nSection 73\nSection 74\nSection 75\nSection 76\nSection 77 All references to the Bureau of Internal Revenue, Commissioner of Internal Revenue, and Ministry of Finance in Section 230 to 238 of the National Internal Revenue Code of 1977 shall hereafter refer to the Forest Management Bureau, and Secretary of Environment and Natural Resources, respectively."}},{"id":"PH-H5649-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The incorporated and numbered Sections 68 to 76 of Presidential Decree No. 705, as amended, are hereby placed under a new subtitle of Chapter III (Utilization and Management) which shall be Subtitle II."}},{"id":"PH-H5649-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 70 of Presidential Decree No. 705, as amended, (formerly Section 232 of the National Revenue Code) is hereby amended to read as follows:\n\"Section 70. Charges on Timber Cut in Forestland- There shall be collected charges on each cubic cubic meter of timber cut in forestland, whether belonging to the first, second, third or fourth group, twenty-five percent (25%) of the actual FOB market price based on species and grading: Provided, however, That, in the case of pulpwood and matchwood cut in forestland, forest charges on each cubic meter shall be ten percent (10%) of the actual FOB market price.\""}},{"id":"PH-H5649-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 71 of Presidential Decree No. 705, as amended, (formerly Section 233 of the National Internal Revenue Code) is hereby amended to read as follows:\n\"Sec. 71. Charges on Firewood, Branches and Other Recoverable Wood Wastes of Timber. - Except for all mangrove species whose cutting shall be banned, there shall be collected forest charges on each cubic meter of firewood cut in forestland, branches and other recoverable wood wastes of timber, such as timber ends, tops and stumps, when used as raw materials for the manufacture of finished products, Ten pesos (P10.00).\n\"Only third or fourth group wood can be taken for firewood. However, if jointly authorized by the Secretary of both the Departments of Environment and Natural Resources, and Agriculture, first and second group woods may be removed for firewood purposes from land which is more valuable for agricultural than for forest purposes.\""}},{"id":"PH-H5649-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section 73 of Presidential Decree No. 705, as amended, (formerly Section 235 of the National Internal Revenue Code) is hereby repealed.\nSection 72 of Presidential Decree No. 705, as amended, (formerly Section 234 of the National Revenue Code) is hereby amended to read as follows:\n\"Section 72. Charges on Minor Forest Products- All other forest products of forestland which are not covered by the preceding sections shall be exempt rattan, gums and resins, beeswax, guta-percha, almaciga resin and bamboo which shall be charged at ten percent (10%) of the actual FOB market price.\""}},{"id":"PH-H5649-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"There shall be added a new section after Section 72 of Presidential Decree No. 705, to be known as Section 73, as to read as follows:\n\"Sec. 73. Effectivity and Application of Forest Charges and Determination of Market Price of Forest Products.-The rates of forest charges provided for in Sections 70,71 and 72 hereof shall be effective upon approval of this Act. The new rates shall be published in the Official Gazette or in two (2) newspapers of national circulation and shall also be posted in conspicuous places in the different Department of Environment and Natural Resources field offices.\n\"The actual FOB market price of forest products shall be justly determined once a year by the Secretary of Environment and Natural Resources: Provided, That he shall cause the creation of a committee to be composed of representatives of the Department of Environment and Natural Resources, the National Economic and Development Authority, the Department of Trade and Industry, the Bureau of Internal Revenue and the wood and furniture industry and consumers sectors which shall formulate the criteria and/or guidelines in the determination of the actual FOB market price to be used as the basis for the assessment of the ad valorem tax. taking into consideration production cost (developing cost, contingencies and miscellaneous cost), species and grade of timber and forest products gathered within public forestlands, alienable and disposable lands and private lands. Forest charges collected shall be in lieu of the administrative charge on environment and other fees and charges imposed thereon: Provided, That planted trees and other forest products harvested from industrial tree plantations and private lands covered by existing tiller or by approved land application are exempted from payment of forest charges.\""}},{"id":"PH-H5649-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Section 77 of Presidential Decree No. 705, as amended, as numbered herein, is hereby repealed.\nSection 68 of Presidential Decree No. 705, as amended by Executive Order No. 277 dated July 25, 1987 and Section 68-A and 68-B of Presidential Decree No. 705, as added by Executive Order No. 277, are hereby renumbered as Sections 89-A, 89-B to 92, respectively."}},{"id":"PH-H5649-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in a newspaper of general circulation."}}],"pack":"ph-p80","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"Revised Forestry Code of the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5650"] = {"id":"PH-H5650","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1991/ra_7162_1991.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"在南三宝颜省设立 Tigbao 市镇的法案","en":"An Act Creating the Municipality of Tigbao in the Province of Zamboanga del Sur","orig":"An Act Creating the Municipality of Tigbao in the Province of Zamboanga del Sur"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7162","issuingBody":"Congress of the Philippines","promulgatedDate":"1991-11-08","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1991/ra_7162_1991.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5650-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Barangays Tigbao, New Tuboran, Nangan- Nangan, Lacarayan, Upper Nilo, Nilo, Lacupayan, Diana Countryside, Busol, Maragang, Limas, Guinlin, Libayoy, Timolan, Mate, Begong, Caluma, and Longmot, all in the Municipality of Dumalinao, Province of Zamboanga del Sur, are hereby separated from the said municipality and constituted into a district and independent Municipality of Tigbao."}},{"id":"PH-H5650-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The technical description of the new municipality shall be as follows:\nLINE\nBEARING\nDISTANCE 1-2 N7º49′57\"-123º19′07\"E, thence, S13º35′15\"E 3,654M 2-3 N7º48′04\"-123º18′40\"E, thence, S12º22′16\"W 1,005M 3-4 N7º47′30\"-123º18′40\"E, thence, N86º05′24\"W 5,434M 4-5 N7º47′42\"-123º15′37\"E, thence, S00º38′00\"W 2,724M 5-6 N7º46′14\"-123º15′03\"E, thence, N61º32′51\"W 3,617M 6-7 N7º47′10\"-123º13′55\"E, thence, N16º58′48\"W 14,569M 7-8 N7º54′41\"-123º11′37\"E, thence, S88º03′24\"E 2,732M 8-9 N7º54′38\"-123º13′05\"E, thence, S63º11′16\"E 12,855M 9-1 N7º51′26\"-123º19′14\"E, thence, S04º54′35\"W 2,821M"}},{"id":"PH-H5650-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The seat of government of the new municipality shall be in Barangay Tigbao."}},{"id":"PH-H5650-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"After ratification by a majority of the votes cast in a plebiscite to be conducted in the areas affected within a period of one hundred eighty (180) days from the approval of this Act, the mayor, vice-mayor and members of the sangguniang bayan of the new municipality shall be elected in the next regular election of local officials. The new municipality shall be considered duly organized upon the assumption of office of the first set of elected local officials."}},{"id":"PH-H5650-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Commission on Elections shall conduct and supervise the plebiscite. The expenses in holding the plebiscite shall be taken out of the Contingent Fund under the current fiscal year appropriations."}},{"id":"PH-H5650-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p80","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Municipality of Tigbao in the Province of Zamboanga del Sur","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5651"] = {"id":"PH-H5651","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1991/ra_7163_1991.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":"授予 Progressive 广播公司在大马尼拉及第一、六、七大区为商业目的建设、安装、运营和维护无线电广播站与电视站并为其他目的法案","en":"An Act Granting the Progressive Broadcasting Corporation a Franchise to Construct, Install, Operate and Maintain for Commercial Purposes Radio Broadcasting Stations and Television Stations in Metro Manila and in Regions I, VI, and VII, and for other purposes","orig":"An Act Granting the Progressive Broadcasting Corporation a Franchise to Construct, Install, Operate and Maintain for Commercial Purposes Radio Broadcasting Stations and Television Stations in Metro Manila and in Regions I, VI, and VII, and for other purposes"},"level":"law","status":"active","topics":["investment","trade"],"docNumber":"Republic Act No. 7163","issuingBody":"Congress of the Philippines","promulgatedDate":"1991-11-17","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1991/ra_7163_1991.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5651-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. – Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Progressive Broadcasting Corporation, hereunder referred to as the grantee, its successors or assigns a franchise to construct, install, operate and maintain for commercial purpose and in the public interest radio broadcasting stations and televisions in Metro Manila and in Regions 1, VI and VII with the corresponding technological auxiliaries or facilities for special broadcast and other program and distribution services and relay stations, and to install radio communication facilities for the grantee's private use in its broadcast services."}},{"id":"PH-H5651-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. – The stations or facilities of the grantee shall be constructed and operated in a manner as well at most result only in the minimum interference on the wavelengths or frequencies of the other existing stations or stations which may be established by law without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's service and/or the availability thereof."}},{"id":"PH-H5651-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. – The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for the technical aspects of its operations, particularly on its frequency assignment in the radio and television spectrum and equipment for its stations. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority, nor impose unnecessary requirements that would impede immediate start of the contemplated service."}},{"id":"PH-H5651-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. – The grantee shall provided reasonable service time to enable the Government, through the said television systems, to reach the population on important public issues; provide at all times sound and balanced programming; promote public participation such as in community, programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public interest, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H5651-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. – The President of the Philippines, in time of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, may temporarily take over and operate the stations of the grantee, temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or authorize the temporary use and operation thereof by any agency of the Government, upon the compensation to the grantee, for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H5651-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. – This franchise shall be for a term of twenty-five (25) years from the date of the effectivity of this Act, unless sooner revoked or cancelled. In the event the grantee fails to operate within two (2) years, this franchise shall be deemed ipso facto revoked from the effectivity of this Act or one (1) year from the grant of certificate of public convenience by the National Telecommunications Commission, whichever is later. Likewise, the term expires if the grantee suspends operation or fails to operate continuously for two (2) years except for reasons outside its control such as force majeure or acts of government, but suspends operation thereafter."}},{"id":"PH-H5651-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. – Acceptance of this franchise shall be given in writing within sixty (60) days after approval of this Act. Refusal or failure to accept the franchise or to operate within the prescribed period shall render the franchise void."}},{"id":"PH-H5651-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tax Provisions. – The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the radio/television business transacted under this franchise by the grantee, its successors or assigns and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof: provided, that the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment has been amended or repealed, in which case the amendment or repeal shall be applicable thereto."}},{"id":"PH-H5651-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Warranty in favor of National and Local Governments. – The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the stations of the grantee, attributable solely to the act or omission of the grantee."}},{"id":"PH-H5651-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. – The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise nor the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor shall the controlling interest in the grantee be transferred to any such private person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H5651-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Public Ownership. – In adherence to the constitutional mandate, the herein grantee shall comply with the enabling law implementing for the purpose the democratization of ownership of all public interest."}},{"id":"PH-H5651-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Separability Clause. – If any of sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H5651-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Repealing Clause. – This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H5651-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Effectivity Clause. – This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p80","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Progressive Broadcasting Corporation a Franchise to Construct, Install, Operate and Maintain for Commercial Purposes Radio Broadcasting Stations and Television Stations in Metro Manila and in Regions I, VI, and VII, and for other purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5652"] = {"id":"PH-H5652","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1991/ra_7164_1991.html","fetchedAt":"2026-10-06","articleCount":35,"structureMode":"ARTICLE","title":{"zh":"护理执业规制法","en":"Philippine Nursing Act of 1991","orig":"Philippine Nursing Act of 1991 An Act Regulating the Practice of Nursing in the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7164","issuingBody":"Congress of the Philippines","promulgatedDate":"1991-11-24","completenessNote":"全文，共 35 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1991/ra_7164_1991.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5652-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title. – This Act shall be known as the \" Philippine Nursing Act of 1991. \" DECLARATION OF POLICY"}},{"id":"PH-H5652-A2","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Declaration of Policy. – It is hereby declared the policy of the State to assume responsibility for the protection and improvement of the nursing profession by instituting measures that will result in relevant nursing education, and in humane working conditions, better career prospects and a dignified existence for our nurses.\nThe State hereby guarantee the delivery of basic health services through an adequate nursing personnel throughout the country. ORGANIZATION OF THE BOARD OF NURSING"}},{"id":"PH-H5652-A3","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Name and Composition of the Board. – There shall be created a Board of Nursing to be composed of a Chairman and four (4) members who shall be appointed by the President from a list of twelve (12) nominees who are registered nurses of recognized standing in the Philippines and who possess the qualifications prescribed in Section 5 of this Act as certified by the accredited national nurses′ association to the Professional Regulation Commission."}},{"id":"PH-H5652-A4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Power and Duties of the Board. – The Board shall have following powers, duties and functions:\n(a) Supervise and regulate the practice of the nursing profession;\n(b) Describe the subjects in the licensure examination, determine the syllabi of the subjects, and their relative weight, construct the test questions, in the licensure examination, and score and rate the examination paper. The Board shall within one hundred twenty (120) days after the examination, submit a report of the examination result which shall contain the weighted average rating of each examinee to the Office of the President for release and publication;\n(c) Issue, suspend, or revoke certificates of registration for the practice of nursing;\n(d) Study the condition affecting the nursing practice in the Philippines and exercise the powers necessary to ensure the maintenance of efficient, ethical, technical, moral and professional standards in the practice of nursing, taking into account the health needs of the nation;\n(e) Examine the prescribed facilities of universities or colleges seeking permission to open colleges of nursing or departments of nursing education in order to ensure that standards and essential requirements for a qualified dean and faculty and adequate budget are property complied with and maintained at all times. The authorization to open colleges of nursing shall be based upon the favorable written recommendation of both the Board and the Department of Education, Culture and Sports;\n(f) Require nurses who graduate from state colleges and universities to render, after being issued the necessary board licenses, at least one (1) year of nursing service in the Philippines before they are allowed to leave for overseas jobs;\n(g) Investigate violations of this Act. For this purpose it may through its Chairman, with the approval of the Board, issue summons, subpoena or subpoena duces tecum to violators of this Act and witnesses thereof and to compel their attendance by the power of contempt; and\n(h) Promulgate decisions or adopt measures as may be necessary for the improvement of the nursing practice, for the advancement of the profession, and for the proper and full enforcement of this Act."}},{"id":"PH-H5652-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Qualifications of Board Members. – A member of the Board shall:\n(a) Be a citizen and resident of the Philippines;\n(b) Be a member in good standing of the accredited national nurses′ association;\n(c) Be a registered nurse and holder of a master′s degree in nursing conferred by a college or university duly recognized by the Government;\n(d) Have at least ten (10) years of continuous practice of the profession prior to appointment;\n(e) Not be a holder of a green card or its equivalent; and\n(f) Not have been convicted of any offense involving moral turpitude even if previously extended pardon by the President of the Philippines."}},{"id":"PH-H5652-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Requirements Upon Qualification as Member of the Board of Nursing. – Any person who qualifies as Chairman or member of the Board shall automatically resign from any teaching position in any school, college or university and/or review program for the local nursing board examinations or in any office or employment in the Government or any subdivision, agency or instrumentality thereof, including government-owned or controlled corporations or their subsidiaries. He shall not have any pecuniary interest in or administrative supervision over any institution offering basic nursing education programs, including review classes."}},{"id":"PH-H5652-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Term of Office. – The Chairman and the members of the Board shall hold office for a term of three (3) years and until their successors shall have qualified: Provided, That a member of the Board may be reappointed for another term not exceeding three (3) years: Provided, further, That, in the event that only one (1) member of the Board is reappointed, he or she, by virtue of seniority, shall automatically become the Chairman of the new Board. However, in case two (2) or more members are reappointed, the best qualified among them, to be determined by all the members of the new Board, shall become the new Chairman of the Board: Provided, finally, That, in case all members of the old Board are reappointed or all members are new, all the members of the new Board shall determine the best qualified from among themselves who shall be recommended to the President of the Philippines to be the Chairman of the Board.\nAny vacancy in the Board occurring within the term of a member shall be filled for the unexpired portion of the term only. Each member of the Board shall take the proper oath of office prior to the performance of his or her duties."}},{"id":"PH-H5652-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Compensation of Board Members. – The Chairman and members of the Board shall receive as compensation an amount equal to that given the Chairman and members of other government boards situated under analogous circumstances."}},{"id":"PH-H5652-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Removal of Board Members. – The President may remove any member of the Board on the following grounds after giving the member concerned an opportunity to defend himself or herself in a proper administrative investigation to be conducted under the supervision and control of the Department of Justice, upon instruction of the President:\n(a) Continued neglect of duty or incompetence;\n(b) Commission or toleration of irregularities in the examination conducted by the Board; and\n(c) Unprofessional or dishonorable conduct."}},{"id":"PH-H5652-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Rules and Regulations. – The Board shall promulgate such rules and regulations as may be necessary to carry out the provisions of this Act."}},{"id":"PH-H5652-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Records. – All records of the Board of Nursing, including examination papers, minutes of deliberations, records of administrative cases and investigations, and examination results shall be kept by the Professional Regulation Commission under the direct custody of the person designated by the Chairman of the Commission. No record shall be removed, altered or examined without the prior authorization of the Board."}},{"id":"PH-H5652-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Examination Required. – All applicants for license to practice nursing shall be required to pass written examination by the Board of Nursing."}},{"id":"PH-H5652-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Qualifications of Applicants. – In order to be admitted to the examination for nurses, an applicant must, at the time of filing his or her application, establish to the satisfaction of the Board of Nursing that:\n(a) He or she is a citizen of the Philippines, or a citizen or subject of a country which permits Filipino nurses to practice within its territorial limits on the same basis as the subject or citizen of such country: Provided, That the requirements for the registration or licensing of nurses in said country are substantially the same as those prescribed in this Act;\n(b) He or she is at least eighteen (18) years of age: Provided, That any underage applicant who successfully passes the examination shall not be permitted or licensed to practice nursing until he or she shall have reached the age of majority;\n(c) He or she is in good health and is of good moral character; and\n(d) He or she is a holder of bachelor′s degree in nursing from a college or university duly recognized by the proper government agency."}},{"id":"PH-H5652-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Licensure Examination. – The licensure examination for the practice of nursing in the Philippines shall by given by the Board not earlier than one (1) month but not later than two (2) months after the closing of the semester prescribed by the Department of Education, Culture and Sports. The examination shall be held in the City of Manila or in such places as may be decided by the Board subject to the approval of the Professional Regulation Commission."}},{"id":"PH-H5652-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Scope of Examination. – The scope of the examination for the practice of nursing in the Philippines shall be determined by the Board. The Board shall take into consideration the objectives of the nursing curriculum, the broad areas of nursing, and other related disciplines and competencies in determining the subjects of examinations."}},{"id":"PH-H5652-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Rating in the examination. – In order to pass the examination, an examinee must obtain a general average rating of at least seventy-five percent (75%) with a rating of not below sixty percent (60%) in any subject. An examinee who obtains an average rating of seventy-five percent (75%) or higher but gets a rating below sixty percent (60%) in any given subject must take the examination again, but only in the subject or subjects where he or she rated below sixty percent (60%).\nIn order to pass the succeeding examination an examinee must obtain a rating of at lest seventy-five percent (75%) in the subject or subjects repeated.\nAn examinee who despite the third examination fails to obtain at least seventy-five percent (75%) in the subject or subjects repeated shall no longer be allowed to take the examination, unless he proves to the satisfaction of the Board that he/she has undergone a refresher course consisting in enrollment and passing in the regular fourth year subjects in a recognized nursing school."}},{"id":"PH-H5652-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Issuance of Certificates. – A certificate of registration as nurse shall be issued to any applicant who passes the examination upon payment of the prescribed fees. Every certificate of registration shall show the full name of the registrant, the serial number, the signature of the members of the Board, and the official seal of the Board."}},{"id":"PH-H5652-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Fees of Examination and Registration. – Applicants for licensure examination and for registration shall pay the prescribed fees set by the Professional Regulation Commission."}},{"id":"PH-H5652-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Registration by Reciprocity. – Certificates of registration may be issued without examination to nurses registered under the laws of any foreign state or country: Provided, That the requirements for the registration or licensing of nurses in said country are substantially the same as those prescribed under this Act: Provided, further, That the laws of such state or country grant the same privileges to registered nurses of the Philippines on the same basis as the subjects or citizens of such foreign state or country."}},{"id":"PH-H5652-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Non-issuance of Certificates in Certain Cases. – No person convicted by final judgment of any criminal offense involving moral turpitude or any person guilty of immoral or dishonorable conduct shall be issued a certificate of registration.\nThe Board shall furnish the applicant a written statement setting forth the reasons for its action which shall be incorporated in the records of the Board."}},{"id":"PH-H5652-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Revocation and Suspension of Certificates. – The Board shall have the power to revoke or suspend the certificate of registration of a nurse upon any of the following grounds:\n(a) For any of the causes mentioned in the preceding section;\n(b) For unprofessional and unethical conduct;\n(c) For gross incompetence and serious ignorance;\n(d) For malpractice or negligence in the practice of nursing; and\n(e) For the use of fraud, deceit, or false statements in obtaining a certificate of registration."}},{"id":"PH-H5652-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Reissuance of Revoked Certificates and Replacement of Lost Certificates. – The Board may, for reasons of equity and justice or when the cause for revocation has disappeared or has been cured and corrected, upon proper application therefor and the payment of the required fees, issue another copy of the certificate of registration. NURSING EDUCATION"}},{"id":"PH-H5652-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"General Entrance Requirements. – Applicants desiring to enroll in a nursing course must belong to the upper forty percent (40%) of the graduating class of the general secondary course, as certified by the school."}},{"id":"PH-H5652-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Nursing Education Program. – The nursing education program shall provide sound academic and professional foundation for the practice of nursing."}},{"id":"PH-H5652-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Learning Experiences. – The learning experiences required in a classroom, hospital, home, community or other health/welfare agency shall adhere strictly to specific requirements embodied in the prescribed curriculum for the nursing course and in the rules, policies, and standards of nursing education. Such learning experience shall not be less than six (6) units or its equivalent."}},{"id":"PH-H5652-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Qualifications of the Faculty. – A member of the faculty in a college or school of nursing must:\n(a) Be a Filipino citizen;\n(b) Be a registered nurse in the Philippines;\n(c) Have at least three (3) years of clinical practice in a field of specialization;\n(d) Be a member of good standing in the accredited national nurses′ association; and\n(e) Be a holder of a master′s degree in nursing or other related fields conferred by a college or university duly recognized by the Government of the Republic of the Philippines; Provided, however, That nothing in this Act shall be construed to disqualify those who have already been considered qualified and actually occupying the position before the effectivity of this Act: Provided, further, That those occupying such position before the effectivity of this Act shall be given a period of five (5) years from the date of effectivity of this Act within which to qualify under the provisions hereof: Provided, finally, That, by the year 2000, all colleges of nursing shall only employ faculty members with a master′s degree in nursing or in other related fields.\nIn addition to the aforementioned qualifications, the dean of a college or school of nursing must have had at least there (3) years of experience in teaching and supervision in nursing education, and preferably must have a master′s degree in administration and supervision of nursing education programs. NURSING PRACTICE"}},{"id":"PH-H5652-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Scope of Nursing. – A person shall be deemed to be practicing nursing within the meaning of this Act when he, for a fee, salary or other reward or compensation, singly or in collaboration with another, initiates and performs nursing services to individuals, families and communities in various stages of development towards the promotion of health, prevention of illness, restoration of health, and alleviation of suffering through:\n(a) Utilization of the nursing process, including assessment, planning, implementation and evaluation of nursing care. Nursing care includes, but not limited to, traditional and innovative approaches in self-executing nursing techniques and procedures, comfort measures, health teaching and administration of legal and written prescription for treatment therapies, medication and hypodermic intramuscular or intravenous injections: Provided, however, That, in the administration of intravenous injections, special training shall be required according to protocol established;\n(b) Establishment of linkages with community resources and coordination of the health team;\n(c) Motivation of individuals, families and communities; resources and coordination of services with other members of the health team;\n(d) Participation in teaching, guidance and supervision of student in nursing education programs, including administering nursing services in varied settings such as hospitals, homes, communities and the like; undertaking consultation services; and engaging in such other activities that require the utilization of knowledge and decision-making skill of a registered nurse; and\n(e) Undertaking nursing and health manpower development training and research and soliciting finances therefor, in cooperation with the appropriate government or private agency: Provided, however, That this provision shall not apply to nursing students who perform nursing functions under the direct supervision of qualified faculty."}},{"id":"PH-H5652-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Qualifications of Nursing Service Administrator. – A person occupying supervisory or managerial positions requiring knowledge of nursing must:\n(a) Be a Filipino citizen or a former Filipino citizen who was has officially declared his/her intention to reacquire Filipino citizenship;\n(b) Be a registered nurse in the Philippines;\n(c) Be a member in good standing of the accredited national organization of nurses;\n(d) Have at least two (2) years experience in general nursing service administration; and\n(e) Possess a degree of Bachelor of Science in Nursing, with at least nine (9) units in management courses at the graduate level.\nProvided, That a person occupying the position of chief nurse or director of nursing service shall, in addition to the foregoing qualifications, possess:\n(a) At least five (5) years of experience in a supervisory or managerial position in nursing; and\n(b) A master′s degree major in nursing service administration or its equivalent: Provided however, That those occupying such position before the effectivity of this Act shall be given a period of five (5) years from the date of effectivity of this Act within which to qualify: Provided, further, That, by the year 2000, only holders of a master′s degree major in nursing administration shall be appointed to such position: Provided finally, That, for hospitals with bed capacity of fifty (50) and below, the minimum academic qualifications and experiences for a chief nurse shall be as specified under subsections (c), (d) and (e) of this section. HEALTH HUMAN RESOURCE DEVELOPMENT, PRODUCTION AND UTILIZATION"}},{"id":"PH-H5652-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Studies for Nursing Manpower Needs, Production, Utilization and Development. – The Nursing Board shall undertake studies and initiate and/or cooperate with appropriate government or private agencies in the conduct of studies for health human resource production, utilization and development. PENAL AND MISCELLANEOUS PROVISIONS"}},{"id":"PH-H5652-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Prohibitions in the Practice of Nursing. – A fine of not less than Ten thousand pesos (P10,000.00) nor more than Forty thousand pesos (P40,000.00) or imprisonment of not less than one (1) year nor more than six (6) years, or both, in the discretion of the court, shall be imposed upon:\n(a) Any person practicing nursing in the Philippines within the meaning of this Act:\n(1) Without a certificate of registration or without having been declared exempt from examination in accordance with the provisions of this Act;\n(2) Who uses as his/her own the certificate or registration of another;\n(3) Who uses an expired, suspended or revoked certificate of registration;\n(4) Who gives any false evidence to the Board of Nursing in order to obtain a certificate of registration;\n(5) Who falsely poses or advertises as a registered nurse or uses any other means that tend to convey the impression that he or she is a registered nurse; or\n(6) Who appends B.S.N./R.N. (Bachelor of Science in Nursing/Registered Nurse) to his/her name without having been conferred said degree or registration;\n(b) Any person who undertakes in-service educational programs or who conducts review classes for both local and foreign examinations without permit/clearance from the Philippine Nursing Association, the Board of Nursing and the appropriate office or officer of the Department of Labor and Employment; and\n(c) Any person violating any provision of this Act."}},{"id":"PH-H5652-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Standard Basic Pay. – Based on current National Economic and Development Authority (NEDA) figures, the proper government office or agency shall fix a standard pay for all nurses working in either public or private health agencies. The same standard basic pay shall be increased periodically to cope with the increase in cost of living."}},{"id":"PH-H5652-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Enforcement of this Act. – It shall be the duty of all duly constituted law-enforcement agencies and officers of national, provincial, city or municipal governments to enforce the provisions of this Act and to prosecute any person violating the same."}},{"id":"PH-H5652-A33","no":33,"noLabel":{"en":"Section 33."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Repealing Clause. – All laws, decrees, orders, circulars, rules and regulations, and other issuances which are inconsistent with this Act are hereby repealed, amended or modified accordingly."}},{"id":"PH-H5652-A34","no":34,"noLabel":{"en":"Section 34."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Separability Clause. – If any part of this Act is declared unconstitutional, the remaining parts not affected thereby shall continue to be valid and operational."}},{"id":"PH-H5652-A35","no":35,"noLabel":{"en":"Section 35."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Effectivity. – This Act shall take effect one (1) month after its publication in any newspaper of general circulation in the Philippines."}}],"pack":"ph-p80"};
  FT["PH-H5653"] = {"id":"PH-H5653","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1991/ra_7165_1991.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"设立扫盲协调委员会、界定其权力与职能并为其拨款的法案，并为其他目的","en":"An Act Creating the Literacy Coordinating Council, Defining It Powers and Functions, Appropriating Funds Therefor, and for other purposes.","orig":"An Act Creating the Literacy Coordinating Council, Defining It Powers and Functions, Appropriating Funds Therefor, and for other purposes."},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7165","issuingBody":"Congress of the Philippines","promulgatedDate":"1991-11-25","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1991/ra_7165_1991.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5653-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"It is the policy of the State to give the highest priority to the adoption of measures for the total eradication of illiteracy. For this purpose, it shall encourage and nationalize the formulation of policies and the implementation of programs on non-formal, informal, and indigenous learning systems, as well as self-learning, independent, and out-of-school study programs particularly those that respond to community needs."}},{"id":"PH-H5653-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"To carry out the declared national policy, there is hereby created a Literacy Coordinating Council, hereinafter referred to as the Council, which shall be an inter-agency body administratively attached to the Department of Education, Culture and Sports."}},{"id":"PH-H5653-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Council shall be composed of eight (8) members as follows: the Undersecretary for Non-Formal Education of the Department of Education, Culture and Sports; the Undersecretary of the Department of Interior and Local Government in charge of Local Governments; the Director of the Philippine Information Agency; the President of the Philippine Normal College; a representative from the National Economic and Development Authority designated by the Director-General; a representative of the Committee on Education, Arts and Culture of the Senate to be designated by the President of the Senate; body, providing policy and program directions for all literacy endeavors in the country."}},{"id":"PH-H5653-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Council shall have the following functions:\n(1) To help act as the overall advisory and coordinating a representative of the Committee on Education and Culture of the House of Representatives to be designated by the Speaker; and the representative of non-government organizations involved in literacy education who shall be appointed by the President of the Philippines for a period of three (3) years.\nThe members of the Council shall annually elect a Chairman from among themselves except the two (2) representatives of Congress.\nThe Council shall meet regularly once a month and may hold special meetings to consider urgent matters upon the call of the Chairman or any three Council members.\n(2) To recommend strategies on the development of a mass movement for the total eradication of illiteracy in the country by the year 2000;\n(3) To formulate measures on the establishment and maintenance of a national data bank and information exchange and dissemination system to support literacy efforts at the national and local levels;\n(4) To assist in identifying and adopting successful management schemes of literacy programs, and adopt measures to boost research and development work in literacy, by government agencies and non-governmental organizations involved in literacy work;\n(5) To recommend ways and means of raising funds in order to support the literacy programs, projects, and activities;\n(6) To recommend measures on how to organize and strengthen support structures for literacy at the regional and local levels; and\n(7) To perform such other functions as may be necessary in furtherance of the purposes of this Act."}},{"id":"PH-H5653-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The administrative and research staff shall be detailed from the existing personnel of the Department of Education, Culture and Sports without prejudice to the designation by the Council of such additional staff members as it may deem necessary for the proper discharge of its function and responsibilities."}},{"id":"PH-H5653-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The Council may, in the performance of its functions, request the cooperation, assistance, and support of appropriate government agencies and non-governmental organizations involved in literacy."}},{"id":"PH-H5653-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The sum of ten million pesos (P10,000,000.00) is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated to carry out the functions of the Council under this Act. Thereafter, the sum needed for the operation and maintenance of the Council shall be included in the annual Budget of the Department of Education, Culture and Sports.\nThe Council shall submit to Congress an annual report which shall include, among other things, policy recommendations which require legislative action towards the total eradication of illiteracy."}},{"id":"PH-H5653-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"All laws, executive orders, presidential decrees, and other issuances, or parts thereof, inconsistent with the provisions of this Act are hereby repealed."}},{"id":"PH-H5653-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"If any section or part of this Act shall be declared unconstitutional, such declaration shall not invalidate other provisions thereof."}},{"id":"PH-H5653-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This Act shall take effect upon its publication in two (2) national newspapers of general circulation."}}],"pack":"ph-p80","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Literacy Coordinating Council, Defining It Powers and Functions, Appropriating Funds Therefor, and for other purposes.","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5654"] = {"id":"PH-H5654","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1991/ra_7166_1991.html","fetchedAt":"2026-10-06","articleCount":40,"structureMode":"ARTICLE","title":{"zh":"规定全国与地方同步选举及选举改革，为此授权拨款并为其他目的法案","en":"An Act Providing for Synchronized National and Local Elections and for Electoral Reforms, Authorizing Appropriations Therefor, and for Other Purposes","orig":"An Act Providing for Synchronized National and Local Elections and for Electoral Reforms, Authorizing Appropriations Therefor, and for Other Purposes"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 7166","issuingBody":"Congress of the Philippines","promulgatedDate":"1991-11-26","completenessNote":"全文，共 40 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1991/ra_7166_1991.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5654-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Statement of Policy. - It is the policy of the State to synchronize elections so that there shall be simultaneous regular elections for national and local officials once every three (3) years."}},{"id":"PH-H5654-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Date of Elections. - In accordance with the policy hereinbefore stated, there shall be an election for President, Vice-President, twenty-four (24) Senators, all elective Members of the House of Representatives, and all elective provincial, city and municipal officials on the second Monday of May, 1992. Thereafter, the President and Vice-President shall be elected on the same day every six (6) years; while the Senators, elective Members of the House of Representatives and all elective provincial, city and municipal officials shall be elected on the same day every three (3) years, except that with respect to Senators, only twelve (12) shall be elected."}},{"id":"PH-H5654-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Election of Members of the Sangguniang Panlalawigan, Sanggunian Panlungsod and Sangguniang Bayan. - The elective members of the Sangguniang Panlalawigan, Sangguniang Panlungsod and Sangguniang Bayan shall be elected as follows:\n(a) For provinces with two (2) or more legislative districts, the elective members of the Sangguniang Panlalawigan shall be elected by legislative districts. For this purpose, the number of seats shall be apportioned equitably: Provided, That, if equal division is not possible, the remaining member or members shall be elected in the district or districts with the greater number of population or, if they be the same, with the greater number of voters: Provided further, That, if a legislative district includes a city that does not vote in the election of provincial officials, the Commission on Elections, hereinafter referred to as the Commission, shall allocate the number of seats among the districts in proportion to the population of the constituencies voting for the Sangguniang Panlalawigan;\n(b) For provinces with only one (1) legislative district, the Commission shall divide them into two (2) districts for purposes of electing the members of the Sangguniang Panlalawigan, as nearly as practicable according to the number of inhabitants, each district comprising a compact, contiguous and adjacent territory, and the number of seats of elective members of their respective sanggunian shall be equitably apportioned between the districts in accordance with the immediately preceding paragraph;\n(c) The number and election of elective members of the Sangguniang Panlungsod and Sangguniang Bayan in the Metro Manila Area, City of Cebu, City of Davao and any other city with two (2) or more legislative districts shall continue to be governed by the provisions of Sections 2 and 3 of Republic Act No. 6636: Provided, That, the Municipalities of Malabon, Navotas, San Juan, Mandaluyong, Muntinlupa, Las Piñas and Taguig shall have twelve (12) councilors, and Pateros, ten (10): Provided, further, That, the Commission shall divide each of the municipalities in Metro Manila Area into two (2) districts by barangay for purposes of representation in the Sangguniang Bayan as nearly as practicable according to the number of inhabitants, each comprising a compact, contiguous and adjacent territory; and\n(d) For purposes of the regular elections on May 11, 1992, elective members of the Sangguniang Panlungsod and Sangguniang Bayan shall be elected a large in accordance with existing laws. However, beginning with the regular elections in 1995, they shall be elected by district.\nThe Commission shall promulgate rules and regulations to effective provide for the election of sectoral representatives in the implementation of the Local Government Code."}},{"id":"PH-H5654-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Postponement, Failure of Election and Special Elections. - The postponement, declaration of failure of election and the calling of special elections as provided in Sections 5, 6 and 7 of the Omnibus Election Code shall be decided by the Commission sitting en banc by a majority vote of its members. The causes for the declaration of a failure of election may occur before or after the casting of votes or on the day of the election.\nIn case a permanent vacancy shall occur in the Senate or House of Representatives at least one (1) year before the expiration of the term, the Commission shall call and hold a special election to fill the vacancy not earlier than sixty (60) days nor longer than ninety (90) days after the occurrence of the vacancy. However, in case of such vacancy in the Senate, the special election shall be held simultaneously with the succeeding regular election."}},{"id":"PH-H5654-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Election and Campaign Period. - Unless otherwise fixed by the Commission, the election period for the May 11, 1992 regular elections shall commence ninety (90) days before the day of the election and shall end thirty (30) days thereafter.\nThe campaign periods are hereby fixed as follows:\n(a) For President, Vice-President and Senators, ninety (90) days before the day of the election; and\n(b) For Members of the House of Representatives and elective provincial, city and municipal officials, forty-five (45) days before the day of the election.\nHowever, in the preparation of the election calendar, the Commission may exclude the day before the day of the election itself, Maundy Thursday and Good Friday.\nAny election campaign or partisan political activity for or against any candidate outside of the campaign period herein provided is prohibited and shall be considered as an election offense punishable under Section 263 and 264 of the Omnibus Election Code."}},{"id":"PH-H5654-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Nomination and Selection of Official Candidates. - No political convention or meeting for the nomination or selection of the official candidates of any political party or organization or political groups or coalition thereof shall be held earlier than the following periods:\n(a) For President, Vice-President and Senators, one hundred sixty-five (165) days before the day of the election; and\n(b) For Members of the House of Representatives and elective provincial, city or municipal officials, seventy-five (75) days before the day of the election."}},{"id":"PH-H5654-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Filing of Certificates of Candidacy. - The certificate of candidacy of any person running for the office of President, Vice-President, Senator, Member of the House of Representatives or any elective provincial, city or municipal official shall be filed in five (5) legible copies with the offices of the Commission specified hereunder not later than the day before the date legally fixed for the beginning of his campaign period.\n(a) The certificate of candidacy for President, Vice-President and Senators shall be filed with the main office of the Commission in Manila;\n(b) The certificate of candidacy for the Members of the House of Representatives shall be filed with the provincial election supervisor of the province concerned. Those for legislative districts in the National Capital Region shall be filed with the regional election director of said region and those for legislative districts in cities outside the National Capital Region which comprise one or more legislative districts shall be filed with the city election registrar concerned;\n(c) The certificate of candidacy for provincial offices shall be filed with the provincial supervisor concerned; and\n(d) The certificate of candidacy for city or municipal offices shall be filed with the city or municipal election registrar concerned.\nWhenever practicable, the names of registered candidates for local positions shall be printed in the election returns: Provided, That, if a candidate has been disqualified or declared a nuisance candidate, it shall be the duty of the Commission to instruct without delay the appropriate election officials to delete the name of said candidate as printed in the election return.\nThe certificate of candidacy shall be filed by the candidate personally or by his duly authorized representative. No certificate of candidacy shall be filed or accepted by mail, telegram or facsimile."}},{"id":"PH-H5654-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Precincts and their Establishment. - Any provision of law to the contrary notwithstanding, where it is not practicable to divide the precinct by territory, the Commission may adjust or split the precinct by assigning the registered voters therein alphabetically and equitably among the adjusted or split precincts: Provided, That, the polling places of said precincts shall be in the same building or premises."}},{"id":"PH-H5654-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Registration of Voters. - There shall be a registration of voters on the fifteenth Saturday before the day of the election for voters who will reach the age of eighteen (18) years on or before the day of the election or for those who are qualified but not registered in the list of voters. However, the Commission may designate an additional date of registration in certain areas to ensure that voters therein are not deprived of their right of suffrage.\nBefore adjourning on registration day, the board of election inspectors shall close the list of voters by affixing their signatures in the space immediately after the last name; number consecutively the names of the voters listed therein and authenticate the list of voters by affixing their signatures on each and every page thereof.\nThe board of election inspectors shall post, on the wall outside the room where the registration was conducted, the list of voters in each precinct beginning on the first working day after registration day until election day. Failure to post said list shall constitute an election offense punishable under Section 263 and 264 of the Omnibus Election Code.\nWhen there is a significant number of inclusions, exclusions and corrections in the list of voters in a precinct, the Commission shall direct the board of election inspectors concerned to meet on the eighth Saturday immediately preceding the day of the election for the purpose of making such inclusions and corrections as may be or may have been ordered by the courts, stating opposite every name so corrected, added or cancelled, the date of the order and the court which issued the same; otherwise, the board shall not meet but such inclusions, exclusions and corrections, if any, shall be made in the list of voters before the voting starts on election day."}},{"id":"PH-H5654-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Annulment of the List of Voters. - Any book of voters the preparation of which has been affected with fraud, bribery, forgery, impersonation, intimidation, force or any other similar irregularity or which is statistically improbable may be annulled, after due notice of a verified complaint: Provided, That, no order, ruling or decision annulling a book of voters shall be executed within sixty (60) days before an election."}},{"id":"PH-H5654-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Voting Booth. - Any provision of law to the contrary notwithstanding, there shall be in each polling place at least ten (10) voting booths of such size, specifications and materials as the Commission may provide to enable the voters to fill out their ballots secretly."}},{"id":"PH-H5654-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Absentee Voting. - Absentee voting as provided for in Executive Order No. 157 dated March 30, 1987 shall apply to the elections for President, Vice-President and Senators only and shall be limited to members of the Armed Forces of the Philippines and the Philippine National Police and other government officers and employees who are duly registered voters and who, on election day, may temporarily be assigned in connection with the performance of election duties to place where they are not registered voters."}},{"id":"PH-H5654-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Authorized Expenses of Candidates and Political Parties. - The agreement amount that a candidate or registered political party may spend for election campaign shall be as follows:\n(a) For candidates. - Ten pesos (P10.00) for President and Vice-President; and for other candidates Three Pesos (P3.00) for every voter currently registered in the constituency where he filed his certificate of candidacy: Provided, That a candidate without any political party and without support from any political party may be allowed to spend Five Pesos (P5.00) for every such voter; and\n(b) For political parties. - Five pesos (P5.00) for every voter currently registered in the constituency or constituencies where it has official candidates.\nAny provision of law to the contrary notwithstanding any contribution in cash or in kind to any candidate or political party or coalition of parties for campaign purposes, duly reported to the Commission shall not be subject to the payment of any gift tax."}},{"id":"PH-H5654-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Statement of Contributions and Expenditures: Effect of Failure to File Statement. - Every candidate and treasurer of the political party shall, within thirty (30) days after the day of the election, file in duplicate with the offices of the Commission the full, true and itemized statement of all contributions and expenditures in connection with the election.\nNo person elected to any public offices shall enter upon the duties of his office until he has filed the statement of contributions and expenditures herein required.\nThe same prohibition shall apply if the political party which nominated the winning candidate fails to file the statement required herein within the period prescribed by this Act.\nExcept candidates for elective barangay office, failure to file the statements or reports in connection with electoral contributions and expenditures are required herein shall constitute an administrative offense for which the offenders shall be liable to pay an administrative fine ranging from One thousand pesos (P1,000.00) to Thirty thousand pesos (P30,000.00), in the discretion of the Commission.\nThe fine shall be paid within thirty (30) days from receipt of notice of such failure; otherwise, it shall be enforceable by a writ of execution issued by the Commission against the properties of the offender.\nIt shall be the duty of every city or municipal election registrar to advise in writing, by personal delivery or registered mail, within five (5) days from the date of election all candidates residing in his jurisdiction to comply with their obligation to file their statements of contributions and expenditures.\nFor the commission of a second or subsequent offense under this section, the administrative fine shall be from Two thousand pesos (P2,000.00) to Sixty thousand pesos (P60,000.00), in the discretion of the Commission. In addition, the offender shall be subject to perpetual disqualification to hold public office."}},{"id":"PH-H5654-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Pre-proclamation Cases Not Allowed in Elections for President Vice-President, Senator, and Member of the House of Representatives. - For purposes of the elections for President, Vice-President, Senator and Member of the House of Representatives, no pre-proclamation cases shall be allowed on matters relating to the preparation, transmission, receipt, custody and appreciation of the election returns or the certificates of canvass, as the case may be. However, this does not preclude the authority of the appropriate canvassing body motu propio or upon written complaint of an interested person to correct manifest errors in the certificate of canvass or election returns before it.\nQuestions affecting the composition or proceedings of the board of canvassers may be initiated in the board or directly with the Commission in accordance with Section 19 hereof.\nAny objection on the election returns before the city or municipal board of canvassers, or on the municipal certificates of canvass before the provincial board of canvassers or district boards of canvassers in Metro Manila Area, shall be specifically noticed in the minutes of their respective proceedings."}},{"id":"PH-H5654-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Pre-proclamation Cases Involving Provincial, City and Municipal Offices. - Pre-proclamation cases involving provincial, city and municipal offices shall be allowed and shall be governed by Sections 17, 18, 19, 20, 21 and 22 hereof.\nAll pre-proclamation cases pending before the Commission shall be deemed terminated at the beginning of the term of the office involved and the rulings of the boards of canvassers concerned shall be deemed affirmed, without prejudice to the filing of a regular election protest by the aggrieved party. However, proceedings may continue when on the basis of the evidence thus far presented, the Commission determined that the petition appears meritorious and accordingly issues an order for the proceeding to continue or when an appropriate order has been issued by the Supreme Court in a petition for certiorari."}},{"id":"PH-H5654-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Pre-proclamation Controversies: How Commenced. - Questions affecting the composition or proceedings of the board of canvassers may be initiated in the board or directly with the Commission. However, matters raised under Sections 233, 234, 235 and 236 of the Omnibus Election Code in relation to the preparation, transmission, receipt, custody and appreciation of the election returns, and the certificates of canvass shall be brought in the first instance before the board of canvassers only."}},{"id":"PH-H5654-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Summary Disposition of Pre-proclamation Controversies. - All pre-proclamation controversies on election returns or certificates of canvass shall, on the basis of the records and evidence elevated to it by the board of canvassers, be disposed of summarily by the Commission within seven (7) days from receipt thereof. Its decisions shall be executory after the lapse of seven (7) days for receipts by the losing party of the decision of the Commission."}},{"id":"PH-H5654-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Consented Composition or Proceedings of the Board: Period to Appeal: Decision by the Commission. - Parties adversely affected by a ruling of the board of canvassers on questions affecting the composition or proceedings of the board may appeal the matter to the Commission within three (3) days from a ruling thereon. The Commission shall summarily decided the case within five (5) days from the filing thereof."}},{"id":"PH-H5654-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Procedure in Disposition of Contested Election Returns. -\n(a) Any candidate, political party or coalition of political parties contesting the inclusion or exclusion in the canvass of any election returns on any of the grounds authorized under Article XX or Sections 234, 235 and 236 of Article XIX of the Omnibus Election Code shall submit their oral objection to the chairman of the board of canvassers at the time the questioned return is presented for inclusion in the canvass. Such objection shall be recorded in the minutes of the canvass.\n(b) Upon receipts of any such objection, the board of canvassers shall automatically defer the canvass of the contested returns and shall proceed to canvass the returns which are not contested by any party.\n(c) Simultaneous with the oral objection, the objecting party shall also enter his objection in the form for written objections to be prescribed by the Commission. Within twenty-four (24) hours from and after the presentation of such an objection, the objecting party shall submit the evidence in support of the objection, which shall be attached to the form for written objections. Within the same period of twenty-four (24) hours after presentation of the objection, any party may file a written and verified opposition to the objection in the form also to be prescribed by the Commission, attaching thereto supporting evidence, if any. The board shall not entertain any objection or opposition unless reduced to writing in the prescribed forms.\nThe evidence attached to the objection or opposition, submitted by the parties, shall be immediately and formally admitted into the records of the board by the chairman affixing his signature at the back of each every page thereof.\n(d) Upon receipt of the evidence, the board shall keep up the contested returns, consider the written objections thereto and opposition, if any, and summarily and immediately rules thereon. The board shall enter its ruling on the prescribed form and authenticate the same by the signatures of its members.\n(e) Any part adversely affected by the ruling of the board shall immediately inform the board if he intends to appeal said ruling. The board shall enter said information in the minutes of the canvass, set aside the returns and proceed to consider the other returns.\n(f) After all the uncontested returns have been canvassed and the contested return ruled upon by it, the board shall suspend the canvass. Within forty-eight (48) hours, therefrom, any party adversely affected by the ruling may file with the board a written and verified notice of appeal; and within an unextendible period of five (5) days thereafter an appeal may be taken to the Commission.\n(g) Immediately upon receipt of the notice of appeal, the board shall make an appropriate report to the Commission, elevating therewith the complete records and evidence submitted in the canvass, and furnishing the parties with copies of the report.\n(h) On the basis of the record and evidence elevate to it by the board, the Commission shall decide summarily the appeal within seven (7) days from receipt of said record and evidence. Any appeal brought before the Commission on the ruling of the board, without the accomplished forms and the evidence appended thereto, shall be summarily dismissed.\nThe decision of the Commission shall be executory after the lapse of seven (7) days from receipts thereof by the losing party.\n(i) The board of canvassers shall not proclaim any candidate as winner unless authorized by the Commission after the latter has ruled on the object brought to it on appeal by the losing party. Any proclamation made in violation hereof shall be void ab initio , unless the contested returns will not adversely affect the results of the election."}},{"id":"PH-H5654-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Partial Proclamation. - Notwithstanding the pendency of any pre-proclamation controversy, the Commission may summarily order the proclamation of other winning candidates whose election will not be affected by the outcome of the controversy."}},{"id":"PH-H5654-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Election Contests for Municipal Offices. - All election contests involving municipal offices filed with the Regional Trial Court shall be decided expeditiously. The decision may be appealed to the Commission within five (5) days from promulgation or receipt of a copy thereof by the aggrieved party. The Commission shall decide the appeal within sixty (60) days after it is submitted for decision, but not later than six (6) months after the filing of the appeal, which decision shall be final, unappealable and executory."}},{"id":"PH-H5654-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Officials Ballots. -\n(a) Ballots for national and local elections, regular or special, plebiscites and referenda, shall be of uniform size and shall be prescribed by the Commission. They shall be printed in black ink on which security paper with distinctive, clear and legible watermarks that will readily distinguish it from ordinary paper. Each ballot shall be in the shape of a strip with stub and detachable coupon containing the serial number of the ballot, and a space for the thumbmark of the voter on the detachable coupon. It shall bear at the top of the voter on the detachable coupon. It shall bear at the top of the middle portion thereof the coat-of-arms of the Republic of the Philippines, the word \"Official Ballot,\" the name of the city or the municipality and province in which the election is to be held, the date of the election, and the following notice in English: \"Fill out this ballot secretly inside the voting booth. Do not put any distinct mark on any part of this ballot.\"\n(b) The official ballot shall also contain the names of all the officer to be voted for in the election, allowing opposite the name of each office, sufficient space of spaces with horizontal lines where the voter may write the name or names of individual candidates voted for by him.\n(c) There shall not be anything printed or written on the back of the ballot except as provided in Section 24 of this Act.\n(d) Official ballot for cities and municipalities where Arabic is of general use shall have each of the titles of the offices to be voted for printed in Arabic in addition to and immediately below the English title.\n(e) Notwithstanding the preceding provisions, the Commission is hereby authorized to prescribe a different form of official ballot on the same watermarked security paper to facilitate voting by illiterate voter only and to use or adopt the latest technological and electronic devices in connection therewith as provided under Section 52(i) of the Omnibus Election Code."}},{"id":"PH-H5654-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Signature of Chairman at the Back of Every Ballot. - In every case before delivering an official ballot to the voter, the chairman of the board of election inspectors shall, in the presence of the voter, affix his signature at the back thereof. Failure to so authenticate shall be noted in the minutes of the board of election inspectors and shall constitute an election offense punishable under Section 263 and 264 of the Omnibus Election Code."}},{"id":"PH-H5654-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Manner of Counting Votes. - In addition to the requirement in the fourth paragraph of Section 12 of Republic Act No. 6646 ad Section 210 of the Omnibus Election Code, in reading the individual official ballots during the counting, the chairman, the poll clerk and the third member shall assume such positions as to provide the watchers and the members of the public as may be conveniently accommodated in the polling place, an unimpeded view of the ballot being read by the chairman, of the election return and the tally board being simultaneously accomplished by the poll clerk and the third member respectively, without touching any of these election documents. The table shall be cleared of all unnecessary writing paraphernalia. Any violation of this requirement shall constitute an election offense punishable under Sections 263 and 264 of the Omnibus Election Code."}},{"id":"PH-H5654-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Official Watchers. - Every registered political party or coalition of political parties, and every candidate shall each be entitled to one watcher in every polling place and canvassing center: Provided, That, candidates for the Sangguniang Panlalawigan, Sangguniang Panlungsod, or Sangguniang Bayan belonging to the same slate or ticket shall collectively be entitled to only one watcher.\nThere shall also be recognized six (6) principal watchers, representing the six (6) accredited major political parties, who shall be designated by the Commission upon nomination of the said parties. These political parties shall be determined by the Commission upon notice and hearing on the basis of the following circumstances:\n(a) The established record of the said parties, coalition of groups that now composed them, taking into account, among other things, their showing in past elections;\n(b) The number of incumbent elective officials belonging to them ninety (90) days before the date of election;\n(c) Their identifiable political organizations and strengths as evidenced by their organized/chapters;\n(d) The ability to fill a complete slate of candidates from the municipal level to the position of President; and\n(e) Other analogous circumstances that may determine their relative organizations and strengths."}},{"id":"PH-H5654-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Number of Copies of Election Returns and their Distribution. - The board of election inspectors shall prepare in handwriting the election returns in their respective polling places, in the number of copies herein provided and in the form to be prescribed and provided by the Commission.\nThe copies of the election returns shall be distributed as follows:\n(a) In the election of President, Vice-President, Senators and Members of the House of Representatives:\n(1) The first copy shall be delivered to the city or municipal board of canvassers;\n(2) The second copy to the Congress, directed to the President of the Senate;\n(3) The third copy, to the Commission;\n(4) The fourth copy, to the provincial board of canvassers;\n(5) The fifth copy, to be known as advance election returns, shall be delivered to the city or municipal treasurer who, in the presence of the election registrar or his authorized representative, shall immediately and publicly open the same and post the votes therein in an election tally board sufficiently large to enable the public to read them, built on the public place preferably within the immediate vicinity of the city hall or municipal building.\n(6) The sixth copy shall be given to the city or municipal trial court judge or in his absence to any official who may be designated by the Commission. The city or municipal trial court judge or the official designated by the Commission shall keep his copies of the election returns, sealed and unopened. Said copy may be opened only during the canvass upon order of the board of canvassers for purposes of comparison with other copies of the returns whose authenticity is in question; and\n(7) The seventh copy shall be deposited inside the compartment of the ballot box for valid ballots; and\n(b) In the election of local officials:\n(1) The first copy shall be delivered to the city or municipal board of canvassers;\n(2) The second copy, to the Commission;\n(3) The third copy, to the provincial board of canvassers;\n(4) The fourth copy, to be known as advance election returns, shall be delivered to the city or municipal treasurer who, in the presence of the election registrar or his authorized representative, shall immediately and publicly open the same and post the votes therein in an election tally board sufficiently large to enable the public to read them, built on a public place preferably within the immediate vicinity of the city hall or municipal building;\n(5) The fifth copy shall be given to the city or municipal trial court judge or in his absence, to any official who may be designated by the Commission. The city or municipal trial court judge or the official designated by the Commission shall keep his copies of the election returns, sealed and unopened. Said copy may be opened only during the canvass upon order of the board of canvassers for purposes of comparison with other copies of the returns whose authenticity is in question; and\n(6) The sixth copy shall be deposited inside the compartment of the ballot box for valid ballots."}},{"id":"PH-H5654-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"Canvassing by Provincial City, District and Municipal Board of Canvassers. -\n(a) The city or municipal board of canvassers shall canvass the election returns of President, Vice-President, Senator and Members of the House of Representatives and for elective provincial and city or municipal officials. Upon completion of the canvass, it shall prepare the certificate of canvass for President, Vice-President, Senators and Members of the House of Representatives and elective provincial officials and thereafter, proclaim the elected city or municipal officials, as the case may be.\n(b) The city board of canvassers of cities comprising one or more legislative districts shall canvass the election returns for President, Vice-President, Senators, Members of the House of Representatives and elective city officials. Upon completion of the canvass, the board shall prepare the certificate of canvass for President, Vice-President, and Senators and thereafter, proclaim the elected Members of the House of Representatives and city officials.\n(c) (1) In the Metro Manila Area each municipality comprising a legislative district shall have a district board of canvassers which shall canvass the election returns for President, Vice-President, Senators, Members of the House of Representatives and elective municipal officials. Upon completion of the canvass, it shall prepare the certificate of canvass for President, Vice-President, and Senators and thereafter, proclaim the elected Member of the House of Representatives and municipal officials.\n(2) Each component municipal in a legislative district in the Metro Manila Area shall have a municipal board of canvassers which shall canvass the election returns for President, Vice-President, Senators, Members of the House of Representatives and elective municipal officials. Upon completion of the canvass, each shall prepare the certificate of canvass for President, Vice-President, Senators and Members of the House of Representatives and thereafter, proclaim the elected municipal officials.\n(3) The district board of canvassers of each legislative district comprising two (2) municipalities in the Metro Manila Area shall canvass the certificate of canvass for President, Vice-President, Senators and Members of the House of Representatives submitted by the municipal board of canvassers of the component municipalities. Upon completion of the canvass, it shall prepare a certificate of canvass for President, Vice-President and Senators and thereafter, proclaim the elected Member of the House of Representatives in the legislative district.\n(d) The provincial board of canvassers shall canvass the certificates of canvass for President, Vice-President, Senators and Members of the House of Representatives and elective provincial officials as well as plebiscite results, if any plebiscite is conducted simultaneously with the same election, as submitted by the board of canvassers of municipalities and component cities. Upon completion of the canvass, it shall prepare the certificate of canvass for President, Vice-President and Senators and thereafter, proclaim the elected Member of the House of Representatives and provincial officials as well as the plebiscite results, if any."}},{"id":"PH-H5654-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"Number of Copies of Certificates of Canvass and their Distribution. -\n(a) The certificate of canvass for President, Vice-President, Senators and Members of the House of Representatives and elective provincial officials shall be prepared in seven (7) copies by the city or municipal board of canvassers and distributed as follows:\n(1) The first copy shall be delivered to the provincial board of canvassers for use in the canvass of election results for President, Vice-President, Senators and Members of the House of Representatives and elective provincial officials;\n(2) The second copy shall be sent to the Commission;\n(3) The third copy shall be kept by the chairman of the board;\n(4) The fourth copy shall be given to the citizens arm designated by the Commission to conduct a media-based unofficial count; and\n(5) The fifth, sixth and seventh copies shall be given to the representatives of three (3) of the six (6) major political parties in accordance with the voluntary agreement of the parties. If no such agreement is reached, the Commission shall decide which parties shall receive the copies of the certificate of canvass on the basis of the criteria provided in Section 26 hereof. The parties receiving the certificates shall have the obligation to furnish the other parties with authentic copies thereof with the least possible delay.\n(b) The certificate of canvass for President, Vice-President, Senators shall be prepared in seven (7) copies by the city boards of canvassers of cities comprising one or more legislative districts, by provincial boards of canvassers and by district boards of canvassers in the Metro Manila Area, and distributed as follows:\n(1) The first copy shall be sent to the Congress, directed to the President of the Senate for use in the canvass of election results for President and Vice-President;\n(2) The second copy shall be sent to the Commission for use in the canvass of the election results for Senators;\n(3) The third copy shall be kept by the chairman of the board;\n(4) The fourth copy shall be given to the citizens arm designated by the Commission to conduct a media-based unofficial count; and\n(5) The fifth, sixth and seventh copies of the certificate of canvass shall be given to any three (3) of the six (6) accredited major political parties in accordance with the voluntary agreement of the parties. If no such agreement is reached, the Commission shall decide which parties shall receive the copies of the certificate of canvass on the basis of the criteria provided in Section 26 hereof. The parties receiving the certificates shall have the obligation to furnish the other parties with authentic copies thereof with the least possible delay.\n(c) The certificate of canvass prepared by the city of municipal boards of canvassers shall each be supported by a statement of votes by precinct, signed and thumbmarked by the chairman and members of the board, and the principal watchers if available. Thereafter, it shall be sealed and placed inside an envelope which shall likewise be properly sealed.\nIn the Metro Manila Area, the certificates of canvass prepared by a district board of canvassers of a legislative district comprising one (1) municipality shall be supported by a statement of votes by precinct. The certificate of canvass prepared by a district board of canvassers of a legislative district comprising two (2) municipalities shall be supported by a statement of votes by municipality.\nThe certificate of canvass prepared by the provincial board of canvassers shall be supported by a statement of votes by municipality, and the original copy thereof for the Congress shall, in addition, be supported by statement of votes by precinct as submitted to the provincial board of canvassers by the city or municipal boards of canvassers. The same requirement shall apply in the case of the certificate of canvass of a district board of canvassers of a legislative district comprising two (2) municipalities in Metro Manila Area."}},{"id":"PH-H5654-A30","no":30,"noLabel":{"en":"Section 30."},"text":{"en":"Congress as the National Board of Canvassers for the Election of President and Vice-President: Determination of Authenticity and Due Execution of Certificates of Canvass. - Congress shall determine the authenticity and due execution of the certificate of canvass for President and Vice-President as accomplished and transmitted to it by the local boards of canvassers, on a showing that: (1) each certificate of canvass was executed, signed and thumbmarked by the chairman and members of the board of canvassers and transmitted or caused to be transmitted to Congress by them; (2) each certificate of canvass contains the names of all of the candidates for President and Vice-President and their corresponding votes in words and in figures; and (3) there exists no discrepancy in other authentic copies of the certificate of canvass or discrepancy in the votes of any candidate in words and figures in the certificate.\nWhen the certificate of canvass, duly certified by the board of canvassers of each province, city or district, appears to be incomplete, the Senate President shall require the board of canvassers concerned to transmit by personal delivery, the election returns from polling places that were not included in the certificate of canvass and supporting statements. Said election returns shall be submitted by personal delivery within two (2) days from receipt of notice.\nWhen it appears that any certificate of canvass or supporting statement of votes by precinct bears erasures or alterations which may cast doubt as to the veracity of the number of votes stated therein and may affect the result of the election, upon request of the Presidential or Vice-Presidential candidate concerned or his party, Congress shall, for the sole purpose of verifying the actual number of votes cast for President and Vice-President, count the votes as they appear in the copies of the election returns submitted to it."}},{"id":"PH-H5654-A31","no":31,"noLabel":{"en":"Section 31."},"text":{"en":"Per Diems of Election Inspectors and Other Officials. - The members of the board of election inspectors shall be paid a per diem of Two hundred pesos (P200.00) each for services on registration and revision days and Four hundred pesos (P400.00) each on the day of the election. Provincial, city and municipal treasurers, administrators and supervisors of the Department of Education, Culture and Sports assigned by the Commission to perform election duty shall receive a per diem of Four hundred pesos (P400.00) each on election day.\nSaid per diem shall be paid by the cashier or other finance officer of the Department of Education, Culture and Sports or of the Commission within fifteen (15) days after registration, revision and election days, respectively. There being funds actually available, any delay in said payments to any of the above mentioned personnel without justifiable reason shall constitute an election offense and all officials and other personnel responsible therefor, directly or indirectly, shall be liable under Sections 263 and 264 of the Omnibus Election Code."}},{"id":"PH-H5654-A32","no":32,"noLabel":{"en":"Section 32."},"text":{"en":"Who May Bear Firearms. - During the election period, no person shall bear, carry or transport firearms or other deadly weapons in public places, including any building, street, park, private vehicle or public conveyance, even if licensed to possess or carry the same, unless authorized in writing by the Commission. The issuance of firearms licenses shall be suspended during the election period.\nOnly regular members or officers of the Philippine National Police, the Armed Forces of the Philippines and other enforcement agencies of the Government who are duly deputized in writing by the Commission for election duty may be authorized to carry and possess firearms during the election period: Provided, That, when in the possession of firearms, the deputized law enforcement officer must be: (a) in full uniform showing clearly and legibly his name, rank and serial number which shall remain visible at all times; and (b) in the actual performance of his election duty in the specific area designated by the Commission."}},{"id":"PH-H5654-A33","no":33,"noLabel":{"en":"Section 33."},"text":{"en":"Security Personnel and Bodyguards. - During the election period, no candidate for public office, including incumbent public officers seeking election to any public office, shall employ, avail himself of or engage the services of security personnel or bodyguards, whether or not such bodyguards are regular members or officers of the Philippine National Police, the Armed Forces of the Philippines or other law enforcement agency of the Government: Provided, That, when circumstances warrant, including but not limited to threats to life and security of a candidate, he may be assigned by the Commission, upon due application, regular members of the Philippine National Police, the Armed Forces of the Philippines or other law enforcement agency who shall provide him security for the duration of the election period. The officers assigned for security duty to a candidate shall be subject to the same requirement as to wearing of uniforms prescribed in the immediately preceding section unless exempted in writing by the Commission.\nIf at any time during the election period, the ground for which the authority to engage the services of security personnel has been granted shall cease to exist of for any other valid cause, the Commission shall revoke the said authority."}},{"id":"PH-H5654-A34","no":34,"noLabel":{"en":"Section 34."},"text":{"en":"Disposition of Firearms. - The firearms of other deadly weapon found in the possession of person prosecuted for the election offense shall be disposed of according to existing laws."}},{"id":"PH-H5654-A35","no":35,"noLabel":{"en":"Section 35."},"text":{"en":"Rules and Regulations. - The Commission shall issue rules and regulations to implement this Act. Said rules shall be published in at least two (2) national newspapers of general circulation."}},{"id":"PH-H5654-A36","no":36,"noLabel":{"en":"Section 36."},"text":{"en":"Governing Laws. - The elections provided herein and all subsequent elections and plebiscite shall be governed by this Act, by the provisions of the Omnibus Election Code, Republic Act No. 6646 and other election laws not inconsistent herewith."}},{"id":"PH-H5654-A37","no":37,"noLabel":{"en":"Section 37."},"text":{"en":"Appropriation. - The amount of One billion pesos (P1,000,000,000.00) is hereby appropriated out of any savings or unexpected balance in the National Treasury not otherwise appropriated to cover the costs of holding the May 11, 1992 elections. Hereafter, the amounts necessary to fund subsequent elections shall be included in the General Appropriations Act for the corresponding fiscal year.\nAny provision of law to the contrary notwithstanding, and for purposes of the May 11, 1992 elections only, the chairman and members of the board of election inspectors shall each be paid a per diem of Four hundred pesos (P400.00) on election day. The Commission may provide hazard pay, when warranted, incentive and merit awards to members of the boards of election inspectors, board of canvassers and personnel of the Commission and its deputized agencies."}},{"id":"PH-H5654-A38","no":38,"noLabel":{"en":"Section 38."},"text":{"en":"Separability Clause. - If any provisions or party of this Act is declared unconstitutional such declaration of unconstitutionality will not affect the other provisions of this Act."}},{"id":"PH-H5654-A39","no":39,"noLabel":{"en":"Section 39."},"text":{"en":"Amending and Repealing Clause. - Section 107, 108 and 245 of the Omnibus Election Code are hereby repealed. Likewise, the inclusion in Section 262 of the Omnibus Election Code of the violations of Sections 105, 106, 107, 108, 109, 110, 111 and 112 as among election offenses is also hereby repealed. This repeal shall have retroactive effect.\nBatas Pambansa Blg. 881, Republic Act No. 6646, Executive Order Nos. 144 and 157 and all other laws, orders, decrees, rules and regulations or other issuances, or any part thereof, inconsistent with the provisions of this Act are hereby amended or repealed accordingly."}},{"id":"PH-H5654-A40","no":40,"noLabel":{"en":"Section 40."},"text":{"en":"Effectivity Clause. - This Act shall take effect upon its publication in full in at least two (2) national newspapers of general circulation.\nApproved: November 26, 1991"}}],"pack":"ph-p80","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for Synchronized National and Local Elections and for Electoral Reforms, Authorizing Appropriations Therefor, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5655"] = {"id":"PH-H5655","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1991/ra_7167_1991.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将个人基本与附加所得税免税额调整至贫困线水平，为此修订国家国内税收法典（经修正）第29条第（L）款第（1）项与第（2）（A）项并为其他目的","en":"An Act Adjusting the Basic Personal and Additional Exemptions Allowable to Individuals for Income Tax Purposes to the Poverty Threshold Level, Amending for the Purpose Section 29, Paragraph (L), Items (1) and (2)(A), of the National Internal Revenue Code, as Amended, and for Other Purposes","orig":"An Act Adjusting the Basic Personal and Additional Exemptions Allowable to Individuals for Income Tax Purposes to the Poverty Threshold Level, Amending for the Purpose Section 29, Paragraph (L), Items (1) and (2)(A), of the National Internal Revenue Code, as Amended, and for Other Purposes"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 7167","issuingBody":"Congress of the Philippines","promulgatedDate":"1991-12-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1991/ra_7167_1991.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5655-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The first paragraph of item (1), paragraph (l) of Section 29 of the National Internal Revenue Code, as amended, is hereby further amended to read as follows:\n\"(l) Personal exemptions allowable to individuals. — (1) Basic personal exemption. — For the purpose of determining the tax provided in Section 21(a) of this Title, there shall be allowed a basic personal exemption as follows:\n\"For single individual or married individual judicially decreed as legally separated with no qualified dependents P9,000 \"For head of a family P12,000 \"For married individual P18,000 Provided, that husband and wife electing to compute their income tax separately shall be entitled to a personal exemption of P9,000 each.\""}},{"id":"PH-H5655-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first paragraph of item (2)(A), paragraph (l) of Section 29 of the same Code, as amended, is hereby further amended to read as follows:\n\"(2) Additional exemption \"(A) Taxpayers with dependents. — A married individual or a head of family shall be allowed an additional exemption of Five thousand pesos (P5,000) for each dependent: provided, that the total number of dependents for which additional exemptions may be claimed shall not exceed four dependents: provided, further, that an additional exemption of One thousand pesos (P1,000) shall be allowed for each child who otherwise qualified as dependent prior to January 1, 1980: provided, finally, that the additional exemption for dependents shall be claimed by only one of the spouses in the case of married individuals electing to compute their income tax liabilities separately.\""}},{"id":"PH-H5655-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p80","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Adjusting the Basic Personal and Additional Exemptions Allowable to Individuals for Income Tax Purposes to the Poverty Threshold Level, Amending for the Purpose Section 29, Paragraph (L), Items (1) and (2)(A), of the National Internal Revenue Code, as Amended, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5656"] = {"id":"PH-H5656","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1991/ra_7168_1991.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将菲律宾师范学院改设为名为菲律宾师范大学的州立大学的法案","en":"An Act Converting the Philippine Normal College into a State University to be known as the Philippine Normal University","orig":"An Act Converting the Philippine Normal College into a State University to be known as the Philippine Normal University"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7168","issuingBody":"Congress of the Philippines","promulgatedDate":"1991-12-26","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1991/ra_7168_1991.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5656-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Philippine Normal College in the City of Manila with branches in the Municipality of Prosperidad in the Province of Agusan, Municipality of Alicia in the Province of Isabela, Cadiz City in the Province of Negros Occidental and Municipality of Lopez in the Province of Quezon is hereby converted into a state university to be known as the Philippine Normal University, hereinafter referred to as the University. The main campus of the University shall be in the City of Manila."}},{"id":"PH-H5656-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The University shall primarily provide higher professional and special instructions for special purposes and to promote research and extension services, advance studies and progressive leadership in education and other fields as may be relevant."}},{"id":"PH-H5656-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The University shall offer undergraduate and graduate courses in the fields of education and other degree courses as the Board of Regents may deem necessary to carry out its objectives."}},{"id":"PH-H5656-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The University shall have the general powers of a corporation set forth in the Corporation Law. The Administration of the University and the exercise of its corporate powers shall be vested exclusively in the Board of Regents and the President of the University insofar as authorized by the Board."}},{"id":"PH-H5656-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The governing body of the University shall be the Board of Regents, hereinafter referred to as the Board, which shall be composed of the following:\nSecretary of Education, Culture and Sports, Chairman"}}],"pack":"ph-p80","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Philippine Normal College into a State University to be known as the Philippine Normal University","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5657"] = {"id":"PH-H5657","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7169_1992.html","fetchedAt":"2026-10-06","articleCount":10,"structureMode":"ARTICLE","title":{"zh":"重整依第 3518 号共和国法设立的菲律宾退伍军人银行、规定其机制并为其他目的法案","en":"An Act to Rehabilitate the Philippine Veterans Bank Created Under Republic Act No. 3518, Providing the Mechanisms therefor, and for Other Purposes","orig":"An Act to Rehabilitate the Philippine Veterans Bank Created Under Republic Act No. 3518, Providing the Mechanisms therefor, and for Other Purposes"},"level":"law","status":"active","topics":["tax","defence"],"docNumber":"Republic Act No. 7169","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-01-02","completenessNote":"全文，共 10 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7169_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5657-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Declaration of Policy. – In order to give meaning and realization to the constitutional mandate to provide immediate and adequate care, benefits and other forms of assistance to war veterans and veterans of military campaigns, their surviving spouses and orphans, it is hereby declared the policy of the Government to provide the necessary mechanisms to rehabilitate the Philippine Veterans Bank, hereinafter known as the Veterans Bank, a bank owned by the Filipino veterans of World War II and deeply imbued and impressed with public interest."}},{"id":"PH-H5657-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Settlement of Liabilities. – The National Government deposit of One billion four hundred eighty-nine million pesos (P1,489,000,000.00) with the Veterans Bank is hereby restructured into a seven-year promissory note of the said bank, carrying an interest rate of four percent (4%) per annum effective on the date of actual operation: Provided, That only the interest shall be paid in the first three (3) years: Provided, further, That repayment of the principal shall be divided into four (4) equal amortizations: Provided, finally, that the said promissory note shall be exempted from the reserve equipment rule of commercial banks.\nThe accrued interests due to the National Government deposits up to and during the time of the Veterans Bank's closure in 1985 and the tax liabilities incurred by the Veterans Bank also up to and during the time of the Veterans Bank's closure are hereby condoned and extinguished.\nThe obligations of the Veterans Bank with the Central Bank of the Philippines and the Philippine Deposit Insurance Corporation are hereby restructured in the same manner governing National Government deposits provided in the first paragraph of this section.\nWith respect to deposits of local government units and other private deposits with the Veterans Bank, the terms and conditions for the retention or withdrawal thereof shall be negotiated individually but may carry more favorable terms in favor of the Veterans Bank."}},{"id":"PH-H5657-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Operations and Changes in the Capital Structure of the Veterans Bank and other Amendments. – The operations and changes in the capital structure of the Veterans Bank, as well as other amendments to its articles of incorporation and bylaws as prescribed under Republic Act No. 3518, shall be in accordance with the Corporation Code, the General Banking Act, and other related laws."}},{"id":"PH-H5657-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Repeal of Amendatory Presidential Decrees. – Presidential Decree Nos. 236, 1637, 919 and 1906 which are inconsistent with this Act are hereby repealed, thus restoring the full force and legal effect of Republic Act No. 3518."}},{"id":"PH-H5657-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Reopening of the Veterans Bank and Its Branches. – Pursuant to and within ninety (90) days from the effectivity of this Act, the Central Bank is hereby authorized to reopen within the period of three (3) years from the date of the reopening of the head office with no branch licensing cost to the said bank."}},{"id":"PH-H5657-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Veterans Bank as a Government Depository. – The Secretary of Finance, the National Treasurer and his authorized representatives, city and municipal treasurers, as well as custodians of public funds or those belonging to government-owned or controlled corporations, are hereby authorized if they so desire to make and actually maintain deposits, of any government of corporate funds with the Veterans Bank, which is hereby declared to be a government depository."}},{"id":"PH-H5657-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Rehabilitation Committee. – To facilitate the implementation of the provisions of this Act, there is hereby created a rehabilitation committee which shall have a term of three (3) months from the date of the approval of this Act composed of the following: the Executive Secretary, as Chairman, and the Administrator of the Philippine Veterans Affairs Office, the President of the Veterans Foundation of the Philippines, a representative from the executive board of the Veterans Federation of the Philippines and a representative from the Board of Trustees of the Veterans of World War II or their respective representatives, as members.\nSpecifically, the committee shall:\n(a) Prepare, finance and submit a viable rehabilitation plan to the Monetary Board of the Central Bank;\n(b) Select and organize an initial manning force headed by a management team to be composed of competent, experienced and professional managers who must possess all qualifications and none of the disqualifications provided under Central Bank rules and regulations. The management team shall be staffed by a trained work force: Provided, That preference shall be given to the veterans and their dependents, other qualifications being equal;\n(c) Exercise management oversight and liaison with Central Bank officers for a period which shall not exceed three (3) months reckoned from the date of approval by the Monetary Board to reopen the Veterans Bank; and\n(d) Submit to the Monetary Board of the Central Bank other recommendations for the successful reopening and operations of the Veterans Bank."}},{"id":"PH-H5657-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Transitory Provisions. – Without requiring new capital infusion either from the Government or from outside investigators, the Filipino veterans of World War II who are real owners-stockholders of the Veterans Bank shall cause the said bank to have at least Seven hundred fifty million pesos (P750,000,000.00) in total unimpaired capital accounts prior to reopening pursuant to this Act as a commercial bank.\nIt is hereby provided that the Board of Trustees of the Veterans of World War II (BTVWW II) created under Republic Act No. 3518 is hereby designated as trustee of all issued but undelivered shares of stock."}},{"id":"PH-H5657-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Repealing Clause. – All laws or parts of any law inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H5657-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Effectivity. – This Act shall take effect upon its approval.\nApproved: January 2, 1992"}}],"pack":"ph-p80","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Rehabilitate the Philippine Veterans Bank Created Under Republic Act No. 3518, Providing the Mechanisms therefor, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5658"] = {"id":"PH-H5658","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7170_1992.html","fetchedAt":"2026-10-06","articleCount":19,"structureMode":"ARTICLE","title":{"zh":"1991 年器官捐献法","en":"Organ Donation Act of 1991","orig":"Organ Donation Act of 1991 An Act Authorizing the Legacy or Donation of All or Part of a Human Body After Death for Specified Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7170","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-01-07","completenessNote":"全文，共 19 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7170_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5658-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title. – This Act shall be known as the \" Organ Donation Act of 1991 \" ."}},{"id":"PH-H5658-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Definition of Terms. – As used in this Act the following terms shall mean:\n(a) \" Organ Bank Storage Facility \" - a facility licensed, accredited or approved under the law for storage of human bodies or parts thereof.\n(b) \" Decedent \" - a deceased individual, and includes a still-born infant or fetus.\n(c) \" Testator \" - an individual who makes a legacy of all or part of his body.\n(d) \" Donor \" - an individual authorized under this Act to donate all or part of the body of a decedent.\n(e) \" Hospital \" - a hospital licensed, accredited or approval under the law, and includes, a hospital operated by the Government.\n(f) \" Part \" - includes transplantable organs, tissues, eyes, bones, arteries, blood, other fluids and other portions of the human body.\n(g) \" Person \" - an individual, corporation, estate, trust, partnership, association, the Government or any of its subdivisions, agencies or instrumentalities, including government-owned or -controlled corporations; or any other legal entity.\n(h) \" Physician\" or \"Surgeon \" - a physician or surgeon licensed or authorized to practice medicine under the laws of the Republic of the Philippines.\n(i) \" Immediate Family \" of the decedent - the persons enumerated in Section 4(a) of this Act.\n(j) \" Death \" - the irreversible cessation of circulatory and respiratory functions or the irreversible cessation of all functions of the entire brain, including the brain stem. A person shall be medically and legally dead if either:\n(1) In the opinion of the attending physician, based on the acceptable standards of medical practice, there is an absence of natural respiratory and cardiac functions and, attempts at resuscitation would not be successful in restoring those functions. In this case, death shall be deemed to have occurred at the time these functions ceased; or\n(2) In the opinion of the consulting physician, concurred in by the attending physician, that on the basis of acceptable standards of medical practice, there is an irreversible cessation of all brain functions; and considering the absence of such functions, further attempts at resuscitation or continued supportive maintenance would not be successful in resorting such natural functions. In this case, death shall be deemed to have occurred at the time when these conditions first appeared.\nThe death of the person shall be determined in accordance with the acceptable standards of medical practice and shall be diagnosed separately by the attending physician and another consulting physician, both of whom must be appropriately qualified and suitably experienced in the care of such parties. The death shall be recorded in the patient's medical record."}},{"id":"PH-H5658-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Person Who May Execute A Legacy. – Any individual, at least eighteen (18) years of age and of sound mind, may give by way of legacy, to take effect after his death, all or part of his body for any purpose specified in Section 6 hereof."}},{"id":"PH-H5658-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Person Who May Execute a Donation. –\n(a) Any of the following, person, in the order of property stated hereunder, in the absence of actual notice of contrary intentions by the decedent or actual notice of opposition by a member of the immediate family of the decedent, may donate all or any part of the decedent's body for any purpose specified in Section 6 hereof:\n(1) Spouse;\n(2) Son or daughter of legal age;\n(3) Either parent;\n(4) Brother or sister of legal age; or\n(5) Guardian over the person of the decedent at the time of his death.\n(b) The persons authorized by sub-section (a) of this Section may make the donation after or immediately before death."}},{"id":"PH-H5658-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Examination of Human Body or Part Thereof . – A legacy of donation of all or part of a human body authorizes any examination necessary to assure medical acceptability of the legacy or donation for the purpose(s) intended.\nFor purposes of this Act, an autopsy shall be conducted on the cadaver of accident, trauma, or other medico-legal cases immediately after the pronouncement of death, to determine qualified and healthy human organs for transplantation and/or in furtherance of medical science."}},{"id":"PH-H5658-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Persons Who May Become Legatees or Donees. – The following persons may become legatees or donees of human bodies or parts thereof for any of the purposes stated hereunder:\n(a) Any hospital, physician or surgeon - For medical or dental education, research, advancement of medical or dental science, therapy or transplantation;\n(b) Any accredited medical or dental school, college or university - For education, research, advancement of medical or dental science, or therapy;\n(c) Any organ bank storage facility - For medical or dental education, research, therapy, or transplantation; and\n(d) Any specified individual - For therapy or transplantation needed by him."}},{"id":"PH-H5658-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Duty of Hospitals. – A hospital authorized to receive organ donations or to conduct transplantation shall train qualified personnel and their staff to handle the task of introducing the organ donation program in a humane and delicate manner to the relatives of the donor-decedent enumerated in Section 4 hereof. The hospital shall accomplish the necessary form or document as proof of compliance with the above requirement."}},{"id":"PH-H5658-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Manner of Executing a Legacy. –\n(a) Legacy of all or part of the human body under Section 3 hereof may be made by will. The legacy becomes effective upon the death of the testator without waiting for probate of the will. If the will is not probated, or if it is declared invalid for testamentary purposes, the legacy, to the extent that it was executed in good faith, is nevertheless valid and effective.\n(b) A legacy of all or part of the human body under Section 3 hereof may also be made in any document other than a will. The legacy becomes effective upon death of the testator and shall be respected by and binding upon his executor or administrator, heirs, assigns, successors-in-interest and all members of the family. The document, which may be a card or any paper designed to be carried on a person, must be signed by the testator in the presence of two witnesses who must sign the document in his presence. If the testator cannot sign, the document may be signed for him at his discretion and in his presence, in the presence of two witnesses who must, likewise, sign the document in the presence of the testator. Delivery of the document of legacy during the testator's lifetime is not necessary to make the legacy valid.\n(c) The legacy may be made to a specified legatee or without specifying a legatee. If the legacy is made to a specified legatee who is not available at the time and place of the testator's death, the attending physician or surgeon, in the absence of any expressed indication that the testator desired otherwise, may accept the legacy as legatee. If the legacy does not specify a legatee, the legacy may be accepted by the attending physician or surgeon as legatee upon or following the testator's death. The physician who becomes a legatee under this subsection shall not participate in the procedures for removing or transplanting a part or parts of the body of the decedent.\n(d) The testator may designate in his will, card or other document, the surgeon or physician who will carry out the appropriate procedures. In the absence of a designation, or if the designee is not available, the legatee or other persons authorized to accept the legacy may authorize any surgeon or physician for the purpose."}},{"id":"PH-H5658-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Manner of Executing a Donation. – Any donation by a person authorized under subsection (a) of Section 4 hereof shall be sufficient if it complies with the formalities of a donation of a movable property.\nIn the absence of any of the persons specified under Section 4 hereof and in the absence of any document of organ donation, the physician in charge of the patient, the head of the hospital or a designated officer of the hospital who has custody of the body of the deceased classified as accident, trauma, or other medico-legal cases, may authorize in a public document the removal from such body for the purpose of transplantation of the organ to the body of a living person: Provided, That the physician, head of hospital or officer designated by the hospital for this purpose has exerted reasonable efforts, within forty-eight (48) hours, to locate the nearest relative listed in Section 4 hereof or guardian of the decedent at the time of death.\nIn all donations, the death of a person from whose body an organ will be removed after his death for the purpose of transplantation to a living person, shall be diagnosed separately and certified by two (2) qualified physicians neither of whom should be:\n(a) A member of the team of medical practitioners who will effect the removal of the organ from the body; nor\n(b) The physician attending to the receipt of the organ to be removed; nor\n(c) The head of hospital or the designated officer authorizing the removal of the organ."}},{"id":"PH-H5658-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Person(s) Authorized to Remove Transplantable Organs. – Only authorized medical practitioners in a hospital shall remove and/or transplant any organ which is authorized to be removed and/or transplanted pursuant to Section 5 hereof."}},{"id":"PH-H5658-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Delivery of Document of Legacy or Donation. – If the legacy or donation is made to a specified legatee or donee, the will, card or other document, or an executed copy thereof, may be delivered by the testator or donor, or is authorized representative, to the legatee or donee to expedite the appropriate procedures immediately after death. The will, card or other document, or an executed copy thereof, may be deposited in any hospital or organ bank storage facility that accepts it for safekeeping or for facilitation or procedures after death. On the request of any interested party upon or after the testator's death, the person in possession shall produce the document of legacy or donation for verification."}},{"id":"PH-H5658-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Amendment or Revocation of Legacy or Donation. –\na) If he will, card or other document, or an executed copy thereof, has been delivered to a specific legatee or donee, the testator or donor may amend or revoke the legacy or donation either by:\n(1) The execution and delivery to the legatee or donee of a signed statement to that effect; or\n(2) An oral statement to that effect made in the presence of two other persons and communicated to the legatee or donee; or\n(3) A statement to that effect during a terminal illness or injury addressed to an attending physician and communicated to the legatee or donee; or\n(4) A signed card or document to that effect found on the person or effects of the testator or donor.\n(b) Any will, card or other document, or an executed copy thereof, which has not been delivered to the legatee or donee may be revoked by the testator or donor in the manner provided in subsection (a) of this Section or by destruction, cancellation or mutilation of the document and all executed copies thereof.\nAny legacy made by a will may also be amended or revoked in the manner provided for amendment or revocation of wills, or as provided in subsection (a) of this Section."}},{"id":"PH-H5658-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Rights and Duties After Death. –\n(a) The legatee or donee may accept or reject the legacy or donation as the case may be. If the legacy of donation is of a part of the body, the legatee or donee, upon the death of the testator and prior to embalming, shall effect the removal of the part, avoiding unnecessary mutilation. After removal of the part, custody of the remainder of the body vests in the surviving spouse, next of kin or other persons under obligation to dispose of the body of the decedent.\n(b) Any person who acts in good faith in accordance with the terms of this Act shall not be liable for damages in any civil action or subject to prosecution in any criminal proceeding of this Act."}},{"id":"PH-H5658-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"International Sharing of Human Organs or Tissues. – Sharing of human organs or tissues shall be made only through exchange programs duly approved by the Department of Health: Provided, That foreign organ or tissue bank storage facilities and similar establishments grant reciprocal rights to their Philippine counterparts to draw organs or tissues at any time."}},{"id":"PH-H5658-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Information Drive. – In order that the public will obtain the maximum benefits from this Act, the Department of Health, in cooperation with institutions, such as the National Kidney Institute, civic and non-government health organizations and other health related agencies, involved in the donation and transplantation of human organs, shall undertake a public information program.\nThe Secretary of Health shall endeavor to persuade all health professionals, both government and private, to make an appeal for human organ donation."}},{"id":"PH-H5658-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Rules and Regulations. – The Secretary of Health, after consultation with all health professionals, both government and private, and non-government health organizations shall promulgate such rules and regulations as may be necessary or proper to implement this Act."}},{"id":"PH-H5658-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Repealing Clause. – All laws, decrees, ordinances, rules and regulations, executive or administrative orders, and other presidential issuance inconsistent with this Act, are hereby repealed, amended or modified accordingly."}},{"id":"PH-H5658-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Separability Clause. – The provisions of this Act are hereby deemed separable. If any provision hereof should be declared invalid or unconstitutional, the remaining provisions shall remain in full force and effect."}},{"id":"PH-H5658-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Effectivity. – This Act shall take effect after fifteen (15) days following its publication in the Official Gazette or at least two (2) newspapers of general circulation.\nApproved: January 7, 1992"}}],"pack":"ph-p80","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"Organ Donation Act of 1991","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5659"] = {"id":"PH-H5659","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7171_1992.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"促进弗吉尼亚烟叶产省农民发展的法案","en":"An Act to Promote the Development of the Farmers in the Virginia Tobacco-producing Provinces","orig":"An Act to Promote the Development of the Farmers in the Virginia Tobacco-producing Provinces"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 7171","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-01-09","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7171_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5659-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Declaration of Policy . - It is hereby declared to be the policy of the Government to extend special support to the farmers of the Virginia tobacco-producing provinces inasmuch as these farmers are the nucleus of the Virginia tobacco industry which generates a sizeable income, in terms of excise taxes from locally manufactured Virginia type cigarettes and customs duties on imported blending tobacco, for the National Government. For the reason stated, it is hereby further declared that the special support for these provinces shall be in terms of financial assistance for developmental projects to be implemented by the local governments of the provinces concerned."}},{"id":"PH-H5659-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Objectives. - The special support to the Virginia tobacco-producing provinces shall be utilized to advance the self-reliance of the tobacco farmers through:\na. Cooperative projects that will enhance better quality of products, increase productivity, guarantee the market and as a whole increase farmers' income;\nb. Livelihood projects particularly the development of alternative farming systems to enhance farmers' income;\nc. Agro-industrial projects that will enable to tobacco farmers in the Virginia tobacco-producing provinces to be involved in the management and subsequent ownership of these projects such as post-harvest and secondary processing like cigarette manufacturing and by-product utilization; and\nd. Infrastructure projects such as farm-to-market roads."}},{"id":"PH-H5659-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Financing and Remittance. - The financial support given by the National Government for the beneficiary provinces shall be constituted and collected from the proceeds of fifteen percent (15%) of the excise taxes on locally manufactured Virginia-type of cigarettes.\nThe funds allotted shall be divided among the beneficiary provinces pro rata according to the volume of Virginia tobacco production.\nProvinces producing Virginia tobacco shall be the beneficiary provinces under this Act: Provided, however, That, to qualify as beneficiary under this Act, a province must have an average annual production of Virginia leaf tobacco in an amount not less than one million kilos: Provided, further, That the Department of Budget and Management (DBM) shall each year determine the beneficiary provinces and their computed share of the funds under this Act, referring to the National Tobacco Administration (NTA) records of tobacco acceptances, at the tobacco trading centers for the immediate past year.\nThe Secretary of Budget and Management is hereby directed to retain annually the said funds equivalent to fifteen percent (15%) of excise taxes on locally manufactured Virginia-type cigarettes to be remitted to the beneficiary provinces qualified under this Act.\nThe provisions of existing laws to the contrary notwithstanding the fifteen percent (15%) share from government revenues mentioned in this Act and due to the Virginia tobacco-producing provinces shall be directly remitted to the provinces concerned."}},{"id":"PH-H5659-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Repealing and Amending Clause. - All enactments, legislative acts and rules and regulations inconsistent or incompatible with the provisions of this Act are hereby repealed."}},{"id":"PH-H5659-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity Clause. - This Act shall take effect upon its approval."}}],"pack":"ph-p80","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Promote the Development of the Farmers in the Virginia Tobacco-producing Provinces","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5660"] = {"id":"PH-H5660","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7172_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"废止1979年5月16日第860号指示函（责令教育文化部长接管菲律宾公立学校教师协会的管理、控制与运营）的法案","en":"An Act to Repeal Letter of Instruction No. 860 Dated May 16, 1979, Directing the Minister of Education and Culture to Take Over the Management, Control and Operation of the Philippine Public School Teachers Association","orig":"An Act to Repeal Letter of Instruction No. 860 Dated May 16, 1979, Directing the Minister of Education and Culture to Take Over the Management, Control and Operation of the Philippine Public School Teachers Association"},"level":"law","status":"active","topics":["education","culture"],"docNumber":"Republic Act No. 7172","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-01-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7172_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5660-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Letter of Instruction No. 860 dated May 16, 1979 directing the Minister of Education and Culture to take over the management, control and operation of the Philippine Public School Teachers Association is hereby repealed."}},{"id":"PH-H5660-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Full management, control and operation of the affairs and funds of the Philippine Public School Teachers Association shall hereafter vest in the officers and members of the Association."}},{"id":"PH-H5660-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All acts, presidential decrees, executive orders and presidential issuances inconsistent with this Act are hereby repealed or amended accordingly."}},{"id":"PH-H5660-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its publication in two (2) newspapers of general circulation."}}],"pack":"ph-p80","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Repeal Letter of Instruction No. 860 Dated May 16, 1979, Directing the Minister of Education and Culture to Take Over the Management, Control and Operation of the Philippine Public School Teachers Association","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5661"] = {"id":"PH-H5661","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7173_1992.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"在伊富高省设立 Asipulo 市镇的法案","en":"An Act Creating the Municipality of Asipulo in the Province of Ifugao","orig":"An Act Creating the Municipality of Asipulo in the Province of Ifugao"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7173","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-01-13","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7173_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5661-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Barangays of Amduntog, Antipolo, Camandag, Cawayan, Pula, Haliap, Panubtuban, Namal and Nungawa in the Municipality of Kiangan, Province of Ifugao, are hereby separated from said municipality and constituted into a new municipality to be known as the Municipality of Asipulo."}},{"id":"PH-H5661-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The seat of the government of the new municipality shall be in a suitable government center site located between the Barangays of Amduntog and Antipolo."}},{"id":"PH-H5661-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The technical description and relative boundaries of the proposed municipality are as follows: starting at a point at Nunhipok River between Barangays Panopdopan, Lamut, Ifugao and Haliap, Kiangan, Ifugao, following the river upstream towards the West between Barangays Haliap and Duit of Kiangan, Ifugao; then following the creek between Barangays Duit and Nungawa of Kiangan, Ifugao, to the ridge of the mountain between Barangays Julongan and Nungawa, Kiangan, Ifugao. Then tracing an imaginary line along the boundary of the Municipalities of Kiangan and Tinoc, both of the Province of Ifugao; then to the provincial boundary of Nueva Vizcaya and lfugao. From this point, following the river between the Municipality of Ambagio, Nueva Vizcaya, and Sitio Ammoeg, Camandag, of the proposed municipality, following the ridge of the mountain between Villaverde, Municipality of Nueva Vizcaya and the proposed municipality; following the boundary of the Municipality of Lamut, Ifugao, and the proposed municipality, then back to the starting point."}},{"id":"PH-H5661-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"After ratification by a majority of the votes cast in a plebiscite to be conducted in the areas affected within a period of one hundred eighty (180) days from the approval of this Act, the first mayor, vice-mayor, and members of the sangguniang bayan of the new municipality shall be elected in the next regular election of local officials. The new municipality shall be considered duly organized upon the assumption of office of the first set of elected local officials."}},{"id":"PH-H5661-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Commission on Elections shall conduct and supervise the plebiscite. The expenses in holding the plebiscite shall be taken out of the Contingent Fund under the current fiscal year appropriations."}},{"id":"PH-H5661-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p80","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Municipality of Asipulo in the Province of Ifugao","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5662"] = {"id":"PH-H5662","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7174_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将马尼拉大都会奎松市Quirino纪念医疗中心床位由200张增至250张并为此拨款的法案","en":"An Act Increasing the Bed Capacity of the Quirino Memorial Medical Center in Quezon City, Metro Manila, From Two Hundred (200) to Two Hundred Fifty (250) Beds, and Appropriating Funds Therefor","orig":"An Act Increasing the Bed Capacity of the Quirino Memorial Medical Center in Quezon City, Metro Manila, From Two Hundred (200) to Two Hundred Fifty (250) Beds, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7174","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-01-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7174_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5662-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Quirino Memorial Medical Center in Quezon City, Metro Manila, is hereby increased from two hundred (200) to two hundred fifty (250) beds."}},{"id":"PH-H5662-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5662-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p80","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of the Quirino Memorial Medical Center in Quezon City, Metro Manila, From Two Hundred (200) to Two Hundred Fifty (250) Beds, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
