  FT["PH-H5678"] = {"id":"PH-H5678","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7190_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立San Miguel市","en":"An Act Establishing a National High School in Barangay Sta. Cruz, Municipality of San Miguel, Province of Leyte, to Be Known as the Sta. Cruz National High School, and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Barangay Sta. Cruz, Municipality of San Miguel, Province of Leyte, to Be Known as the Sta. Cruz National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 7190","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-02-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7190_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5678-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a national high school in Barangay Sta. Cruz, Municipality of San Miguel, Province of Leyte, to be known as the Sta. Cruz National High School."}},{"id":"PH-H5678-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purposes of this Act."}},{"id":"PH-H5678-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary for the implementation of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5678-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p80"};
  FT["PH-H5679"] = {"id":"PH-H5679","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7191_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Tacloban市","en":"An Act Establishing a National High School in the District of Panalaron, City of Tacloban, Province of Leyte, to Be Known as the Panalaron National High School and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in the District of Panalaron, City of Tacloban, Province of Leyte, to Be Known as the Panalaron National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7191","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-02-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7191_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5679-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a national high school in the District of Panalaron, City of Tacloban, Province of Leyte, to be known as the Panalaron National High School."}},{"id":"PH-H5679-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purposes of this Act."}},{"id":"PH-H5679-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary for the implementation of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5679-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p80"};
  FT["PH-H5680"] = {"id":"PH-H5680","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7192_1992.html","fetchedAt":"2026-10-06","articleCount":13,"structureMode":"ARTICLE","title":{"zh":"促进妇女作为男子充分平等伙伴参与发展与国家建设并为其他目的法案","en":"An Act Promoting the Integration of Women as Full and Equal Partners of Men in Development and Nation Building and for Other Purposes","orig":"An Act Promoting the Integration of Women as Full and Equal Partners of Men in Development and Nation Building and for Other Purposes"},"level":"law","status":"active","topics":["civil"],"docNumber":"Republic Act No. 7192","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-02-12","completenessNote":"全文，共 13 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7192_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5680-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title . - This Act shall be cited as the \"Women in Development and Nation Building Act.\""}},{"id":"PH-H5680-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy . - The State recognizes the role of women in nation building and shall ensure the fundamental equality before the law of women and men. The State shall provide women rights and opportunities equal to that of men.\nTo attain the foregoing policy:\n1. A substantial portion of official development assistance funds received from foreign governments and multilateral agencies and organizations shall be set aside and utilized by the agencies concerned to support programs and activities for women;\n2. All government departments shall ensure that women benefit equally and participate directly in the development programs and projects of said department, specifically those funded under official foreign development assistance, to ensure the full participation and involvement of women in the development process; and\n3. All government departments and agencies shall review and revise all their regulations, circulars, issuances and procedures to remove gender bias therein."}},{"id":"PH-H5680-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Responsible Agency. - The National Economic and Development Authority (NEDA) shall primarily be responsible for ensuring the participation of women as recipients in foreign aid, grants and loans. It shall determine and recommend the amount to be allocated for the development activity involving women."}},{"id":"PH-H5680-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Mandate. - The NEDA, with the assistance of the National Commission on the Role of Filipino Women, shall ensure that the different government departments, including its agencies and instrumentalities which, directly, or indirectly, affect the participation of women in national development and their integration therein:\n1. Formulate and prioritize rural or countryside development programs or projects, provide income and employment opportunities to women in the rural areas and thus, prevent their heavy migration from rural to urban or foreign countries;\n2. Include an assessment of the extent to which their programs and/or projects integrate women in the development process and of the impact of said programs or projects on women, including their implications in enhancing the self-reliance of women in improving their income;\n3. Ensure the active participation of women and women's organizations in the development programs and/or projects including their involvement in the planning, design, implementation, management, monitoring and evaluation thereof;\n4. Collect sex-disaggregated data and include such data in its program/project paper, proposal or strategy;\n5. Ensure that programs and/or projects are designed so that the percentage of women who receive assistance is approximately proportionate to either their traditional participation in the targeted activities or their proportion of the population, whichever is higher. Otherwise, the following should be stated in the program/project paper, proposal or strategy:\na. The obstacles in achieving the goal;\nb. The steps being taken to overcome those obstacles; and\nc. To the extent that steps are not being taken to overcome those obstacles, why they are not being taken.\n6. Assist women in activities that are of critical significance to their self-reliance and development."}},{"id":"PH-H5680-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Equality in Capacity to Act. - Women of legal age, regardless of civil status, shall have the capacity to act and enter into contracts which shall in every respect be equal to that of men under similar circumstances.\nIn all contractual situations where married men have the capacity to act, married women shall have equal rights.\nTo this end:\n1. Women shall have the capacity to borrow and obtain loans and execute security and credit arrangements under the same conditions as men;\n2. Women shall have equal access to all government and private sector programs granting agricultural credit, loans and nonmaterial resources and shall enjoy equal treatment in agrarian reform and land resettlement programs;\n3. Women shall have equal rights to act as incorporators and enter into insurance contracts; and\n4. Married women shall have rights equal to those of married men in applying for passports, secure visas and other travel documents, without need to secure the consent of their spouses.\nIn all other similar contractual relations, women shall enjoy equal rights and shall have the capacity to act which shall in every respect be equal to those of men under similar circumstances."}},{"id":"PH-H5680-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Equal Membership in Clubs. - Women shall enjoy equal access to membership in all social, civic and recreational clubs, committees, associations and similar other organizations devoted to public purpose. They shall be entitled to the same rights and privileges accorded to their spouses if they belong to the same organization."}},{"id":"PH-H5680-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Admission to Military Schools. - Any provision of the law to the contrary notwithstanding, consistent with the needs of the services, women shall be accorded equal opportunities for appointment, admission, training, graduation and commissioning in all military or similar schools of the Armed Forces of the Philippines and the Philippine National Police not later than the fourth academic year following the approval of this Act in accordance with the standards required for men except for those minimum essential adjustments required by physiological differences between sexes."}},{"id":"PH-H5680-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Voluntary Pag-IBIG, GSIS and SSS Coverage . - Married persons who devote full time to managing the household and family affairs shall, upon the working spouse's consent, be entitled to voluntary Pag-IBIG (Pagtutulungan-Ikaw, Bangko, Industriya at Gobyerno), Government Service Insurance System (GSIS) or Social Security System (SSS) coverage to the extent of one-half (1/2) of the salary and compensation of the working spouse. The contributions due thereon shall be deducted from the salary of the working spouse.\nThe GSIS or the SSS, as the case may be, shall issue rules and regulations necessary to effectively implement the provisions of this section."}},{"id":"PH-H5680-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Implementing Rules. - The NEDA in consultation with the different government agencies concerned shall issue rules and regulations as may be necessary for the effective implementation of Sections 2, 3 and 4 of this Act within six (6) months from its effectivity."}},{"id":"PH-H5680-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Compliance Report. - Within six (6) months from the effectivity of this Act and every six (6) months thereafter, all government departments, including its agencies and instrumentalities, shall submit a report to Congress on their compliance with this Act."}},{"id":"PH-H5680-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Separability Clause . - If for any reasons any section or provision of this Act is declared unconstitutional or invalid, the other sections or provisions hereof which are not affected thereby shall continue to be in full force and effect."}},{"id":"PH-H5680-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Repealing Clause . - The provisions of Republic Act No. 386, otherwise known as the Civil Code of the Philippines, as amended, and of Executive Order No. 209, otherwise known as the Family Code of the Philippines, and all laws, decrees, executive orders, proclamations, rules and regulations, or parts thereof, inconsistent herewith are hereby repealed."}},{"id":"PH-H5680-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Effectivity Clause. - The rights of women and all the provisions of this Act shall take effect immediately upon its publication in the Official Gazette or in two (2) newspapers of general circulation."}}],"pack":"ph-p80","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Promoting the Integration of Women as Full and Equal Partners of Men in Development and Nation Building and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5681"] = {"id":"PH-H5681","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7193_1992.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"在巴拉望省设立 Culion 市镇的法案","en":"An Act Creating the Municipality of Culion in the Province of Palawan","orig":"An Act Creating the Municipality of Culion in the Province of Palawan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7193","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-02-19","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7193_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5681-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Islands of Culion Leper Colony, Marily, Sand, Tampel, Lamud, Galoc, Lanka, Tambon, Dunaun, Alava, Chindonan and a small island without a name situated directly south of Chindonan Island in latitude 11 deg. 55'N, longitude 12 deg. 02'E, comprising the national reservation for lepers in the Province of Palawan as described under Executive Order No. 35, Series of 1912, are hereby constituted into a distinct and independent municipality to be known as the Municipality of Culion. The seat of government of the new municipality shall be in Barangay Balala."}},{"id":"PH-H5681-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Municipality of Culion shall be bounded and described as follows:\nThe municipality shall be bounded on the north by the Municipality of Busuanga-Coron Island with Concepcion and Salvacion in the Calamian Island Group; on the south by the Municipality of Bacuit-Taytay and Linapacan area; on the east by the South China Sea; on the west by the Cuyo West Pass.\nThe land contained in all the above named islands in Section One is shown on C.G. Map No. 4717 published in Washington D.C., September, 1908, and lies within the following limits, i.e. between the parallels of 11 deg. 36'N and 12 deg. 03'N, and the meridians of 119 deg. 47'E and 120 deg. 15' E."}},{"id":"PH-H5681-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Municipality of Culion shall begin to exist upon the ratification by the majority of the votes cast in a plebiscite to be conducted in the areas affected within One hundred eighty (180) days after approval of this Act.\nThe Commission on Elections shall conduct and supervise the plebiscite. The expenses for such plebiscite shall be paid out of the appropriations provided for the Commission on Elections under the annual General Appropriations Act."}},{"id":"PH-H5681-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"After the approval of the creation of such municipality in the plebiscite, the mayor, vice-mayor and members of the sangguniang bayan of the new Municipality of Culion shall be elected in the next regular election of local officials. The new municipality shall be considered duly organized upon the assumption of office of the first set of elected local officials."}},{"id":"PH-H5681-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"All laws, decrees, executive orders or regulations contrary to or inconsistent herewith are hereby repealed or amended accordingly."}},{"id":"PH-H5681-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p80","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Municipality of Culion in the Province of Palawan","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5682"] = {"id":"PH-H5682","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7194_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将莱特省比利兰副省Naval市镇Naval总医院床位由25张增至50张并为此拨款的法案","en":"An Act Increasing the Bed Capacity of the Naval General Hospital in the Municipality of Naval, Subprovince of Biliran, Leyte, From Twenty-five (25) to Fifty (50) Beds, and Appropriating Funds Therefor","orig":"An Act Increasing the Bed Capacity of the Naval General Hospital in the Municipality of Naval, Subprovince of Biliran, Leyte, From Twenty-five (25) to Fifty (50) Beds, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7194","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-02-25","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7194_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5682-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Naval General Hospital in the Municipality of Naval, Subprovince of Biliran, Leyte, is hereby increased from twenty-five (25) to fifty (50) beds."}},{"id":"PH-H5682-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law."}},{"id":"PH-H5682-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p80","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of the Naval General Hospital in the Municipality of Naval, Subprovince of Biliran, Leyte, From Twenty-five (25) to Fifty (50) Beds, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5683"] = {"id":"PH-H5683","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7195_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将苏禄省Siasi市镇Siasi区医院床位由25张增至50张并为此拨款的法案","en":"An Act Increasing the Bed Capacity of the Siasi District Hospital in the Municipality of Siasi, Province of Sulu, From Twenty-five (25) to Fifty (50) Beds, and Appropriating Funds Therefor","orig":"An Act Increasing the Bed Capacity of the Siasi District Hospital in the Municipality of Siasi, Province of Sulu, From Twenty-five (25) to Fifty (50) Beds, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7195","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-02-25","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7195_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5683-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Siasi District Hospital in the Municipality of Siasi, Province of Sulu, is hereby increased from twenty-five (25) to fifty (50) beds."}},{"id":"PH-H5683-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law."}},{"id":"PH-H5683-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p80","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of the Siasi District Hospital in the Municipality of Siasi, Province of Sulu, From Twenty-five (25) to Fifty (50) Beds, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
